import AppKit
import ImageIO
import Vision

/// RED-only compile seam for S4. Before production owns a second history
/// stack the default witness is deliberately false; once AnnotationSurface
/// supplies concrete `canRedo`/`redo`, this conformance exercises them.
@MainActor private protocol S4RedoProbe {
    var canRedo: Bool { get }
    func redo() -> Bool
}

private extension S4RedoProbe {
    var canRedo: Bool { false }
    func redo() -> Bool { false }
}

extension AnnotationSurface: S4RedoProbe {}

/// Headless feature tests: `Snippr --selftest [outdir]`.
/// Exercises everything that doesn't need Screen Recording permission.
enum SelfTest {
    private static func luma(_ pixel: (Int, Int, Int)) -> Int {
        (pixel.0 * 299 + pixel.1 * 587 + pixel.2 * 114) / 1000
    }

    private final class LockedStringBox: @unchecked Sendable {
        private let lock = NSLock()
        private var value = ""

        func set(_ newValue: String) {
            lock.lock()
            value = newValue
            lock.unlock()
        }

        func get() -> String {
            lock.lock()
            defer { lock.unlock() }
            return value
        }
    }

    /// Counts the real repaint path without replacing the production delegate.
    /// Kept at type scope because save-lock gates use it before the later
    /// backdrop fixtures that originally declared their own local copy.
    @MainActor
    private final class ForwardingRepaintDelegate:
        RedactionSurfaceDelegate
    {
        var repaints = 0
        private let wrapped: RedactionSurfaceDelegate?

        init(wrapping wrapped: RedactionSurfaceDelegate?) {
            self.wrapped = wrapped
        }

        func surfaceNeedsRedactionRepaint() {
            repaints += 1
            wrapped?.surfaceNeedsRedactionRepaint()
        }
    }

    @MainActor
    static func run(outputDir: String) -> Int32 {
        // Headless tests may run from the installed bundle and therefore share
        // its preferences domain. Never mutate real user settings here.
        Settings.registerDefaults(applyMigrations: false)
        // Gates below write last-used / multiple-spotlight. Restore the
        // operator's real defaults when we leave, and start from a clean
        // slate so a leftover last-used cannot preselect a panel that a
        // gate expects to show None.
        let defaults = UserDefaults.standard
        let savedLastStyle = defaults.data(forKey: Settings.Keys.backdropLastStyle)
        let savedMultiple = defaults.object(forKey: Settings.Keys.multipleSpotlight)
        defaults.removeObject(forKey: Settings.Keys.backdropLastStyle)
        defer {
            if let savedLastStyle {
                defaults.set(savedLastStyle, forKey: Settings.Keys.backdropLastStyle)
            } else {
                defaults.removeObject(forKey: Settings.Keys.backdropLastStyle)
            }
            if let savedMultiple {
                defaults.set(savedMultiple, forKey: Settings.Keys.multipleSpotlight)
            } else {
                defaults.removeObject(forKey: Settings.Keys.multipleSpotlight)
            }
            SliceBCompositor.multipleSpotlightOverrideForTesting = nil
        }
        try? FileManager.default.createDirectory(atPath: outputDir, withIntermediateDirectories: true)
        var failures = 0

        func check(_ name: String, _ condition: Bool, _ detail: String = "") {
            if condition {
                print("PASS \(name)")
            } else {
                failures += 1
                print("FAIL \(name) \(detail)")
            }
        }

        // 0a. Bundle integrity: one canonical Snippr, duplicates are named ------
        // A second bundle with our identifier (ad-hoc dev copy in
        // ~/Applications, a mounted DMG, Downloads) shares the TCC subject but
        // not the designated requirement; LaunchServices may open it first and
        // the user is asked to grant Screen Recording "again". The verdict is a
        // pure function of paths so it is provable headlessly.
        do {
            let canonical = URL(fileURLWithPath: "/Applications/Snippr.app")
            let home = URL(fileURLWithPath: "/Users/tester/Applications/Snippr.app")
            let dmg = URL(fileURLWithPath: "/Volumes/Snippr/Snippr.app")
            let messy = URL(fileURLWithPath: "/Applications/./Snippr.app/")
            let clean = BundleIntegrity.evaluate(
                running: canonical, discovered: [canonical], canonical: canonical)
            let withDup = BundleIntegrity.evaluate(
                running: canonical, discovered: [canonical, home, dmg], canonical: canonical)
            let nonCanonical = BundleIntegrity.evaluate(
                running: home, discovered: [canonical, home], canonical: canonical)
            let orphan = BundleIntegrity.evaluate(
                running: home, discovered: [home], canonical: canonical)
            let normalized = BundleIntegrity.evaluate(
                running: messy, discovered: [messy, canonical], canonical: canonical)
            check("integrity-verdict-canonical-clean",
                  clean == .canonical(duplicates: [])
                    && BundleIntegrity.isCanonical(canonical, canonical: canonical),
                  "\(clean)")
            check("integrity-verdict-duplicates-named",
                  withDup == .canonical(duplicates: [home, dmg]),
                  "\(withDup)")
            check("integrity-verdict-noncanonical-blocked",
                  nonCanonical == .runningNonCanonical(
                    running: home, canonicalExists: true, duplicates: [canonical])
                    && orphan == .runningNonCanonical(
                        running: home, canonicalExists: false, duplicates: [])
                    && !BundleIntegrity.isCanonical(home, canonical: canonical),
                  "\(nonCanonical) / \(orphan)")
            check("integrity-verdict-path-normalized",
                  normalized == .canonical(duplicates: [])
                    && BundleIntegrity.isCanonical(messy, canonical: canonical),
                  "\(normalized)")
            // The updater must refuse to run from a non-canonical copy: it
            // would swap /Applications/Snippr.app while the user is running
            // something else, and the relaunch would open the wrong app.
            check("integrity-updater-refuses-noncanonical",
                  UpdateChecker.updateAllowed(for: clean)
                    && UpdateChecker.updateAllowed(for: withDup)
                    && !UpdateChecker.updateAllowed(for: nonCanonical)
                    && !UpdateChecker.updateAllowed(for: orphan),
                  "clean \(UpdateChecker.updateAllowed(for: clean)) nonCanonical \(UpdateChecker.updateAllowed(for: nonCanonical))")
            // Launch disposition is decided BEFORE status item / hotkeys /
            // launch status / TCC prompt: a wrong copy blocks — production
            // has no "continue"; only the explicit debug override proceeds.
            let dispClean = BundleIntegrity.launchDisposition(for: clean)
            let dispDup = BundleIntegrity.launchDisposition(for: withDup)
            let dispWrong = BundleIntegrity.launchDisposition(for: nonCanonical)
            let dispOrphan = BundleIntegrity.launchDisposition(for: orphan)
            let dispDebug = BundleIntegrity.launchDisposition(
                for: nonCanonical, allowNonCanonical: true)
            let dispNoBundle = BundleIntegrity.launchDisposition(for: nil)
            check("integrity-launch-blocks-wrong-copy",
                  dispClean == .proceed
                    && dispDup == .proceed
                    && dispWrong == .blockWrongCopy(running: home, canonicalExists: true)
                    && dispOrphan == .blockWrongCopy(running: home, canonicalExists: false)
                    && dispDebug == .proceed
                    && dispNoBundle == .proceed,
                  "wrong \(dispWrong) orphan \(dispOrphan) debug \(dispDebug)")
            // Handoff ordering, run for real: the helper must wait for the
            // wrong-copy pid to be gone BEFORE opening the canonical app
            // (`open -n`, quoted path) — otherwise the canonical
            // single-instance guard sees the wrong copy and exits, leaving no
            // Snippr at all. A fake "wrong copy" (sleep 1) stands in for our
            // pid; /bin/echo stands in for /usr/bin/open.
            var handoffOK = false
            var handoffDetail = "not run"
            do {
                let fake = Process()
                fake.executableURL = URL(fileURLWithPath: "/bin/sleep")
                fake.arguments = ["1"]
                try fake.run()
                let argv = BundleIntegrity.handoffCommand(
                    canonical: URL(fileURLWithPath: "/Applications/Snippr's Test.app"),
                    waitForPID: fake.processIdentifier, timeoutSeconds: 5,
                    openTool: "/bin/echo")
                let helper = Process()
                helper.executableURL = URL(fileURLWithPath: argv[0])
                helper.arguments = Array(argv.dropFirst())
                let pipe = Pipe()
                helper.standardOutput = pipe
                let started = Date()
                try helper.run()
                helper.waitUntilExit()
                let elapsed = Date().timeIntervalSince(started)
                let out = String(
                    data: pipe.fileHandleForReading.readDataToEndOfFile(),
                    encoding: .utf8) ?? ""
                // /bin/echo -n <path> prints the path without newline: the
                // helper reached `open -n` only after the fake pid ended.
                handoffOK = !fake.isRunning
                    && out == "/Applications/Snippr's Test.app"
                    && elapsed >= 0.9 && elapsed < 4.5
                    && argv[0] == "/bin/sh"
                    && argv[2].range(of: "kill -0")!.lowerBound
                        < argv[2].range(of: " -n ")!.lowerBound
                handoffDetail = "out '\(out)' elapsed \(String(format: "%.2f", elapsed)) fakeRunning \(fake.isRunning)"
            } catch {
                handoffDetail = "error \(error)"
            }
            check("integrity-handoff-waits-then-opens-canonical", handoffOK, handoffDetail)

            // Timeout fixture: the wrong-copy pid outlives the helper's
            // budget → the helper must exit non-zero and open NOTHING
            // (a second instance next to a live wrong copy is the failure
            // mode this whole slice exists to prevent).
            var timeoutOK = false
            var timeoutDetail = "not run"
            do {
                let stubborn = Process()
                stubborn.executableURL = URL(fileURLWithPath: "/bin/sleep")
                stubborn.arguments = ["30"]
                try stubborn.run()
                defer { stubborn.terminate() }
                let argv = BundleIntegrity.handoffCommand(
                    canonical: URL(fileURLWithPath: "/Applications/Snippr.app"),
                    waitForPID: stubborn.processIdentifier, timeoutSeconds: 1,
                    openTool: "/bin/echo")
                let helper = Process()
                helper.executableURL = URL(fileURLWithPath: argv[0])
                helper.arguments = Array(argv.dropFirst())
                let pipe = Pipe()
                helper.standardOutput = pipe
                try helper.run()
                helper.waitUntilExit()
                let out = String(
                    data: pipe.fileHandleForReading.readDataToEndOfFile(),
                    encoding: .utf8) ?? ""
                timeoutOK = helper.terminationStatus != 0 && out.isEmpty && stubborn.isRunning
                timeoutDetail = "status \(helper.terminationStatus) out '\(out)' stubbornRunning \(stubborn.isRunning)"
            } catch {
                timeoutDetail = "error \(error)"
            }
            check("integrity-handoff-timeout-fails-closed", timeoutOK, timeoutDetail)

            // Instance arbitration (main.swift): canonical evicts wrong
            // copies; a wrong copy never blocks the canonical; a second
            // canonical (double launch) yields.
            let arbNone = BundleIntegrity.instanceArbitration(
                selfIsCanonical: true, others: [], canonical: canonical)
            let arbEvict = BundleIntegrity.instanceArbitration(
                selfIsCanonical: true, others: [(pid_t(4242), home)], canonical: canonical)
            let arbEvictUnknown = BundleIntegrity.instanceArbitration(
                selfIsCanonical: true, others: [(pid_t(4243), nil)], canonical: canonical)
            let arbDouble = BundleIntegrity.instanceArbitration(
                selfIsCanonical: true, others: [(pid_t(4244), canonical)], canonical: canonical)
            let arbWrong = BundleIntegrity.instanceArbitration(
                selfIsCanonical: false, others: [(pid_t(4245), canonical)], canonical: canonical)
            let arbWrongVsWrong = BundleIntegrity.instanceArbitration(
                selfIsCanonical: false, others: [(pid_t(4246), home)], canonical: canonical)
            check("integrity-instance-arbitration-canonical-wins",
                  arbNone == .proceed
                    && arbEvict == .evictThenProceed(pids: [4242])
                    && arbEvictUnknown == .evictThenProceed(pids: [4243])
                    && arbDouble == .exitOtherRunning
                    && arbWrong == .exitOtherRunning
                    && arbWrongVsWrong == .exitOtherRunning,
                  "evict \(arbEvict) double \(arbDouble) wrong \(arbWrong)")

            // Launch plan: wrong copy touches nothing; canonical initialises
            // normally and silently even when discovery finds build/test
            // bundles. Duplicate discovery remains useful for arbitration and
            // updater safety, but must never put a modal in front of startup.
            let planWrong = BundleIntegrity.launchPlan(
                for: dispWrong, isDevTool: false, needsCaptureServices: true)
            let planDup = BundleIntegrity.launchPlan(
                for: dispDup, isDevTool: false, needsCaptureServices: true)
            let planClean = BundleIntegrity.launchPlan(
                for: dispClean, isDevTool: false, needsCaptureServices: true)
            let planDev = BundleIntegrity.launchPlan(
                for: dispDup, isDevTool: true, needsCaptureServices: false)
            check("integrity-launch-plan-canonical-silent-with-duplicates",
                  planWrong == [.presentWrongCopyAlertAndExit]
                    && planClean == [.setupStatusItem, .writeLaunchStatus, .startHotkeys, .requestScreenCapture]
                    && planDup == planClean
                    && planDev.isEmpty,
                  "wrong \(planWrong) dup \(planDup) dev \(planDev)")

            // Live discovery must not crash headless; from a bare binary the
            // verdict is nil (no bundle to judge). Direct probing never
            // reports a path that is not a Snippr bundle.
            let bogus = BundleIntegrity.isSnipprBundle(at: URL(fileURLWithPath: "/System/Applications/Calculator.app"))
            let missing = BundleIntegrity.isSnipprBundle(at: URL(fileURLWithPath: "/nonexistent/Snippr.app"))
            check("integrity-discovery-filters-foreign-and-missing", !bogus && !missing, "bogus \(bogus) missing \(missing)")
            // Positive discovery: a REAL temp .app with our bundle id at an
            // injectable known location is found by the direct probe, a
            // foreign-id .app is not, and the same path listed twice
            // (LaunchServices + known location) is reported once.
            var discoveryOK = false
            var discoveryDetail = "not run"
            do {
                let root = URL(fileURLWithPath: NSTemporaryDirectory())
                    .appendingPathComponent("snippr-integrity-\(getpid())")
                try? FileManager.default.removeItem(at: root)
                defer { try? FileManager.default.removeItem(at: root) }
                func makeApp(_ name: String, id: String) throws -> URL {
                    let app = root.appendingPathComponent(name)
                    let contents = app.appendingPathComponent("Contents")
                    try FileManager.default.createDirectory(
                        at: contents.appendingPathComponent("MacOS"), withIntermediateDirectories: true)
                    let plist: [String: Any] = [
                        "CFBundleIdentifier": id, "CFBundleExecutable": "Snippr",
                        "CFBundlePackageType": "APPL", "CFBundleName": "Snippr",
                    ]
                    try PropertyListSerialization.data(fromPropertyList: plist, format: .xml, options: 0)
                        .write(to: contents.appendingPathComponent("Info.plist"))
                    return app
                }
                let stray = try makeApp("Applications/Snippr.app", id: BundleIntegrity.bundleIdentifier)
                let foreign = try makeApp("Other/Snippr.app", id: "com.example.notsnippr")
                let runningApp = try makeApp("Applications/Canonical.app", id: BundleIntegrity.bundleIdentifier)
                let strayAlias = URL(fileURLWithPath: stray.path + "/") // same path, other spelling
                let found = BundleIntegrity.discoveredBundles(
                    running: runningApp, registered: [stray, foreign, strayAlias],
                    knownLocations: [stray, foreign, URL(fileURLWithPath: root.path + "/Applications/Missing.app")])
                let paths = found.map(BundleIntegrity.normalizedPath)
                discoveryOK = paths.count == 2
                    && paths[0] == BundleIntegrity.normalizedPath(runningApp)
                    && paths[1] == BundleIntegrity.normalizedPath(stray)
                    && BundleIntegrity.isSnipprBundle(at: stray)
                    && !BundleIntegrity.isSnipprBundle(at: foreign)
                discoveryDetail = "found \(found.map(\.path))"
            } catch {
                discoveryDetail = "error \(error)"
            }
            check("integrity-discovery-finds-real-duplicate", discoveryOK, discoveryDetail)

            // Eviction executor against REAL children: one dies on the
            // request (sleep), one ignores it (trap '' TERM) and needs
            // force, one is "immortal" (isAlive lies) → stillAlive → the
            // canonical must abort. Order and budgets are the invariant:
            // request → wait → force → verify; never proceed with survivors.
            var evictionOK = false
            var evictionDetail = "not run"
            do {
                let polite = Process()
                polite.executableURL = URL(fileURLWithPath: "/bin/sleep")
                polite.arguments = ["30"]
                try polite.run()
                let stubborn = Process()
                stubborn.executableURL = URL(fileURLWithPath: "/bin/sh")
                stubborn.arguments = ["-c", "trap '' TERM; while :; do /bin/sleep 0.2; done"]
                try stubborn.run()
                Thread.sleep(forTimeInterval: 0.5) // let the trap install
                defer { polite.terminate(); stubborn.terminate(); kill(stubborn.processIdentifier, SIGKILL) }
                var events: [String] = []
                let outcome = BundleIntegrity.evictInstances(
                    [polite.processIdentifier, stubborn.processIdentifier],
                    gracefulTimeout: 1.0, forceTimeout: 1.0,
                    requestTerminate: { events.append("term \($0)"); kill($0, SIGTERM) },
                    forceTerminate: { events.append("kill \($0)"); kill($0, SIGKILL) },
                    isAlive: { kill($0, 0) == 0 },
                    wait: { Thread.sleep(forTimeInterval: $0) })
                let immortalOutcome = BundleIntegrity.evictInstances(
                    [pid_t(99999)], gracefulTimeout: 0.3, forceTimeout: 0.3,
                    requestTerminate: { _ in }, forceTerminate: { _ in },
                    isAlive: { _ in true },
                    wait: { Thread.sleep(forTimeInterval: $0) })
                let politeDead = kill(polite.processIdentifier, 0) != 0
                let stubbornDead = kill(stubborn.processIdentifier, 0) != 0
                evictionOK = outcome == .evicted(forced: [stubborn.processIdentifier])
                    && politeDead && stubbornDead
                    && events.first?.hasPrefix("term") == true
                    && events.contains("kill \(stubborn.processIdentifier)")
                    && !events.contains("kill \(polite.processIdentifier)")
                    && immortalOutcome == .stillAlive([99999])
                    && BundleIntegrity.evictionGracefulTimeout >= 10
                    && BundleIntegrity.evictionMaxDuration == 15
                evictionDetail = "outcome \(outcome) events \(events) immortal \(immortalOutcome)"
            } catch {
                evictionDetail = "error \(error)"
            }
            check("integrity-eviction-request-wait-force-verify", evictionOK, evictionDetail)

            check("integrity-updater-health-outlives-eviction",
                  TimeInterval(UpdateChecker.installerHealthWaitSeconds)
                    >= BundleIntegrity.evictionMaxDuration + 5
                    && TimeInterval(
                        UpdateChecker.installerCandidateStopGraceSeconds
                            + UpdateChecker.installerCandidateStopForceSeconds)
                        >= BundleIntegrity.evictionMaxDuration,
                  "health \(UpdateChecker.installerHealthWaitSeconds)s stop \(UpdateChecker.installerCandidateStopGraceSeconds + UpdateChecker.installerCandidateStopForceSeconds)s eviction \(BundleIntegrity.evictionMaxDuration)s")

            let live = BundleIntegrity.discoveredBundles()
            check("integrity-live-discovery-headless",
                  Bundle.main.bundleURL.pathExtension == "app"
                    || BundleIntegrity.currentVerdict() == nil,
                  "live \(live.count) verdict \(String(describing: BundleIntegrity.currentVerdict()))")
        }

        // 0. Updater detached-shell regression ----------------------------------
        let uppercaseHash = String(repeating: "AB", count: 32)
        let normalizedUppercase = UpdateChecker.normalizedSHA256(uppercaseHash)
        check("updater13-manifest-sha-required",
              UpdateChecker.normalizedSHA256(nil) == nil
                && UpdateChecker.normalizedSHA256("") == nil
                && UpdateChecker.normalizedSHA256(String(repeating: "a", count: 63)) == nil
                && UpdateChecker.normalizedSHA256(String(repeating: "g", count: 64)) == nil
                && normalizedUppercase == uppercaseHash.lowercased(),
              "normalized \(normalizedUppercase ?? "nil")")
        check("updater13-update-server-url-policy",
              UpdateChecker.isAllowedUpdateServerURL(
                  URL(string: "https://snippr.pages.dev/version.json"))
                && UpdateChecker.isAllowedUpdateServerURL(
                    URL(string: "https://snippr.pages.dev:443/Snippr.dmg"))
                && !UpdateChecker.isAllowedUpdateServerURL(nil)
                && !UpdateChecker.isAllowedUpdateServerURL(
                    URL(string: "http://snippr.pages.dev/version.json"))
                && !UpdateChecker.isAllowedUpdateServerURL(
                    URL(string: "https://evil.snippr.pages.dev/version.json"))
                && !UpdateChecker.isAllowedUpdateServerURL(
                    URL(string: "https://snippr.pages.dev.evil.test/version.json"))
                && !UpdateChecker.isAllowedUpdateServerURL(
                    URL(string: "https://attacker@snippr.pages.dev/version.json"))
                && !UpdateChecker.isAllowedUpdateServerURL(
                    URL(string: "https://snippr.pages.dev:444/version.json")))

        // The updater must preserve TCC grants by accepting only candidates
        // signed by the one release identity. Identifier-only verification is
        // insufficient: a second certificate can sign the same bundle ID and
        // macOS will treat that update as a different app.
        let expectedReleaseRoot = "946c43e6456970f5ec11544b3244c192aae949d6"
        let installerScript = UpdateChecker.detachedInstallerScript()
        check("updater14-release-signer-pinned",
              installerScript.contains("certificate root = H\"\(expectedReleaseRoot)\"")
                && installerScript.contains("identifier \"com.manhhoang.snippr\""),
              "detached verifier does not pin the canonical release root")

        let latchOK = MainActor.assumeIsolated { () -> Bool in
            UpdateChecker.releaseUpdateAttempt()
            let first = UpdateChecker.claimUpdateAttempt()
            let second = UpdateChecker.claimUpdateAttempt()
            UpdateChecker.finishUpdateAttempt(didHandoff: false)
            let afterFailure = UpdateChecker.claimUpdateAttempt()
            UpdateChecker.finishUpdateAttempt(didHandoff: true)
            let afterHandoff = UpdateChecker.claimUpdateAttempt()
            UpdateChecker.releaseUpdateAttempt()
            return first && !second && afterFailure && !afterHandoff
        }
        check("updater13-single-attempt-latch", latchOK)

        do {
            let base = URL(fileURLWithPath: outputDir)
            let first = try UpdateChecker.createUpdateAttemptDirectory(in: base)
            let second = try UpdateChecker.createUpdateAttemptDirectory(in: base)
            defer {
                try? FileManager.default.removeItem(at: first)
                try? FileManager.default.removeItem(at: second)
            }
            let firstMode = (try FileManager.default.attributesOfItem(
                atPath: first.path)[.posixPermissions] as? NSNumber)?.intValue ?? 0
            let secondMode = (try FileManager.default.attributesOfItem(
                atPath: second.path)[.posixPermissions] as? NSNumber)?.intValue ?? 0
            check("updater13-private-unique-attempt-paths",
                  first != second && first.lastPathComponent.hasPrefix("SnipprUpdate-")
                    && second.lastPathComponent.hasPrefix("SnipprUpdate-")
                    && firstMode & 0o777 == 0o700 && secondMode & 0o777 == 0o700,
                  "first \(first.lastPathComponent) \(String(firstMode, radix: 8)) second \(second.lastPathComponent) \(String(secondMode, radix: 8))")
        } catch {
            check("updater13-private-unique-attempt-paths", false,
                  "fixture error \(error)")
        }
        check("updater13-exit-wait-exceeds-save-failsafe",
              UpdateChecker.installerExitWaitSeconds > 10,
              "wait \(UpdateChecker.installerExitWaitSeconds)")

        // The detached installer requests graceful termination through the
        // candidate binary itself. Exercise the real NSRunningApplication
        // path against a child whose AppKit delegate records
        // applicationShouldTerminate — plain SIGTERM would not create this
        // marker and therefore cannot satisfy the gate.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-appkit-terminate-\(UUID().uuidString)")
            try FileManager.default.createDirectory(
                at: root, withIntermediateDirectories: true)
            defer { try? FileManager.default.removeItem(at: root) }
            let ready = root.appendingPathComponent("ready")
            let terminated = root.appendingPathComponent("terminated")
            let executable = URL(fileURLWithPath: CommandLine.arguments[0]).standardizedFileURL
            let probe = Process()
            probe.executableURL = executable
            probe.arguments = [
                "--selftest-termination-probe", ready.path, terminated.path,
            ]
            try probe.run()
            defer {
                if probe.isRunning { kill(probe.processIdentifier, SIGKILL) }
                probe.waitUntilExit()
            }
            var spins = 100
            while !FileManager.default.fileExists(atPath: ready.path), spins > 0 {
                Thread.sleep(forTimeInterval: 0.05)
                spins -= 1
            }
            let request = runCommand(
                executable.path,
                ["--request-terminate-pid", String(probe.processIdentifier)])
            spins = 100
            while probe.isRunning, spins > 0 {
                Thread.sleep(forTimeInterval: 0.05)
                spins -= 1
            }
            check("updater15-appkit-terminate-invokes-save-aware-delegate",
                  request.status == 0 && !probe.isRunning
                    && FileManager.default.fileExists(atPath: ready.path)
                    && FileManager.default.fileExists(atPath: terminated.path),
                  "request \(request.status) running \(probe.isRunning) ready \(FileManager.default.fileExists(atPath: ready.path)) terminated \(FileManager.default.fileExists(atPath: terminated.path)) output \(request.output)")
        } catch {
            check("updater15-appkit-terminate-invokes-save-aware-delegate", false,
                  "fixture error \(error)")
        }

        // A recycled/foreign PID must not cross the helper boundary merely
        // because the caller checked it moments earlier. The helper performs
        // its own executable-identity check before requesting termination.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-appkit-foreign-\(UUID().uuidString)")
            try FileManager.default.createDirectory(
                at: root, withIntermediateDirectories: true)
            defer { try? FileManager.default.removeItem(at: root) }
            let ready = root.appendingPathComponent("ready")
            let terminated = root.appendingPathComponent("terminated")
            let helperExecutable = URL(fileURLWithPath: CommandLine.arguments[0])
                .standardizedFileURL
            let foreignExecutable = root.appendingPathComponent("ForeignSnippr")
            try FileManager.default.copyItem(
                at: helperExecutable, to: foreignExecutable)
            let probe = Process()
            probe.executableURL = foreignExecutable
            probe.arguments = [
                "--selftest-termination-probe", ready.path, terminated.path,
            ]
            try probe.run()
            defer {
                if probe.isRunning { kill(probe.processIdentifier, SIGKILL) }
                probe.waitUntilExit()
            }
            var spins = 100
            while !FileManager.default.fileExists(atPath: ready.path), spins > 0 {
                Thread.sleep(forTimeInterval: 0.05)
                spins -= 1
            }
            let request = runCommand(
                helperExecutable.path,
                ["--request-terminate-pid", String(probe.processIdentifier)])
            Thread.sleep(forTimeInterval: 0.2)
            check("updater15-appkit-terminate-refuses-foreign-executable",
                  request.status != 0 && probe.isRunning
                    && FileManager.default.fileExists(atPath: ready.path)
                    && !FileManager.default.fileExists(atPath: terminated.path),
                  "request \(request.status) running \(probe.isRunning) ready \(FileManager.default.fileExists(atPath: ready.path)) terminated \(FileManager.default.fileExists(atPath: terminated.path)) output \(request.output)")
        } catch {
            check("updater15-appkit-terminate-refuses-foreign-executable", false,
                  "fixture error \(error)")
        }

        do {
            let tempDownload = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("owned-download-\(UUID().uuidString)")
            try Data("download".utf8).write(to: tempDownload)
            var existedInsideScope = false
            MainActor.assumeIsolated {
                UpdateChecker.consumeTemporaryDownload(tempDownload) { ownedURL in
                    existedInsideScope = FileManager.default.fileExists(
                        atPath: ownedURL.path)
                }
            }
            check("updater13-temporary-download-scope-cleans-up",
                  existedInsideScope
                    && !FileManager.default.fileExists(atPath: tempDownload.path))
        } catch {
            check("updater13-temporary-download-scope-cleans-up", false,
                  "fixture error \(error)")
        }

        // Exercise the exact production shell against a real ad-hoc signed app
        // in a disposable DMG. A live sentinel models AppDelegate's delayed
        // termination: no mount/swap may start until the old PID is gone.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-valid-\(UUID().uuidString)")
            defer { try? FileManager.default.removeItem(at: root) }
            let installed = root.appendingPathComponent("installed/Snippr.app")
            try makeUpdaterInstalledFixture(at: installed, marker: "old")
            if var fixture = makeUpdaterDMGFixture(at: root, tamperAfterSigning: false) {
                let attemptDirectory = root.appendingPathComponent("private-attempt")
                try FileManager.default.createDirectory(
                    at: attemptDirectory, withIntermediateDirectories: false,
                    attributes: [.posixPermissions: 0o700])
                let privateDMG = attemptDirectory.appendingPathComponent("SnipprUpdate.dmg")
                try FileManager.default.moveItem(at: fixture.url, to: privateDMG)
                fixture = UpdaterDMGFixture(
                    url: privateDMG, volumeName: fixture.volumeName,
                    designatedRequirement: fixture.designatedRequirement)
                defer { cleanupUpdaterDMGFixture(fixture) }
                let log = root.appendingPathComponent("update.log")
                let sentinel = Process()
                sentinel.executableURL = URL(fileURLWithPath: "/bin/sleep")
                sentinel.arguments = ["2"]
                try sentinel.run()
                let activationStub = root.appendingPathComponent("activation-after-old-exit.sh")
                try makeUpdaterExecutable(
                    at: activationStub,
                    contents: "#!/bin/sh\nif /bin/kill -0 \(sentinel.processIdentifier) 2>/dev/null; then exit 74; fi\nexec /bin/mv \"$1\" \"$2\"\n")
                defer {
                    if sentinel.isRunning { sentinel.terminate() }
                    sentinel.waitUntilExit()
                }
                let started = Date()
                let result = runUpdaterInstaller(
                    fixture, installed: installed, log: log,
                    oldPID: sentinel.processIdentifier, waitTimeout: 5,
                    activationTool: activationStub.path,
                    attemptDirectory: attemptDirectory.path)
                let elapsed = Date().timeIntervalSince(started)
                let waitedForOldProcess = !sentinel.isRunning && elapsed >= 1.5
                let marker = updaterFixtureMarker(at: installed) ?? "missing"
                let logText = (try? String(contentsOf: log, encoding: .utf8)) ?? ""
                let cleanSwap = updaterFixtureIsClean(fixture, installed: installed)
                check("updater13-valid-signed-candidate-installs",
                      result.status == 0 && marker == "new" && cleanSwap
                        && waitedForOldProcess
                        && !FileManager.default.fileExists(atPath: attemptDirectory.path)
                        && logText.contains("WAIT stage=old-process")
                        && logText.contains("READY stage=old-process")
                        && logText.contains("SUCCESS version=1.2.3"),
                      "status \(result.status) marker \(marker) clean \(cleanSwap) waited \(waitedForOldProcess) elapsed \(elapsed) log \(logText) output \(result.output)")
            } else {
                check("updater13-valid-signed-candidate-installs", false,
                      "could not create signed DMG fixture")
            }
        } catch {
            check("updater13-valid-signed-candidate-installs", false,
                  "fixture error \(error)")
        }

        // A persistent log is best-effort diagnostics. An unwritable log path
        // must not suppress hash/signature/swap/relaunch commands.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-no-log-\(UUID().uuidString)")
            defer { try? FileManager.default.removeItem(at: root) }
            let installed = root.appendingPathComponent("installed/Snippr.app")
            try makeUpdaterInstalledFixture(at: installed, marker: "old")
            let logDirectory = root.appendingPathComponent("unwritable-log")
            try FileManager.default.createDirectory(
                at: logDirectory, withIntermediateDirectories: true)
            try FileManager.default.setAttributes(
                [.posixPermissions: 0o500], ofItemAtPath: logDirectory.path)
            defer {
                try? FileManager.default.setAttributes(
                    [.posixPermissions: 0o700], ofItemAtPath: logDirectory.path)
            }
            let openStub = root.appendingPathComponent("open-succeeds.sh")
            let healthFile = root.appendingPathComponent("status.txt")
            try makeUpdaterHealthyOpenStub(
                at: openStub, healthFile: healthFile,
                touchFile: root.appendingPathComponent("opened"))
            if let fixture = makeUpdaterDMGFixture(at: root, tamperAfterSigning: false) {
                defer { cleanupUpdaterDMGFixture(fixture) }
                let log = logDirectory.appendingPathComponent("update.log")
                let result = runUpdaterInstaller(
                    fixture, installed: installed, log: log,
                    relaunch: true, openTool: openStub.path,
                    healthFile: healthFile.path)
                let marker = updaterFixtureMarker(at: installed) ?? "missing"
                let opened = FileManager.default.fileExists(
                    atPath: root.appendingPathComponent("opened").path)
                check("updater13-unwritable-log-does-not-block-install",
                      result.status == 0 && marker == "new" && opened
                        && updaterFixtureIsClean(fixture, installed: installed),
                      "status \(result.status) marker \(marker) opened \(opened) output \(result.output)")
            } else {
                check("updater13-unwritable-log-does-not-block-install", false,
                      "could not create signed DMG fixture")
            }
        } catch {
            check("updater13-unwritable-log-does-not-block-install", false,
                  "fixture error \(error)")
        }

        // A still-running old process past the bounded wait must abort before
        // attaching the DMG or moving either installed-app path.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-wait-timeout-\(UUID().uuidString)")
            defer { try? FileManager.default.removeItem(at: root) }
            let installed = root.appendingPathComponent("installed/Snippr.app")
            try makeUpdaterInstalledFixture(at: installed, marker: "old")
            if let fixture = makeUpdaterDMGFixture(at: root, tamperAfterSigning: false) {
                defer { cleanupUpdaterDMGFixture(fixture) }
                let log = root.appendingPathComponent("update.log")
                let sentinel = Process()
                sentinel.executableURL = URL(fileURLWithPath: "/bin/sleep")
                sentinel.arguments = ["5"]
                try sentinel.run()
                let result = runUpdaterInstaller(
                    fixture, installed: installed, log: log,
                    oldPID: sentinel.processIdentifier, waitTimeout: 1)
                if sentinel.isRunning { sentinel.terminate() }
                sentinel.waitUntilExit()
                let marker = updaterFixtureMarker(at: installed) ?? "missing"
                let logText = (try? String(contentsOf: log, encoding: .utf8)) ?? ""
                check("updater13-old-process-timeout-preserves-old",
                      result.status != 0 && marker == "old"
                        && updaterFixtureIsClean(fixture, installed: installed)
                        && logText.contains("FAIL stage=wait-old-process"),
                      "status \(result.status) marker \(marker) log \(logText)")
            } else {
                check("updater13-old-process-timeout-preserves-old", false,
                      "could not create signed DMG fixture")
            }
        } catch {
            check("updater13-old-process-timeout-preserves-old", false,
                  "fixture error \(error)")
        }

        // The detached shell re-hashes the exact DMG it will mount. A wrong
        // expected digest must therefore fail even if all bundle checks pass.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-hash-\(UUID().uuidString)")
            defer { try? FileManager.default.removeItem(at: root) }
            let installed = root.appendingPathComponent("installed/Snippr.app")
            try makeUpdaterInstalledFixture(at: installed, marker: "old")
            if let fixture = makeUpdaterDMGFixture(at: root, tamperAfterSigning: false) {
                defer { cleanupUpdaterDMGFixture(fixture) }
                let log = root.appendingPathComponent("update.log")
                let result = runUpdaterInstaller(
                    fixture, installed: installed, log: log,
                    expectedSHA: String(repeating: "0", count: 64))
                let marker = updaterFixtureMarker(at: installed) ?? "missing"
                let logText = (try? String(contentsOf: log, encoding: .utf8)) ?? ""
                check("updater13-dmg-hash-mismatch-preserves-old",
                      result.status != 0 && marker == "old"
                        && updaterFixtureIsClean(fixture, installed: installed)
                        && logText.contains("FAIL stage=hash"),
                      "status \(result.status) marker \(marker) log \(logText)")
            } else {
                check("updater13-dmg-hash-mismatch-preserves-old", false,
                      "could not create signed DMG fixture")
            }
        } catch {
            check("updater13-dmg-hash-mismatch-preserves-old", false,
                  "fixture error \(error)")
        }

        // A candidate modified after signing must never replace the old app.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-tampered-\(UUID().uuidString)")
            defer { try? FileManager.default.removeItem(at: root) }
            let installed = root.appendingPathComponent("installed/Snippr.app")
            try makeUpdaterInstalledFixture(at: installed, marker: "old")
            if let fixture = makeUpdaterDMGFixture(at: root, tamperAfterSigning: true) {
                defer { cleanupUpdaterDMGFixture(fixture) }
                let log = root.appendingPathComponent("update.log")
                let result = runUpdaterInstaller(fixture, installed: installed, log: log)
                let marker = updaterFixtureMarker(at: installed) ?? "missing"
                let logText = (try? String(contentsOf: log, encoding: .utf8)) ?? ""
                let preserved = result.status != 0 && marker == "old"
                    && updaterFixtureIsClean(fixture, installed: installed)
                    && logText.contains("FAIL stage=verify-staged-copy")
                check("updater13-tampered-candidate-preserves-old",
                      preserved,
                      "status \(result.status) marker \(marker) log \(logText) output \(result.output)")
            } else {
                check("updater13-tampered-candidate-preserves-old", false,
                      "could not create tampered DMG fixture")
            }
        } catch {
            check("updater13-tampered-candidate-preserves-old", false,
                  "fixture error \(error)")
        }

        // A structurally valid ad-hoc signature is not sufficient: the bundle
        // must also carry Snippr's exact identifier requirement.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-wrong-id-\(UUID().uuidString)")
            defer { try? FileManager.default.removeItem(at: root) }
            let installed = root.appendingPathComponent("installed/Snippr.app")
            try makeUpdaterInstalledFixture(at: installed, marker: "old")
            if let fixture = makeUpdaterDMGFixture(
                at: root,
                tamperAfterSigning: false,
                bundleIdentifier: "com.example.not-snippr"
            ) {
                defer { cleanupUpdaterDMGFixture(fixture) }
                let log = root.appendingPathComponent("update.log")
                let result = runUpdaterInstaller(
                    fixture, installed: installed, log: log,
                    signatureRequirement: "identifier \"com.manhhoang.snippr\"")
                let marker = updaterFixtureMarker(at: installed) ?? "missing"
                let logText = (try? String(contentsOf: log, encoding: .utf8)) ?? ""
                check("updater13-wrong-bundle-identifier-preserves-old",
                      result.status != 0 && marker == "old"
                        && updaterFixtureIsClean(fixture, installed: installed)
                        && logText.contains("FAIL stage=verify-staged-copy"),
                      "status \(result.status) marker \(marker) log \(logText)")
            } else {
                check("updater13-wrong-bundle-identifier-preserves-old", false,
                      "could not create wrong-identifier DMG fixture")
            }
        } catch {
            check("updater13-wrong-bundle-identifier-preserves-old", false,
                  "fixture error \(error)")
        }

        // A valid signature with the correct bundle identifier but a
        // DIFFERENT signer must also be rejected. That is the exact boundary
        // macOS TCC uses to decide whether an update is still the same app.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-wrong-signer-\(UUID().uuidString)")
            defer { try? FileManager.default.removeItem(at: root) }
            let installed = root.appendingPathComponent("installed/Snippr.app")
            try makeUpdaterInstalledFixture(at: installed, marker: "old")
            let candidateRoot = root.appendingPathComponent("candidate")
            let otherSignerRoot = root.appendingPathComponent("other-signer")
            if let candidate = makeUpdaterDMGFixture(
                at: candidateRoot, tamperAfterSigning: false, marker: "new"),
               let otherSigner = makeUpdaterDMGFixture(
                at: otherSignerRoot, tamperAfterSigning: false, marker: "other") {
                defer {
                    cleanupUpdaterDMGFixture(candidate)
                    cleanupUpdaterDMGFixture(otherSigner)
                }
                let log = root.appendingPathComponent("update.log")
                let result = runUpdaterInstaller(
                    candidate, installed: installed, log: log,
                    signatureRequirement: otherSigner.designatedRequirement)
                let marker = updaterFixtureMarker(at: installed) ?? "missing"
                let logText = (try? String(contentsOf: log, encoding: .utf8)) ?? ""
                check("updater14-wrong-release-signer-preserves-old",
                      candidate.designatedRequirement != otherSigner.designatedRequirement
                        && result.status != 0 && marker == "old"
                        && updaterFixtureIsClean(candidate, installed: installed)
                        && logText.contains("FAIL stage=verify-staged-copy"),
                      "status \(result.status) marker \(marker) candidate \(candidate.designatedRequirement) other \(otherSigner.designatedRequirement) log \(logText)")
            } else {
                check("updater14-wrong-release-signer-preserves-old", false,
                      "could not create different-signer fixtures")
            }
        } catch {
            check("updater14-wrong-release-signer-preserves-old", false,
                  "fixture error \(error)")
        }

        // A validly signed bundle with the wrong marketing version is a
        // release-packaging error and must fail before replacing the old app.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-version-\(UUID().uuidString)")
            defer { try? FileManager.default.removeItem(at: root) }
            let installed = root.appendingPathComponent("installed/Snippr.app")
            try makeUpdaterInstalledFixture(at: installed, marker: "old")
            if let fixture = makeUpdaterDMGFixture(at: root, tamperAfterSigning: false) {
                defer { cleanupUpdaterDMGFixture(fixture) }
                let log = root.appendingPathComponent("update.log")
                let result = runUpdaterInstaller(
                    fixture, installed: installed, log: log,
                    expectedVersion: "9.9.9")
                let marker = updaterFixtureMarker(at: installed) ?? "missing"
                let logText = (try? String(contentsOf: log, encoding: .utf8)) ?? ""
                check("updater13-version-mismatch-preserves-old",
                      result.status != 0 && marker == "old"
                        && updaterFixtureIsClean(fixture, installed: installed)
                        && logText.contains("FAIL stage=version"),
                      "status \(result.status) marker \(marker) log \(logText)")
            } else {
                check("updater13-version-mismatch-preserves-old", false,
                      "could not create version-mismatch fixture")
            }
        } catch {
            check("updater13-version-mismatch-preserves-old", false,
                  "fixture error \(error)")
        }

        // If a prior interruption left only APP.old, recover it before any
        // cleanup. A forced post-backup activation failure must restore it.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-activation-\(UUID().uuidString)")
            defer { try? FileManager.default.removeItem(at: root) }
            let installed = root.appendingPathComponent("installed/Snippr.app")
            let staleBackup = URL(fileURLWithPath: installed.path + ".old")
            try makeUpdaterInstalledFixture(at: staleBackup, marker: "old")
            let activationStub = root.appendingPathComponent("activation-fails.sh")
            try makeUpdaterExecutable(
                at: activationStub,
                contents: "#!/bin/sh\nexit 71\n")
            if let fixture = makeUpdaterDMGFixture(at: root, tamperAfterSigning: false) {
                defer { cleanupUpdaterDMGFixture(fixture) }
                let log = root.appendingPathComponent("update.log")
                let result = runUpdaterInstaller(
                    fixture, installed: installed, log: log,
                    activationTool: activationStub.path)
                let marker = updaterFixtureMarker(at: installed) ?? "missing"
                let logText = (try? String(contentsOf: log, encoding: .utf8)) ?? ""
                check("updater13-activation-failure-restores-stale-backup",
                      result.status != 0 && marker == "old"
                        && updaterFixtureIsClean(fixture, installed: installed)
                        && logText.contains("FAIL stage=activate"),
                      "status \(result.status) marker \(marker) log \(logText)")
            } else {
                check("updater13-activation-failure-restores-stale-backup", false,
                      "could not create signed DMG fixture")
            }
        } catch {
            check("updater13-activation-failure-restores-stale-backup", false,
                  "fixture error \(error)")
        }

        // A termination signal delivered after APP was journaled to APP.old
        // must run the same rollback path rather than leave the canonical app
        // missing. The activation stub signals its parent shell deterministically.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-signal-\(UUID().uuidString)")
            defer { try? FileManager.default.removeItem(at: root) }
            let installed = root.appendingPathComponent("installed/Snippr.app")
            try makeUpdaterInstalledFixture(at: installed, marker: "old")
            let activationStub = root.appendingPathComponent("activation-signals.sh")
            try makeUpdaterExecutable(
                at: activationStub,
                contents: "#!/bin/sh\n/bin/mv \"$1\" \"$2\" || exit 72\n/bin/kill -TERM \"$PPID\"\n/bin/sleep 1\nexit 0\n")
            if let fixture = makeUpdaterDMGFixture(at: root, tamperAfterSigning: false) {
                defer { cleanupUpdaterDMGFixture(fixture) }
                let log = root.appendingPathComponent("update.log")
                let result = runUpdaterInstaller(
                    fixture, installed: installed, log: log,
                    activationTool: activationStub.path)
                let marker = updaterFixtureMarker(at: installed) ?? "missing"
                let logText = (try? String(contentsOf: log, encoding: .utf8)) ?? ""
                check("updater13-signal-after-backup-restores-old",
                      result.status != 0 && marker == "old"
                        && updaterFixtureIsClean(fixture, installed: installed)
                        && logText.contains("FAIL stage=signal-term"),
                      "status \(result.status) marker \(marker) log \(logText)")
            } else {
                check("updater13-signal-after-backup-restores-old", false,
                      "could not create signed DMG fixture")
            }
        } catch {
            check("updater13-signal-after-backup-restores-old", false,
                  "fixture error \(error)")
        }

        // LaunchServices refusal is a failed update outcome: it must not be
        // logged as SUCCESS, and the journaled old app must be restored.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-relaunch-\(UUID().uuidString)")
            defer { try? FileManager.default.removeItem(at: root) }
            let installed = root.appendingPathComponent("installed/Snippr.app")
            try makeUpdaterInstalledFixture(at: installed, marker: "old")
            let openStub = root.appendingPathComponent("open-fails.sh")
            try makeUpdaterExecutable(
                at: openStub,
                contents: "#!/bin/sh\necho relaunch-stub-error >&2\nexit 23\n")
            if let fixture = makeUpdaterDMGFixture(at: root, tamperAfterSigning: false) {
                defer { cleanupUpdaterDMGFixture(fixture) }
                let log = root.appendingPathComponent("update.log")
                let result = runUpdaterInstaller(
                    fixture, installed: installed, log: log,
                    relaunch: true, openTool: openStub.path)
                let marker = updaterFixtureMarker(at: installed) ?? "missing"
                let logText = (try? String(contentsOf: log, encoding: .utf8)) ?? ""
                check("updater13-relaunch-failure-rolls-back",
                      result.status != 0 && marker == "old"
                        && updaterFixtureIsClean(fixture, installed: installed)
                        && logText.contains("relaunch-stub-error")
                        && logText.contains("FAIL stage=relaunch")
                        && !logText.contains("SUCCESS"),
                      "status \(result.status) marker \(marker) log \(logText)")
            } else {
                check("updater13-relaunch-failure-rolls-back", false,
                      "could not create signed DMG fixture")
            }
        } catch {
            check("updater13-relaunch-failure-rolls-back", false,
                  "fixture error \(error)")
        }

        // LaunchServices accepting an `open` request is not proof that the
        // candidate survived startup. Without a fresh exact-path breadcrumb,
        // the old bundle must remain as the rollback journal and be restored.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-launch-health-\(UUID().uuidString)")
            defer { try? FileManager.default.removeItem(at: root) }
            let installed = root.appendingPathComponent("installed/Snippr.app")
            try makeUpdaterInstalledFixture(at: installed, marker: "old")
            let openStub = root.appendingPathComponent("open-accepts-but-no-health.sh")
            try makeUpdaterExecutable(at: openStub, contents: "#!/bin/sh\nexit 0\n")
            if let fixture = makeUpdaterDMGFixture(at: root, tamperAfterSigning: false) {
                defer { cleanupUpdaterDMGFixture(fixture) }
                let log = root.appendingPathComponent("update.log")
                let healthFile = root.appendingPathComponent("status.txt")
                let result = runUpdaterInstaller(
                    fixture, installed: installed, log: log,
                    relaunch: true, openTool: openStub.path,
                    healthFile: healthFile.path, healthTimeout: 1)
                let marker = updaterFixtureMarker(at: installed) ?? "missing"
                let logText = (try? String(contentsOf: log, encoding: .utf8)) ?? ""
                check("updater14-launch-health-required-before-commit",
                      result.status != 0 && marker == "old"
                        && updaterFixtureIsClean(fixture, installed: installed)
                        && logText.contains("FAIL stage=health")
                        && !logText.contains("SUCCESS"),
                      "status \(result.status) marker \(marker) log \(logText)")
            } else {
                check("updater14-launch-health-required-before-commit", false,
                      "could not create signed DMG fixture")
            }
        } catch {
            check("updater14-launch-health-required-before-commit", false,
                  "fixture error \(error)")
        }

        // Breadcrumb text is not process identity. A foreign live PID with
        // the right claimed version/build/executable must not commit the swap
        // or cause that unrelated process to be stopped during rollback.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-forged-health-\(UUID().uuidString)")
            defer { try? FileManager.default.removeItem(at: root) }
            let installed = root.appendingPathComponent("installed/Snippr.app")
            try makeUpdaterInstalledFixture(at: installed, marker: "old")
            let callFile = root.appendingPathComponent("open-called")
            let foreignPIDFile = root.appendingPathComponent("foreign.pid")
            let reopenedFile = root.appendingPathComponent("old-reopened")
            let healthFile = root.appendingPathComponent("status.txt")
            let openStub = root.appendingPathComponent("open-forges-health.sh")
            try makeUpdaterExecutable(
                at: openStub,
                contents: """
                    #!/bin/sh
                    APP="${2:-$1}"
                    if [ ! -e "\(callFile.path)" ]; then
                      /usr/bin/touch "\(callFile.path)"
                      /bin/sleep 30 &
                      PID=$!
                      /usr/bin/printf '%s\n' "$PID" > "\(foreignPIDFile.path)"
                      /usr/bin/printf 'pid=%s\\nversion=1.2.3\\nbuild=18\\nexecutable=%s\\n' "$PID" "$APP/Contents/MacOS/Snippr" > "\(healthFile.path)"
                    else
                      /usr/bin/touch "\(reopenedFile.path)"
                    fi
                    exit 0
                    """)
            if let fixture = makeUpdaterDMGFixture(
                at: root, tamperAfterSigning: false) {
                defer { cleanupUpdaterDMGFixture(fixture) }
                let log = root.appendingPathComponent("update.log")
                let result = runUpdaterInstaller(
                    fixture, installed: installed, log: log,
                    relaunch: true, openTool: openStub.path,
                    healthFile: healthFile.path, healthTimeout: 1)
                let foreignPID = (try? String(
                    contentsOf: foreignPIDFile, encoding: .utf8))
                    .flatMap { Int32($0.trimmingCharacters(
                        in: .whitespacesAndNewlines)) }
                let foreignAlive = foreignPID.map { kill($0, 0) == 0 } ?? false
                defer {
                    if let foreignPID, kill(foreignPID, 0) == 0 {
                        kill(foreignPID, SIGKILL)
                    }
                }
                let marker = updaterFixtureMarker(at: installed) ?? "missing"
                let logText = (try? String(
                    contentsOf: log, encoding: .utf8)) ?? ""
                check("updater15-forged-health-pid-rejected",
                      result.status != 0 && marker == "old" && foreignAlive
                        && FileManager.default.fileExists(atPath: reopenedFile.path)
                        && updaterFixtureIsClean(fixture, installed: installed)
                        && logText.contains("FAIL stage=health")
                        && !logText.contains("SUCCESS"),
                      "status \(result.status) marker \(marker) foreign \(String(describing: foreignPID))/\(foreignAlive) log \(logText)")
            } else {
                check("updater15-forged-health-pid-rejected", false,
                      "could not create signed DMG fixture")
            }
        } catch {
            check("updater15-forged-health-pid-rejected", false,
                  "fixture error \(error)")
        }

        // A candidate can be alive even when its best-effort launch breadcrumb
        // was never written. Never swap the old bundle back underneath that
        // process: terminate the exact activated executable first.
        if let stopped = runUpdaterCandidateStopFixture(
            in: URL(fileURLWithPath: outputDir), mode: .polite) {
            check("updater15-live-no-health-stops-before-restore",
                  stopped.status != 0 && stopped.installedMarker == "old"
                    && stopped.oldMarker == nil && !stopped.candidateAlive
                    && stopped.canonicalOpenCount == 2
                    && stopped.reopenedOld && stopped.transactionClean
                    && stopped.signalLog.contains("--request-terminate-pid")
                    && stopped.log.contains("STOP stage=activated-candidate")
                    && stopped.log.contains("STOPPED stage=activated-candidate")
                    && !stopped.log.contains("FORCE stage=activated-candidate"),
                  stopped.detail)
        } else {
            check("updater15-live-no-health-stops-before-restore", false,
                  "could not create polite candidate-stop fixture")
        }

        // If the AppKit helper itself hangs and the candidate stays alive,
        // the helper invocation must not defeat the rollback bound. Reap the
        // helper, force only the verified candidate, then restore.
        if let forced = runUpdaterCandidateStopFixture(
            in: URL(fileURLWithPath: outputDir), mode: .force) {
            check("updater15-stubborn-candidate-forced-before-restore",
                  forced.status != 0 && forced.installedMarker == "old"
                    && forced.oldMarker == nil && !forced.candidateAlive
                    && forced.gracefulHelperStarted
                    // The translated x86_64 process pays Rosetta startup
                    // overhead for each shell/tool child. Keep this fixture
                    // bounded while allowing the same transaction to run on
                    // both native arm64 (<10 s observed) and Rosetta.
                    && !forced.gracefulHelperAlive && forced.elapsed < 15
                    && forced.canonicalOpenCount == 2
                    && forced.reopenedOld && forced.transactionClean
                    && forced.signalLog.contains("--request-terminate-pid")
                    && forced.signalLog.contains("-KILL")
                    && forced.log.contains("FORCE stage=activated-candidate")
                    && forced.log.contains("STOPPED stage=activated-candidate"),
                  forced.detail)
        } else {
            check("updater15-stubborn-candidate-forced-before-restore", false,
                  "could not create forced candidate-stop fixture")
        }

        // If even the force step cannot stop the process, fail closed: keep
        // candidate and APP.old side-by-side instead of moving the old bundle
        // over a live process. The fixture is killed only after observation.
        if let immortal = runUpdaterCandidateStopFixture(
            in: URL(fileURLWithPath: outputDir), mode: .immortal) {
            check("updater15-unstoppable-candidate-keeps-journal",
                  immortal.status != 0 && immortal.installedMarker == "new"
                    && immortal.oldMarker == "old" && immortal.candidateAlive
                    && immortal.canonicalOpenCount == 1
                    && !immortal.reopenedOld && immortal.downloadClean
                    && immortal.signalLog.contains("--request-terminate-pid")
                    && immortal.signalLog.contains("-KILL")
                    && immortal.log.contains("FATAL stage=stop-activated-candidate")
                    && !immortal.log.contains("SUCCESS"),
                  immortal.detail)
        } else {
            check("updater15-unstoppable-candidate-keeps-journal", false,
                  "could not create unstoppable candidate fixture")
        }

        // Once launch health commits the new app, failure to delete the old
        // journal is only a cleanup warning. It must never roll back a healthy
        // candidate using a potentially partial backup.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-cleanup-warning-\(UUID().uuidString)")
            defer { try? FileManager.default.removeItem(at: root) }
            let installed = root.appendingPathComponent("installed/Snippr.app")
            try makeUpdaterInstalledFixture(at: installed, marker: "old")
            let removalStub = root.appendingPathComponent("remove-backup-fails.sh")
            try makeUpdaterExecutable(at: removalStub, contents: "#!/bin/sh\nexit 23\n")
            if let fixture = makeUpdaterDMGFixture(at: root, tamperAfterSigning: false) {
                defer { cleanupUpdaterDMGFixture(fixture) }
                let log = root.appendingPathComponent("update.log")
                let result = runUpdaterInstaller(
                    fixture, installed: installed, log: log,
                    removalTool: removalStub.path)
                let marker = updaterFixtureMarker(at: installed) ?? "missing"
                let oldMarker = updaterFixtureMarker(
                    at: URL(fileURLWithPath: installed.path + ".old")) ?? "missing"
                let logText = (try? String(contentsOf: log, encoding: .utf8)) ?? ""
                let transactionClean = !FileManager.default.fileExists(
                    atPath: installed.path + ".new")
                    && !FileManager.default.fileExists(atPath: fixture.url.path)
                    && !FileManager.default.fileExists(
                        atPath: "/Volumes/\(fixture.volumeName)")
                check("updater14-backup-cleanup-failure-keeps-new",
                      result.status == 0 && marker == "new" && oldMarker == "old"
                        && transactionClean
                        && logText.contains("WARN stage=remove-backup")
                        && logText.contains("SUCCESS"),
                      "status \(result.status) marker \(marker) old \(oldMarker) clean \(transactionClean) log \(logText)")
            } else {
                check("updater14-backup-cleanup-failure-keeps-new", false,
                      "could not create signed DMG fixture")
            }
        } catch {
            check("updater14-backup-cleanup-failure-keeps-new", false,
                  "fixture error \(error)")
        }

        // If an activated candidate cannot be removed, never move APP.old into
        // the still-existing bundle and falsely report rollback success.
        do {
            let root = URL(fileURLWithPath: outputDir)
                .appendingPathComponent("updater-restore-rm-\(UUID().uuidString)")
            defer { try? FileManager.default.removeItem(at: root) }
            let installed = root.appendingPathComponent("installed/Snippr.app")
            try makeUpdaterInstalledFixture(at: installed, marker: "old")
            defer {
                _ = runCommand("/usr/bin/chflags", ["-R", "nouchg", installed.path])
                _ = runCommand(
                    "/usr/bin/chflags", ["-R", "nouchg", installed.path + ".old"])
            }
            let activationStub = root.appendingPathComponent("activation-immutable.sh")
            try makeUpdaterExecutable(
                at: activationStub,
                contents: "#!/bin/sh\n/bin/mv \"$1\" \"$2\" || exit 72\n/usr/bin/chflags -R uchg \"$2\" || exit 73\n")
            let openStub = root.appendingPathComponent("open-fails.sh")
            try makeUpdaterExecutable(at: openStub, contents: "#!/bin/sh\nexit 23\n")
            if let fixture = makeUpdaterDMGFixture(at: root, tamperAfterSigning: false) {
                defer { cleanupUpdaterDMGFixture(fixture) }
                let log = root.appendingPathComponent("update.log")
                let result = runUpdaterInstaller(
                    fixture, installed: installed, log: log,
                    relaunch: true, openTool: openStub.path,
                    activationTool: activationStub.path)
                let newMarker = updaterFixtureMarker(at: installed) ?? "missing"
                let oldMarker = updaterFixtureMarker(
                    at: URL(fileURLWithPath: installed.path + ".old")) ?? "missing"
                let nestedBackup = installed.appendingPathComponent("Snippr.app.old")
                let logText = (try? String(contentsOf: log, encoding: .utf8)) ?? ""
                let detachedAndDownloadedClean = !FileManager.default.fileExists(
                    atPath: fixture.url.path)
                    && !FileManager.default.fileExists(
                        atPath: "/Volumes/\(fixture.volumeName)")
                    && !FileManager.default.fileExists(atPath: installed.path + ".new")
                check("updater13-restore-removal-failure-keeps-journal",
                      result.status != 0 && newMarker == "new" && oldMarker == "old"
                        && !FileManager.default.fileExists(atPath: nestedBackup.path)
                        && detachedAndDownloadedClean
                        && logText.contains("FATAL stage=restore"),
                      "status \(result.status) new \(newMarker) old \(oldMarker) clean \(detachedAndDownloadedClean) log \(logText)")
            } else {
                check("updater13-restore-removal-failure-keeps-journal", false,
                      "could not create signed DMG fixture")
            }
        } catch {
            check("updater13-restore-removal-failure-keeps-journal", false,
                  "fixture error \(error)")
        }

        // 1. Annotation rendering ------------------------------------------------
        let base = makeTestImage(width: 1600, height: 1200)
        let scale: CGFloat = 2
        var annotations: [Annotation] = []

        let arrow = ShapeAnnotation(kind: .arrow, start: CGPoint(x: 200, y: 200), end: CGPoint(x: 700, y: 500), uiScale: scale)
        arrow.color = .systemRed
        annotations.append(arrow)

        let rect = ShapeAnnotation(kind: .rect, start: CGPoint(x: 800, y: 700), end: CGPoint(x: 1300, y: 1000), uiScale: scale)
        rect.color = .systemBlue
        annotations.append(rect)

        let oval = ShapeAnnotation(kind: .oval, start: CGPoint(x: 150, y: 700), end: CGPoint(x: 500, y: 950), uiScale: scale)
        oval.color = .systemGreen
        annotations.append(oval)

        let highlight = ShapeAnnotation(kind: .highlight, start: CGPoint(x: 600, y: 100), end: CGPoint(x: 1100, y: 220), uiScale: scale)
        highlight.color = .systemYellow
        annotations.append(highlight)

        let pen = PenAnnotation(uiScale: scale)
        pen.color = .systemOrange
        pen.points = stride(from: 0.0, to: 400.0, by: 8).map {
            CGPoint(x: 900 + $0, y: 350 + sin($0 / 40) * 60)
        }
        annotations.append(pen)

        let text = TextAnnotation(uiScale: scale)
        text.text = "Hello Snippr"
        text.origin = CGPoint(x: 250, y: 1050)
        text.color = .white
        annotations.append(text)

        for (i, pt) in [CGPoint(x: 120, y: 420), CGPoint(x: 120, y: 320)].enumerated() {
            let counter = CounterAnnotation(uiScale: scale)
            counter.center = pt
            counter.number = i + 1
            counter.color = .systemRed
            annotations.append(counter)
        }

        let blur = BlurAnnotation(uiScale: scale)
        blur.rect = CGRect(x: 1200, y: 150, width: 300, height: 200)
        annotations.append(blur)

        let pixellated = AnnotationRenderer.pixellate(base, scale: scale)
        check("pixellate", pixellated != nil)

        let rendered = AnnotationRenderer.render(base: base, annotations: annotations, pixellated: pixellated)
        check("annotation-render-size", rendered.width == base.width && rendered.height == base.height)
        check("annotation-render-changed", !imagesEqual(base, rendered))
        writePNG(rendered, to: "\(outputDir)/annotations.png")

        // 2. Stitcher --------------------------------------------------------------
        let tall = makeStripePattern(width: 400, height: 2000)
        let viewport = 500
        var offsets: [Int] = []
        var o = 0
        while o < 2000 - viewport {
            offsets.append(o)
            o += 320
        }
        offsets.append(2000 - viewport) // final clamped frame

        var stitcher: VerticalStitcher?
        for off in offsets {
            guard let frame = tall.cropping(to: CGRect(x: 0, y: off, width: 400, height: viewport)) else {
                check("stitch-crop", false); break
            }
            if let s = stitcher {
                _ = s.append(frame)
            } else {
                stitcher = VerticalStitcher(first: frame)
            }
        }
        let composed = stitcher?.compose()
        check("stitch-height", composed?.height == 2000, "got \(composed?.height ?? -1), want 2000")
        if let composed {
            check("stitch-content", imagesRoughlyEqual(tall, composed), "stitched content mismatch")
            writePNG(composed, to: "\(outputDir)/stitched.png")
        }

        // 2b. Self-similar content must be REJECTED, not guessed -------------------
        // (repetitive chat-like UI used to produce duplicated blocks and
        // corrupted seams — the matcher now requires a unique best offset)
        let periodic = makePeriodicPattern(width: 400, height: 1000, period: 40)
        if let f0 = periodic.cropping(to: CGRect(x: 0, y: 0, width: 400, height: 500)),
           let f1 = periodic.cropping(to: CGRect(x: 0, y: 100, width: 400, height: 500)) {
            let s2 = VerticalStitcher(first: f0)
            let appended = s2.append(f1).newRows
            check("stitch-ambiguous-rejected", appended == 0,
                  "appended \(appended) rows from ambiguous content")
        } else {
            check("stitch-ambiguous-crop", false)
        }

        // 2b-up. Bottom-to-top capture ---------------------------------------------
        // Scrolling upward reveals new content at the TOP of the viewport. The
        // matcher finds the reversed overlap and the stitcher prepends, so a
        // session that starts at the end of a page still produces the full page.
        do {
            let doc = makeStripePattern(width: 400, height: 2000, seed: 0xB1D1_5EED)
            let vp = 500
            var upOffsets: [Int] = []
            var position = 2000 - vp
            while position > 0 {
                upOffsets.append(position)
                position -= 320
            }
            upOffsets.append(0)
            var up: VerticalStitcher?
            var prepends = 0
            var rejects = 0
            for off in upOffsets {
                guard let frame = doc.cropping(to: CGRect(
                    x: 0, y: off, width: 400, height: vp)) else {
                    check("stitch-upscroll-crop", false); break
                }
                if let s = up {
                    switch s.append(frame) {
                    case .prepended: prepends += 1
                    case .rejected: rejects += 1
                    default: break
                    }
                } else {
                    up = VerticalStitcher(first: frame)
                }
            }
            let upComposed = up?.compose()
            check("stitch-upscroll-height", upComposed?.height == 2000,
                  "got \(upComposed?.height ?? -1), want 2000")
            check("stitch-upscroll-all-prepended",
                  prepends == upOffsets.count - 1 && rejects == 0,
                  "prepends \(prepends)/\(upOffsets.count - 1), rejects \(rejects)")
            if let upComposed {
                check("stitch-upscroll-content", imagesRoughlyEqual(doc, upComposed),
                      "up-scrolled content mismatch")
                writePNG(upComposed, to: "\(outputDir)/stitched-upscroll.png")
            }
        }

        // 2b-retrace. Reversing over already-captured rows -------------------------
        // Scrolling back up to re-read (then continuing down) used to reject
        // every reversed frame until the session dead-locked into a new segment
        // full of duplicates. A reversal over captured content must be a
        // confirmed `moved`, never a reject, and must not duplicate rows.
        do {
            let doc = makeStripePattern(width: 400, height: 2000, seed: 0x0FF5_E70D)
            let vp = 500
            let path = [0, 320, 640, 320, 80, 400, 720, 1040, 1360, 1500]
            var s: VerticalStitcher?
            var rejects = 0
            var moves = 0
            for off in path {
                guard let frame = doc.cropping(to: CGRect(
                    x: 0, y: off, width: 400, height: vp)) else {
                    check("stitch-retrace-crop", false); break
                }
                if let st = s {
                    switch st.append(frame) {
                    case .rejected: rejects += 1
                    case .moved: moves += 1
                    default: break
                    }
                } else {
                    s = VerticalStitcher(first: frame)
                }
            }
            let composed = s?.compose()
            check("stitch-retrace-height", composed?.height == 2000,
                  "got \(composed?.height ?? -1), want 2000")
            check("stitch-retrace-no-rejects", rejects == 0 && moves == 3,
                  "rejects \(rejects), moves \(moves) (want 0 and 3)")
            if let composed {
                check("stitch-retrace-content", imagesRoughlyEqual(doc, composed),
                      "retraced content mismatch")
            }
        }

        // 2b-mixed. Start mid-page, scroll up first, then down past the start ------
        do {
            let doc = makeStripePattern(width: 400, height: 2000, seed: 0x001A_ED00)
            let vp = 500
            let path = [800, 480, 160, 480, 800, 1120, 1440]
            var s: VerticalStitcher?
            var rejects = 0
            var prepends = 0
            var appends = 0
            for off in path {
                guard let frame = doc.cropping(to: CGRect(
                    x: 0, y: off, width: 400, height: vp)) else {
                    check("stitch-mixed-crop", false); break
                }
                if let st = s {
                    switch st.append(frame) {
                    case .rejected: rejects += 1
                    case .prepended: prepends += 1
                    case .appended: appends += 1
                    default: break
                    }
                } else {
                    s = VerticalStitcher(first: frame)
                }
            }
            let composed = s?.compose()
            let wantHeight = (1440 + vp) - 160
            check("stitch-mixed-height", composed?.height == wantHeight,
                  "got \(composed?.height ?? -1), want \(wantHeight)")
            check("stitch-mixed-outcomes",
                  rejects == 0 && prepends == 2 && appends == 2,
                  "rejects \(rejects), prepends \(prepends), appends \(appends)")
            if let composed,
               let wantImage = doc.cropping(to: CGRect(
                x: 0, y: 160, width: 400, height: wantHeight)) {
                check("stitch-mixed-content", imagesRoughlyEqual(wantImage, composed),
                      "mixed-direction content mismatch")
            }
        }

        // 2b-header-up. Up-scroll under fixed top chrome ---------------------------
        // Prepended strips must slide UNDER the header: the composed page keeps
        // the chrome on top exactly once, never repeated mid-page.
        do {
            let hW = 400, hViewport = 500, hHeader = 40
            let doc = makeStripePattern(width: hW, height: 2000, seed: 0x4EAD_F00D)
            let chrome = makeStripePattern(width: hW, height: hHeader, seed: 0xC0FF_EE00)
            func chromedFrame(offset: Int) -> CGImage? {
                guard let body = doc.cropping(to: CGRect(
                    x: 0, y: offset + hHeader, width: hW,
                    height: hViewport - hHeader)) else { return nil }
                let c = ctx(hW, hViewport)
                c.draw(chrome, in: CGRect(
                    x: 0, y: CGFloat(hViewport - hHeader),
                    width: CGFloat(hW), height: CGFloat(hHeader)))
                c.draw(body, in: CGRect(
                    x: 0, y: 0, width: CGFloat(hW),
                    height: CGFloat(hViewport - hHeader)))
                return c.makeImage()
            }
            let path = [1000, 700, 400, 100]
            var s: VerticalStitcher?
            var prepends = 0
            var rejects = 0
            for off in path {
                guard let frame = chromedFrame(offset: off) else {
                    check("stitch-header-up-crop", false); break
                }
                if let st = s {
                    switch st.append(frame) {
                    case .prepended: prepends += 1
                    case .rejected: rejects += 1
                    default: break
                    }
                } else {
                    s = VerticalStitcher(first: frame)
                }
            }
            let composed = s?.compose()
            // chrome once + doc body from (100 + hHeader) to (1000 + hViewport)
            let wantHeight = hHeader + (1000 + hViewport) - (100 + hHeader)
            check("stitch-header-up-height", composed?.height == wantHeight,
                  "got \(composed?.height ?? -1), want \(wantHeight)")
            check("stitch-header-up-outcomes", prepends == 3 && rejects == 0,
                  "prepends \(prepends), rejects \(rejects)")
            if let composed,
               let composedTop = composed.cropping(to: CGRect(
                x: 0, y: 0, width: hW, height: hHeader)) {
                check("stitch-header-up-chrome-on-top",
                      imagesRoughlyEqual(chrome, composedTop),
                      "top of composed image is not the fixed chrome")
            }
        }

        // 2b-dup. Duplicated content blocks vs the reverse matcher -----------------
        // A block appearing twice on the page (an image posted twice, repeated
        // cards) is a near-perfect unique template hit in the WRONG direction.
        // Whole-overlap coherence must veto it — without regressing correct
        // same-direction matches on the same page.
        func withDuplicatedBlock(
            _ src: CGImage, from: Int, to: Int, rows: Int
        ) -> CGImage? {
            guard let block = src.cropping(to: CGRect(
                x: 0, y: from, width: src.width, height: rows)) else { return nil }
            let c = ctx(src.width, src.height)
            c.draw(src, in: CGRect(
                x: 0, y: 0, width: src.width, height: src.height))
            c.draw(block, in: CGRect(
                x: 0, y: src.height - to - rows,
                width: src.width, height: rows))
            return c.makeImage()
        }
        do {
            // No genuine overlap (fast down flick) + duplicated block: the up
            // direction "finds" the duplicate. Must reject, never prepend.
            if let doc = withDuplicatedBlock(
                makeStripePattern(width: 400, height: 1200, seed: 0xD0B1_0C05),
                from: 100, to: 975, rows: 125),
               let a = doc.cropping(to: CGRect(x: 0, y: 0, width: 400, height: 500)),
               let b = doc.cropping(to: CGRect(x: 0, y: 600, width: 400, height: 500)) {
                let s = VerticalStitcher(first: a)
                let result = s.append(b)
                check("stitch-dup-block-flick-rejected", result == .rejected,
                      "no-overlap flick over duplicated block got \(result)")
            } else {
                check("stitch-dup-block-flick-frames", false)
            }

            // Same duplicated-block page, frames presented in the REVERSED
            // order: the spurious hit now lands in the DOWN direction. A lone
            // down match must pass whole-overlap coherence exactly like a lone
            // up match — neither direction is exempt.
            if let doc = withDuplicatedBlock(
                makeStripePattern(width: 400, height: 1200, seed: 0xD0B1_0C05),
                from: 100, to: 975, rows: 125),
               let a = doc.cropping(to: CGRect(x: 0, y: 0, width: 400, height: 500)),
               let b = doc.cropping(to: CGRect(x: 0, y: 600, width: 400, height: 500)) {
                let s = VerticalStitcher(first: b)
                let result = s.append(a)
                check("stitch-dup-block-flick-reversed-rejected", result == .rejected,
                      "reversed no-overlap flick over duplicated block got \(result)")
            } else {
                check("stitch-dup-block-flick-reversed-frames", false)
            }

            // Healthy down overlap on a page with one duplicated block: the up
            // direction also matches (on the duplicate), but the down match is
            // whole-overlap coherent and must win — not be rejected as
            // ambiguous. (This was the old field failure mode resurfacing.)
            if let doc = withDuplicatedBlock(
                makeStripePattern(width: 400, height: 2000, seed: 0xD0B2_0C05),
                from: 625, to: 925, rows: 150),
               let a = doc.cropping(to: CGRect(x: 0, y: 300, width: 400, height: 500)),
               let b = doc.cropping(to: CGRect(x: 0, y: 550, width: 400, height: 500)) {
                let s = VerticalStitcher(first: a)
                let result = s.append(b)
                check("stitch-dup-block-down-still-appends",
                      result == .appended(rows: 250),
                      "healthy down overlap got \(result), want appended(250)")
            } else {
                check("stitch-dup-block-down-frames", false)
            }
        }

        // 2b-window. Bounded preview windows ---------------------------------------
        // The live preview refresh after a direction flip must render only the
        // visible window: at source width it is BYTE-identical to cropping the
        // full compose, the full-compose spy proves zero full composes, and a
        // wide-display source still allocates only the target-sized canvas.
        do {
            let doc = makeStripePattern(width: 400, height: 2000, seed: 0x81D0_11E4)
            let vp = 500
            let path = [800, 480, 160, 480, 800, 1120, 1440]
            var s: SegmentedVerticalStitcher?
            for off in path {
                guard let frame = doc.cropping(to: CGRect(
                    x: 0, y: off, width: 400, height: vp)) else {
                    check("stitch-window-crop", false); break
                }
                if let st = s { _ = st.append(frame) } else {
                    s = SegmentedVerticalStitcher(first: frame)
                }
            }
            if let s {
                let windowRows = 300
                let top = s.previewWindowImage(
                    targetWidth: 400, maxHeight: windowRows, anchor: .currentTop)
                let bottom = s.previewWindowImage(
                    targetWidth: 400, maxHeight: windowRows, anchor: .bottom)
                check("stitch-window-no-full-compose", s.fullComposeCount == 0,
                      "window render performed \(s.fullComposeCount) full composes")
                if let top, let bottom, let full = s.compose(),
                   let wantTop = full.cropping(to: CGRect(
                    x: 0, y: 0, width: 400, height: windowRows)),
                   let wantBottom = full.cropping(to: CGRect(
                    x: 0, y: full.height - windowRows,
                    width: 400, height: windowRows)) {
                    check("stitch-window-top-content",
                          imagesEqual(wantTop, top),
                          "top window differs from full-compose crop")
                    check("stitch-window-bottom-content",
                          imagesEqual(wantBottom, bottom),
                          "bottom window differs from full-compose crop")
                } else {
                    check("stitch-window-compose", false)
                }
            }

            // Wide display: the returned canvas must be target-sized no
            // matter the source width (the old path allocated
            // width × (1400·width/400) — ~350 MiB at width 5120).
            let wideDoc = makeStripePattern(
                width: 5120, height: 1400, seed: 0x81D0_57DE)
            if let w0 = wideDoc.cropping(to: CGRect(
                x: 0, y: 0, width: 5120, height: 500)),
               let w1 = wideDoc.cropping(to: CGRect(
                x: 0, y: 300, width: 5120, height: 500)) {
                let wide = SegmentedVerticalStitcher(first: w0)
                _ = wide.append(w1)
                if let window = wide.previewWindowImage(
                    targetWidth: 400, maxHeight: 1400, anchor: .bottom) {
                    check("stitch-window-wide-allocation-capped",
                          window.width == 400 && window.height <= 1400,
                          "got \(window.width)x\(window.height)")
                    // Fractional-scale geometry: 800 source rows at 400/5120
                    // is 62.5 — cumulative floor must yield exactly 62 (the
                    // same rule scaledForPreview uses) with no blank seam
                    // row anywhere in the window.
                    let expectedRows = Int(CGFloat(800) * 400.0 / 5120.0)
                    check("stitch-window-wide-floor-height",
                          window.height == expectedRows,
                          "got \(window.height), want \(expectedRows)")
                    var blankRow = -1
                    var bytes = [UInt8](
                        repeating: 0, count: window.width * window.height * 4)
                    if let c = CGContext(
                        data: &bytes, width: window.width, height: window.height,
                        bitsPerComponent: 8, bytesPerRow: window.width * 4,
                        space: CGColorSpace(name: CGColorSpace.sRGB)!,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) {
                        c.draw(window, in: CGRect(
                            x: 0, y: 0,
                            width: window.width, height: window.height))
                        for row in 0..<window.height {
                            var sum = 0
                            for x in 0..<window.width {
                                sum += Int(bytes[(row * window.width + x) * 4 + 3])
                            }
                            if sum == 0 { blankRow = row; break }
                        }
                    }
                    check("stitch-window-wide-no-blank-seam", blankRow == -1,
                          "blank seam at scaled row \(blankRow)")
                } else {
                    check("stitch-window-wide-render", false)
                }
            } else {
                check("stitch-window-wide-frames", false)
            }
        }

        // 2b-window-marker. Gap separator must survive a direction flip ------------
        // After a re-anchor the composed strip contains segment + separator +
        // segment; the flip preview window over that region must be
        // pixel-EXACT against the full compose, separator included.
        do {
            let doc = makeStripePattern(width: 400, height: 3000, seed: 0x5E9A_9A99)
            let vp = 500
            // 0→300: appends; flick to 1200 (no overlap) rejects and builds
            // the pending segment at 1200/1400/1600/1800; promote inserts the
            // marked gap. Then scroll back up inside segment 2 until a real
            // prepend happens.
            let path = [0, 300, 1200, 1400, 1600, 1800, 1650, 1350, 1050]
            if let first = doc.cropping(to: CGRect(
                x: 0, y: path[0], width: 400, height: vp)) {
                let segmented = SegmentedVerticalStitcher(first: first)
                var sawSegment = false
                var sawPrepend = false
                for off in path.dropFirst() {
                    guard let frame = doc.cropping(to: CGRect(
                        x: 0, y: off, width: 400, height: vp)) else {
                        check("stitch-window-marker-crop", false); break
                    }
                    switch segmented.append(frame) {
                    case .startedSegment: sawSegment = true
                    case .prepended: sawPrepend = true
                    default: break
                    }
                }
                check("stitch-window-marker-fixture",
                      sawSegment && sawPrepend && segmented.segmentCount == 2,
                      "segment \(sawSegment) prepend \(sawPrepend) count \(segmented.segmentCount)")
                // segment 1 composes to rows [0, 800); the separator starts
                // there. currentTop anchors on that separator (clamped so the
                // window still fills), bottom anchors on the composition end.
                if let full = segmented.compose() {
                    let windowRows = 1400
                    let separatorStart = 800
                    for (label, anchor, origin) in [
                        ("top", SegmentedVerticalStitcher.PreviewAnchor.currentTop,
                         min(separatorStart, full.height - windowRows)),
                        ("bottom", .bottom, full.height - windowRows),
                    ] {
                        if let window = segmented.previewWindowImage(
                            targetWidth: 400, maxHeight: windowRows, anchor: anchor),
                           let want = full.cropping(to: CGRect(
                            x: 0, y: origin, width: 400, height: windowRows)) {
                            check("stitch-window-marker-\(label)-exact",
                                  imagesEqual(want, window),
                                  "\(label) window differs from full compose (separator lost?)")
                        } else {
                            check("stitch-window-marker-\(label)-render", false)
                        }
                    }
                } else {
                    check("stitch-window-marker-compose", false)
                }
            } else {
                check("stitch-window-marker-crop", false)
            }
        }

        // 2b-window-tallseg. Anchor must follow the CURRENT segment ----------------
        // With a first segment TALLER than the preview window, a global-top
        // anchor would show only old content and the preview would look
        // frozen during upward capture. The window must start at the gap
        // separator and contain the current segment's newest prepends.
        do {
            let doc = makeStripePattern(width: 400, height: 4200, seed: 0x7A11_5E91)
            let vp = 500
            let path = [0, 300, 600, 900, 1200,
                        3000, 3200, 3400, 3600,
                        3450, 3150, 2850]
            if let first = doc.cropping(to: CGRect(
                x: 0, y: path[0], width: 400, height: vp)) {
                let segmented = SegmentedVerticalStitcher(first: first)
                var sawSegment = false
                var sawPrepend = false
                for off in path.dropFirst() {
                    guard let frame = doc.cropping(to: CGRect(
                        x: 0, y: off, width: 400, height: vp)) else {
                        check("stitch-window-tallseg-crop", false); break
                    }
                    switch segmented.append(frame) {
                    case .startedSegment: sawSegment = true
                    case .prepended: sawPrepend = true
                    default: break
                    }
                }
                let full = segmented.compose()
                check("stitch-window-tallseg-fixture",
                      sawSegment && sawPrepend && full?.height == 2962,
                      "segment \(sawSegment) prepend \(sawPrepend) height \(full?.height ?? -1)")
                let windowRows = 1400
                if let full,
                   let window = segmented.previewWindowImage(
                    targetWidth: 400, maxHeight: windowRows, anchor: .currentTop),
                   let want = full.cropping(to: CGRect(
                    // separator starts at segment-1 height 1700; window is
                    // clamped so it still fills: origin 2962-1400 = 1562,
                    // which keeps the separator AND the prepends in view.
                    x: 0, y: min(1700, full.height - windowRows),
                    width: 400, height: windowRows)) {
                    check("stitch-window-tallseg-anchored",
                          imagesEqual(want, window),
                          "tall-segment window not anchored on current segment")
                } else {
                    check("stitch-window-tallseg-render", false)
                }
            } else {
                check("stitch-window-tallseg-crop", false)
            }
        }

        // 2c-bounce-revisit. Scroll-back-to-top must never re-enter the output ----
        // The rubber-band / Home-key ending: after a long downward capture the
        // page jumps back to the top. Those frames fail the edge matcher,
        // then verify against EACH OTHER — and the pending promotion used to
        // append the page top AGAIN behind a separator (the duplicated-block
        // + phantom-stripe capture from the field report). Revisited content
        // must resolve as a retrace: no growth, no new segment. A real gap
        // (flick to unseen content) shares no captured rows and still
        // re-anchors through the pending path — covered by 2b fixtures above.
        do {
            // textured rows: real pages carry horizontal detail (text,
            // borders); the revisit ledger deliberately ignores flat rows,
            // so a solid-stripe fixture could never exercise it.
            let doc = makeTexturedStripePattern(width: 400, height: 5200, seed: 0xB0B0_57AF)
            let vp = 500
            if let first = doc.cropping(to: CGRect(
                x: 0, y: 0, width: 400, height: vp)) {
                let segmented = SegmentedVerticalStitcher(first: first)
                var walkOK = true
                var off = 0
                for step in [300, 250, 300, 250, 300, 250, 300, 250,
                             300, 250, 300, 250, 300, 250, 300, 250] {
                    off += step
                    guard let frame = doc.cropping(to: CGRect(
                            x: 0, y: off, width: 400, height: vp)),
                          case .appended = segmented.append(frame) else {
                        walkOK = false
                        break
                    }
                }
                let heightBefore = segmented.totalHeight
                let segmentsBefore = segmented.segmentCount
                var badOutcome = false
                // the bounce: settle near the top, then small drifts — enough
                // ticks to cross the re-anchor threshold twice over
                for bounceOff in [40, 40, 60, 80, 100, 120, 140, 160] {
                    guard let frame = doc.cropping(to: CGRect(
                        x: 0, y: bounceOff, width: 400, height: vp)) else {
                        badOutcome = true
                        break
                    }
                    switch segmented.append(frame) {
                    case .appended, .prepended, .startedSegment:
                        badOutcome = true
                    case .moved, .rejected:
                        break
                    }
                }
                check("scroll7-bounce-revisit",
                      walkOK && !badOutcome
                        && segmented.totalHeight == heightBefore
                        && segmented.segmentCount == segmentsBefore,
                      "walk \(walkOK) bad \(badOutcome) "
                        + "height \(segmented.totalHeight)/\(heightBefore) "
                        + "segments \(segmented.segmentCount)/\(segmentsBefore)")
            } else {
                check("scroll7-bounce-revisit", false, "crop fail")
            }
        }

        // 2d-animated-band. A side ad that changes must not re-anchor ---------------
        // Field report (VnExpress, 2026-08-15): the right-column ad creative
        // changed right after the first frame. Every later frame failed the
        // full-width matcher against frame #1 (two of four bands differed),
        // the pending strip verified against itself and was PROMOTED — the
        // page top entered the output twice behind a separator. A page whose
        // body scrolls coherently in the untouched bands must keep stitching
        // as ONE segment; a frame that differs in MORE than half the width
        // must still fail closed.
        do {
            let vp = 500, w = 400
            let doc = makeTexturedStripePattern(width: w, height: 3000, seed: 0xAD11_5EED)
            // `bands` = which quarter-width bands carry the "ad" (changes
            // between frame #1 and every later frame).
            func animatedRun(bands: Set<Int>) -> (segments: Int, height: Int, appended: Int, started: Int, ok: Bool) {
                let adA = makeTexturedStripePattern(width: w, height: vp, seed: 0xADA0_0001)
                let adB = makeTexturedStripePattern(width: w, height: vp, seed: 0xADB0_0002)
                func page(_ ad: CGImage) -> CGImage {
                    let c = ctx(w, 3000)
                    c.draw(doc, in: CGRect(x: 0, y: 0, width: w, height: 3000))
                    // rows 0..<vp of the page hold the ad in the given bands
                    for band in bands {
                        let x = band * (w / 4)
                        let rect = CGRect(x: x, y: 3000 - vp, width: w / 4, height: vp)
                        if let piece = ad.cropping(to: CGRect(x: x, y: 0, width: w / 4, height: vp)) {
                            c.draw(piece, in: rect)
                        }
                    }
                    return c.makeImage()!
                }
                let pageA = page(adA), pageB = page(adB)
                guard let first = pageA.cropping(to: CGRect(x: 0, y: 0, width: w, height: vp)) else {
                    return (0, 0, 0, 0, false)
                }
                let s = SegmentedVerticalStitcher(first: first)
                var off = 0, appended = 0, started = 0
                for step in [40, 40, 60, 80, 120, 160, 200, 200, 200] {
                    off += step
                    guard let f = pageB.cropping(to: CGRect(x: 0, y: off, width: w, height: vp)) else { break }
                    switch s.append(f) {
                    case .appended: appended += 1
                    case .startedSegment: started += 1
                    default: break
                    }
                }
                return (s.segmentCount, s.totalHeight, appended, started, true)
            }
            let one = animatedRun(bands: [3])
            let two = animatedRun(bands: [2, 3])
            let three = animatedRun(bands: [1, 2, 3])
            let walkHeight = 500 + 40 + 40 + 60 + 80 + 120 + 160 + 200 + 200 + 200
            check("scroll8-animated-band-stitches",
                  one.ok && two.ok
                    && one.segments == 1 && one.appended == 9 && one.height == walkHeight
                    && two.segments == 1 && two.appended == 9 && two.height == walkHeight,
                  "one seg \(one.segments) app \(one.appended) h \(one.height)/\(walkHeight); "
                    + "two seg \(two.segments) app \(two.appended) h \(two.height)")
            // Three of four bands changed: no band mask may bless that, so the
            // session re-anchors exactly as before (marked gap, no silent seam).
            check("scroll8-animated-majority-fails-closed",
                  three.ok && three.segments == 2 && three.started == 1,
                  "three-band segments \(three.segments) started \(three.started) appended \(three.appended)")
        }

        // 2b-window-materialize. Preview refresh copies no pixel buffers -----------
        // A 5K source with sticky chrome and prepends used to materialize the
        // trimmed first viewport (~54 MiB) on every preview rebuild. The
        // ref-based window render must perform ZERO materializations and no
        // full composes.
        do {
            let wW = 5120, wViewport = 800, wHeader = 100
            let doc = makeStripePattern(width: wW, height: 2400, seed: 0x3A55_17E0)
            let chrome = makeStripePattern(width: wW, height: wHeader, seed: 0xC42F_EE00)
            func chromedWideFrame(offset: Int) -> CGImage? {
                guard let body = doc.cropping(to: CGRect(
                    x: 0, y: offset + wHeader, width: wW,
                    height: wViewport - wHeader)) else { return nil }
                let c = ctx(wW, wViewport)
                c.draw(chrome, in: CGRect(
                    x: 0, y: CGFloat(wViewport - wHeader),
                    width: CGFloat(wW), height: CGFloat(wHeader)))
                c.draw(body, in: CGRect(
                    x: 0, y: 0, width: CGFloat(wW),
                    height: CGFloat(wViewport - wHeader)))
                return c.makeImage()
            }
            let path = [1000, 700, 400]
            if let first = chromedWideFrame(offset: path[0]) {
                let segmented = SegmentedVerticalStitcher(first: first)
                var prepends = 0
                for off in path.dropFirst() {
                    guard let frame = chromedWideFrame(offset: off) else {
                        check("stitch-window-materialize-crop", false); break
                    }
                    if case .prepended = segmented.append(frame) { prepends += 1 }
                }
                let composesBefore = segmented.fullComposeCount
                let materializesBefore = MaterializeSpy.count
                let window = segmented.previewWindowImage(
                    targetWidth: 400, maxHeight: 1400, anchor: .currentTop)
                let materializeDelta = MaterializeSpy.count - materializesBefore
                let composeDelta = segmented.fullComposeCount - composesBefore
                check("stitch-window-materialize-free",
                      prepends == 2 && window != nil
                        && materializeDelta == 0 && composeDelta == 0
                        && (window?.width ?? 0) == 400
                        && (window?.height ?? 9999) <= 1400,
                      "prepends \(prepends), materialize \(materializeDelta), "
                      + "compose \(composeDelta), "
                      + "size \(window?.width ?? -1)x\(window?.height ?? -1)")
            } else {
                check("stitch-window-materialize-crop", false)
            }
        }

        // 2b-flip-production. Direction flips through the PRODUCTION dispatch ------
        // Drives applyStitchOutcome — the exact function the capture loop
        // calls — through down→up→down flips: every preview refresh must do
        // zero full composes and zero pixel materializations, and the
        // rebuilt preview must be the anchored bounded window.
        do {
            let doc = makeStripePattern(width: 400, height: 2700, seed: 0xF11B_0D0D)
            let vp = 500
            // The down phase captures 1700 rows (> the 1400-px preview
            // window) BEFORE the flip, so a buggy incremental append after
            // the up phase cannot coincidentally equal the bottom window.
            let path = [600, 900, 1200, 1500, 1800,
                        1500, 1200, 900, 600, 300,
                        600, 900, 1200, 1500, 1800, 2100]
            MainActor.assumeIsolated {
                guard let first = doc.cropping(to: CGRect(
                    x: 0, y: path[0], width: 400, height: vp)) else {
                    check("stitch-flip-production-crop", false)
                    return
                }
                let session = ScrollingCapture(onFinish: { _ in })
                session.startPreviewForTesting(with: first)
                let segmented = SegmentedVerticalStitcher(first: first)
                var prepends = 0
                var appends = 0
                var previewSpyClean = true
                var pinnedAfterPrepend = false
                var firstAppendAfterFlipRebuilt = false
                var awaitingFlipBack = false
                for off in path.dropFirst() {
                    guard let frame = doc.cropping(to: CGRect(
                        x: 0, y: off, width: 400, height: vp)) else {
                        check("stitch-flip-production-crop", false)
                        return
                    }
                    let outcome = segmented.append(frame)
                    switch outcome {
                    case .prepended: prepends += 1
                    case .appended: appends += 1
                    default: break
                    }
                    let composesBefore = segmented.fullComposeCount
                    let materializesBefore = MaterializeSpy.count
                    session.applyStitchOutcome(
                        outcome, stitcher: segmented, stopHint: "test")
                    if segmented.fullComposeCount != composesBefore
                        || MaterializeSpy.count != materializesBefore {
                        previewSpyClean = false
                    }
                    if case .prepended = outcome {
                        pinnedAfterPrepend = session.previewPinnedTop
                        awaitingFlipBack = true
                    } else if case .appended = outcome, awaitingFlipBack {
                        // The FIRST appended frame after an upward phase must
                        // rebuild the bottom-anchored window immediately —
                        // this is the branch a nil preview view used to skip.
                        awaitingFlipBack = false
                        if let preview = session.previewImageForTesting,
                           let want = segmented.previewWindowImage(
                            targetWidth: 400, maxHeight: 1400,
                            anchor: .bottom) {
                            firstAppendAfterFlipRebuilt =
                                !session.previewPinnedTop
                                && imagesEqual(want, preview)
                        }
                    }
                }
                check("stitch-flip-production-outcomes",
                      prepends == 1 && appends == 5,
                      "prepends \(prepends), appends \(appends)")
                check("stitch-flip-production-spy-clean", previewSpyClean,
                      "preview dispatch performed a full compose or materialize")
                check("stitch-flip-production-pinned-state", pinnedAfterPrepend,
                      "previewPinnedTop not set by the prepend rebuild")
                check("stitch-flip-production-first-append-rebuilds",
                      firstAppendAfterFlipRebuilt,
                      "first append after up-phase did not rebuild bottom window")
                if let preview = session.previewImageForTesting,
                   let want = segmented.previewWindowImage(
                    targetWidth: 400, maxHeight: 1400, anchor: .bottom) {
                    check("stitch-flip-production-anchored",
                          imagesEqual(want, preview),
                          "preview after down-flip is not the bottom-anchored window")
                } else {
                    check("stitch-flip-production-preview", false)
                }
            }
        }

        // 2b-preview-parity. Incremental and rebuilt previews agree ----------------
        // Incremental strip heights use the same cumulative floor as the
        // rebuilt window. At 5120→400 with 500 + 4×30 source rows, per-slice
        // floors summed to 47 while the rebuild showed 48 — a visible jump on
        // every flip.
        do {
            let doc = makeStripePattern(width: 5120, height: 700, seed: 0x0F10_0AA1)
            let vp = 500
            let path = [0, 30, 60, 90, 120]
            MainActor.assumeIsolated {
                guard let first = doc.cropping(to: CGRect(
                    x: 0, y: path[0], width: 5120, height: vp)) else {
                    check("stitch-preview-parity-crop", false)
                    return
                }
                let session = ScrollingCapture(onFinish: { _ in })
                session.startPreviewForTesting(with: first)
                let segmented = SegmentedVerticalStitcher(first: first)
                var appends = 0
                for off in path.dropFirst() {
                    guard let frame = doc.cropping(to: CGRect(
                        x: 0, y: off, width: 5120, height: vp)) else {
                        check("stitch-preview-parity-crop", false)
                        return
                    }
                    let outcome = segmented.append(frame)
                    if case .appended = outcome { appends += 1 }
                    session.applyStitchOutcome(
                        outcome, stitcher: segmented, stopHint: "test")
                }
                let wantRows = Int(CGFloat(620) * 400.0 / 5120.0)
                let incremental = session.previewImageForTesting?.height ?? -1
                let rebuilt = segmented.previewWindowImage(
                    targetWidth: 400, maxHeight: 1400, anchor: .bottom)?
                    .height ?? -2
                check("stitch-preview-parity",
                      appends == 4 && incremental == wantRows
                        && rebuilt == wantRows,
                      "appends \(appends), incremental \(incremental), "
                      + "rebuilt \(rebuilt), want \(wantRows)")
            }
        }

        // 2b-preview-footer-live. Sticky footer stays at the live preview's
        // bottom. The final compose re-attaches a latched footer at the very
        // bottom; the incremental paste used to leave the FIRST frame's
        // footer band mid-image with no footer at the bottom. Every accepted
        // outcome must leave the production preview byte-equal to the
        // bounded window.
        do {
            let fW = 400, fViewport = 500, fFooter = 60
            let content = makeStripePattern(width: fW, height: 2000, seed: 0xF007_E210)
            let footerBand = makeStripePattern(width: fW, height: fFooter, seed: 0xF007_BA9D)
            func footeredFrame(offset: Int, blinkFooter: Bool = false) -> CGImage? {
                guard let body = content.cropping(to: CGRect(
                    x: 0, y: offset, width: fW,
                    height: fViewport - fFooter)) else { return nil }
                let c = ctx(fW, fViewport)
                c.draw(footerBand, in: CGRect(
                    x: 0, y: 0, width: fW, height: fFooter))
                if blinkFooter {
                    // one blinking row inside the sticky bar — within the
                    // footer-stability tolerance, but a real pixel change the
                    // preview must show after the retrace
                    c.setFillColor(CGColor(gray: 0.95, alpha: 1))
                    c.fill(CGRect(x: 0, y: 30, width: fW, height: 1))
                }
                c.draw(body, in: CGRect(
                    x: 0, y: fFooter, width: fW,
                    height: fViewport - fFooter))
                return c.makeImage()
            }
            // The last frame is a RETRACE whose footer carries the blink: if
            // the moved branch stopped rebuilding, the preview would keep the
            // pre-blink footer while the bounded window shows the new one —
            // the gate is red without the moved-branch rebuild.
            let path = [0, 320, 640, 320]
            MainActor.assumeIsolated {
                guard let first = footeredFrame(offset: path[0]) else {
                    check("stitch-footer-preview-live-crop", false)
                    return
                }
                let session = ScrollingCapture(onFinish: { _ in })
                session.startPreviewForTesting(with: first)
                let segmented = SegmentedVerticalStitcher(first: first)
                var appended = 0
                var moved = 0
                var allExact = true
                for (index, off) in path.dropFirst().enumerated() {
                    let isLast = index == path.count - 2
                    guard let frame = footeredFrame(
                        offset: off, blinkFooter: isLast) else {
                        check("stitch-footer-preview-live-crop", false)
                        return
                    }
                    let outcome = segmented.append(frame)
                    session.applyStitchOutcome(
                        outcome, stitcher: segmented, stopHint: "test")
                    if isLast, case .moved = outcome {} else if isLast {
                        allExact = false // blink frame must be a retrace
                    }
                    switch outcome {
                    case .appended, .prepended, .moved:
                        if case .appended = outcome { appended += 1 }
                        if case .moved = outcome { moved += 1 }
                        if session.previewSourceRowsForTesting
                            != segmented.totalHeight {
                            allExact = false
                        }
                        if let preview = session.previewImageForTesting,
                           let want = segmented.previewWindowImage(
                            targetWidth: 400, maxHeight: 1400,
                            anchor: session.previewPinnedTop
                                ? .currentTop : .bottom) {
                            if !imagesEqual(want, preview) { allExact = false }
                        } else {
                            allExact = false
                        }
                    default: break
                    }
                }
                // Both patched branches must actually run: at least one
                // appended AND one moved (retrace) accepted outcome.
                check("stitch-footer-preview-live",
                      appended >= 1 && moved >= 1
                        && segmented.currentSegment.footerRows == fFooter
                        && allExact,
                      "appended \(appended), moved \(moved), footer "
                      + "\(segmented.currentSegment.footerRows), exact \(allExact)")
            }
        }

        // 2b-preview-omit-revocation. Header-omit revocation resyncs preview ------
        // Segment 2 initially omits its proven duplicate header; a later
        // accepted frame with changed chrome revokes the omit, raising
        // totalHeight by the restored header WITHOUT any rows in the outcome
        // (the restored band lives in the first slice, not lastSlice). The
        // preview must resync to the bounded window immediately — on the
        // appended outcome AND on a moved outcome.
        do {
            let rW = 400, rViewport = 500, rHeader = 40
            let content = makeStripePattern(width: rW, height: 3000, seed: 0x4EAD_0117)
            let band = makeStripePattern(width: rW, height: rHeader, seed: 0xBAA0_0001)
            let changedBand = makeStripePattern(width: rW, height: rHeader, seed: 0xBAA0_0002)
            func revFrame(offset: Int, band: CGImage) -> CGImage? {
                guard let body = content.cropping(to: CGRect(
                    x: 0, y: offset, width: rW,
                    height: rViewport - rHeader)) else { return nil }
                let c = ctx(rW, rViewport)
                c.draw(body, in: CGRect(
                    x: 0, y: 0, width: rW, height: rViewport - rHeader))
                c.draw(band, in: CGRect(
                    x: 0, y: rViewport - rHeader, width: rW, height: rHeader))
                return c.makeImage()
            }
            // variant true = revocation lands on an APPENDED frame,
            // false = revocation lands on a MOVED (retrace) frame.
            for revokeOnAppend in [true, false] {
                let label = revokeOnAppend ? "appended" : "moved"
                let basePath = [0, 200, 2000, 2041, 2083, 2126]
                let revokeOffset = revokeOnAppend ? 2170 : 2085
                MainActor.assumeIsolated {
                    guard let first = revFrame(offset: basePath[0], band: band) else {
                        check("stitch-omit-revocation-\(label)-crop", false)
                        return
                    }
                    let session = ScrollingCapture(onFinish: { _ in })
                    session.startPreviewForTesting(with: first)
                    let segmented = SegmentedVerticalStitcher(first: first)
                    var sawSegment = false
                    for off in basePath.dropFirst() {
                        guard let frame = revFrame(offset: off, band: band) else {
                            check("stitch-omit-revocation-\(label)-crop", false)
                            return
                        }
                        let outcome = segmented.append(frame)
                        if case .startedSegment = outcome { sawSegment = true }
                        session.applyStitchOutcome(
                            outcome, stitcher: segmented, stopHint: "test")
                    }
                    let omitBefore = segmented.totalHeight
                    guard sawSegment,
                          let revoker = revFrame(
                            offset: revokeOffset, band: changedBand) else {
                        check("stitch-omit-revocation-\(label)-fixture", false)
                        return
                    }
                    let outcome = segmented.append(revoker)
                    let expectedOutcome: Bool
                    var outcomeRows = 0
                    switch outcome {
                    case let .appended(rows):
                        expectedOutcome = revokeOnAppend
                        outcomeRows = rows
                    case .moved:
                        expectedOutcome = !revokeOnAppend
                    default:
                        expectedOutcome = false
                    }
                    session.applyStitchOutcome(
                        outcome, stitcher: segmented, stopHint: "test")
                    // totalHeight must have grown by the outcome's rows PLUS
                    // the restored header — that surplus is the revocation.
                    let revoked = segmented.totalHeight - omitBefore
                        == outcomeRows + rHeader
                    check("stitch-omit-revocation-\(label)-fixture",
                          expectedOutcome && revoked,
                          "outcome \(outcome), Δtotal \(segmented.totalHeight - omitBefore), rows \(outcomeRows)")
                    let basisSynced = session.previewSourceRowsForTesting
                        == segmented.totalHeight
                    if let preview = session.previewImageForTesting,
                       let want = segmented.previewWindowImage(
                        targetWidth: 400, maxHeight: 1400, anchor: .bottom) {
                        check("stitch-omit-revocation-\(label)-resync",
                              basisSynced && imagesEqual(want, preview),
                              "basis synced \(basisSynced) "
                              + "(\(session.previewSourceRowsForTesting) vs "
                              + "\(segmented.totalHeight))")
                    } else {
                        check("stitch-omit-revocation-\(label)-preview", false)
                    }
                }
            }
        }

        // 2b-promotion-compose. Promotion composes ONLY the old segment ------------
        // The startedSegment payload is gone; promoting a pending segment
        // must compose exactly the outgoing segment (it becomes the completed
        // raster) and never the new one — the dead pending.compose() used to
        // allocate a source-resolution canvas on the capture loop per
        // re-anchor.
        do {
            let doc = makeStripePattern(width: 400, height: 3000, seed: 0x9407_C0DE)
            let vp = 500
            let path = [0, 300, 1200, 1400, 1600, 1800]
            if let first = doc.cropping(to: CGRect(
                x: 0, y: path[0], width: 400, height: vp)) {
                let segmented = SegmentedVerticalStitcher(first: first)
                var promoteDelta = -1
                var nonPromoteDelta = 0
                var sawSegment = false
                for off in path.dropFirst() {
                    guard let frame = doc.cropping(to: CGRect(
                        x: 0, y: off, width: 400, height: vp)) else {
                        check("stitch-promotion-compose-crop", false); break
                    }
                    let before = FullComposeSpy.count
                    let outcome = segmented.append(frame)
                    let delta = FullComposeSpy.count - before
                    if case .startedSegment = outcome {
                        sawSegment = true
                        promoteDelta = delta
                    } else {
                        nonPromoteDelta += delta
                    }
                }
                check("stitch-promotion-compose-old-only",
                      sawSegment && promoteDelta == 1 && nonPromoteDelta == 0
                        && segmented.fullComposeCount == 0,
                      "segment \(sawSegment), promoteΔ \(promoteDelta), "
                      + "otherΔ \(nonPromoteDelta), "
                      + "current \(segmented.fullComposeCount)")
                check("stitch-promotion-compose-preview-works",
                      segmented.previewWindowImage(
                        targetWidth: 400, maxHeight: 1400,
                        anchor: .currentTop) != nil,
                      "bounded preview failed after payloadless promotion")
            } else {
                check("stitch-promotion-compose-crop", false)
            }
        }

        // 2b-preview-parity-reanchor. Re-anchor keeps the global floor basis -------
        // startedSegment used to seed the incremental preview from separator
        // + segment image, resetting the cumulative-floor basis to a local
        // value while flip rebuilds used the global total — a 1px jump after
        // every re-anchor at fractional scales. The re-anchor now rebuilds
        // the bounded window, so incremental and rebuilt geometry stay equal
        // through gap + append.
        do {
            let doc = makeStripePattern(width: 5120, height: 4200, seed: 0x9EA9_C40A)
            let vp = 800
            let path = [0, 600, 2400, 2600, 2800, 3000, 3200]
            MainActor.assumeIsolated {
                guard let first = doc.cropping(to: CGRect(
                    x: 0, y: path[0], width: 5120, height: vp)) else {
                    check("stitch-preview-reanchor-crop", false)
                    return
                }
                let session = ScrollingCapture(onFinish: { _ in })
                session.startPreviewForTesting(with: first)
                let segmented = SegmentedVerticalStitcher(first: first)
                var sawSegment = false
                var appendsAfterSegment = 0
                for off in path.dropFirst() {
                    guard let frame = doc.cropping(to: CGRect(
                        x: 0, y: off, width: 5120, height: vp)) else {
                        check("stitch-preview-reanchor-crop", false)
                        return
                    }
                    let outcome = segmented.append(frame)
                    switch outcome {
                    case .startedSegment: sawSegment = true
                    case .appended: if sawSegment { appendsAfterSegment += 1 }
                    default: break
                    }
                    session.applyStitchOutcome(
                        outcome, stitcher: segmented, stopHint: "test")
                }
                let incremental = session.previewImageForTesting?.height ?? -1
                let rebuilt = segmented.previewWindowImage(
                    targetWidth: 400, maxHeight: 1400, anchor: .bottom)?
                    .height ?? -2
                check("stitch-preview-reanchor-parity",
                      sawSegment && appendsAfterSegment >= 1
                        && incremental == rebuilt,
                      "segment \(sawSegment), appends \(appendsAfterSegment), "
                      + "incremental \(incremental), rebuilt \(rebuilt)")
            }
        }

        // 2b-window-gap-marker-wide. 5K + gap + prepend: marker survives, no
        // source-width canvas after the cache warms, no materialize/compose.
        do {
            let gW = 5120, gViewport = 800
            // Blue-only stripes so the ORANGE gap marker is unmistakable in
            // the scaled output — the gate detects real marker pixels, not
            // just a nonzero destination height.
            func blueStripes(width: Int, height: Int, seed: UInt64) -> CGImage {
                let c = ctx(width, height)
                var seed = seed
                for y in 0..<height {
                    seed = seed &* 6364136223846793005 &+ 1442695040888963407
                    let b = 0.25 + 0.75 * CGFloat((seed >> 33) & 0xFF) / 255
                    c.setFillColor(CGColor(
                        srgbRed: 0.05, green: 0.08, blue: b, alpha: 1))
                    c.fill(CGRect(x: 0, y: y, width: width, height: 1))
                }
                return c.makeImage()!
            }
            let doc = blueStripes(width: gW, height: 4000, seed: 0x5EA9_A9B1)
            // Completed segment = 1024 rows: at 400/5120 the separator's 12
            // source rows floor to ZERO destination pixels, so the 1-px
            // marker floor branch is genuinely exercised (asserted below).
            let path = [0, 224, 2400, 2600, 2800, 3000, 2500, 2000]
            if let first = doc.cropping(to: CGRect(
                x: 0, y: path[0], width: gW, height: gViewport)) {
                let segmented = SegmentedVerticalStitcher(first: first)
                var sawSegment = false
                var sawPrepend = false
                for off in path.dropFirst() {
                    guard let frame = doc.cropping(to: CGRect(
                        x: 0, y: off, width: gW, height: gViewport)) else {
                        check("stitch-window-gap-wide-crop", false); break
                    }
                    switch segmented.append(frame) {
                    case .startedSegment: sawSegment = true
                    case .prepended: sawPrepend = true
                    default: break
                    }
                }
                check("stitch-window-gap-wide-fixture",
                      sawSegment && sawPrepend && segmented.segmentCount == 2,
                      "segment \(sawSegment) prepend \(sawPrepend) count \(segmented.segmentCount)")
                // Lock the fixture's intent: without the floor, the separator
                // occupies zero scaled pixels at this geometry.
                let sepStart = 1024
                let sepScaled = Int(CGFloat(sepStart + 12) * 400.0 / 5120.0)
                    - Int(CGFloat(sepStart) * 400.0 / 5120.0)
                check("stitch-window-gap-wide-floor-branch", sepScaled == 0,
                      "separator naturally scales to \(sepScaled)px — fixture no longer exercises the floor")
                // Warm call may build the cached separator once; afterwards
                // repeated refreshes must allocate NOTHING at source width.
                let warm = segmented.previewWindowImage(
                    targetWidth: 400, maxHeight: 1400, anchor: .currentTop)
                let canvasesAfterWarm = SourceCanvasSpy.count
                let materializesAfterWarm = MaterializeSpy.count
                let composesAfterWarm = segmented.fullComposeCount
                let window = segmented.previewWindowImage(
                    targetWidth: 400, maxHeight: 1400, anchor: .currentTop)
                _ = segmented.previewWindowImage(
                    targetWidth: 400, maxHeight: 1400, anchor: .bottom)
                check("stitch-window-gap-wide-no-source-canvas",
                      warm != nil
                        && SourceCanvasSpy.count == canvasesAfterWarm
                        && MaterializeSpy.count == materializesAfterWarm
                        && segmented.fullComposeCount == composesAfterWarm,
                      "canvases +\(SourceCanvasSpy.count - canvasesAfterWarm), "
                      + "materializes +\(MaterializeSpy.count - materializesAfterWarm), "
                      + "composes +\(segmented.fullComposeCount - composesAfterWarm)")
                if let window {
                    var markerFound = false
                    var bytes = [UInt8](
                        repeating: 0, count: window.width * window.height * 4)
                    if let c = CGContext(
                        data: &bytes, width: window.width, height: window.height,
                        bitsPerComponent: 8, bytesPerRow: window.width * 4,
                        space: CGColorSpace(name: CGColorSpace.sRGB)!,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) {
                        c.interpolationQuality = .none
                        c.draw(window, in: CGRect(
                            x: 0, y: 0,
                            width: window.width, height: window.height))
                        for i in stride(from: 0, to: bytes.count, by: 4) {
                            let r = Int(bytes[i]), g = Int(bytes[i + 1])
                            let b = Int(bytes[i + 2])
                            // orange marker: strong red, moderate green, low blue
                            if r > 120, g > 40, b < 80, r > b * 2 {
                                markerFound = true
                                break
                            }
                        }
                    }
                    check("stitch-window-gap-wide-marker-visible", markerFound,
                          "gap marker pixels absent from scaled 5K window")
                } else {
                    check("stitch-window-gap-wide-render", false)
                }
            } else {
                check("stitch-window-gap-wide-crop", false)
            }
        }

        // 2b-halfrow. Coherence at an exact half-row offset ------------------------
        // The subpixel matcher's smallest emission is offset 0.5 (floor 0).
        // Coherence must compare rows 0/1 blends, not shift everything by a
        // whole row — a synthetic half-row blend must pass in BOTH directions.
        do {
            let rows = 64
            var baseBands = [Double](repeating: 0, count: rows * 4)
            var seed: UInt64 = 0x4A1F_0BEE
            for i in 0..<baseBands.count {
                seed = seed &* 6364136223846793005 &+ 1442695040888963407
                baseBands[i] = Double((seed >> 33) & 0xFF)
            }
            var shiftedBands = [Double](repeating: 0, count: rows * 4)
            for y in 0..<(rows - 1) {
                for band in 0..<4 {
                    shiftedBands[y * 4 + band] =
                        (baseBands[y * 4 + band] + baseBands[(y + 1) * 4 + band]) * 0.5
                }
            }
            for band in 0..<4 {
                shiftedBands[(rows - 1) * 4 + band] = baseBands[(rows - 1) * 4 + band]
            }
            let energy = [Double](repeating: 4.0, count: rows)
            let baseSig = VerticalStitcher.RowSig(bands: baseBands, energy: energy)
            let shiftedSig = VerticalStitcher.RowSig(bands: shiftedBands, energy: energy)
            check("stitch-halfrow-coherence-forward",
                  VerticalStitcher.wholeOverlapAgrees(
                    base: baseSig, shifted: shiftedSig, offset: 0.5,
                    headerRows: 0, effectiveHeight: rows),
                  "half-row blend rejected (base→shifted)")
            check("stitch-halfrow-coherence-reverse",
                  VerticalStitcher.wholeOverlapAgrees(
                    base: shiftedSig, shifted: baseSig, offset: 0.5,
                    headerRows: 0, effectiveHeight: rows),
                  "half-row blend rejected (shifted→base)")
        }

        // 2b-sparse. Sparse white page + repeated detailed card --------------------
        // Blank rows agree under any offset, so an unweighted quorum let a
        // duplicated card carry a fake match on a mostly-white page (75% of
        // rows "agreed" while every real content row differed). Blank rows
        // must not vote — with them excluded, the card cannot outvote the
        // differing content, in either direction.
        do {
            let sW = 400, sViewport = 500
            let cardSrc = makeStripePattern(width: sW, height: 125, seed: 0x0CA9_D0CA)
            let contentA = makeStripePattern(width: sW, height: 100, seed: 0x0C0A_AAAA)
            let contentB = makeStripePattern(width: sW, height: 100, seed: 0x0C0B_BBBB)
            func sparseFrame(
                card cardTop: Int, content: CGImage, contentTop: Int
            ) -> CGImage? {
                let c = ctx(sW, sViewport)
                c.setFillColor(CGColor(gray: 1, alpha: 1))
                c.fill(CGRect(x: 0, y: 0, width: sW, height: sViewport))
                c.draw(cardSrc, in: CGRect(
                    x: 0, y: sViewport - cardTop - 125,
                    width: sW, height: 125))
                c.draw(content, in: CGRect(
                    x: 0, y: sViewport - contentTop - content.height,
                    width: sW, height: content.height))
                return c.makeImage()
            }
            // Claimed offset 100: cards align (a[375..500) ↔ b[275..400)) and
            // the whitespace matches too, but the only real content rows
            // (a[100..200) vs b[0..100)) disagree — no true overlap exists.
            if let a = sparseFrame(card: 375, content: contentA, contentTop: 100),
               let b = sparseFrame(card: 275, content: contentB, contentTop: 0) {
                let down = VerticalStitcher(first: a)
                let downResult = down.append(b)
                check("stitch-sparse-card-rejected", downResult == .rejected,
                      "sparse repeated-card page got \(downResult) (a→b)")
                let up = VerticalStitcher(first: b)
                let upResult = up.append(a)
                check("stitch-sparse-card-reversed-rejected", upResult == .rejected,
                      "sparse repeated-card page got \(upResult) (b→a)")
            } else {
                check("stitch-sparse-card-frames", false)
            }

            // Same geometry but the differing content blocks are SOLID fills
            // (zero energy, zero interior contrast). Flat-but-DIFFERENT rows
            // must vote against the offset — skipping them as neutral let the
            // repeated card become nearly the entire electorate.
            let solidA = makeSolidImage(
                width: sW, height: 100, color: CGColor(gray: 0.3, alpha: 1))
            let solidB = makeSolidImage(
                width: sW, height: 100, color: CGColor(gray: 0.6, alpha: 1))
            if let a = sparseFrame(card: 375, content: solidA, contentTop: 100),
               let b = sparseFrame(card: 275, content: solidB, contentTop: 0) {
                let down = VerticalStitcher(first: a)
                let downResult = down.append(b)
                check("stitch-sparse-solid-card-rejected", downResult == .rejected,
                      "solid-panel repeated-card page got \(downResult) (a→b)")
                let up = VerticalStitcher(first: b)
                let upResult = up.append(a)
                check("stitch-sparse-solid-card-reversed-rejected",
                      upResult == .rejected,
                      "solid-panel repeated-card page got \(upResult) (b→a)")
            } else {
                check("stitch-sparse-solid-card-frames", false)
            }

            // Fail-closed liveness decision (team-locked): from two frames an
            // animated band is indistinguishable from genuinely different
            // content next to a duplicated card, so a TRUE sparse overlap
            // with an 80-row animated band REJECTS rather than risking
            // silent row loss. (80 rows, not 60: anti-aliased block edges
            // contribute a handful of extra matching votes, and 60 sat at a
            // brittle 71% — the fixture must sit clearly below the 70%
            // quorum.) A page with a large animation re-anchors with a
            // visible marker instead.
            func liveFrame(
                anim: CGImage, extra: CGImage?, offset: Int
            ) -> CGImage? {
                // document: detail block at doc[475..600); animated band at
                // doc[250..330) (inside the 400-row overlap of both shots);
                // extra content at doc[600..700) (revealed by the scroll);
                // white elsewhere. Frame shows doc[offset..offset+500).
                let c = ctx(sW, sViewport)
                c.setFillColor(CGColor(gray: 1, alpha: 1))
                c.fill(CGRect(x: 0, y: 0, width: sW, height: sViewport))
                func place(_ image: CGImage, docTop: Int) {
                    let top = docTop - offset
                    guard top + image.height > 0, top < sViewport else { return }
                    c.draw(image, in: CGRect(
                        x: 0, y: sViewport - top - image.height,
                        width: sW, height: image.height))
                }
                place(cardSrc, docTop: 475)      // shared detail (125 rows)
                place(anim, docTop: 250)         // animated band (80 rows)
                if let extra { place(extra, docTop: 600) }
                return c.makeImage()
            }
            let animFrame1 = makeStripePattern(width: sW, height: 80, seed: 0x0A11_0001)
            let animFrame2 = makeStripePattern(width: sW, height: 80, seed: 0x0A11_0002)
            let extraContent = makeStripePattern(width: sW, height: 100, seed: 0x0E17_0000)
            if let a = liveFrame(anim: animFrame1, extra: nil, offset: 100),
               let b = liveFrame(anim: animFrame2, extra: extraContent, offset: 200) {
                let down = VerticalStitcher(first: a)
                let downResult = down.append(b)
                check("stitch-sparse-animated-band-rejected",
                      downResult == .rejected,
                      "sparse page with animated band got \(downResult) (down)")
                let up = VerticalStitcher(first: b)
                let upResult = up.append(a)
                check("stitch-sparse-animated-band-reversed-rejected",
                      upResult == .rejected,
                      "sparse page with animated band got \(upResult) (up)")
            } else {
                check("stitch-sparse-animated-frames", false)
            }

            // The case that killed the escape hatch: an 80-row block of REAL
            // differing content next to the repeated 125-row card satisfied
            // "majority match + disagreement ≤ 20% of overlap" and was
            // silently swallowed. Must reject in both directions.
            let content80A = makeStripePattern(width: sW, height: 80, seed: 0x0C8A_0001)
            let content80B = makeStripePattern(width: sW, height: 80, seed: 0x0C8B_0002)
            if let a = sparseFrame(card: 375, content: content80A, contentTop: 120),
               let b = sparseFrame(card: 275, content: content80B, contentTop: 20) {
                let down = VerticalStitcher(first: a)
                let downResult = down.append(b)
                check("stitch-sparse-card-d80-rejected", downResult == .rejected,
                      "80-row real-content page got \(downResult) (a→b)")
                let up = VerticalStitcher(first: b)
                let upResult = up.append(a)
                check("stitch-sparse-card-d80-reversed-rejected",
                      upResult == .rejected,
                      "80-row real-content page got \(upResult) (b→a)")
            } else {
                check("stitch-sparse-card-d80-frames", false)
            }
        }

        // 2b-alternating. A raster that is NOT one translation must reject ---------
        // Even rows copied from offset k, odd rows from k+1: every single
        // phase explains only half the rows, so no globally-consistent
        // translation exists. Both directions must reject.
        do {
            let rows = 80
            var baseBands = [Double](repeating: 0, count: rows * 4)
            var seed: UInt64 = 0xA17E_44A7
            for i in 0..<baseBands.count {
                seed = seed &* 6364136223846793005 &+ 1442695040888963407
                baseBands[i] = Double((seed >> 33) & 0xFF)
            }
            let k = 10
            var mixedBands = [Double](repeating: 0, count: rows * 4)
            for y in 0..<rows {
                let source = min(rows - 1, y + k + (y % 2))
                for band in 0..<4 {
                    mixedBands[y * 4 + band] = baseBands[source * 4 + band]
                }
            }
            let energy = [Double](repeating: 4.0, count: rows)
            let baseSig = VerticalStitcher.RowSig(bands: baseBands, energy: energy)
            let mixedSig = VerticalStitcher.RowSig(bands: mixedBands, energy: energy)
            check("stitch-alternating-raster-rejected",
                  !VerticalStitcher.wholeOverlapAgrees(
                    base: baseSig, shifted: mixedSig, offset: Double(k) + 0.5,
                    headerRows: 0, effectiveHeight: rows),
                  "alternating floor/ceil raster passed (base→mixed)")
            check("stitch-alternating-raster-reversed-rejected",
                  !VerticalStitcher.wholeOverlapAgrees(
                    base: mixedSig, shifted: baseSig, offset: Double(k) + 0.5,
                    headerRows: 0, effectiveHeight: rows),
                  "alternating floor/ceil raster passed (mixed→base)")
        }

        // 2b-anchor. Prepend anchor must not drift with the header estimate --------
        // Two identical bands 30 rows apart fake a 20-row "header" on the first
        // up pair; the next pair disproves it. Cutting the second prepend at
        // the tightened header would drop and duplicate rows. The anchor is
        // latched instead and the disproving frame is rejected fail-closed;
        // everything accepted must still compose to the exact page raster.
        do {
            if let doc = withDuplicatedBlock(
                makeStripePattern(width: 400, height: 2000, seed: 0x0A2C_4042),
                from: 1010, to: 1040, rows: 20),
               let f0 = doc.cropping(to: CGRect(x: 0, y: 1040, width: 400, height: 500)),
               let f1 = doc.cropping(to: CGRect(x: 0, y: 1010, width: 400, height: 500)),
               let f2 = doc.cropping(to: CGRect(x: 0, y: 980, width: 400, height: 500)) {
                let s = VerticalStitcher(first: f0)
                let r1 = s.append(f1)
                let r2 = s.append(f2)
                check("stitch-anchor-first-prepend", r1 == .prepended(rows: 30),
                      "got \(r1), want prepended(30)")
                check("stitch-anchor-disproven-rejected", r2 == .rejected,
                      "header-estimate collapse got \(r2), want rejected")
                let composed = s.compose()
                check("stitch-anchor-height", composed?.height == 530,
                      "got \(composed?.height ?? -1), want 530")
                if let composed,
                   let want = doc.cropping(to: CGRect(
                    x: 0, y: 1010, width: 400, height: 530)) {
                    check("stitch-anchor-content",
                          imagesRoughlyEqual(want, composed),
                          "anchored prepend composed wrong rows")
                }
            } else {
                check("stitch-anchor-frames", false)
            }
        }

        // 2c. Sticky footer inside the viewport ------------------------------------
        // A fixed bottom bar (chat input, cookie banner…) used to either stall
        // matching entirely or get baked into every seam. The stitcher must
        // keep matching AND move the footer to the very end of the page.
        do {
            let fW = 400, fViewport = 500, fFooterH = 60
            let bodyH = fViewport - fFooterH
            let content = makeStripePattern(width: fW, height: 2000, seed: 0xC0FFEE42)
            let footerBand = makeStripePattern(width: fW, height: fFooterH, seed: 0x0DDBA11)

            func footerFrame(offset: Int) -> CGImage? {
                guard let body = content.cropping(to: CGRect(x: 0, y: offset, width: fW, height: bodyH))
                else { return nil }
                let c = ctx(fW, fViewport)
                // CG drawing is bottom-left: footer at the bottom, body above
                c.draw(footerBand, in: CGRect(x: 0, y: 0, width: fW, height: fFooterH))
                c.draw(body, in: CGRect(x: 0, y: fFooterH, width: fW, height: bodyH))
                return c.makeImage()
            }

            let offsets = [0, 320, 640, 900]
            var s3: VerticalStitcher?
            var appendsOK = true
            for (i, off) in offsets.enumerated() {
                guard let frame = footerFrame(offset: off) else { appendsOK = false; break }
                if let s = s3 {
                    let rows = s.append(frame).newRows
                    let want = off - offsets[i - 1]
                    if rows != want {
                        appendsOK = false
                        print("  footer step +\(want) → got \(rows)")
                    }
                } else {
                    s3 = VerticalStitcher(first: frame)
                }
            }
            check("stitch-footer-appends", appendsOK)

            if let composed3 = s3?.compose() {
                // expected: body content [0, bodyH + 900) then the footer once
                let totalBody = bodyH + 900
                let expected = ctx(fW, totalBody + fFooterH)
                if let allBody = content.cropping(to: CGRect(x: 0, y: 0, width: fW, height: totalBody)) {
                    expected.draw(footerBand, in: CGRect(x: 0, y: 0, width: fW, height: fFooterH))
                    expected.draw(allBody, in: CGRect(x: 0, y: fFooterH, width: fW, height: totalBody))
                }
                let expectedImg = expected.makeImage()!
                check("stitch-footer-height", composed3.height == totalBody + fFooterH,
                      "got \(composed3.height), want \(totalBody + fFooterH)")
                check("stitch-footer-content", imagesRoughlyEqual(expectedImg, composed3),
                      "footer relocated wrong")
                writePNG(composed3, to: "\(outputDir)/stitched-footer.png")
            } else {
                check("stitch-footer-compose", false)
            }

            // The short-overlap path must apply the same footer geometry as
            // the primary matcher: recover the body, then attach the bar once.
            let recoveryOffsets = [0, 350, 390]
            var footerRecovery: VerticalStitcher?
            var recoveryRows: [Int] = []
            for off in recoveryOffsets {
                guard let frame = footerFrame(offset: off) else { break }
                if let footerRecovery {
                    recoveryRows.append(footerRecovery.append(frame).newRows)
                } else {
                    footerRecovery = VerticalStitcher(first: frame)
                }
            }
            check("stitch-footer-short-overlap-appends",
                  recoveryRows == [350, 40],
                  "appended \(recoveryRows), want [350, 40]")
            if let recovered = footerRecovery?.compose() {
                let totalBody = bodyH + recoveryOffsets.last!
                let expected = ctx(fW, totalBody + fFooterH)
                if let allBody = content.cropping(to: CGRect(
                    x: 0, y: 0, width: fW, height: totalBody)) {
                    expected.draw(footerBand, in: CGRect(
                        x: 0, y: 0, width: fW, height: fFooterH))
                    expected.draw(allBody, in: CGRect(
                        x: 0, y: fFooterH, width: fW, height: totalBody))
                }
                let expectedImage = expected.makeImage()!
                check("stitch-footer-short-overlap-height",
                      recovered.height == totalBody + fFooterH,
                      "got \(recovered.height), want \(totalBody + fFooterH)")
                check("stitch-footer-short-overlap-content",
                      imagesRoughlyEqual(expectedImage, recovered),
                      "short-overlap footer was duplicated or misplaced")
            } else {
                check("stitch-footer-short-overlap-compose", false)
            }
        }

        // 2c2. A low-detail fixed footer must beat a plausible no-footer match ----
        // Solid chat/cookie bars carry little horizontal energy. The moving body
        // can dominate the no-footer template enough to make both geometries
        // look confident, so footer selection must compare their actual scores.
        do {
            let fW = 400, fViewport = 500, fFooterH = 60
            let bodyH = fViewport - fFooterH
            let content = makeNoiseImage(width: fW, height: 1800)
            let footerBand = makeSolidImage(
                width: fW, height: fFooterH,
                color: CGColor(gray: 0.94, alpha: 1))

            func lowDetailFooterFrame(offset: Int) -> CGImage? {
                guard let body = content.cropping(to: CGRect(
                    x: 0, y: offset, width: fW, height: bodyH))
                else { return nil }
                let c = ctx(fW, fViewport)
                c.draw(footerBand, in: CGRect(
                    x: 0, y: 0, width: fW, height: fFooterH))
                c.draw(body, in: CGRect(
                    x: 0, y: fFooterH, width: fW, height: bodyH))
                return c.makeImage()
            }

            let positions = [0, 320, 640]
            var lowDetail: VerticalStitcher?
            var rows: [Int] = []
            for position in positions {
                guard let frame = lowDetailFooterFrame(offset: position) else { break }
                if let lowDetail {
                    rows.append(lowDetail.append(frame).newRows)
                } else {
                    lowDetail = VerticalStitcher(first: frame)
                }
            }
            check("stitch-low-detail-footer-appends",
                  rows == [320, 320], "appended \(rows)")
            check("stitch-low-detail-footer-detected",
                  lowDetail?.footerRows == fFooterH,
                  "got footer \(lowDetail?.footerRows ?? -1)")
            if let composed = lowDetail?.compose() {
                let totalBody = bodyH + positions.last!
                let expected = ctx(fW, totalBody + fFooterH)
                if let body = content.cropping(to: CGRect(
                    x: 0, y: 0, width: fW, height: totalBody)) {
                    expected.draw(footerBand, in: CGRect(
                        x: 0, y: 0, width: fW, height: fFooterH))
                    expected.draw(body, in: CGRect(
                        x: 0, y: fFooterH, width: fW, height: totalBody))
                }
                check("stitch-low-detail-footer-content",
                      imagesRoughlyEqual(expected.makeImage()!, composed),
                      "low-detail footer duplicated or body rows dropped")
            } else {
                check("stitch-low-detail-footer-compose", false)
            }
        }

        // 2c3. A coincidentally static page tail is not a sticky footer ---------
        // A long blank/repeated block can make both footer hypotheses score
        // perfectly. Latching a footer on that tie would silently discard real
        // page rows, so the complete-viewport interpretation must win.
        do {
            let height = 500, shift = 120, staticTail = 60
            var seed: UInt64 = 0xF00D_CAFE
            var document = [Double](repeating: 0, count: 620 * 4)
            for index in document.indices {
                seed = seed &* 6364136223846793005 &+ 1442695040888963407
                document[index] = Double((seed >> 32) & 0xFF)
            }
            for row in 0..<staticTail {
                for band in 0..<4 {
                    document[(560 + row) * 4 + band]
                        = document[(440 + row) * 4 + band]
                }
            }
            func signature(start: Int) -> VerticalStitcher.RowSig {
                let first = start * 4
                let last = (start + height) * 4
                return VerticalStitcher.RowSig(
                    bands: Array(document[first..<last]),
                    energy: [Double](repeating: 10, count: height))
            }
            let match = VerticalStitcher.findOverlap(
                prev: signature(start: 0), next: signature(start: shift),
                height: height, scale: 1)
            check("stitch-static-page-tail-not-footer",
                  match?.footerRows == 0,
                  "got footer \(match?.footerRows ?? -1)")
            check("stitch-static-page-tail-offset",
                  abs((match?.preciseOffset ?? -1) - Double(shift)) < 0.001,
                  "got offset \(match?.preciseOffset ?? -1)")
        }

        // 2c4. Conflicting footer hypotheses must fail closed ---------------------
        // Two individually confident offsets describe mutually exclusive seams.
        // Score tie-breaking is unsafe here regardless of which geometry wins.
        do {
            let height = 500, footerRows = 60
            var seed: UInt64 = 0xF007_EA11
            func randomBands() -> [Double] {
                var values = [Double](repeating: 0, count: height * 4)
                for index in values.indices {
                    seed = seed &* 6364136223846793005
                        &+ 1442695040888963407
                    values[index] = Double((seed >> 32) & 0xFF)
                }
                return values
            }
            let previousBands = randomBands()
            var nextBands = randomBands()
            func copyRows(
                previousStart: Int, nextStart: Int, count: Int
            ) {
                for row in 0..<count {
                    for band in 0..<4 {
                        nextBands[(nextStart + row) * 4 + band]
                            = previousBands[(previousStart + row) * 4 + band]
                    }
                }
            }
            copyRows(previousStart: 375, nextStart: 255, count: 125)
            copyRows(previousStart: 330, nextStart: 130, count: 110)
            copyRows(
                previousStart: height - footerRows,
                nextStart: height - footerRows,
                count: footerRows)
            let previous = VerticalStitcher.RowSig(
                bands: previousBands,
                energy: [Double](repeating: 10, count: height))
            let next = VerticalStitcher.RowSig(
                bands: nextBands,
                energy: [Double](repeating: 10, count: height))
            let match = VerticalStitcher.findOverlap(
                prev: previous, next: next, height: height, scale: 1)
            check("stitch-conflicting-footer-hypotheses-rejected",
                  match == nil,
                  "accepted offset \(match?.preciseOffset ?? -1), "
                    + "footer \(match?.footerRows ?? -1)")
        }

        // 2d. Sticky footer with a BLINKING cursor row ------------------------------
        // The bar's cursor toggles between frames; the footer estimate must be
        // latched once for the session (a flapping per-pair estimate used to
        // bake bar fragments into the page mid-seam) and detection must bridge
        // the small dynamic band so the full bar height is latched up front.
        do {
            let fW = 400, fViewport = 500, fFooterH = 60, cursorH = 6, cursorFromBottom = 24
            let bodyH = fViewport - fFooterH
            let content = makeStripePattern(width: fW, height: 2000, seed: 0xB114_CAFE)
            let barA = makeStripePattern(width: fW, height: fFooterH, seed: 0xFEE7)
            // variant B: same bar, one bright "cursor" band toggled
            let barB: CGImage = {
                let c = ctx(fW, fFooterH)
                c.draw(barA, in: CGRect(x: 0, y: 0, width: fW, height: fFooterH))
                c.setFillColor(CGColor(srgbRed: 1, green: 1, blue: 1, alpha: 1))
                c.fill(CGRect(x: 20, y: cursorFromBottom, width: 80, height: cursorH))
                return c.makeImage()!
            }()

            func blinkFrame(offset: Int, phase: Int) -> CGImage? {
                guard let body = content.cropping(to: CGRect(x: 0, y: offset, width: fW, height: bodyH))
                else { return nil }
                let c = ctx(fW, fViewport)
                c.draw(phase % 2 == 0 ? barA : barB, in: CGRect(x: 0, y: 0, width: fW, height: fFooterH))
                c.draw(body, in: CGRect(x: 0, y: fFooterH, width: fW, height: bodyH))
                return c.makeImage()
            }

            let offsets = [0, 300, 620, 880]
            var s4: VerticalStitcher?
            var blinkOK = true
            for (i, off) in offsets.enumerated() {
                guard let frame = blinkFrame(offset: off, phase: i) else { blinkOK = false; break }
                if let s = s4 {
                    let rows = s.append(frame).newRows
                    let want = off - offsets[i - 1]
                    if rows != want {
                        blinkOK = false
                        print("  blink step +\(want) → got \(rows)")
                    }
                } else {
                    s4 = VerticalStitcher(first: frame)
                }
            }
            check("stitch-footer-blink-appends", blinkOK)
            if let s4, let composed4 = s4.compose() {
                let totalBody = bodyH + 880
                check("stitch-footer-blink-height", composed4.height == totalBody + fFooterH,
                      "got \(composed4.height), want \(totalBody + fFooterH)")
                check("stitch-footer-blink-detected",
                      s4.footerRows == fFooterH,
                      "got footer \(s4.footerRows), want \(fFooterH)")
                let expected = ctx(fW, totalBody + fFooterH)
                if let body = content.cropping(to: CGRect(
                    x: 0, y: 0, width: fW, height: totalBody)) {
                    expected.draw(barB, in: CGRect(
                        x: 0, y: 0, width: fW, height: fFooterH))
                    expected.draw(body, in: CGRect(
                        x: 0, y: fFooterH, width: fW, height: totalBody))
                }
                check("stitch-footer-blink-content",
                      imagesRoughlyEqual(expected.makeImage()!, composed4),
                      "blinking footer duplicated or misplaced")
            } else {
                check("stitch-footer-blink-compose", false)
            }
        }

        // 2e. macOS overlay scroller -------------------------------------------------
        // NSScroller is drawn on top of the page and its thumb moves/fades while
        // the user scrolls.  It is not page content, so a changing strip at the
        // viewport edge must not make an otherwise exact overlap fail.
        do {
            let fW = 400, fViewport = 500
            let content: CGImage = {
                let c = ctx(fW, 1800)
                c.setFillColor(CGColor(gray: 0.98, alpha: 1))
                c.fill(CGRect(x: 0, y: 0, width: fW, height: 1800))
                var seed: UInt64 = 0x5C20_11E2
                func next() -> CGFloat {
                    seed = seed &* 6364136223846793005 &+ 1442695040888963407
                    return CGFloat((seed >> 33) & 0xFF) / 255
                }
                var y = 12
                while y < 1780 {
                    let lines = 1 + Int(next() * 3)
                    c.setFillColor(CGColor(gray: 0.72 + next() * 0.12, alpha: 1))
                    c.fillEllipse(in: CGRect(x: 12, y: y, width: 22, height: 22))
                    for line in 0..<lines {
                        c.setFillColor(CGColor(gray: 0.35 + next() * 0.22, alpha: 1))
                        c.fill(CGRect(x: 48, y: y + line * 13,
                                      width: 70 + Int(next() * 260), height: 7))
                    }
                    y += 34 + Int(next() * 23)
                }
                return c.makeImage()!
            }()

            func scrollerFrame(offset: Int, thumbY: Int) -> CGImage? {
                guard let body = content.cropping(to: CGRect(
                    x: 0, y: offset, width: fW, height: fViewport
                )) else { return nil }
                let c = ctx(fW, fViewport)
                c.draw(body, in: CGRect(x: 0, y: 0, width: fW, height: fViewport))
                // Deliberately high-contrast to cover both light and dark pages.
                c.setFillColor(CGColor(gray: 0.08, alpha: 0.85))
                c.fill(CGRect(x: fW - 14, y: thumbY, width: 10, height: 96))
                return c.makeImage()
            }

            let offsets = [0, 120, 260, 430]
            let thumbPositions = [350, 290, 205, 105]
            var s5: VerticalStitcher?
            var scrollerOK = true
            for (i, off) in offsets.enumerated() {
                guard let frame = scrollerFrame(offset: off, thumbY: thumbPositions[i])
                else { scrollerOK = false; break }
                if let s = s5 {
                    let rows = s.append(frame).newRows
                    let want = off - offsets[i - 1]
                    if rows != want {
                        scrollerOK = false
                        print("  overlay-scroller step +\(want) → got \(rows)")
                    }
                } else {
                    s5 = VerticalStitcher(first: frame)
                }
            }
            check("stitch-overlay-scroller", scrollerOK)
        }

        // 2f. fractional-pixel trackpad scroll -------------------------------------
        // A 23.5-point scroll on a 1x display re-rasterizes horizontal edges
        // between pixel rows. Multiple half-pixel stops must carry their
        // residual: 23.5 + 23.5 is 47 rows, not two rounded 24-row slices.
        do {
            let fW = 400, fViewport = 500
            let content = makeStripePattern(width: fW, height: 1200, seed: 0xF12A_C710)
            func frame(offset: Int) -> CGImage? {
                content.cropping(to: CGRect(
                    x: 0, y: offset, width: fW, height: fViewport
                ))
            }
            func blend(_ a: CGImage, _ b: CGImage, fraction: CGFloat) -> CGImage? {
                let c = ctx(fW, fViewport)
                c.interpolationQuality = .high
                c.draw(a, in: CGRect(x: 0, y: 0, width: fW, height: fViewport))
                c.setAlpha(fraction)
                c.draw(b, in: CGRect(x: 0, y: 0, width: fW, height: fViewport))
                return c.makeImage()
            }
            func frame(offset: Double) -> CGImage? {
                let low = Int(floor(offset))
                let fraction = CGFloat(offset - Double(low))
                guard fraction > 0.001 else { return frame(offset: low) }
                guard let a = frame(offset: low), let b = frame(offset: low + 1) else { return nil }
                return blend(a, b, fraction: fraction)
            }
            let positions = [0.0, 23.5, 47.0, 70.5, 94.0]
            let expectedRows = [24, 23, 24, 23]
            if let first = frame(offset: positions[0]) {
                let fractional = VerticalStitcher(first: first)
                var rows: [Int] = []
                for position in positions.dropFirst() {
                    guard let next = frame(offset: position) else { break }
                    rows.append(fractional.append(next).newRows)
                }
                check("stitch-fractional-trackpad-sequence", rows == expectedRows,
                      "got \(rows), want \(expectedRows)")
                check("stitch-fractional-trackpad-no-drift",
                      fractional.totalHeight == fViewport + 94,
                      "got \(fractional.totalHeight), want \(fViewport + 94)")
                check("stitch-fractional-trackpad-compose-height",
                      fractional.compose()?.height == fViewport + 94)
            } else {
                check("stitch-fractional-trackpad-frame", false)
            }
        }

        // 2g. Fine text while a macOS trackpad is between backing pixels ----------
        // The coarse stripe fixture above stays easy after interpolation. Real
        // glyph strokes are only a couple of pixels tall: WindowServer's
        // subpixel re-rasterization changes their raw per-row signatures enough
        // that the correct offset can lose the matcher's absolute-score gate.
        do {
            let fW = 1000, fViewport = 1200, documentHeight = 8000
            let content: CGImage = {
                let c = ctx(fW, documentHeight)
                c.setFillColor(CGColor(gray: 1, alpha: 1))
                c.fill(CGRect(x: 0, y: 0, width: fW, height: documentHeight))
                var seed: UInt64 = 0xBEEF_F00D
                func next() -> CGFloat {
                    seed = seed &* 6364136223846793005 &+ 1442695040888963407
                    return CGFloat((seed >> 33) & 0xFF) / 255
                }
                c.translateBy(x: 0, y: CGFloat(documentHeight))
                c.scaleBy(x: 1, y: -1)
                var y: CGFloat = 10
                while y < CGFloat(documentHeight) {
                    var x: CGFloat = 40 + next() * 60
                    let lineEnd = 200 + next() * 700
                    while x < lineEnd {
                        c.setFillColor(CGColor(gray: 0.15 + next() * 0.25, alpha: 1))
                        c.fill(CGRect(x: x, y: y, width: 4 + next() * 14, height: 2))
                        x += 6 + next() * 12
                    }
                    y += 32
                }
                return c.makeImage()!
            }()

            func fineTextFrame(offset: Double) -> CGImage? {
                let c = ctx(fW, fViewport)
                c.interpolationQuality = .high
                c.draw(content, in: CGRect(
                    x: 0,
                    y: CGFloat(fViewport - documentHeight) + CGFloat(offset),
                    width: CGFloat(fW),
                    height: CGFloat(documentHeight)))
                return c.makeImage()
            }

            let positions = [0.0, 100.4, 220.7, 340.3, 500.6, 640.2]
            if let first = fineTextFrame(offset: positions[0]) {
                let fineText = VerticalStitcher(first: first, scale: 2)
                var rows: [Int] = []
                for position in positions.dropFirst() {
                    guard let next = fineTextFrame(offset: position) else { break }
                    rows.append(fineText.append(next).newRows)
                }
                check("stitch-fine-text-fractional-accepts-all",
                      rows.count == positions.count - 1 && rows.allSatisfy { $0 > 0 },
                      "appended \(rows)")
                let expectedHeight = fViewport + Int(positions.last!.rounded())
                check("stitch-fine-text-fractional-no-drift",
                      abs(fineText.totalHeight - expectedHeight) <= 1,
                      "got \(fineText.totalHeight), want \(expectedHeight)±1")

                // Same fractional trackpad positions, scrolled bottom-to-top.
                // The macOS failure mode (odd backing-pixel offsets from
                // momentum scrolling) must not resurface in the up direction.
                if let upFirst = fineTextFrame(offset: positions.last!) {
                    let fineTextUp = VerticalStitcher(first: upFirst, scale: 2)
                    var upRows: [Int] = []
                    var upRejects = 0
                    for position in positions.dropLast().reversed() {
                        guard let next = fineTextFrame(offset: position) else { break }
                        let result = fineTextUp.append(next)
                        upRows.append(result.newRows)
                        if !result.isAccepted { upRejects += 1 }
                    }
                    check("stitch-fine-text-fractional-upscroll-accepts-all",
                          upRows.count == positions.count - 1 && upRejects == 0
                            && upRows.allSatisfy { $0 > 0 },
                          "prepended \(upRows), rejects \(upRejects)")
                    check("stitch-fine-text-fractional-upscroll-no-drift",
                          abs(fineTextUp.totalHeight - expectedHeight) <= 1,
                          "got \(fineTextUp.totalHeight), want \(expectedHeight)±1")
                }

                // A real flick combines both failure modes: fractional
                // re-rasterization and less overlap than the primary 25%
                // template. Keep this distinct from the small-step case above
                // and the integer stripe recovery below.
                let recoveryViewport = 1000
                func recoveryFrame(offset: Double) -> CGImage? {
                    let c = ctx(fW, recoveryViewport)
                    c.interpolationQuality = .high
                    c.draw(content, in: CGRect(
                        x: 0,
                        y: CGFloat(recoveryViewport - documentHeight) + CGFloat(offset),
                        width: CGFloat(fW),
                        height: CGFloat(documentHeight)))
                    return c.makeImage()
                }
                let recoveryPositions = [0.0, 800.4, 880.4]
                if let recoveryFirst = recoveryFrame(offset: recoveryPositions[0]) {
                    let fractionalRecovery = VerticalStitcher(
                        first: recoveryFirst, scale: 2)
                    var recoveryRows: [Int] = []
                    for position in recoveryPositions.dropFirst() {
                        guard let next = recoveryFrame(offset: position) else { break }
                        recoveryRows.append(fractionalRecovery.append(next).newRows)
                    }
                    check("stitch-fine-text-fractional-short-overlap-recovers",
                          recoveryRows.count == recoveryPositions.count - 1
                            && recoveryRows.allSatisfy { $0 > 0 },
                          "appended \(recoveryRows)")
                    let expectedRecoveryHeight = recoveryViewport
                        + Int(recoveryPositions.last!.rounded())
                    check("stitch-fine-text-fractional-short-overlap-no-drift",
                          abs(fractionalRecovery.totalHeight
                              - expectedRecoveryHeight) <= 1,
                          "got \(fractionalRecovery.totalHeight), "
                            + "want \(expectedRecoveryHeight)±1")
                    check("stitch-fine-text-fractional-short-overlap-no-footer",
                          fractionalRecovery.footerRows == 0,
                          "false footer \(fractionalRecovery.footerRows)")
                    if let recoveredImage = fractionalRecovery.compose() {
                        let expected = ctx(fW, expectedRecoveryHeight)
                        expected.interpolationQuality = .high
                        expected.draw(content, in: CGRect(
                            x: 0,
                            y: CGFloat(expectedRecoveryHeight - documentHeight),
                            width: CGFloat(fW),
                            height: CGFloat(documentHeight)))
                        check("stitch-fine-text-fractional-short-overlap-content",
                              imagesRoughlyEqual(
                                expected.makeImage()!, recoveredImage),
                              "fractional short-overlap content mismatch")
                    } else {
                        check("stitch-fine-text-fractional-short-overlap-compose",
                              false)
                    }

                    let driftPositions = [
                        0.0, 800.4, 1600.8, 2401.2, 3201.6, 4002.0
                    ]
                    if let driftFirst = recoveryFrame(offset: driftPositions[0]) {
                        let driftRecovery = VerticalStitcher(
                            first: driftFirst, scale: 2)
                        var driftRows: [Int] = []
                        for position in driftPositions.dropFirst() {
                            guard let next = recoveryFrame(offset: position) else {
                                break
                            }
                            driftRows.append(driftRecovery.append(next).newRows)
                        }
                        let expectedDriftHeight = recoveryViewport
                            + Int(driftPositions.last!.rounded())
                        check("stitch-fine-text-fractional-short-overlap-sequence",
                              driftRows.count == driftPositions.count - 1
                                && driftRows.allSatisfy { $0 > 0 },
                              "appended \(driftRows)")
                        check("stitch-fine-text-fractional-short-overlap-carries-phase",
                              driftRecovery.totalHeight == expectedDriftHeight,
                              "got \(driftRecovery.totalHeight), "
                                + "want \(expectedDriftHeight)")
                        check("stitch-fine-text-fractional-short-overlap-sequence-no-footer",
                              driftRecovery.footerRows == 0,
                              "false footer \(driftRecovery.footerRows)")
                        if let driftImage = driftRecovery.compose() {
                            let expected = ctx(fW, expectedDriftHeight)
                            expected.interpolationQuality = .high
                            expected.draw(content, in: CGRect(
                                x: 0,
                                y: CGFloat(expectedDriftHeight - documentHeight),
                                width: CGFloat(fW),
                                height: CGFloat(documentHeight)))
                            check("stitch-fine-text-fractional-short-overlap-sequence-content",
                                  imagesRoughlyEqual(
                                    expected.makeImage()!, driftImage),
                                  "fractional short-overlap sequence mismatch")
                        } else {
                            check("stitch-fine-text-fractional-short-overlap-sequence-compose",
                                  false)
                        }
                    } else {
                        check("stitch-fine-text-fractional-short-overlap-drift-frame",
                              false)
                    }
                } else {
                    check("stitch-fine-text-fractional-short-overlap-frame", false)
                }
            } else {
                check("stitch-fine-text-fractional-frame", false)
            }
        }

        // 2g2. Raw short-overlap must preserve fractional phase -------------------
        // Not every fractional flick needs the blur fallback. On a smooth but
        // unique signal the raw short matcher can score below 2.0 at the right
        // integer row while the true displacement is still fractional. Returning
        // the integer valley here loses that phase on every fast step.
        do {
            let height = 500
            func signal(_ row: Double, band: Int) -> Double {
                128 + 100 * sin(
                    2 * Double.pi * row / 800
                    + Double(band) * Double.pi / 2)
            }
            func signature(offset: Double) -> VerticalStitcher.RowSig {
                var bands: [Double] = []
                bands.reserveCapacity(height * 4)
                for row in 0..<height {
                    for band in 0..<4 {
                        bands.append(signal(Double(row) + offset, band: band))
                    }
                }
                return VerticalStitcher.RowSig(
                    bands: bands,
                    energy: [Double](repeating: 10, count: height))
            }

            let previous = signature(offset: 0)
            let fractional = VerticalStitcher.findOverlap(
                prev: previous, next: signature(offset: 400.4),
                height: height, scale: 1, lockedFooter: 0)
            check("stitch-raw-short-overlap-preserves-fractional-phase",
                  abs((fractional?.preciseOffset ?? -1) - 400.4) < 0.15,
                  "got \(fractional?.preciseOffset ?? -1), want 400.4±0.15")

            let exact = VerticalStitcher.findOverlap(
                prev: previous, next: signature(offset: 400),
                height: height, scale: 1, lockedFooter: 0)
            check("stitch-raw-short-overlap-keeps-exact-integer",
                  abs((exact?.preciseOffset ?? -1) - 400) < 0.001,
                  "got \(exact?.preciseOffset ?? -1), want 400")
        }

        // 2h. Short-overlap recovery after a fast trackpad step -------------------
        // The primary matcher deliberately requires about 25% overlap. A fast
        // but still recoverable step can leave 10–20%; without a conservative
        // second pass, the reference frame never advances and all later slow
        // frames are rejected too.
        do {
            let fW = 400, fViewport = 500
            let content = makeStripePattern(width: fW, height: 1100, seed: 0x5A07_0A11)
            let positions = [0, 400, 440]
            var recovery: VerticalStitcher?
            var rows: [Int] = []
            for position in positions {
                guard let frame = content.cropping(to: CGRect(
                    x: 0, y: position, width: fW, height: fViewport))
                else { break }
                if let recovery {
                    rows.append(recovery.append(frame).newRows)
                } else {
                    recovery = VerticalStitcher(first: frame)
                }
            }
            check("stitch-short-overlap-recovers",
                  rows == [400, 40], "appended \(rows), want [400, 40]")
            check("stitch-short-overlap-height",
                  recovery?.totalHeight == 940,
                  "got \(recovery?.totalHeight ?? -1), want 940")
            if let composed = recovery?.compose(),
               let expected = content.cropping(to: CGRect(
                   x: 0, y: 0, width: fW, height: 940)) {
                check("stitch-short-overlap-content",
                      imagesRoughlyEqual(expected, composed),
                      "short-overlap stitch content mismatch")
            } else {
                check("stitch-short-overlap-compose", false)
            }

            let ambiguous = makePeriodicPattern(width: fW, height: 1000, period: 37)
            if let a0 = ambiguous.cropping(to: CGRect(
                   x: 0, y: 0, width: fW, height: fViewport)),
               let a400 = ambiguous.cropping(to: CGRect(
                   x: 0, y: 400, width: fW, height: fViewport)) {
                let alias = VerticalStitcher(first: a0)
                check("stitch-short-overlap-ambiguous-rejected",
                      alias.append(a400).newRows == 0)
            } else {
                check("stitch-short-overlap-ambiguous-frame", false)
            }

            if let n0 = content.cropping(to: CGRect(
                   x: 0, y: 0, width: fW, height: fViewport)),
               let n500 = content.cropping(to: CGRect(
                   x: 0, y: 500, width: fW, height: fViewport)) {
                let noOverlap = VerticalStitcher(first: n0)
                check("stitch-no-overlap-rejected", noOverlap.append(n500).newRows == 0)
            } else {
                check("stitch-no-overlap-frame", false)
            }

            func replacingRows(
                in image: CGImage, destinationStart: Int,
                from source: CGImage, sourceStart: Int, count: Int
            ) -> CGImage? {
                let rowBytes = fW * 4
                let sourceBytes = rgbaBytes(source)
                var destinationBytes = rgbaBytes(image)
                for row in 0..<count {
                    let sourceOffset = (sourceStart + row) * rowBytes
                    let destinationOffset = (destinationStart + row) * rowBytes
                    destinationBytes.replaceSubrange(
                        destinationOffset..<(destinationOffset + rowBytes),
                        with: sourceBytes[sourceOffset..<(sourceOffset + rowBytes)])
                }
                return destinationBytes.withUnsafeMutableBytes { bytes in
                    guard let context = CGContext(
                        data: bytes.baseAddress,
                        width: fW, height: fViewport,
                        bitsPerComponent: 8, bytesPerRow: rowBytes,
                        space: CGColorSpace(name: CGColorSpace.sRGB)!,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                    else { return nil }
                    return context.makeImage()
                }
            }

            // A copied strip shorter than the recovery evidence must not turn
            // two adjacent, non-overlapping frames into a fabricated seam.
            if let a = content.cropping(to: CGRect(
                   x: 0, y: 0, width: fW, height: fViewport)),
               let b = content.cropping(to: CGRect(
                   x: 0, y: fViewport, width: fW, height: fViewport)),
               let decoy = replacingRows(
                   in: b, destinationStart: 0,
                   from: a, sourceStart: fViewport - 64, count: 64) {
                let decoyRecovery = VerticalStitcher(first: a)
                check("stitch-short-overlap-64-row-decoy-rejected",
                      decoyRecovery.append(decoy).newRows == 0)
            } else {
                check("stitch-short-overlap-64-row-decoy-frame", false)
            }

            // A long primary template can be an exact one-off duplicate while
            // the true displacement lives just outside its search range. The
            // shorter global probe must expose both basins and veto the alias.
            if let a = content.cropping(to: CGRect(
                   x: 0, y: 0, width: fW, height: fViewport)),
               let b = content.cropping(to: CGRect(
                   x: 0, y: 400, width: fW, height: fViewport)),
               let decoy = replacingRows(
                   in: b, destinationStart: 275,
                   from: a, sourceStart: 375, count: 125) {
                let primaryDecoy = VerticalStitcher(first: a)
                check("stitch-primary-alias-with-short-overlap-rejected",
                      primaryDecoy.append(decoy).newRows == 0,
                      "ambiguous 100/400-row basins must not be guessed")
            } else {
                check("stitch-primary-alias-with-short-overlap-frame", false)
            }

            // A primary candidate that reaches into a fixed header is not a
            // valid body overlap. A one-off copied block spanning that boundary
            // must be rejected instead of silently dropping page content.
            do {
                let height = 500, headerRows = 60
                var seed: UInt64 = 0xA11A_5EAD
                func randomBands() -> [Double] {
                    var values = [Double](repeating: 0, count: height * 4)
                    for index in values.indices {
                        seed = seed &* 6364136223846793005
                            &+ 1442695040888963407
                        values[index] = Double((seed >> 32) & 0xFF)
                    }
                    return values
                }
                var previousBands = randomBands()
                var nextBands = randomBands()
                for row in 0..<headerRows {
                    for band in 0..<4 {
                        nextBands[row * 4 + band]
                            = previousBands[row * 4 + band]
                    }
                }
                // next[5..<130] = previous[375..<500]. Preserve the already
                // static header where those ranges intersect.
                for row in 0..<55 {
                    for band in 0..<4 {
                        previousBands[(375 + row) * 4 + band]
                            = previousBands[(5 + row) * 4 + band]
                    }
                }
                for row in 0..<125 {
                    for band in 0..<4 {
                        nextBands[(5 + row) * 4 + band]
                            = previousBands[(375 + row) * 4 + band]
                    }
                }
                let previous = VerticalStitcher.RowSig(
                    bands: previousBands,
                    energy: [Double](repeating: 10, count: height))
                let next = VerticalStitcher.RowSig(
                    bands: nextBands,
                    energy: [Double](repeating: 10, count: height))
                let match = VerticalStitcher.findOverlap(
                    prev: previous, next: next, height: height,
                    scale: 1, lockedFooter: 0)
                check("stitch-primary-alias-crossing-header-rejected",
                      match == nil,
                      "accepted offset \(match?.preciseOffset ?? -1) "
                        + "from an ambiguous header/body frame")
            }

            let retinaContent = makeStripePattern(
                width: fW, height: 2200, seed: 0x2A2A_8008)
            if let r0 = retinaContent.cropping(to: CGRect(
                   x: 0, y: 0, width: fW, height: 1000)),
               let r800 = retinaContent.cropping(to: CGRect(
                   x: 0, y: 800, width: fW, height: 1000)) {
                let retina = VerticalStitcher(first: r0, scale: 2)
                check("stitch-short-overlap-retina-recovers",
                      retina.append(r800).newRows == 800)
            } else {
                check("stitch-short-overlap-retina-frame", false)
            }

            // A fixed top navigation bar is not part of the moving overlap.
            // Recovery must validate only the body while keeping the header
            // once at the top of the composed shot.
            let headerH = 60
            let headerBodyH = fViewport - headerH
            let headerContent = makeStripePattern(
                width: fW, height: 1200, seed: 0x1EA0_EA01)
            let headerBand = makeStripePattern(
                width: fW, height: headerH, seed: 0xAEAD_EA01)
            func headerFrame(offset: Int) -> CGImage? {
                guard let body = headerContent.cropping(to: CGRect(
                    x: 0, y: offset, width: fW, height: headerBodyH))
                else { return nil }
                let c = ctx(fW, fViewport)
                c.draw(body, in: CGRect(
                    x: 0, y: 0, width: fW, height: headerBodyH))
                c.draw(headerBand, in: CGRect(
                    x: 0, y: headerBodyH, width: fW, height: headerH))
                return c.makeImage()
            }
            let headerPositions = [0, 350, 390]
            var headerRecovery: VerticalStitcher?
            var headerRows: [Int] = []
            for position in headerPositions {
                guard let frame = headerFrame(offset: position) else { break }
                if let headerRecovery {
                    headerRows.append(headerRecovery.append(frame).newRows)
                } else {
                    headerRecovery = VerticalStitcher(first: frame)
                }
            }
            check("stitch-short-overlap-sticky-header-appends",
                  headerRows == [350, 40],
                  "appended \(headerRows), want [350, 40]")
            if let headerImage = headerRecovery?.compose() {
                let totalBody = headerBodyH + headerPositions.last!
                let expected = ctx(fW, headerH + totalBody)
                if let body = headerContent.cropping(to: CGRect(
                    x: 0, y: 0, width: fW, height: totalBody)) {
                    expected.draw(body, in: CGRect(
                        x: 0, y: 0, width: fW, height: totalBody))
                    expected.draw(headerBand, in: CGRect(
                        x: 0, y: totalBody, width: fW, height: headerH))
                }
                check("stitch-short-overlap-sticky-header-content",
                      imagesRoughlyEqual(expected.makeImage()!, headerImage),
                      "sticky header duplicated or body seam corrupted")
            } else {
                check("stitch-short-overlap-sticky-header-compose", false)
            }
        }

        // 2h1b. Mid-session reversal must NOT split a segment ----------------------
        // The field failure behind duplicated blocks: scroll down, scroll back
        // up to re-read, continue down. Reversed frames used to reject until
        // the session re-anchored a new segment from the higher viewport and
        // re-captured everything below it. Now the reversal is a confirmed
        // move: one segment, no separator, no duplicate rows.
        do {
            let doc = makeStripePattern(width: 400, height: 2200, seed: 0x5E63_4EAD)
            let vp = 500
            let path = [0, 300, 600, 900, 600, 300, 600, 900, 1200, 1500, 1700]
            if let first = doc.cropping(to: CGRect(
                x: 0, y: path[0], width: 400, height: vp)) {
                let segmented = SegmentedVerticalStitcher(first: first)
                var splits = 0
                var rejects = 0
                for off in path.dropFirst() {
                    guard let frame = doc.cropping(to: CGRect(
                        x: 0, y: off, width: 400, height: vp)) else {
                        check("stitch-segment-reversal-crop", false); break
                    }
                    switch segmented.append(frame) {
                    case .startedSegment: splits += 1
                    case .rejected: rejects += 1
                    default: break
                    }
                }
                check("stitch-segment-reversal-single-segment",
                      splits == 0 && rejects == 0 && segmented.segmentCount == 1,
                      "splits \(splits), rejects \(rejects), segments \(segmented.segmentCount)")
                let composed = segmented.compose()
                check("stitch-segment-reversal-height", composed?.height == 2200,
                      "got \(composed?.height ?? -1), want 2200")
                if let composed {
                    check("stitch-segment-reversal-content",
                          imagesRoughlyEqual(doc, composed),
                          "reversal duplicated or dropped rows")
                }
            } else {
                check("stitch-segment-reversal-crop", false)
            }
        }

        // 2h2. Complete overlap loss re-anchors only to a proven new segment -------
        // A fast flick can move farther than the viewport. There is no honest
        // seam to infer in that case, so the session waits until later frames
        // prove a new contiguous strip, then inserts a visible boundary marker.
        do {
            func expectedSegmentedImage(
                upper: CGImage, separator: CGImage, lower: CGImage
            ) -> CGImage? {
                guard upper.width == lower.width,
                      upper.width == separator.width else { return nil }
                let height = upper.height + separator.height + lower.height
                let c = ctx(upper.width, height)
                var y = height
                for image in [upper, separator, lower] {
                    y -= image.height
                    c.draw(image, in: CGRect(
                        x: 0, y: y, width: image.width, height: image.height))
                }
                return c.makeImage()
            }

            // S-C: one valid step, a huge flick, then several slow frames.
            let width = 400, viewport = 600
            let document = makeStripePattern(
                width: width, height: 3600, seed: 0x5C00_0F11)
            let positions = [0, 150, 2650, 2690, 2730, 2770, 2810]
            if let first = document.cropping(to: CGRect(
                x: 0, y: positions[0], width: width, height: viewport)) {
                let segmented = SegmentedVerticalStitcher(first: first)
                var promotedAt: Int?
                var lastRows = 0
                for position in positions.dropFirst() {
                    guard let frame = document.cropping(to: CGRect(
                        x: 0, y: position, width: width, height: viewport))
                    else { break }
                    switch segmented.append(frame) {
                    case let .appended(rows):
                        lastRows = rows
                    case .prepended, .moved, .rejected:
                        break
                    case .startedSegment:
                        promotedAt = position
                    }
                }
                check("stitch-segment-reanchor-after-flick",
                      promotedAt == 2770 && segmented.segmentCount == 2,
                      "promotedAt \(promotedAt ?? -1), segments "
                        + "\(segmented.segmentCount)")
                check("stitch-segment-reanchor-continues",
                      lastRows == 40 && segmented.totalHeight
                        == 750 + segmented.separatorRows + 760,
                      "lastRows \(lastRows), height \(segmented.totalHeight)")
                if let upper = document.cropping(to: CGRect(
                       x: 0, y: 0, width: width, height: 750)),
                   let lower = document.cropping(to: CGRect(
                       x: 0, y: 2650, width: width, height: 760)),
                   let separator = segmented.segmentSeparator(),
                   let expected = expectedSegmentedImage(
                       upper: upper, separator: separator, lower: lower),
                   let actual = segmented.compose() {
                    check("stitch-segment-reanchor-marked-content",
                          imagesRoughlyEqual(expected, actual),
                          "segment boundary/content mismatch")
                } else {
                    check("stitch-segment-reanchor-compose", false)
                }
            } else {
                check("stitch-segment-reanchor-frame", false)
            }

            // S-F: 200 pt selection at 2x, 170 pt steps. The first three
            // candidates cannot prove the minimum 64 pt overlap; 1020→1060 can,
            // so reject #4 promotes that pending strip and 1100 continues it.
            let retinaViewport = 400
            let fineDocument: CGImage = {
                let c = ctx(width, 1800)
                c.setFillColor(CGColor(gray: 1, alpha: 1))
                c.fill(CGRect(x: 0, y: 0, width: width, height: 1800))
                var seed: UInt64 = 0x5F00_2A2A
                for y in stride(from: 8, to: 1790, by: 24) {
                    seed = seed &* 6364136223846793005
                        &+ 1442695040888963407
                    let inset = Int((seed >> 32) % 90)
                    c.setFillColor(CGColor(gray: 0.18, alpha: 1))
                    c.fill(CGRect(
                        x: 24 + inset, y: y,
                        width: 180 + Int((seed >> 40) % 150), height: 2))
                }
                return c.makeImage()!
            }()
            let retinaPositions = [0, 340, 680, 1020, 1060, 1100]
            if let first = fineDocument.cropping(to: CGRect(
                x: 0, y: 0, width: width, height: retinaViewport)) {
                let segmented = SegmentedVerticalStitcher(first: first, scale: 2)
                var promotedAt: Int?
                var successfulFrames = 0
                for position in retinaPositions.dropFirst() {
                    guard let frame = fineDocument.cropping(to: CGRect(
                        x: 0, y: position,
                        width: width, height: retinaViewport)) else { break }
                    switch segmented.append(frame) {
                    case .appended:
                        successfulFrames += 1
                    case .startedSegment:
                        successfulFrames += 1
                        promotedAt = position
                    case .prepended, .moved, .rejected:
                        break
                    }
                }
                check("stitch-small-retina-reanchor",
                      promotedAt == 1060 && successfulFrames >= 2
                        && segmented.segmentCount == 2,
                      "promotedAt \(promotedAt ?? -1), successes "
                        + "\(successfulFrames), segments \(segmented.segmentCount)")
                let expectedHeight = 400 + segmented.separatorRows + 480
                check("stitch-small-retina-reanchor-height",
                      segmented.totalHeight == expectedHeight
                        && segmented.compose()?.height == expectedHeight,
                      "got \(segmented.totalHeight), want \(expectedHeight)")
                if let upper = fineDocument.cropping(to: CGRect(
                       x: 0, y: 0, width: width, height: 400)),
                   let lower = fineDocument.cropping(to: CGRect(
                       x: 0, y: 1020, width: width, height: 480)),
                   let separator = segmented.segmentSeparator(),
                   let expected = expectedSegmentedImage(
                       upper: upper, separator: separator, lower: lower),
                   let actual = segmented.compose() {
                    check("stitch-small-retina-reanchor-marked-content",
                          imagesRoughlyEqual(expected, actual))
                } else {
                    check("stitch-small-retina-reanchor-compose", false)
                }
            } else {
                check("stitch-small-retina-reanchor-frame", false)
            }

            // Each re-anchored strip starts from a full viewport, so a fixed
            // navigation bar would otherwise be repeated after every visible
            // gap marker. Keep it on the first segment only; later segments
            // may trim it only after their own first transition proves it is
            // fixed chrome.
            let segmentedHeaderHeight = 60
            let segmentedHeaderBodyHeight = viewport - segmentedHeaderHeight
            let segmentedHeaderContent = makeStripePattern(
                width: width, height: 3000, seed: 0x5E67_AEAD)
            let segmentedHeaderBand = makeStripePattern(
                width: width, height: segmentedHeaderHeight,
                seed: 0xBAA0_AEAD)
            func segmentedHeaderFrame(
                offset: Int, band: CGImage
            ) -> CGImage? {
                guard let body = segmentedHeaderContent.cropping(to: CGRect(
                    x: 0, y: offset,
                    width: width, height: segmentedHeaderBodyHeight
                )) else { return nil }
                let c = ctx(width, viewport)
                c.draw(body, in: CGRect(
                    x: 0, y: 0,
                    width: width, height: segmentedHeaderBodyHeight))
                c.draw(band, in: CGRect(
                    x: 0, y: segmentedHeaderBodyHeight,
                    width: width, height: segmentedHeaderHeight))
                return c.makeImage()
            }
            let segmentedHeaderPositions = [
                0, 200, 2000, 2041, 2083, 2126, 2170,
            ]
            if let first = segmentedHeaderFrame(
                offset: segmentedHeaderPositions[0],
                band: segmentedHeaderBand) {
                let segmented = SegmentedVerticalStitcher(first: first)
                for position in segmentedHeaderPositions.dropFirst() {
                    if let frame = segmentedHeaderFrame(
                        offset: position, band: segmentedHeaderBand) {
                        _ = segmented.append(frame)
                    }
                }
                let upperBodyHeight = segmentedHeaderBodyHeight + 200
                let lowerBodyHeight = segmentedHeaderBodyHeight + 170
                let upper = ctx(
                    width, upperBodyHeight + segmentedHeaderHeight)
                if let upperBody = segmentedHeaderContent.cropping(to: CGRect(
                       x: 0, y: 0,
                       width: width, height: upperBodyHeight)),
                   let lower = segmentedHeaderContent.cropping(to: CGRect(
                       x: 0, y: 2000,
                       width: width, height: lowerBodyHeight)),
                   let separator = segmented.segmentSeparator() {
                    upper.draw(upperBody, in: CGRect(
                        x: 0, y: 0,
                        width: width, height: upperBodyHeight))
                    upper.draw(segmentedHeaderBand, in: CGRect(
                        x: 0, y: upperBodyHeight,
                        width: width, height: segmentedHeaderHeight))
                    if let upperImage = upper.makeImage(),
                       let expected = expectedSegmentedImage(
                           upper: upperImage,
                           separator: separator,
                           lower: lower),
                       let actual = segmented.compose() {
                        let expectedHeight = upperBodyHeight
                            + segmentedHeaderHeight
                            + segmented.separatorRows + lowerBodyHeight
                        check("stitch-segment-header-only-on-first-segment",
                              segmented.segmentCount == 2
                                && segmented.currentSegment.headerRows
                                    == segmentedHeaderHeight
                                && imagesRoughlyEqual(expected, actual),
                              "segments \(segmented.segmentCount), header "
                                + "\(segmented.currentSegment.headerRows)")
                        check("stitch-segment-header-height",
                              segmented.totalHeight == expectedHeight
                                && actual.height == expectedHeight,
                              "total \(segmented.totalHeight), image \(actual.height), "
                                + "want \(expectedHeight)")
                    } else {
                        check("stitch-segment-header-compose", false)
                    }
                } else {
                    check("stitch-segment-header-crops", false)
                }
            } else {
                check("stitch-segment-header-frame", false)
            }

            // Local stability does not mean duplicate chrome. If the first
            // segment had no header, a stable header introduced later is page
            // content and must be retained in full.
            if let first = segmentedHeaderContent.cropping(to: CGRect(
                   x: 0, y: 0, width: width, height: viewport)),
               let second = segmentedHeaderContent.cropping(to: CGRect(
                   x: 0, y: 200, width: width, height: viewport)) {
                let segmented = SegmentedVerticalStitcher(first: first)
                _ = segmented.append(second)
                for position in segmentedHeaderPositions.dropFirst(2) {
                    if let frame = segmentedHeaderFrame(
                        offset: position, band: segmentedHeaderBand) {
                        _ = segmented.append(frame)
                    }
                }
                let upperHeight = viewport + 200
                let lowerBodyHeight = segmentedHeaderBodyHeight + 170
                let lower = ctx(
                    width, lowerBodyHeight + segmentedHeaderHeight)
                if let upper = segmentedHeaderContent.cropping(to: CGRect(
                       x: 0, y: 0, width: width, height: upperHeight)),
                   let body = segmentedHeaderContent.cropping(to: CGRect(
                       x: 0, y: 2000,
                       width: width, height: lowerBodyHeight)),
                   let separator = segmented.segmentSeparator() {
                    lower.draw(body, in: CGRect(
                        x: 0, y: 0,
                        width: width, height: lowerBodyHeight))
                    lower.draw(segmentedHeaderBand, in: CGRect(
                        x: 0, y: lowerBodyHeight,
                        width: width, height: segmentedHeaderHeight))
                    if let lowerImage = lower.makeImage(),
                       let expected = expectedSegmentedImage(
                           upper: upper,
                           separator: separator,
                           lower: lowerImage),
                       let actual = segmented.compose() {
                        check("stitch-segment-later-new-header-retained",
                              segmented.segmentCount == 2
                                && imagesRoughlyEqual(expected, actual),
                              "later header was removed")
                    } else {
                        check("stitch-segment-later-new-header-compose", false)
                    }
                } else {
                    check("stitch-segment-later-new-header-crops", false)
                }
            } else {
                check("stitch-segment-later-new-header-frames", false)
            }

            // Two locally fixed headers can name different sections. Keep the
            // later one unless its raw raster and height match the canonical
            // header retained from segment one.
            let differentHeaderBand = makeStripePattern(
                width: width, height: segmentedHeaderHeight,
                seed: 0xD1FF_AEAD)
            if let first = segmentedHeaderFrame(
                   offset: 0, band: segmentedHeaderBand),
               let second = segmentedHeaderFrame(
                   offset: 200, band: segmentedHeaderBand) {
                let segmented = SegmentedVerticalStitcher(first: first)
                _ = segmented.append(second)
                for position in segmentedHeaderPositions.dropFirst(2) {
                    if let frame = segmentedHeaderFrame(
                        offset: position, band: differentHeaderBand) {
                        _ = segmented.append(frame)
                    }
                }
                let upperBodyHeight = segmentedHeaderBodyHeight + 200
                let lowerBodyHeight = segmentedHeaderBodyHeight + 170
                let upper = ctx(
                    width, upperBodyHeight + segmentedHeaderHeight)
                let lower = ctx(
                    width, lowerBodyHeight + segmentedHeaderHeight)
                if let upperBody = segmentedHeaderContent.cropping(to: CGRect(
                       x: 0, y: 0,
                       width: width, height: upperBodyHeight)),
                   let lowerBody = segmentedHeaderContent.cropping(to: CGRect(
                       x: 0, y: 2000,
                       width: width, height: lowerBodyHeight)),
                   let separator = segmented.segmentSeparator() {
                    upper.draw(upperBody, in: CGRect(
                        x: 0, y: 0,
                        width: width, height: upperBodyHeight))
                    upper.draw(segmentedHeaderBand, in: CGRect(
                        x: 0, y: upperBodyHeight,
                        width: width, height: segmentedHeaderHeight))
                    lower.draw(lowerBody, in: CGRect(
                        x: 0, y: 0,
                        width: width, height: lowerBodyHeight))
                    lower.draw(differentHeaderBand, in: CGRect(
                        x: 0, y: lowerBodyHeight,
                        width: width, height: segmentedHeaderHeight))
                    if let upperImage = upper.makeImage(),
                       let lowerImage = lower.makeImage(),
                       let expected = expectedSegmentedImage(
                           upper: upperImage,
                           separator: separator,
                           lower: lowerImage),
                       let actual = segmented.compose() {
                        check("stitch-segment-different-header-retained",
                              segmented.segmentCount == 2
                                && imagesRoughlyEqual(expected, actual),
                              "different later header was removed")
                    } else {
                        check("stitch-segment-different-header-compose", false)
                    }
                } else {
                    check("stitch-segment-different-header-crops", false)
                }
            } else {
                check("stitch-segment-different-header-frames", false)
            }

            // De-duplication is optional, so its identity proof is byte-exact
            // over the full width. A tiny meaningful glyph/badge change in the
            // middle or at the edge must fail closed and retain the new header.
            let tinyCenterContext = ctx(width, segmentedHeaderHeight)
            tinyCenterContext.draw(segmentedHeaderBand, in: CGRect(
                x: 0, y: 0,
                width: width, height: segmentedHeaderHeight))
            tinyCenterContext.setFillColor(CGColor(
                srgbRed: 1, green: 0, blue: 1, alpha: 1))
            tinyCenterContext.fill(CGRect(
                x: width / 2, y: segmentedHeaderHeight / 2,
                width: 2, height: 2))
            let tinyEdgeContext = ctx(width, segmentedHeaderHeight)
            tinyEdgeContext.draw(segmentedHeaderBand, in: CGRect(
                x: 0, y: 0,
                width: width, height: segmentedHeaderHeight))
            tinyEdgeContext.setFillColor(CGColor(
                srgbRed: 1, green: 0, blue: 1, alpha: 1))
            tinyEdgeContext.fill(CGRect(
                x: 1, y: segmentedHeaderHeight / 2,
                width: 2, height: 2))
            if let tinyCenterBand = tinyCenterContext.makeImage(),
               let tinyEdgeBand = tinyEdgeContext.makeImage(),
               let canonicalFirst = segmentedHeaderFrame(
                   offset: 0, band: segmentedHeaderBand),
               let canonicalNext = segmentedHeaderFrame(
                   offset: 41, band: segmentedHeaderBand),
               let centerFirst = segmentedHeaderFrame(
                   offset: 2000, band: tinyCenterBand),
               let centerNext = segmentedHeaderFrame(
                   offset: 2041, band: tinyCenterBand),
               let edgeFirst = segmentedHeaderFrame(
                   offset: 2000, band: tinyEdgeBand),
               let edgeNext = segmentedHeaderFrame(
                   offset: 2041, band: tinyEdgeBand) {
                let canonical = VerticalStitcher(first: canonicalFirst)
                let center = VerticalStitcher(first: centerFirst)
                let edge = VerticalStitcher(first: edgeFirst)
                _ = canonical.append(canonicalNext)
                _ = center.append(centerNext)
                _ = edge.append(edgeNext)
                if let reference = canonical.topRowsImage(
                    rows: canonical.headerRows) {
                    check("stitch-segment-tiny-center-header-change-retained",
                          canonical.headerRows == segmentedHeaderHeight
                            && center.headerRows == segmentedHeaderHeight
                            && !center.topRowsMatch(
                                reference, rows: center.headerRows))
                    check("stitch-segment-tiny-edge-header-change-retained",
                          edge.headerRows == segmentedHeaderHeight
                            && !edge.topRowsMatch(
                                reference, rows: edge.headerRows))
                } else {
                    check("stitch-segment-tiny-header-reference", false)
                }
            } else {
                check("stitch-segment-tiny-header-frames", false)
            }

            // A sticky composer belongs only at the bottom of the final page,
            // not before every marked segment boundary.
            let footerViewport = 500, footerHeight = 60
            let footerBodyHeight = footerViewport - footerHeight
            let footerContent = makeStripePattern(
                width: width, height: 3000, seed: 0x5E67_F007)
            let footerBand = makeStripePattern(
                width: width, height: footerHeight, seed: 0xBAA0_F007)
            func segmentedFooterFrame(offset: Int) -> CGImage? {
                guard let body = footerContent.cropping(to: CGRect(
                    x: 0, y: offset,
                    width: width, height: footerBodyHeight)) else { return nil }
                let c = ctx(width, footerViewport)
                c.draw(footerBand, in: CGRect(
                    x: 0, y: 0, width: width, height: footerHeight))
                c.draw(body, in: CGRect(
                    x: 0, y: footerHeight,
                    width: width, height: footerBodyHeight))
                return c.makeImage()
            }
            let footerPositions = [0, 200, 2000, 2040, 2080, 2120, 2160]
            if let first = segmentedFooterFrame(offset: footerPositions[0]) {
                let segmented = SegmentedVerticalStitcher(first: first)
                for position in footerPositions.dropFirst() {
                    if let frame = segmentedFooterFrame(offset: position) {
                        _ = segmented.append(frame)
                    }
                }
                let upperBodyHeight = footerBodyHeight + 200
                let lowerBodyHeight = footerBodyHeight + 160
                let lower = ctx(width, lowerBodyHeight + footerHeight)
                if let body = footerContent.cropping(to: CGRect(
                    x: 0, y: 2000,
                    width: width, height: lowerBodyHeight)) {
                    lower.draw(footerBand, in: CGRect(
                        x: 0, y: 0, width: width, height: footerHeight))
                    lower.draw(body, in: CGRect(
                        x: 0, y: footerHeight,
                        width: width, height: lowerBodyHeight))
                }
                if let upper = footerContent.cropping(to: CGRect(
                       x: 0, y: 0,
                       width: width, height: upperBodyHeight)),
                   let separator = segmented.segmentSeparator(),
                   let lowerImage = lower.makeImage(),
                   let expected = expectedSegmentedImage(
                       upper: upper, separator: separator, lower: lowerImage),
                   let actual = segmented.compose() {
                    check("stitch-segment-footer-only-on-final-segment",
                          segmented.segmentCount == 2
                            && imagesRoughlyEqual(expected, actual),
                          "segments \(segmented.segmentCount), footer duplicated")
                    check("stitch-segment-footer-height",
                          actual.height == upperBodyHeight
                            + segmented.separatorRows
                            + lowerBodyHeight + footerHeight,
                          "got \(actual.height)")
                } else {
                    check("stitch-segment-footer-compose", false)
                }
            } else {
                check("stitch-segment-footer-frame", false)
            }

            // The gap can happen immediately after the first frame, before
            // the old segment has an accepted transition from which to latch
            // its footer. The proven footer on the new segment may infer and
            // trim the matching bottom band from that one-frame segment, but
            // it must still appear exactly once at the final page bottom.
            let immediateFooterPositions = [0, 2000, 2040, 2080, 2120, 2160]
            if let first = segmentedFooterFrame(
                offset: immediateFooterPositions[0]) {
                let segmented = SegmentedVerticalStitcher(first: first)
                for position in immediateFooterPositions.dropFirst() {
                    if let frame = segmentedFooterFrame(offset: position) {
                        _ = segmented.append(frame)
                    }
                }
                let lowerBodyHeight = footerBodyHeight + 160
                let lower = ctx(width, lowerBodyHeight + footerHeight)
                if let upper = footerContent.cropping(to: CGRect(
                       x: 0, y: 0,
                       width: width, height: footerBodyHeight)),
                   let body = footerContent.cropping(to: CGRect(
                       x: 0, y: 2000,
                       width: width, height: lowerBodyHeight)),
                   let separator = segmented.segmentSeparator() {
                    lower.draw(footerBand, in: CGRect(
                        x: 0, y: 0, width: width, height: footerHeight))
                    lower.draw(body, in: CGRect(
                        x: 0, y: footerHeight,
                        width: width, height: lowerBodyHeight))
                    if let lowerImage = lower.makeImage(),
                       let expected = expectedSegmentedImage(
                           upper: upper,
                           separator: separator,
                           lower: lowerImage),
                       let actual = segmented.compose() {
                        check("stitch-segment-first-frame-footer-only-final",
                              segmented.segmentCount == 2
                                && imagesRoughlyEqual(expected, actual),
                              "segments \(segmented.segmentCount), footer duplicated")
                        check("stitch-segment-first-frame-footer-height",
                              actual.height == footerBodyHeight
                                + segmented.separatorRows
                                + lowerBodyHeight + footerHeight,
                              "got \(actual.height)")
                    } else {
                        check("stitch-segment-first-frame-footer-compose", false)
                    }
                } else {
                    check("stitch-segment-first-frame-footer-crops", false)
                }
            } else {
                check("stitch-segment-first-frame-footer-frame", false)
            }

            // Inference may delete rows, so local footer similarity is not
            // enough. A tiny edge badge/change in a footer-like one-frame page
            // tail must make the cross-segment proof fail closed and preserve
            // that entire first viewport.
            let changedFooterContext = ctx(width, footerHeight)
            changedFooterContext.draw(footerBand, in: CGRect(
                x: 0, y: 0, width: width, height: footerHeight))
            changedFooterContext.setFillColor(CGColor(
                srgbRed: 1, green: 0, blue: 1, alpha: 1))
            changedFooterContext.fill(CGRect(
                x: 1, y: footerHeight / 2, width: 2, height: 2))
            if let changedFooterBand = changedFooterContext.makeImage(),
               let firstBody = footerContent.cropping(to: CGRect(
                   x: 0, y: 0,
                   width: width, height: footerBodyHeight)) {
                let firstContext = ctx(width, footerViewport)
                firstContext.draw(changedFooterBand, in: CGRect(
                    x: 0, y: 0, width: width, height: footerHeight))
                firstContext.draw(firstBody, in: CGRect(
                    x: 0, y: footerHeight,
                    width: width, height: footerBodyHeight))
                if let first = firstContext.makeImage() {
                    let segmented = SegmentedVerticalStitcher(first: first)
                    for position in immediateFooterPositions.dropFirst() {
                        if let frame = segmentedFooterFrame(offset: position) {
                            _ = segmented.append(frame)
                        }
                    }
                    let lowerBodyHeight = footerBodyHeight + 160
                    let lower = ctx(width, lowerBodyHeight + footerHeight)
                    if let body = footerContent.cropping(to: CGRect(
                           x: 0, y: 2000,
                           width: width, height: lowerBodyHeight)),
                       let separator = segmented.segmentSeparator() {
                        lower.draw(footerBand, in: CGRect(
                            x: 0, y: 0,
                            width: width, height: footerHeight))
                        lower.draw(body, in: CGRect(
                            x: 0, y: footerHeight,
                            width: width, height: lowerBodyHeight))
                        if let lowerImage = lower.makeImage(),
                           let expected = expectedSegmentedImage(
                               upper: first,
                               separator: separator,
                               lower: lowerImage),
                           let actual = segmented.compose() {
                            check("stitch-segment-tiny-footer-change-retained",
                                  segmented.segmentCount == 2
                                    && imagesRoughlyEqual(expected, actual),
                                  "footer-like first-frame tail was removed")
                            check("stitch-segment-tiny-footer-change-height",
                                  actual.height == footerViewport
                                    + segmented.separatorRows
                                    + lowerBodyHeight + footerHeight,
                                  "got \(actual.height)")
                        } else {
                            check("stitch-segment-tiny-footer-change-compose", false)
                        }
                    } else {
                        check("stitch-segment-tiny-footer-change-crops", false)
                    }
                } else {
                    check("stitch-segment-tiny-footer-change-first", false)
                }
            } else {
                check("stitch-segment-tiny-footer-change-band", false)
            }

            // Footer inference is safe only for a segment that never accepted
            // an append. Here the old multi-frame segment has no footer, but
            // its LAST viewport happens to end in the exact band later used as
            // a sticky footer. Trimming that band from its FIRST viewport would
            // delete unrelated page rows, so the entire old segment must stay.
            if let lateFooterBand = footerContent.cropping(to: CGRect(
                x: 0, y: 640, width: width, height: footerHeight
            )) {
                func lateFooterFrame(offset: Int) -> CGImage? {
                    guard let body = footerContent.cropping(to: CGRect(
                        x: 0, y: offset,
                        width: width, height: footerBodyHeight)) else {
                        return nil
                    }
                    let c = ctx(width, footerViewport)
                    c.draw(lateFooterBand, in: CGRect(
                        x: 0, y: 0,
                        width: width, height: footerHeight))
                    c.draw(body, in: CGRect(
                        x: 0, y: footerHeight,
                        width: width, height: footerBodyHeight))
                    return c.makeImage()
                }
                if let first = footerContent.cropping(to: CGRect(
                       x: 0, y: 0, width: width, height: footerViewport)),
                   let second = footerContent.cropping(to: CGRect(
                       x: 0, y: 200, width: width, height: footerViewport)) {
                    let segmented = SegmentedVerticalStitcher(first: first)
                    _ = segmented.append(second)
                    for position in [2000, 2040, 2080, 2120, 2160] {
                        if let frame = lateFooterFrame(offset: position) {
                            _ = segmented.append(frame)
                        }
                    }
                    let upperHeight = footerViewport + 200
                    let lowerBodyHeight = footerBodyHeight + 160
                    let lower = ctx(width, lowerBodyHeight + footerHeight)
                    if let upper = footerContent.cropping(to: CGRect(
                           x: 0, y: 0,
                           width: width, height: upperHeight)),
                       let body = footerContent.cropping(to: CGRect(
                           x: 0, y: 2000,
                           width: width, height: lowerBodyHeight)),
                       let separator = segmented.segmentSeparator() {
                        lower.draw(lateFooterBand, in: CGRect(
                            x: 0, y: 0,
                            width: width, height: footerHeight))
                        lower.draw(body, in: CGRect(
                            x: 0, y: footerHeight,
                            width: width, height: lowerBodyHeight))
                        if let lowerImage = lower.makeImage(),
                           let expected = expectedSegmentedImage(
                               upper: upper,
                               separator: separator,
                               lower: lowerImage),
                           let actual = segmented.compose() {
                            check("stitch-segment-no-false-footer-inference",
                                  segmented.segmentCount == 2
                                    && imagesRoughlyEqual(expected, actual),
                                  "segments \(segmented.segmentCount), old rows trimmed")
                            check("stitch-segment-no-false-footer-height",
                                  actual.height == upperHeight
                                    + segmented.separatorRows
                                    + lowerBodyHeight + footerHeight,
                                  "got \(actual.height)")
                        } else {
                            check("stitch-segment-no-false-footer-compose", false)
                        }
                    } else {
                        check("stitch-segment-no-false-footer-crops", false)
                    }
                } else {
                    check("stitch-segment-no-false-footer-active-frames", false)
                }
            } else {
                check("stitch-segment-no-false-footer-band", false)
            }

            // Unrelated/ambiguous frames must never turn into a segment merely
            // because four rejects elapsed.
            let unrelatedFirst = makeSolidImage(
                width: width, height: viewport, color: NSColor.red.cgColor)
            let unrelated = SegmentedVerticalStitcher(first: unrelatedFirst)
            let colors: [NSColor] = [
                .blue, .green, .yellow, .purple, .orange, .brown,
            ]
            for color in colors {
                _ = unrelated.append(makeSolidImage(
                    width: width, height: viewport, color: color.cgColor))
            }
            check("stitch-unproven-segment-not-promoted",
                  unrelated.segmentCount == 1
                    && unrelated.compose()?.height == viewport,
                  "segments \(unrelated.segmentCount)")

            let periodic = makePeriodicPattern(
                width: width, height: 1300, period: 37)
            if let p0 = periodic.cropping(to: CGRect(
                x: 0, y: 0, width: width, height: viewport)) {
                let ambiguous = SegmentedVerticalStitcher(first: p0)
                for position in [100, 200, 300, 400, 500, 600] {
                    if let frame = periodic.cropping(to: CGRect(
                        x: 0, y: position, width: width, height: viewport)) {
                        _ = ambiguous.append(frame)
                    }
                }
                check("stitch-ambiguous-segment-not-promoted",
                      ambiguous.segmentCount == 1,
                      "segments \(ambiguous.segmentCount)")
            } else {
                check("stitch-ambiguous-segment-frame", false)
            }

            // A later match against the active strip cancels an uncommitted
            // candidate, and a geometry error does not advance the reject gate.
            if let active0 = document.cropping(to: CGRect(
                x: 0, y: 0, width: width, height: viewport)),
               let active100 = document.cropping(to: CGRect(
                x: 0, y: 100, width: width, height: viewport)) {
                let resumed = SegmentedVerticalStitcher(first: active0)
                for color in [NSColor.blue, .green, .yellow] {
                    _ = resumed.append(makeSolidImage(
                        width: width, height: viewport, color: color.cgColor))
                }
                let outcome = resumed.append(active100)
                let resumedRows: Int
                if case let .appended(rows) = outcome { resumedRows = rows }
                else { resumedRows = 0 }
                _ = resumed.append(makeSolidImage(
                    width: width + 1, height: viewport,
                    color: NSColor.black.cgColor))
                check("stitch-active-resume-cancels-pending",
                      resumedRows == 100 && resumed.segmentCount == 1
                        && resumed.consecutiveRejects == 0,
                      "rows \(resumedRows), segments \(resumed.segmentCount), "
                        + "rejects \(resumed.consecutiveRejects)")
            } else {
                check("stitch-active-resume-frame", false)
            }
        }

        // 2i. capture backend fallback state ---------------------------------------
        // A transient sourceRect error must keep the fast path. Three consecutive
        // failures switch once to full-display crop without discarding content
        // already stitched from sourceRect (both backends produce the same pixel
        // geometry; append's size/confidence guards still reject a bad frame).
        do {
            var backend = ScrollingCapture.CaptureBackend.sourceRect
            check("scroll-fallback-transient-keeps-fast-path",
                  !backend.switchToFallback(afterConsecutiveFailures: 2)
                  && backend == .sourceRect)
            let switched = backend.switchToFallback(afterConsecutiveFailures: 3)
            check("scroll-fallback-after-three-errors", switched && backend == .fullDisplayCrop)

            // `screenRect` is attached to the same ScreenCaptureKit frame as
            // the pixels. Include a negative-origin display to catch accidental
            // NSScreen/global-coordinate assumptions on multi-monitor Macs.
            let requested = ValidatedRectCapture.requestedScreenRect(
                displayFrame: CGRect(x: -1728, y: 240, width: 1728, height: 1117),
                sourceRect: CGRect(x: 125, y: 210, width: 500, height: 400))
            check("scroll-sourcerect-metadata-global-origin",
                  requested == CGRect(x: -1603, y: 450, width: 500, height: 400),
                  "got \(requested)")
            check("scroll-sourcerect-metadata-valid",
                  ValidatedRectCapture.matches(
                    CGRect(x: -1602.5, y: 449.5, width: 500, height: 400),
                    requested: requested))
            check("scroll-sourcerect-success-wrong-region-rejected",
                  !ValidatedRectCapture.matches(
                    CGRect(x: -1478, y: 450, width: 500, height: 400),
                    requested: requested))
            check("scroll-sourcerect-missing-metadata-rejected",
                  !ValidatedRectCapture.matches(nil, requested: requested))

            // Canonicalize a fractional @2x selection once. Both SCK output
            // and a full-display fallback must use this exact 801x601 bitmap,
            // rather than independently rounding to 800/801 pixels.
            let fractionalRegion = CanonicalCaptureRegion(
                screenSize: CGSize(width: 1440, height: 900),
                viewRect: CGRect(x: 100.25, y: 80.25, width: 400.1, height: 300.1),
                scale: 2)
            check("scroll-canonical-fractional-2x-size",
                  fractionalRegion?.pixelWidth == 801
                  && fractionalRegion?.pixelHeight == 601,
                  "got \(String(describing: fractionalRegion?.pixelRect))")
            check("scroll-canonical-fractional-2x-source-size",
                  fractionalRegion.map {
                    Int(($0.sourceRect.width * $0.scale).rounded()) == $0.pixelWidth
                    && Int(($0.sourceRect.height * $0.scale).rounded()) == $0.pixelHeight
                  } ?? false)

            if let fractionalRegion {
                let full = makeStripePattern(
                    width: 2880, height: 1800, seed: 0xCA90_21CA)
                let captured = CapturedImage(cgImage: full, scale: 2)
                check("scroll-canonical-fallback-crop-size",
                      captured.cropping(to: fractionalRegion).map {
                        $0.cgImage.width == fractionalRegion.pixelWidth
                        && $0.cgImage.height == fractionalRegion.pixelHeight
                      } ?? false)
            }

            let content = makeStripePattern(width: 200, height: 900, seed: 0xFA11_BACC)
            if let f0 = content.cropping(to: CGRect(x: 0, y: 0, width: 200, height: 400)),
               let f1 = content.cropping(to: CGRect(x: 0, y: 120, width: 200, height: 400)),
               let f2 = content.cropping(to: CGRect(x: 0, y: 240, width: 200, height: 400)) {
                let retained = VerticalStitcher(first: f0)
                _ = retained.append(f1) // content accumulated on sourceRect
                check("scroll-fallback-overlap-handshake",
                      ScrollingCapture.validateBackendTransition(
                        stitcher: retained, frame: f2))
                _ = retained.append(f2) // first validated full-crop frame
                check("scroll-fallback-retains-accumulated-content",
                      retained.totalHeight == 640, "got \(retained.totalHeight), want 640")
                if let f3 = content.cropping(to: CGRect(
                    x: 0, y: 360, width: 200, height: 400)) {
                    let continued = retained.append(f3).newRows
                    check("scroll-fallback-continues-after-switch", continued == 120,
                          "appended \(continued), want 120")
                    check("scroll-fallback-continued-height", retained.totalHeight == 760,
                          "got \(retained.totalHeight), want 760")
                } else {
                    check("scroll-fallback-continuation-frame", false)
                }

                let unrelated = makeStripePattern(
                    width: 200, height: 400, seed: 0xBAD0_C00D)
                check("scroll-fallback-wrong-region-not-mixed",
                      !ScrollingCapture.validateBackendTransition(
                        stitcher: retained, frame: unrelated))
                if let wrongGeometry = unrelated.cropping(to: CGRect(
                    x: 0, y: 0, width: 199, height: 400)) {
                    check("scroll-fallback-geometry-not-mixed",
                          !ScrollingCapture.validateBackendTransition(
                            stitcher: retained, frame: wrongGeometry))
                } else {
                    check("scroll-fallback-geometry-frame", false)
                }

                // If the three sourceRect failures coincide with a flick, the
                // first full-crop frame may no longer overlap the old baseline.
                // Two mutually consistent fallback frames must start a marked
                // segment instead of leaving the backend handshake stuck.
                let switchedContent = makeStripePattern(
                    width: 200, height: 1600, seed: 0xFA11_5E67)
                if let a0 = switchedContent.cropping(to: CGRect(
                       x: 0, y: 0, width: 200, height: 400)),
                   let a100 = switchedContent.cropping(to: CGRect(
                       x: 0, y: 100, width: 200, height: 400)),
                   let b720 = switchedContent.cropping(to: CGRect(
                       x: 0, y: 720, width: 200, height: 400)),
                   let b760 = switchedContent.cropping(to: CGRect(
                       x: 0, y: 760, width: 200, height: 400)),
                   let b800 = switchedContent.cropping(to: CGRect(
                       x: 0, y: 800, width: 200, height: 400)),
                   let b840 = switchedContent.cropping(to: CGRect(
                       x: 0, y: 840, width: 200, height: 400)) {
                    let segmented = SegmentedVerticalStitcher(first: a0)
                    _ = segmented.append(a100)
                    // Leave a proven-but-uncommitted sourceRect candidate in
                    // place. Switching backends must discard it; otherwise a
                    // single fallback frame could complete a mixed-backend
                    // segment and be promoted without fallback-only proof.
                    let oldPendingFirst = segmented.append(b720)
                    let oldPendingSecond = segmented.append(b760)
                    let oldPendingStayedUncommitted: Bool
                    if case .rejected = oldPendingFirst,
                       case .rejected = oldPendingSecond {
                        oldPendingStayedUncommitted = segmented.segmentCount == 1
                    } else {
                        oldPendingStayedUncommitted = false
                    }
                    segmented.prepareForBackendTransition()
                    check("scroll-fallback-lost-overlap-detected",
                          !ScrollingCapture.validateBackendTransition(
                            stitcher: segmented.currentSegment, frame: b800))
                    let firstFallback = segmented
                        .appendBackendTransitionFrame(b800)
                    let secondFallback = segmented
                        .appendBackendTransitionFrame(b840)
                    let firstWasPending: Bool
                    if case .rejected = firstFallback { firstWasPending = true }
                    else { firstWasPending = false }
                    let secondStarted: Bool
                    if case .startedSegment = secondFallback {
                        secondStarted = true
                    } else {
                        secondStarted = false
                    }
                    let expectedHeight = 500 + segmented.separatorRows + 440
                    check("scroll-fallback-reanchors-proven-segment",
                          oldPendingStayedUncommitted
                            && firstWasPending && secondStarted
                            && segmented.segmentCount == 2
                            && segmented.totalHeight == expectedHeight,
                          "segments \(segmented.segmentCount), height "
                            + "\(segmented.totalHeight), want \(expectedHeight)")
                    check("scroll-fallback-reanchor-compose",
                          segmented.compose()?.height == expectedHeight)
                } else {
                    check("scroll-fallback-reanchor-frames", false)
                }
            } else {
                check("scroll-fallback-retains-frames", false)
            }
            check("scroll-fallback-switches-once",
                  !backend.switchToFallback(afterConsecutiveFailures: 4))
        }

        // 2f. Editable capture/crop selection geometry -----------------------------
        // Both the full-screen overlay and editor crop UI use these helpers.
        let selectionBounds = CGRect(x: 0, y: 0, width: 1000, height: 700)
        let initialSelection = EditableSelectionGeometry.rect(
            from: CGPoint(x: 500, y: 500),
            to: CGPoint(x: 100, y: 120),
            within: selectionBounds
        )
        check("selection-normalizes-reverse-drag",
              initialSelection == CGRect(x: 100, y: 120, width: 400, height: 380))
        let movedSelection = EditableSelectionGeometry.moved(
            initialSelection,
            by: CGPoint(x: 900, y: -400),
            within: selectionBounds
        )
        check("selection-move-clamps",
              movedSelection == CGRect(x: 600, y: 0, width: 400, height: 380),
              "got \(movedSelection)")
        let resizedSelection = EditableSelectionGeometry.resized(
            initialSelection,
            using: .topRight,
            to: CGPoint(x: 1200, y: 900),
            within: selectionBounds
        )
        check("selection-resize-clamps",
              resizedSelection == CGRect(x: 100, y: 120, width: 900, height: 580),
              "got \(resizedSelection)")
        check("selection-handle-hit",
              EditableSelectionGeometry.handle(
                at: CGPoint(x: initialSelection.maxX + 3, y: initialSelection.maxY - 2),
                in: initialSelection
              ) == .topRight)

        // Corner handles sit on the 45° point of the plate arc so the
        // square does not cover the cut. Radius 0 is the eight centres
        // selection-handle-hit already uses. Mid-edge handles never
        // move. Hit size stays 18; shrink is the drawn square only.
        let insetCrop = CGRect(x: 100, y: 80, width: 200, height: 150)
        let insetBaseline = EditableSelectionGeometry.handleRects(
            for: insetCrop, size: 18)
        let insetZero = EditableSelectionGeometry.handleRects(
            for: insetCrop, size: 18, cornerRadius: 0)
        var insetFails: [String] = []
        if insetBaseline.count != 8 {
            insetFails.append("expected 8 handles, got \(insetBaseline.count)")
        }
        for (got, want) in zip(insetBaseline, insetZero)
        where got.0 != want.0 || got.1 != want.1 {
            insetFails.append("radius 0 moved \(got.0)")
        }
        for (handle, rect) in insetBaseline {
            let centre = CGPoint(x: rect.midX, y: rect.midY)
            if EditableSelectionGeometry.handle(
                at: centre, in: insetCrop, tolerance: 9
            ) != handle {
                insetFails.append("radius 0 \(handle) no longer grabs itself")
            }
        }
        let insetRadius: CGFloat = 37
        let insetD = EditableSelectionGeometry.cornerInset(forRadius: insetRadius)
        let insetRects = EditableSelectionGeometry.handleRects(
            for: insetCrop, size: 18, cornerRadius: insetRadius)
        func insetCentre(_ rect: CGRect) -> CGPoint {
            CGPoint(x: rect.midX, y: rect.midY)
        }
        func insetDist(_ a: CGPoint, _ b: CGPoint) -> CGFloat {
            hypot(a.x - b.x, a.y - b.y)
        }
        let insetBaseByHandle = Dictionary(
            uniqueKeysWithValues: insetBaseline.map { ($0.0, $0.1) })
        let insetByHandle = Dictionary(
            uniqueKeysWithValues: insetRects.map { ($0.0, $0.1) })
        let insetCorners: [SelectionHandle] = [
            .bottomLeft, .bottomRight, .topLeft, .topRight,
        ]
        let insetEdges: [SelectionHandle] = [.bottom, .top, .left, .right]
        for handle in insetEdges {
            guard let moved = insetByHandle[handle],
                  let base = insetBaseByHandle[handle] else {
                insetFails.append("missing mid-edge \(handle)"); continue
            }
            if insetDist(insetCentre(moved), insetCentre(base)) > 0.01 {
                insetFails.append("mid-edge \(handle) moved")
            }
            if abs(moved.width - 18) > 0.01 {
                insetFails.append("hit \(handle) shrank to \(moved.width)")
            }
        }
        let insetWant: [SelectionHandle: (CGFloat, CGFloat)] = [
            .bottomLeft: (insetD, insetD),
            .topLeft: (insetD, -insetD),
            .bottomRight: (-insetD, insetD),
            .topRight: (-insetD, -insetD),
        ]
        for handle in insetCorners {
            guard let moved = insetByHandle[handle],
                  let base = insetBaseByHandle[handle],
                  let delta = insetWant[handle] else {
                insetFails.append("missing corner \(handle)"); continue
            }
            let got = insetCentre(moved)
            let expect = CGPoint(
                x: insetCentre(base).x + delta.0,
                y: insetCentre(base).y + delta.1)
            if insetDist(got, expect) > 0.01 {
                insetFails.append("corner \(handle): \(got) want \(expect)")
            }
            if abs(moved.width - 18) > 0.01 {
                insetFails.append("hit corner \(handle) shrank to \(moved.width)")
            }
            if EditableSelectionGeometry.handle(
                at: got, in: insetCrop, tolerance: 9,
                cornerRadius: insetRadius
            ) != handle {
                insetFails.append("inset \(handle) does not grab itself")
            }
            if EditableSelectionGeometry.handle(
                at: insetCentre(base), in: insetCrop, tolerance: 9,
                cornerRadius: insetRadius
            ) == handle {
                insetFails.append("geometric \(handle) still grabs")
            }
        }
        // Drawn 8 pt square on Medium floor 12 → d ≈ 3.51: 4 > d so the
        // square shrinks to 2d (floor 5). Size 7 does not (3.5 < d) —
        // that is the production draw size, covered by the owner case
        // below. Centres stay on the arc.
        let floorR: CGFloat = 12
        let floorD = EditableSelectionGeometry.cornerInset(forRadius: floorR)
        let drawn = EditableSelectionGeometry.handleRects(
            for: insetCrop, size: 8, cornerRadius: floorR, shrinkToArc: true)
        let wantVisual = max(5 as CGFloat, 2 * floorD)
        let drawnByHandle = Dictionary(
            uniqueKeysWithValues: drawn.map { ($0.0, $0.1) })
        for handle in insetCorners {
            guard let rect = drawnByHandle[handle] else { continue }
            if abs(rect.width - wantVisual) > 0.01 {
                insetFails.append(
                    "visual \(handle) size \(rect.width) want \(wantVisual)")
            }
        }
        for handle in insetEdges {
            guard let rect = drawnByHandle[handle] else { continue }
            if abs(rect.width - 8) > 0.01 {
                insetFails.append("visual mid-edge \(handle) shrank to \(rect.width)")
            }
        }
        // Owner-sized crop, Medium 37 pt: 7/2 < d, so the square stays 7.
        let ownerCrop = CGRect(x: 0, y: 0, width: 2400, height: 1523)
        let ownerDrawn = EditableSelectionGeometry.handleRects(
            for: ownerCrop, size: 7, cornerRadius: insetRadius, shrinkToArc: true)
        for (handle, rect) in ownerDrawn where insetCorners.contains(handle) {
            if abs(rect.width - 7) > 0.01 {
                insetFails.append("owner visual \(handle) size \(rect.width) want 7")
            }
        }
        check("selection-handle-inset",
              insetFails.isEmpty,
              insetFails.prefix(6).joined(separator: " | "))
        let pixelCrop = EditableSelectionGeometry.pixelCropRect(
            for: initialSelection, in: selectionBounds, scale: 2
        )
        check("selection-pixel-crop-orientation",
              pixelCrop == CGRect(x: 200, y: 400, width: 800, height: 760),
              "got \(pixelCrop)")
        let fractionalPixelCrop = EditableSelectionGeometry.pixelCropRect(
            for: CGRect(x: 10.25, y: 20.25, width: 100.1, height: 80.1),
            in: selectionBounds, scale: 2
        )
        let annotationOffset = EditableSelectionGeometry.annotationOffset(
            forPixelCrop: fractionalPixelCrop,
            imageHeight: selectionBounds.height * 2
        )
        check("selection-crop-annotation-integral-offset",
              annotationOffset == CGPoint(
                x: fractionalPixelCrop.minX,
                y: selectionBounds.height * 2 - fractionalPixelCrop.maxY
              ), "got \(annotationOffset)")

        // 3. Save format heuristic --------------------------------------------------
        let flat = makeSolidImage(width: 500, height: 500, color: NSColor.systemTeal.cgColor)
        let noisy = makeNoiseImage(width: 500, height: 500)
        check("format-flat-png", SaveService.decideFormat(for: flat) == .png)
        check("format-noise-jpeg", SaveService.decideFormat(for: noisy) == .jpeg)

        // 4. KeyCombo round-trip ----------------------------------------------------
        let combo = KeyCombo(keyCode: 18, modifiers: 768)
        check("keycombo-roundtrip", KeyCombo(encoded: combo.encoded) == combo)
        check("keycombo-display", HotkeyAction.fullscreen.defaultCombo?.display == "⇧⌘1",
              "got \(HotkeyAction.fullscreen.defaultCombo?.display ?? "nil")")

        // 5. OCR ---------------------------------------------------------------------
        let textImage = makeTextImage(text: "SNIPPR TEST 123", width: 900, height: 240)
        writePNG(textImage, to: "\(outputDir)/ocr-input.png")
        let sem = DispatchSemaphore(value: 0)
        let ocrText = LockedStringBox()
        Task.detached {
            let result = await OCRService.shared.recognize(textImage)
            ocrText.set(result.text)
            sem.signal()
        }
        _ = sem.wait(timeout: .now() + 30)
        let recognizedText = ocrText.get()
        check(
            "ocr-text", recognizedText.uppercased().contains("SNIPPR"),
            "got '\(recognizedText)'")

        // 6. Window shot composition ---------------------------------------------------
        let windowShot = CapturedImage(cgImage: makeSolidImage(width: 400, height: 300, color: NSColor.darkGray.cgColor), scale: 2)
        let composedShot = CaptureEngine.composeWindowShot(windowShot, style: .solid, screen: nil)
        check("windowshot-padding", composedShot.cgImage.width == 400 + 96 * 2,
              "got \(composedShot.cgImage.width)")
        let trimmed = CaptureEngine.composeWindowShot(windowShot, style: .trimShadow, screen: nil)
        check("windowshot-trim", trimmed.cgImage.width == 400)
        writePNG(composedShot.cgImage, to: "\(outputDir)/windowshot.png")

        // 7. Retina downscale -----------------------------------------------------------
        let down = windowShot.downscaledTo1x()
        check("downscale-1x", down.cgImage.width == 200 && down.scale == 1)

        // 8. Overlay session + action router (slice 1) -----------------------------
        MainActor.assumeIsolated {
            @MainActor func makeSession(
                _ purpose: OverlayPurpose,
                afterShow: Bool = true, afterCopy: Bool = false,
                afterSave: Bool = false
            ) -> OverlaySession {
                OverlaySession(purpose: purpose, inputs: OverlaySessionInputs(
                    afterShow: afterShow, afterCopy: afterCopy,
                    afterSave: afterSave))
            }

            // Reducer: area-review with afterShow reviews; headless completes.
            let review = makeSession(.areaReview, afterShow: true)
            check("overlay-session-initial-once",
                  review.commitInitialCapture()
                    && review.phase == .reviewing
                    && !review.commitInitialCapture()
                    && review.acceptsCommits,
                  "phase \(review.phase)")
            // Reviewing is unreachable via transition() even for area-review:
            // only the atomic latch may enter it.
            let latchOnly = makeSession(.areaReview, afterShow: true)
            check("overlay-session-reviewing-latch-only",
                  !latchOnly.transition(to: .reviewing)
                    && latchOnly.phase == .selecting,
                  "phase \(latchOnly.phase)")
            let headless = makeSession(.areaReview, afterShow: false)
            check("overlay-session-headless-completes",
                  headless.commitInitialCapture()
                    && headless.phase == .completed
                    && !headless.acceptsCommits,
                  "phase \(headless.phase)")

            // Save round trip: reviewing → saving → (fail) reviewing →
            // saving → completed; completed accepts nothing further.
            check("overlay-session-save-cycle",
                  review.transition(to: .saving)
                    && !review.acceptsCommits
                    && review.transition(to: .reviewing)
                    && review.transition(to: .saving)
                    && review.transition(to: .completed)
                    && !review.transition(to: .reviewing)
                    && review.phase == .completed,
                  "phase \(review.phase)")

            // Non-area purposes: initialCapture latch refused, review/saving
            // transitions forbidden with phase untouched, straight completion
            // allowed.
            for purpose in [OverlayPurpose.scrollRegion, .instantOCRRegion, .windowPick] {
                let s = makeSession(purpose, afterShow: true)
                let latchRefused = !s.commitInitialCapture()
                let reviewingRefused = !s.transition(to: .reviewing)
                let savingRefused = !s.transition(to: .saving)
                check("overlay-session-purpose-locked-\(purpose)",
                      latchRefused && reviewingRefused && savingRefused
                        && s.phase == .selecting
                        && s.transition(to: .completed),
                      "phase \(s.phase)")
            }

            // Router intent matrix with spies.
            let snapshotImage = CapturedImage(
                cgImage: makeSolidImage(
                    width: 8, height: 8, color: NSColor.systemTeal.cgColor),
                scale: 1)
            final class Spy {
                var copies = 0, autoSaves = 0, saveAsCalls = 0
                var pins = 0, ocrs = 0, editors = 0
                var ocrModes: [Bool] = []
                var toasts: [String] = []
                var lastCaptures = 0
                var areaRects: [CGRect] = []
                var logs = 0
                var autoSaveDone: (@MainActor (URL?) -> Void)?
                var saveAsDone: (@MainActor (SaveAsOutcome) -> Void)?
            }
            @MainActor func deps(_ spy: Spy) -> CaptureActionRouter.Dependencies {
                CaptureActionRouter.Dependencies(
                    copyToClipboard: { _ in spy.copies += 1 },
                    autoSave: { _, done in
                        spy.autoSaves += 1; spy.autoSaveDone = done },
                    saveAs: { _, done in
                        spy.saveAsCalls += 1; spy.saveAsDone = done },
                    pin: { _ in spy.pins += 1 },
                    ocrWithMode: { _, autoTranslate in
                        spy.ocrs += 1
                        spy.ocrModes.append(autoTranslate)
                    },
                    openEditor: { _ in spy.editors += 1 },
                    toast: { spy.toasts.append($0) },
                    setLastCapture: { _ in spy.lastCaptures += 1 },
                    setLastAreaRect: { spy.areaRects.append($0) },
                    logEvent: { _ in spy.logs += 1 })
            }
            let rect = CGRect(x: 10, y: 20, width: 30, height: 40)

            // initialCapture entering review: auto-copy only, no toast, no
            // lastAreaRect yet (the action that completes review writes it).
            let s1 = Spy()
            let o1 = CaptureActionRouter.commit(
                snapshotImage, source: .areaReview, intent: .initialCapture,
                inputs: .init(afterShow: true, afterCopy: true, afterSave: false),
                finalGlobalRect: rect, dependencies: deps(s1))
            check("overlay-router-initial-reviewing",
                  o1 == .completed && s1.copies == 1 && s1.toasts.isEmpty
                    && s1.areaRects.isEmpty && s1.lastCaptures == 1
                    && s1.logs == 1 && s1.autoSaves == 0,
                  "copies \(s1.copies) toasts \(s1.toasts) rects \(s1.areaRects)")

            // initialCapture headless with nothing configured: rescue copy +
            // toast + lastAreaRect written.
            let s2 = Spy()
            _ = CaptureActionRouter.commit(
                snapshotImage, source: .areaReview, intent: .initialCapture,
                inputs: .init(afterShow: false, afterCopy: false, afterSave: false),
                finalGlobalRect: rect, dependencies: deps(s2))
            check("overlay-router-initial-headless-fallback",
                  s2.copies == 1 && s2.toasts.count == 1
                    && s2.areaRects == [rect],
                  "copies \(s2.copies) toasts \(s2.toasts) rects \(s2.areaRects)")

            // initialCapture headless with afterSave: announce toast comes
            // from the save completion, exactly once.
            let s3 = Spy()
            _ = CaptureActionRouter.commit(
                snapshotImage, source: .areaReview, intent: .initialCapture,
                inputs: .init(afterShow: false, afterCopy: false, afterSave: true),
                finalGlobalRect: rect, dependencies: deps(s3))
            s3.autoSaveDone?(URL(fileURLWithPath: "/tmp/x.png"))
            check("overlay-router-initial-autosave",
                  s3.autoSaves == 1 && s3.toasts.count == 1
                    && s3.copies == 0 && s3.areaRects == [rect],
                  "saves \(s3.autoSaves) toasts \(s3.toasts)")

            // Manual copy: one clipboard write, NO auto-save replay even with
            // afterSave configured; lastAreaRect written at completion.
            let s4 = Spy()
            let o4 = CaptureActionRouter.commit(
                snapshotImage, source: .areaReview, intent: .copy,
                inputs: .init(afterShow: true, afterCopy: true, afterSave: true),
                finalGlobalRect: rect, dependencies: deps(s4))
            check("overlay-router-copy-no-replay",
                  o4 == .completed && s4.copies == 1 && s4.autoSaves == 0
                    && s4.saveAsCalls == 0 && s4.areaRects == [rect],
                  "copies \(s4.copies) autoSaves \(s4.autoSaves)")

            // Save-As success: .saving outcome, one-shot resolution, area
            // rect written once even if the dependency calls back twice.
            let s5 = Spy()
            var resolutions: [CaptureCommitOutcome] = []
            let o5 = CaptureActionRouter.commit(
                snapshotImage, source: .areaReview, intent: .save,
                inputs: .init(afterShow: true, afterCopy: false, afterSave: false),
                finalGlobalRect: rect, dependencies: deps(s5),
                resolution: { resolutions.append($0) })
            s5.saveAsDone?(.saved(URL(fileURLWithPath: "/tmp/y.png")))
            s5.saveAsDone?(.saved(URL(fileURLWithPath: "/tmp/z.png")))
            check("overlay-router-save-once",
                  o5 == .saving && s5.saveAsCalls == 1
                    && resolutions == [.completed]
                    && s5.areaRects == [rect] && s5.autoSaves == 0,
                  "resolutions \(resolutions) rects \(s5.areaRects)")

            // Save-As cancel: back to review, silent, no lastAreaRect.
            let s6 = Spy()
            var cancelResolutions: [CaptureCommitOutcome] = []
            _ = CaptureActionRouter.commit(
                snapshotImage, source: .areaReview, intent: .save,
                inputs: .init(afterShow: true, afterCopy: false, afterSave: false),
                finalGlobalRect: rect, dependencies: deps(s6),
                resolution: { cancelResolutions.append($0) })
            s6.saveAsDone?(.cancelled)
            check("overlay-router-save-cancel",
                  cancelResolutions == [.cancelled] && s6.areaRects.isEmpty
                    && s6.toasts.isEmpty,
                  "resolutions \(cancelResolutions) toasts \(s6.toasts)")

            // Save-As failure: toast, resolution .failed, no lastAreaRect —
            // review state is the session's job, the router must not
            // complete anything.
            let s6b = Spy()
            var failResolutions: [CaptureCommitOutcome] = []
            _ = CaptureActionRouter.commit(
                snapshotImage, source: .areaReview, intent: .save,
                inputs: .init(afterShow: true, afterCopy: false, afterSave: false),
                finalGlobalRect: rect, dependencies: deps(s6b),
                resolution: { failResolutions.append($0) })
            s6b.saveAsDone?(.failed)
            check("overlay-router-save-failed",
                  failResolutions == [.failed] && s6b.areaRects.isEmpty
                    && s6b.toasts == ["Save failed"] && s6b.lastCaptures == 0,
                  "resolutions \(failResolutions) toasts \(s6b.toasts)")

            // Inputs are a value-type SNAPSHOT: mutating the source value
            // after the session captured it must change nothing. (Real
            // Settings/UserDefaults are never touched in selftest.)
            var mutableInputs = OverlaySessionInputs(
                afterShow: false, afterCopy: true, afterSave: false)
            let frozenSession = OverlaySession(
                purpose: .areaReview, inputs: mutableInputs)
            mutableInputs.afterCopy = false
            mutableInputs.afterSave = true
            mutableInputs.afterShow = true
            let s9 = Spy()
            _ = CaptureActionRouter.commit(
                snapshotImage, source: .areaReview, intent: .initialCapture,
                inputs: frozenSession.inputs,
                finalGlobalRect: rect, dependencies: deps(s9))
            check("overlay-router-inputs-snapshot",
                  frozenSession.inputs == OverlaySessionInputs(
                    afterShow: false, afterCopy: true, afterSave: false)
                    && s9.copies == 1 && s9.autoSaves == 0
                    && s9.areaRects == [rect],
                  "inputs \(frozenSession.inputs), copies \(s9.copies), autoSaves \(s9.autoSaves)")

            // scrollFinished positive matrix: headless runs auto actions +
            // toast; presenting runs auto silently; NEVER a Repeat-Area rect.
            let s10 = Spy()
            let o10 = CaptureActionRouter.commit(
                snapshotImage, source: .scrollResult, intent: .scrollFinished,
                inputs: .init(afterShow: false, afterCopy: true, afterSave: false),
                finalGlobalRect: rect, dependencies: deps(s10))
            check("overlay-router-scrollfinished-headless",
                  o10 == .completed && s10.copies == 1
                    && s10.toasts.count == 1 && s10.areaRects.isEmpty,
                  "copies \(s10.copies) toasts \(s10.toasts) rects \(s10.areaRects)")
            let s10b = Spy()
            let o10b = CaptureActionRouter.commit(
                snapshotImage, source: .scrollResult, intent: .scrollFinished,
                inputs: .init(afterShow: true, afterCopy: true, afterSave: false),
                finalGlobalRect: rect, dependencies: deps(s10b))
            check("overlay-router-scrollfinished-presenting",
                  o10b == .completed && s10b.copies == 1
                    && s10b.toasts.isEmpty && s10b.areaRects.isEmpty,
                  "copies \(s10b.copies) toasts \(s10b.toasts)")
            let s10c = Spy()
            let o10c = CaptureActionRouter.commit(
                snapshotImage, source: .scrollResult, intent: .scrollFinished,
                inputs: .init(afterShow: false, afterCopy: false, afterSave: true),
                finalGlobalRect: nil, dependencies: deps(s10c))
            s10c.autoSaveDone?(URL(fileURLWithPath: "/tmp/s.png"))
            check("overlay-router-scrollfinished-autosave",
                  o10c == .completed && s10c.autoSaves == 1
                    && s10c.toasts.count == 1 && s10c.areaRects.isEmpty,
                  "saves \(s10c.autoSaves) toasts \(s10c.toasts)")

            // Wrong intent×source pairings fail closed with ZERO side
            // effects of any kind.
            let s11 = Spy()
            let wrong1 = CaptureActionRouter.commit(
                snapshotImage, source: .areaReview, intent: .scrollFinished,
                inputs: .init(afterShow: false, afterCopy: true, afterSave: false),
                finalGlobalRect: rect, dependencies: deps(s11))
            let wrong2 = CaptureActionRouter.commit(
                snapshotImage, source: .scrollResult, intent: .initialCapture,
                inputs: .init(afterShow: false, afterCopy: true, afterSave: false),
                finalGlobalRect: rect, dependencies: deps(s11))
            let wrong3 = CaptureActionRouter.commit(
                snapshotImage, source: .area, intent: .initialCapture,
                inputs: .init(afterShow: false, afterCopy: true, afterSave: false),
                finalGlobalRect: rect, dependencies: deps(s11))
            check("overlay-router-intent-source-enforced",
                  wrong1 == .failed && wrong2 == .failed && wrong3 == .failed
                    && s11.copies == 0 && s11.autoSaves == 0
                    && s11.lastCaptures == 0 && s11.logs == 0
                    && s11.toasts.isEmpty && s11.areaRects.isEmpty,
                  "w1 \(wrong1) w2 \(wrong2) w3 \(wrong3) copies \(s11.copies)")

            // Pin / OCR / open editor: exactly one respective effect, no auto
            // replay.
            let s7 = Spy()
            _ = CaptureActionRouter.commit(
                snapshotImage, source: .areaReview, intent: .pin,
                inputs: .init(afterShow: true, afterCopy: true, afterSave: true),
                finalGlobalRect: rect, dependencies: deps(s7))
            _ = CaptureActionRouter.commit(
                snapshotImage, source: .areaReview, intent: .ocr,
                inputs: .init(afterShow: true, afterCopy: true, afterSave: true),
                finalGlobalRect: rect, dependencies: deps(s7))
            _ = CaptureActionRouter.commit(
                snapshotImage, source: .areaReview, intent: .openEditor,
                inputs: .init(afterShow: true, afterCopy: true, afterSave: true),
                finalGlobalRect: rect, dependencies: deps(s7))
            check("overlay-router-terminal-intents",
                  s7.pins == 1 && s7.ocrs == 1 && s7.editors == 1
                    && s7.copies == 0 && s7.autoSaves == 0
                    && s7.saveAsCalls == 0,
                  "pins \(s7.pins) ocrs \(s7.ocrs) editors \(s7.editors)")

            // S5 fail-first gate of record. Normal OCR must remain offline
            // (`false`); explicit Translate must route exactly one `true`
            // presentation, preserve area-rect authority, and never replay
            // the initial capture's copy/save settings.
            let s12OCR = Spy()
            let o12OCR = CaptureActionRouter.commit(
                snapshotImage, source: .areaReview, intent: .ocr,
                inputs: .init(afterShow: true, afterCopy: true, afterSave: true),
                finalGlobalRect: rect, dependencies: deps(s12OCR))
            let s12Area = Spy()
            let o12Area = CaptureActionRouter.commit(
                snapshotImage, source: .areaReview, intent: .translate,
                inputs: .init(afterShow: true, afterCopy: true, afterSave: true),
                finalGlobalRect: rect, dependencies: deps(s12Area))
            let s12Scroll = Spy()
            let o12Scroll = CaptureActionRouter.commit(
                snapshotImage, source: .scrollResult, intent: .translate,
                inputs: .init(afterShow: true, afterCopy: true, afterSave: true),
                finalGlobalRect: rect, dependencies: deps(s12Scroll))
            let translateRouterOK = o12OCR == .completed
                && s12OCR.ocrModes == [false]
                && o12Area == .completed && s12Area.ocrModes == [true]
                && s12Area.lastCaptures == 1 && s12Area.areaRects == [rect]
                && s12Area.copies == 0 && s12Area.autoSaves == 0
                && s12Area.saveAsCalls == 0
                && o12Scroll == .completed && s12Scroll.ocrModes == [true]
                && s12Scroll.lastCaptures == 1 && s12Scroll.areaRects.isEmpty
                && s12Scroll.copies == 0 && s12Scroll.autoSaves == 0
                && s12Scroll.saveAsCalls == 0
            check("overlay12-translate-router-s5", translateRouterOK,
                  "ocr \(o12OCR)/\(s12OCR.ocrModes) area \(o12Area)/\(s12Area.ocrModes) last/rect \(s12Area.lastCaptures)/\(s12Area.areaRects) replay \(s12Area.copies)/\(s12Area.autoSaves)/\(s12Area.saveAsCalls) scroll \(o12Scroll)/\(s12Scroll.ocrModes) rect \(s12Scroll.areaRects)")

            // Source enforcement: finalGlobalRect from any non-areaReview
            // source is IGNORED by the router itself.
            let s8 = Spy()
            for source in [CaptureSource.area, .scrolling, .scrollResult,
                           .fullscreen, .window] {
                _ = CaptureActionRouter.commit(
                    snapshotImage, source: source, intent: .copy,
                    inputs: .init(afterShow: false, afterCopy: false,
                                  afterSave: false),
                    finalGlobalRect: rect, dependencies: deps(s8))
            }
            check("overlay-router-source-enforced", s8.areaRects.isEmpty,
                  "rects \(s8.areaRects)")

            // Late-view guard: after the single terminal route ran, the
            // production addOverlay guard refuses new windows and `current`
            // stays detached.
            if let screen = NSScreen.main {
                let overlay = SelectionOverlay(
                    purpose: .areaReview, completion: { _ in })
                overlay.finish(.cancelled)
                let windowsAfter = overlay.addOverlayForTesting(
                    screen: screen, frozen: nil)
                check("overlay-late-view-guard",
                      windowsAfter == 0
                        && overlay.session.phase == .completed
                        && SelectionOverlay.current == nil,
                      "windows \(windowsAfter), phase \(overlay.session.phase)")
            } else {
                // headless display environment — the guard path is still
                // covered by the reducer checks above
                check("overlay-late-view-guard", true)
            }
        }

        // 9. Overlay slice 2: in-place area review (production paths, headless) ----
        MainActor.assumeIsolated {
            guard let screen = NSScreen.main ?? NSScreen.screens.first else {
                print("SKIP overlay2-environment — no display attached; MUST re-run on an unlocked session")
                return
            }
            let frozenImage = CapturedImage(
                cgImage: makeStripePattern(width: 800, height: 600, seed: 0x0F0E_0D0C),
                scale: 1)

            final class Spy2 {
                var copies: [CapturedImage] = []
                var toasts: [String] = []
                var areaRects: [CGRect] = []
                var logs = 0
                var editors: [(phase: OverlaySessionPhase, completionDone: Bool)] = []
                var saveAsDone: (@MainActor (SaveAsOutcome) -> Void)?
                var saveAsCalls = 0
                var completionDone = false
            }
            @MainActor func makeOverlay(
                afterShow: Bool, afterCopy: Bool = false, afterSave: Bool = false,
                spy: Spy2
            ) -> (SelectionOverlay, SelectionOverlayView) {
                let overlay = SelectionOverlay(
                    purpose: .areaReview,
                    inputs: OverlaySessionInputs(
                        afterShow: afterShow, afterCopy: afterCopy,
                        afterSave: afterSave),
                    completion: { [weak spy] result in
                        if case .handled = result { spy?.completionDone = true }
                        if case .cancelled = result { spy?.completionDone = true }
                    })
                overlay.routerDependenciesOverride =
                    CaptureActionRouter.Dependencies(
                        copyToClipboard: { spy.copies.append($0) },
                        autoSave: { _, _ in },
                        saveAs: { _, done in
                            spy.saveAsCalls += 1; spy.saveAsDone = done },
                        pin: { _ in },
                        ocr: { _ in },
                        openEditor: { [weak overlay] _ in
                            spy.editors.append((
                                overlay?.session.phase ?? .selecting,
                                spy.completionDone)) },
                        toast: { spy.toasts.append($0) },
                        setLastCapture: { _ in },
                        setLastAreaRect: { spy.areaRects.append($0) },
                        logEvent: { _ in spy.logs += 1 })
                let view = SelectionOverlayView(
                    mode: .area, screen: screen, frozen: frozenImage,
                    windowList: [], owner: overlay)
                return (overlay, view)
            }

            // Headless mouse-up: one initialCapture, rescue copy + toast +
            // Repeat-Area rect, overlay handled, snapshot pixel-exact.
            let h = Spy2()
            let (headlessOverlay, headlessView) = makeOverlay(
                afterShow: false, spy: h)
            let rect1 = CGRect(x: 40, y: 50, width: 120, height: 90)
            headlessView.selectForTesting(rect: rect1)
            let wantGlobal1 = CGRect(
                x: 40 + screen.frame.minX, y: 50 + screen.frame.minY,
                width: 120, height: 90)
            var snapshotExact = false
            if let image = h.copies.first,
               let want = frozenImage.cropping(toViewRect: rect1) {
                snapshotExact = imagesEqual(want.cgImage, image.cgImage)
            }
            check("overlay2-headless-flow",
                  h.copies.count == 1 && h.toasts.count == 1 && h.logs == 1
                    && h.areaRects == [wantGlobal1]
                    && headlessOverlay.session.phase == .completed
                    && h.completionDone && snapshotExact,
                  "copies \(h.copies.count) toasts \(h.toasts) rects \(h.areaRects) phase \(headlessOverlay.session.phase)")

            // Review mouse-up: auto-copy runs silently, session reviews,
            // toolbar laid out inside bounds, completion NOT called yet.
            let r = Spy2()
            let (reviewOverlay, reviewView) = makeOverlay(
                afterShow: true, afterCopy: true, spy: r)
            reviewView.selectForTesting(rect: rect1)
            let toolbarFrame = reviewView.reviewToolbarFrameForTesting
            check("overlay2-review-begins",
                  r.copies.count == 1 && r.toasts.isEmpty && r.logs == 1
                    && r.areaRects.isEmpty
                    && reviewOverlay.session.phase == .reviewing
                    && !r.completionDone
                    && toolbarFrame != nil
                    && reviewView.bounds.contains(toolbarFrame ?? .null),
                  "copies \(r.copies.count) phase \(reviewOverlay.session.phase) toolbar \(String(describing: toolbarFrame))")

            // Competing second mouse-up (late display / double gesture): no
            // second initialCapture side effects.
            let (_, competingView) = (reviewOverlay, SelectionOverlayView(
                mode: .area, screen: screen, frozen: frozenImage,
                windowList: [], owner: reviewOverlay))
            competingView.selectForTesting(rect: rect1)
            check("overlay2-competing-mouseup",
                  r.copies.count == 1 && r.logs == 1
                    && reviewOverlay.session.phase == .reviewing,
                  "copies \(r.copies.count) logs \(r.logs)")

            // Resize during review, then manual Copy: the action reads the
            // FINAL rect — snapshot pixel-exact vs the resized crop, and the
            // Repeat-Area rect equals the final global rect.
            let rect2 = CGRect(x: 30, y: 40, width: 200, height: 150)
            reviewView.adjustSelectionForTesting(rect: rect2)
            reviewView.performReviewActionForTesting(.copy)
            let wantGlobal2 = CGRect(
                x: 30 + screen.frame.minX, y: 40 + screen.frame.minY,
                width: 200, height: 150)
            var finalExact = false
            if r.copies.count == 2,
               let want = frozenImage.cropping(toViewRect: rect2) {
                finalExact = imagesEqual(want.cgImage, r.copies[1].cgImage)
                    && r.copies[1].cgImage.width == 200
                    && r.copies[1].cgImage.height == 150
            }
            check("overlay2-final-rect-copy",
                  finalExact && r.areaRects == [wantGlobal2]
                    && reviewOverlay.session.phase == .completed
                    && r.completionDone,
                  "copies \(r.copies.count) rects \(r.areaRects) phase \(reviewOverlay.session.phase)")

            // Save cycle on the production dispatch: .saving blocks competing
            // intents, double callback resolves once, cancel returns to
            // review, a later successful save completes exactly once.
            let s = Spy2()
            let (saveOverlay, saveView) = makeOverlay(
                afterShow: true, spy: s)
            saveView.selectForTesting(rect: rect1)
            saveView.performReviewActionForTesting(.save)
            let phaseDuringSave = saveOverlay.session.phase
            saveView.performReviewActionForTesting(.copy) // must be swallowed
            let copiesDuringSave = s.copies.count
            // While saving: Esc, outside click and Close must NOT tear the
            // overlay down; the canvas stays locked until the typed callback.
            saveView.handleEscapeForTesting()
            saveView.handleOutsideClickForTesting()
            let survivedSaving = saveOverlay.session.phase == .saving
                && !s.completionDone
            s.saveAsDone?(.cancelled)
            let phaseAfterCancel = saveOverlay.session.phase
            s.saveAsDone?(.cancelled) // double callback: ignored
            saveView.performReviewActionForTesting(.save)
            s.saveAsDone?(.saved(URL(fileURLWithPath: "/tmp/ov.png")))
            check("overlay2-save-cycle",
                  phaseDuringSave == .saving && copiesDuringSave == 0
                    && survivedSaving
                    && phaseAfterCancel == .reviewing
                    && s.saveAsCalls == 2
                    && saveOverlay.session.phase == .completed
                    && s.completionDone
                    && s.areaRects.count == 1,
                  "during \(phaseDuringSave) afterCancel \(phaseAfterCancel) calls \(s.saveAsCalls) rects \(s.areaRects.count)")

            // Synchronous save callback: a dependency that resolves INSIDE
            // commit must behave identically — the session entered .saving
            // before the effect, so the sync resolution lands on the right
            // phase and completes exactly once.
            let sync = Spy2()
            let (syncOverlay, syncView) = makeOverlay(afterShow: true, spy: sync)
            syncView.selectForTesting(rect: rect1)
            syncOverlay.routerDependenciesOverride?.saveAs = { _, done in
                sync.saveAsCalls += 1
                done(.saved(URL(fileURLWithPath: "/tmp/sync.png")))
                done(.saved(URL(fileURLWithPath: "/tmp/sync2.png"))) // double
            }
            syncView.performReviewActionForTesting(.save)
            check("overlay2-save-sync-callback",
                  sync.saveAsCalls == 1
                    && syncOverlay.session.phase == .completed
                    && sync.completionDone
                    && sync.areaRects.count == 1,
                  "calls \(sync.saveAsCalls) phase \(syncOverlay.session.phase) rects \(sync.areaRects.count)")

            // Frozen-blit spy: N redraws must not re-blit the 5K source —
            // the background layer was committed exactly once per view.
            let blitBefore = SelectionOverlayView.frozenBlitCountForTesting
            let b = Spy2()
            let (blitOverlay, blitView) = makeOverlay(afterShow: true, spy: b)
            _ = blitOverlay
            blitView.selectForTesting(rect: rect1)
            let afterSetup = SelectionOverlayView.frozenBlitCountForTesting
            for step in 0..<5 {
                blitView.adjustSelectionForTesting(rect: CGRect(
                    x: 40, y: 50, width: 120 + CGFloat(step) * 10, height: 90))
                var buffer = [UInt8](repeating: 0, count: 64 * 64 * 4)
                if let ctx = CGContext(
                    data: &buffer, width: 64, height: 64,
                    bitsPerComponent: 8, bytesPerRow: 64 * 4,
                    space: CGColorSpace(name: CGColorSpace.sRGB)!,
                    bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) {
                    let ns = NSGraphicsContext(cgContext: ctx, flipped: false)
                    NSGraphicsContext.saveGraphicsState()
                    NSGraphicsContext.current = ns
                    blitView.draw(blitView.bounds)
                    NSGraphicsContext.restoreGraphicsState()
                }
            }
            check("overlay2-frozen-blit-once",
                  afterSetup == blitBefore + 1
                    && SelectionOverlayView.frozenBlitCountForTesting == afterSetup,
                  "setup Δ\(afterSetup - blitBefore), after draws Δ\(SelectionOverlayView.frozenBlitCountForTesting - afterSetup)")

            // Terminal order: openEditor presents only AFTER teardown — the
            // dependency observes phase completed and completion already run.
            let t = Spy2()
            let (terminalOverlay, terminalView) = makeOverlay(afterShow: true, spy: t)
            _ = terminalOverlay // keep the weakly-owned overlay alive
            terminalView.selectForTesting(rect: rect1)
            terminalView.performReviewActionForTesting(.openEditor)
            check("overlay2-teardown-before-present",
                  t.editors.count == 1
                    && t.editors[0].phase == .completed
                    && t.editors[0].completionDone,
                  "editors \(t.editors)")
        }

        // 10. Overlay slice 3: scroll finish payload + teardown order --------------
        MainActor.assumeIsolated {
            // finalize: cleanup BEFORE callback, exactly once, payload
            // carries the snapshotted inputs + origin screen.
            let inputs = OverlaySessionInputs(
                afterShow: true, afterCopy: true, afterSave: false)
            var callbacks = 0
            var activeAtCall: ScrollingCapture?
            var payloadInputs: OverlaySessionInputs?
            let session = ScrollingCapture(inputs: inputs, onFinish: { finish in
                callbacks += 1
                activeAtCall = ScrollingCapture.active
                payloadInputs = finish.inputs
            })
            ScrollingCapture.active = session
            session.finalizeForTesting(image: nil)
            session.finalizeForTesting(image: nil) // double: must be one-shot
            check("overlay3-finalize-order",
                  callbacks == 1 && activeAtCall == nil
                    && payloadInputs == inputs
                    && ScrollingCapture.active == nil
                    && session.previewPanelForTesting == nil,
                  "callbacks \(callbacks), active \(String(describing: activeAtCall)), inputs \(String(describing: payloadInputs))")

            // presenter headless: scrollFinished auto exactly once, no panel.
            let img = CapturedImage(
                cgImage: makeSolidImage(
                    width: 12, height: 12, color: NSColor.systemBlue.cgColor),
                scale: 1)
            var copies = 0
            var toasts = 0
            var rects = 0
            let deps = CaptureActionRouter.Dependencies(
                copyToClipboard: { _ in copies += 1 },
                autoSave: { _, _ in },
                saveAs: { _, _ in },
                pin: { _ in }, ocr: { _ in }, openEditor: { _ in },
                toast: { _ in toasts += 1 },
                setLastCapture: { _ in },
                setLastAreaRect: { _ in rects += 1 },
                logEvent: { _ in })
            let screen = NSScreen.main ?? NSScreen.screens.first
            if let screen {
                ScrollResultPresenter.present(
                    ScrollFinish(
                        image: img,
                        inputs: OverlaySessionInputs(
                            afterShow: false, afterCopy: true, afterSave: false),
                        screen: screen),
                    dependencies: deps)
            }
            check("overlay3-presenter-headless",
                  screen == nil || (copies == 1 && toasts == 1 && rects == 0
                    && ScrollResultPanel.current == nil),
                  "copies \(copies) toasts \(toasts) rects \(rects) panel \(String(describing: ScrollResultPanel.current))")

            // screen-nil with afterShow=true: the shot must still be
            // secured through the headless auto path — all 4 copy/save
            // combos, exactly one action set, zero panels.
            var screenNilOK = true
            for copyOn in [false, true] {
                for saveOn in [false, true] {
                    var copies2 = 0, saves2 = 0, toasts2 = 0
                    var deps2 = CaptureActionRouter.Dependencies(
                        copyToClipboard: { _ in copies2 += 1 },
                        autoSave: { _, done in
                            saves2 += 1
                            done(URL(fileURLWithPath: "/tmp/n.png")) },
                        saveAs: { _, _ in },
                        pin: { _ in }, ocr: { _ in }, openEditor: { _ in },
                        toast: { _ in toasts2 += 1 },
                        setLastCapture: { _ in },
                        setLastAreaRect: { _ in }, logEvent: { _ in })
                    _ = deps2
                    ScrollResultPresenter.present(
                        ScrollFinish(
                            image: img,
                            inputs: OverlaySessionInputs(
                                afterShow: true, afterCopy: copyOn,
                                afterSave: saveOn),
                            screen: nil),
                        dependencies: deps2)
                    let wantCopies2 = copyOn ? 1 : (saveOn ? 0 : 1)
                    let wantSaves2 = saveOn ? 1 : 0
                    if copies2 != wantCopies2 || saves2 != wantSaves2
                        || toasts2 != 1
                        || ScrollResultPanel.current != nil {
                        screenNilOK = false
                        print("  screen-nil mismatch copy=\(copyOn) save=\(saveOn): c\(copies2)/\(wantCopies2) s\(saves2)/\(wantSaves2) t\(toasts2)")
                    }
                }
            }
            check("overlay6-screen-nil-secured", screenNilOK, "see above")

            // nil image: nothing runs, nothing presents.
            if let screen {
                ScrollResultPresenter.present(
                    ScrollFinish(
                        image: nil,
                        inputs: OverlaySessionInputs(
                            afterShow: true, afterCopy: true, afterSave: false),
                        screen: screen),
                    dependencies: deps)
            }
            check("overlay3-presenter-nil-image",
                  copies <= 1 && ScrollResultPanel.current == nil,
                  "copies \(copies)")

            // afterScrollShow = .editor (default): the finished stitch opens
            // the EDITOR through the router's openEditor effect exactly once
            // — auto copy still exactly once, no in-place panel. .panel keeps
            // the borderless panel and never touches the editor.
            if let screen {
                var edCopies = 0, edOpens = 0, edToasts = 0
                let edDeps = CaptureActionRouter.Dependencies(
                    copyToClipboard: { _ in edCopies += 1 },
                    autoSave: { _, _ in },
                    saveAs: { _, _ in },
                    pin: { _ in }, ocr: { _ in },
                    openEditor: { _ in edOpens += 1 },
                    toast: { _ in edToasts += 1 },
                    setLastCapture: { _ in },
                    setLastAreaRect: { _ in },
                    logEvent: { _ in })
                let showInputs = OverlaySessionInputs(
                    afterShow: true, afterCopy: true, afterSave: false)
                ScrollResultPresenter.present(
                    ScrollFinish(image: img, inputs: showInputs, screen: screen),
                    dependencies: edDeps, afterScrollShow: .editor)
                let editorPath = edOpens == 1 && edCopies == 1
                    && ScrollResultPanel.current == nil
                let editorDetail = "editor: opens \(edOpens) copies \(edCopies) "
                    + "panel \(ScrollResultPanel.current != nil)"
                edOpens = 0; edCopies = 0
                ScrollResultPresenter.present(
                    ScrollFinish(image: img, inputs: showInputs, screen: screen),
                    dependencies: edDeps, afterScrollShow: .panel)
                let panelPath = edOpens == 0 && edCopies == 1
                    && ScrollResultPanel.current != nil
                let panelDetail = "panel: opens \(edOpens) copies \(edCopies) "
                    + "panel \(ScrollResultPanel.current != nil)"
                ScrollResultPanel.current?.performActionForTesting(.copy)
                check("scroll9-result-opens-editor",
                      editorPath && panelPath
                        && Settings.shared.afterScrollShow == .editor,
                      editorDetail + "; " + panelDetail
                        + "; default \(Settings.shared.afterScrollShow)")
            }
        }

        // 11. Overlay slice 4: annotations (shared surface, both paths) -----------
        MainActor.assumeIsolated {
            guard let screen = NSScreen.main ?? NSScreen.screens.first else {
                print("SKIP overlay4-environment — no display attached; MUST re-run on an unlocked session")
                return
            }
            let base = makeStripePattern(width: 800, height: 600, seed: 0x4A4A_4A4A)
            let frozenImage = CapturedImage(cgImage: base, scale: 1)

            final class Spy4 {
                var copies: [CapturedImage] = []
            }
            let spy = Spy4()
            let overlay = SelectionOverlay(
                purpose: .areaReview,
                inputs: OverlaySessionInputs(
                    afterShow: true, afterCopy: false, afterSave: false),
                completion: { _ in })
            overlay.routerDependenciesOverride = CaptureActionRouter.Dependencies(
                copyToClipboard: { spy.copies.append($0) },
                autoSave: { _, _ in }, saveAs: { _, _ in },
                pin: { _ in }, ocr: { _ in }, openEditor: { _ in },
                toast: { _ in }, setLastCapture: { _ in },
                setLastAreaRect: { _ in }, logEvent: { _ in })
            let view = SelectionOverlayView(
                mode: .area, screen: screen, frozen: frozenImage,
                windowList: [], owner: overlay)
            let rect = CGRect(x: 100, y: 100, width: 300, height: 200)
            view.selectForTesting(rect: rect)
            guard let surface = view.annotationSurface else {
                check("overlay4-surface-created", false)
                return
            }
            check("overlay4-surface-created", true)

            // draw a rect annotation inside the crop (pixel coords, BL)
            surface.tool = .rect
            _ = surface.beginDrag(atPixel: CGPoint(x: 150, y: 150))
            surface.continueDrag(toPixel: CGPoint(x: 250, y: 220))
            surface.endDrag()
            surface.tool = .select
            let plainCrop = base.cropping(
                to: overlay.session.pixelRect)!
            view.performReviewActionForTesting(.copy)
            var flattenChanged = false
            var flattenMatchesSurface = false
            if let copied = spy.copies.first {
                flattenChanged = !imagesEqual(plainCrop, copied.cgImage)
                if let want = surface.flattened(
                    base: base, cropPixels: overlay.session.pixelRect) {
                    flattenMatchesSurface = imagesEqual(want, copied.cgImage)
                }
            }
            check("overlay4-flatten-hash",
                  flattenChanged && flattenMatchesSurface,
                  "changed \(flattenChanged) matches \(flattenMatchesSurface)")

            // Remap/clip: a fresh session — annotation OUTSIDE a shrunken
            // crop disappears from flatten (absolute positions, clipped),
            // and returns when the crop expands again.
            let spyB = Spy4()
            let overlayB = SelectionOverlay(
                purpose: .areaReview,
                inputs: OverlaySessionInputs(
                    afterShow: true, afterCopy: false, afterSave: false),
                completion: { _ in })
            overlayB.routerDependenciesOverride = CaptureActionRouter.Dependencies(
                copyToClipboard: { spyB.copies.append($0) },
                autoSave: { _, _ in }, saveAs: { _, _ in },
                pin: { _ in }, ocr: { _ in }, openEditor: { _ in },
                toast: { _ in }, setLastCapture: { _ in },
                setLastAreaRect: { _ in }, logEvent: { _ in })
            let viewB = SelectionOverlayView(
                mode: .area, screen: screen, frozen: frozenImage,
                windowList: [], owner: overlayB)
            viewB.selectForTesting(rect: rect)
            guard let surfaceB = viewB.annotationSurface else {
                check("overlay4-remap-surface", false)
                return
            }
            surfaceB.tool = .rect
            _ = surfaceB.beginDrag(atPixel: CGPoint(x: 320, y: 150))
            surfaceB.continueDrag(toPixel: CGPoint(x: 380, y: 250))
            surfaceB.endDrag()
            surfaceB.tool = .select
            // shrink so the annotation (x 320..380) is fully outside
            viewB.adjustSelectionForTesting(rect: CGRect(
                x: 100, y: 100, width: 150, height: 200))
            let shrunkenPlain = base.cropping(to: overlayB.session.pixelRect)!
            let shrunkenFlat = surfaceB.flattened(
                base: base, cropPixels: overlayB.session.pixelRect)
            let clipped = shrunkenFlat.map { imagesEqual(shrunkenPlain, $0) } ?? false
            // expand back: the annotation is visible again
            viewB.adjustSelectionForTesting(rect: rect)
            let expandedPlain = base.cropping(to: overlayB.session.pixelRect)!
            let expandedFlat = surfaceB.flattened(
                base: base, cropPixels: overlayB.session.pixelRect)
            let restored = expandedFlat.map { !imagesEqual(expandedPlain, $0) } ?? false
            check("overlay4-remap-clip", clipped && restored,
                  "clipped \(clipped) restored \(restored)")

            // Undo removes the newest annotation; text adds via the shared
            // API and changes flatten.
            let before = surfaceB.annotations.count
            surfaceB.addText("Snippr", atPixel: CGPoint(x: 150, y: 150))
            let afterText = surfaceB.annotations.count
            _ = surfaceB.undo()
            check("overlay4-text-and-undo",
                  afterText == before + 1
                    && surfaceB.annotations.count == before,
                  "before \(before) afterText \(afterText) final \(surfaceB.annotations.count)")
        }

        // 12. Overlay slice 5: final layout/matrix gates ---------------------------
        MainActor.assumeIsolated {
            // The setting matrix is PURE router logic — it must run even on
            // a headless runner, so it lives before the screen guard.
            let tinyHeadless = CapturedImage(
                cgImage: makeSolidImage(
                    width: 6, height: 6, color: NSColor.systemPink.cgColor),
                scale: 1)
            var matrixHeadlessOK = true
            for intent in [CaptureIntent.initialCapture, .scrollFinished] {
                let source: CaptureSource =
                    intent == .initialCapture ? .areaReview : .scrollResult
                for show in [false, true] {
                    for copy in [false, true] {
                        for save in [false, true] {
                            var copies = 0, saves = 0, toasts = 0, rects = 0
                            let deps = CaptureActionRouter.Dependencies(
                                copyToClipboard: { _ in copies += 1 },
                                autoSave: { _, done in
                                    saves += 1
                                    done(URL(fileURLWithPath: "/tmp/m.png")) },
                                saveAs: { _, _ in },
                                pin: { _ in }, ocr: { _ in },
                                openEditor: { _ in },
                                toast: { _ in toasts += 1 },
                                setLastCapture: { _ in },
                                setLastAreaRect: { _ in rects += 1 },
                                logEvent: { _ in })
                            _ = CaptureActionRouter.commit(
                                tinyHeadless, source: source, intent: intent,
                                inputs: OverlaySessionInputs(
                                    afterShow: show, afterCopy: copy,
                                    afterSave: save),
                                finalGlobalRect: CGRect(
                                    x: 1, y: 2, width: 3, height: 4),
                                dependencies: deps)
                            let wantCopies = copy
                                ? 1 : ((show || save) ? 0 : 1)
                            let wantSaves = save ? 1 : 0
                            let wantToasts = show ? 0 : 1
                            let wantRects = (intent == .initialCapture && !show)
                                ? 1 : 0
                            if copies != wantCopies || saves != wantSaves
                                || toasts != wantToasts || rects != wantRects {
                                matrixHeadlessOK = false
                                print("  matrix mismatch: \(intent) show=\(show) copy=\(copy) save=\(save) → c\(copies)/\(wantCopies) s\(saves)/\(wantSaves) t\(toasts)/\(wantToasts) r\(rects)/\(wantRects)")
                            }
                        }
                    }
                }
            }
            check("overlay5-setting-matrix", matrixHeadlessOK, "see mismatches above")

            // The review rail's left-to-right order, pinned. Windows keeps a
            // copy of this sequence in `win-overlay-tool-order-matches-mac`
            // (its icon keys differ in two names: `blur` is `pixelate` there,
            // and it has no `pixelateText` tool at all). Without a gate on
            // THIS side, appending a case to the enum would quietly land the
            // new tool at the end of the macOS rail and leave the Windows
            // copy stale with nothing red on either platform — which is how
            // the two rails drifted apart in the first place.
            let wantRailOrder = [
                "select", "pen", "arrow", "rect", "text", "line",
                "oval", "highlight", "counter", "blur", "spotlight",
                "pixelateText", "magnifier",
            ]
            let liveRailOrder = OverlayAnnotationTool.areaReviewTools
                .map(\.rawValue)
            check("overlay-tool-order", liveRailOrder == wantRailOrder,
                  "rail \(liveRailOrder) want \(wantRailOrder)")

            guard let screen = NSScreen.main ?? NSScreen.screens.first else {
                print("SKIP overlay5-environment — no display attached; MUST re-run on an unlocked session")
                return
            }
            // frozen must cover the whole screen: edge selections crop from
            // it through the pixel authority
            let frozenImage = CapturedImage(
                cgImage: makeStripePattern(
                    width: max(8, Int(screen.frame.width)),
                    height: max(8, Int(screen.frame.height)),
                    seed: 0x5555_AAAA),
                scale: 1)
            @MainActor func noopDeps() -> CaptureActionRouter.Dependencies {
                CaptureActionRouter.Dependencies(
                    copyToClipboard: { _ in }, autoSave: { _, _ in },
                    saveAs: { _, _ in }, pin: { _ in }, ocr: { _ in },
                    openEditor: { _ in }, toast: { _ in },
                    setLastCapture: { _ in }, setLastAreaRect: { _ in },
                    logEvent: { _ in })
            }
            @MainActor func reviewView() -> (SelectionOverlay, SelectionOverlayView) {
                let overlay = SelectionOverlay(
                    purpose: .areaReview,
                    inputs: OverlaySessionInputs(
                        afterShow: true, afterCopy: false, afterSave: false),
                    completion: { _ in })
                overlay.routerDependenciesOverride = noopDeps()
                let view = SelectionOverlayView(
                    mode: .area, screen: screen, frozen: frozenImage,
                    windowList: [], owner: overlay)
                return (overlay, view)
            }

            // Toolbar at the edges: bottom-left, bottom-right, top edge,
            // full-frame — always inside bounds, never over a handle hit rect.
            let b = screen.frame.size
            let edgeRects = [
                CGRect(x: 4, y: 4, width: 200, height: 120),
                CGRect(x: b.width - 210, y: 4, width: 200, height: 120),
                CGRect(x: b.width / 2 - 100, y: b.height - 130, width: 200, height: 120),
                CGRect(x: 4, y: 4, width: b.width - 8, height: b.height - 8),
            ]
            var edgeFailures: [String] = []
            for (index, rect) in edgeRects.enumerated() {
                let (overlay, view) = reviewView()
                _ = overlay
                view.selectForTesting(rect: rect)
                let buttonFrames = view.reviewToolbarButtonFramesForTesting
                guard !buttonFrames.isEmpty else {
                    edgeFailures.append("#\(index) no toolbar"); continue
                }
                for (buttonIndex, buttonFrame) in buttonFrames.enumerated() {
                    if !view.bounds.contains(buttonFrame) {
                        edgeFailures.append(
                            "#\(index) button \(buttonIndex) out of bounds \(buttonFrame)")
                    }
                    if let sel = view.hasAreaSelectionForTesting
                        ? rect.intersection(view.bounds) : nil {
                        for (handle, handleRect) in EditableSelectionGeometry
                            .handleRects(for: sel, size: 18)
                            where buttonFrame.intersects(handleRect) {
                            edgeFailures.append(
                                "#\(index) button \(buttonIndex) overlaps \(handle) \(handleRect) frame \(buttonFrame)")
                        }
                    }
                }
            }
            check("overlay5-toolbar-edges", edgeFailures.isEmpty,
                  edgeFailures.joined(separator: "; "))

            // Regression: the review toolbar and pixel-crop authority must
            // follow a REAL move/resize drag before mouseUp.  The old edge
            // gate used adjustSelectionForTesting(), which performs sync +
            // layout itself and therefore stayed green while production
            // mouseDragged left both values stale until the button released.
            @MainActor func liveMouse(
                _ type: NSEvent.EventType, _ point: CGPoint
            ) -> NSEvent? {
                NSEvent.mouseEvent(
                    with: type, location: point, modifierFlags: [],
                    timestamp: 0, windowNumber: 0, context: nil,
                    eventNumber: 0, clickCount: 1, pressure: 1)
            }
            @MainActor func expectedPixels(
                for rect: CGRect, frozen: CapturedImage
            ) -> CGRect {
                let scale = frozen.scale
                return CGRect(
                    x: rect.minX * scale,
                    y: (CGFloat(frozen.cgImage.height) / scale - rect.maxY) * scale,
                    width: rect.width * scale,
                    height: rect.height * scale
                ).integral
            }

            let moveRect = CGRect(
                x: max(40, b.width / 2 - 130),
                y: max(100, b.height / 2 - 80),
                width: 260, height: 160)
            let moveDelta = CGPoint(x: 37, y: 29)
            let movedRect = EditableSelectionGeometry.moved(
                moveRect, by: moveDelta,
                within: CGRect(origin: .zero, size: b))
            let (moveOverlay, moveView) = reviewView()
            moveView.selectForTesting(rect: moveRect)
            let moveBarBefore = moveView.reviewToolbarFrameForTesting
            let moveStart = CGPoint(x: moveRect.midX, y: moveRect.midY)
            let moveEnd = CGPoint(
                x: moveStart.x + moveDelta.x,
                y: moveStart.y + moveDelta.y)
            if let down = liveMouse(.leftMouseDown, moveStart) {
                moveView.mouseDown(with: down)
            }
            if let drag = liveMouse(.leftMouseDragged, moveEnd) {
                moveView.mouseDragged(with: drag)
            }
            let moveBarDuring = moveView.reviewToolbarFrameForTesting
            let movePixelsDuring = moveOverlay.session.pixelRect
            let moveToolbarLive = moveBarBefore != nil
                && moveBarDuring != moveBarBefore
            let movePixelsLive = movePixelsDuring == expectedPixels(
                for: movedRect, frozen: frozenImage)
            if let up = liveMouse(.leftMouseUp, moveEnd) {
                moveView.mouseUp(with: up)
            }
            let moveToolbarNoJump =
                moveView.reviewToolbarFrameForTesting == moveBarDuring
            let movePixelsNoJump =
                moveOverlay.session.pixelRect == movePixelsDuring

            let resizeRect = CGRect(
                x: max(40, b.width / 2 - 130),
                y: min(max(180, b.height / 3), b.height - 220),
                width: 260, height: 180)
            let resizedRect = EditableSelectionGeometry.resized(
                resizeRect, using: .bottom,
                to: CGPoint(x: resizeRect.midX, y: 5),
                within: CGRect(origin: .zero, size: b))
            let (resizeOverlay, resizeView) = reviewView()
            resizeView.selectForTesting(rect: resizeRect)
            let resizeBarBefore = resizeView.reviewToolbarFrameForTesting
            let resizeStart = SelectionHandle.bottom.point(in: resizeRect)
            let resizeEnd = CGPoint(x: resizeStart.x, y: 5)
            if let down = liveMouse(.leftMouseDown, resizeStart) {
                resizeView.mouseDown(with: down)
            }
            if let drag = liveMouse(.leftMouseDragged, resizeEnd) {
                resizeView.mouseDragged(with: drag)
            }
            let resizeBarDuring = resizeView.reviewToolbarFrameForTesting
            let resizePixelsDuring = resizeOverlay.session.pixelRect
            let resizeToolbarLive = resizeBarBefore != nil
                && resizeBarDuring != resizeBarBefore
            let resizePixelsLive = resizePixelsDuring == expectedPixels(
                for: resizedRect, frozen: frozenImage)
            if let up = liveMouse(.leftMouseUp, resizeEnd) {
                resizeView.mouseUp(with: up)
            }
            let resizeToolbarNoJump =
                resizeView.reviewToolbarFrameForTesting == resizeBarDuring
            let resizePixelsNoJump =
                resizeOverlay.session.pixelRect == resizePixelsDuring

            check("overlay7-toolbar-live-follow",
                  moveToolbarLive && moveToolbarNoJump
                    && resizeToolbarLive && resizeToolbarNoJump,
                  "moveLive \(moveToolbarLive) moveNoJump \(moveToolbarNoJump) resizeLive \(resizeToolbarLive) resizeNoJump \(resizeToolbarNoJump)")
            check("overlay7-pixelrect-live-follow",
                  movePixelsLive && movePixelsNoJump
                    && resizePixelsLive && resizePixelsNoJump,
                  "moveLive \(movePixelsLive) moveNoJump \(movePixelsNoJump) resizeLive \(resizePixelsLive) resizeNoJump \(resizePixelsNoJump)")

            // Wiring, not just the helper: after Ocean is on, a mouseDown
            // at the geometric corner must not grab the handle, and a
            // mouseDown on the 45° point must. Restoring radius 0 (the
            // old call) makes the first assertion go red — that is the
            // mutation this exists to catch.
            let (insetOverlay, insetView) = reviewView()
            _ = insetOverlay
            // Geometric-corner probe only works when d > hit half (9):
            // Medium on a small crop floors at 12 (d ≈ 3.5) and the 18 pt
            // hit still covers the cut. Large on a screen-sized crop
            // matches the owner case (d > 9).
            let insetSel = CGRect(
                x: 40, y: 40,
                width: max(200, b.width - 80),
                height: max(160, b.height - 80))
            insetView.selectForTesting(rect: insetSel)
            var wireFails: [String] = []
            if !insetView.isReviewingForTesting {
                wireFails.append("not reviewing")
            }
            if !insetView.applyBackdropPreset(.ocean) {
                wireFails.append("ocean refused")
            }
            let styleBefore = Settings.shared.backdropCornerStyle
            Settings.shared.backdropCornerStyle = .large
            defer { Settings.shared.backdropCornerStyle = styleBefore }
            let liveSel = insetView.areaSelectionForTesting ?? insetSel
            let liveR = SliceBBackdrop.cornerRadius(
                documentPoints: liveSel.size, style: .large)
            let liveD = EditableSelectionGeometry.cornerInset(forRadius: liveR)
            if liveR <= 0 { wireFails.append("large radius is 0") }
            if liveD <= 9 {
                wireFails.append("d \(liveD) ≤ 9, geometric probe is inside the hit")
            }
            let geoTR = SelectionHandle.topRight.point(in: liveSel)
            let arcTR = EditableSelectionGeometry.handlePoint(
                .topRight, in: liveSel, cornerRadius: liveR)
            // Exact maxX/maxY is outside CGRect.contains and would
            // cancel review. Nudge onto the crop; stay farther than
            // the 9 pt hit from the inset centre.
            let geoInside = CGPoint(x: geoTR.x - 0.5, y: geoTR.y - 0.5)
            if let down = liveMouse(.leftMouseDown, arcTR) {
                insetView.mouseDown(with: down)
            }
            if insetView.areaDragHandleForTesting != .topRight {
                wireFails.append(
                    "arc corner grabs \(String(describing: insetView.areaDragHandleForTesting))")
            }
            if let up = liveMouse(.leftMouseUp, arcTR) {
                insetView.mouseUp(with: up)
            }
            if let down = liveMouse(.leftMouseDown, geoInside) {
                insetView.mouseDown(with: down)
            }
            if insetView.areaDragHandleForTesting == .topRight {
                wireFails.append("geometric corner still grabs")
            }
            if let up = liveMouse(.leftMouseUp, geoInside) {
                insetView.mouseUp(with: up)
            }
            check("overlay-handle-inset-wired",
                  wireFails.isEmpty,
                  wireFails.joined(separator: " | "))

            // The pointer must answer to the TOOL, not to geometry alone.
            // Before this, every point inside the crop was an open hand while
            // the very same click drew with the pen — the cursor promised a
            // move the app never performed. Real mouseMoved events go in and
            // the cursor production actually set comes back out, so reverting
            // to the unconditional openHand turns this red.
            let (cursorOverlay, cursorView) = reviewView()
            _ = cursorOverlay
            let cursorSel = CGRect(
                x: 60, y: 60,
                width: max(220, b.width - 200),
                height: max(160, b.height - 200))
            cursorView.selectForTesting(rect: cursorSel)
            var cursorFails: [String] = []
            if !cursorView.isReviewingForTesting {
                cursorFails.append("not reviewing")
            }
            let cursorLive = cursorView.areaSelectionForTesting ?? cursorSel
            let cursorCentre = CGPoint(x: cursorLive.midX, y: cursorLive.midY)
            let cursorOutside = CGPoint(x: 20, y: 20)
            let cursorRightHandle = SelectionHandle.right.point(in: cursorLive)
            if cursorLive.contains(cursorOutside) {
                cursorFails.append("outside probe is inside the crop")
            }
            if cursorLive.contains(cursorRightHandle) {
                // maxX is outside CGRect.contains, so mouseDown falls through
                // to the handle branch there — the premise the "a drawing
                // tool does not swallow the frame" case rests on.
                cursorFails.append("edge handle probe counts as inside")
            }
            @MainActor func moveCursor(to point: CGPoint) {
                guard let move = liveMouse(.mouseMoved, point) else {
                    cursorFails.append("no mouseMoved event")
                    return
                }
                cursorView.mouseMoved(with: move)
            }
            @MainActor func expectCursor(
                _ tool: OverlayAnnotationTool, at point: CGPoint,
                _ want: AppCursor, _ label: String
            ) {
                cursorView.clickReviewToolbarButtonForTesting(
                    tag: tool.toolbarTag)
                moveCursor(to: point)
                let got = cursorView.currentCursorForTesting
                if got != want {
                    cursorFails.append(
                        "\(label): got \(String(describing: got)) want \(want)")
                }
            }
            expectCursor(.select, at: cursorCentre, .openHand, "select inside")
            expectCursor(.pen, at: cursorCentre, .crosshair, "pen inside")
            expectCursor(
                .highlight, at: cursorCentre, .crosshair, "highlight inside")
            expectCursor(.magnifier, at: cursorCentre, .crosshair, "magnifier inside")
            expectCursor(.text, at: cursorCentre, .iBeam, "text inside")
            expectCursor(
                .select, at: cursorRightHandle, .resize(.right),
                "select edge handle")
            // A drawing tool does not swallow the frame: the handle square
            // straddles the edge and a mouseDown out there still resizes.
            expectCursor(
                .pen, at: cursorRightHandle, .resize(.right), "pen edge handle")
            expectCursor(.pen, at: cursorOutside, .crosshair, "pen outside")
            // Switching tools re-derives where the pointer already is — no
            // mouse movement in between, which is the state a keyboard tool
            // switch leaves the app in.
            expectCursor(.pen, at: cursorCentre, .crosshair, "pen before switch")
            cursorView.clickReviewToolbarButtonForTesting(
                tag: OverlayAnnotationTool.select.toolbarTag)
            if cursorView.currentCursorForTesting != .openHand {
                cursorFails.append(
                    "tool switch did not re-derive: \(String(describing: cursorView.currentCursorForTesting))")
            }
            check("overlay-cursor-follows-tool", cursorFails.isEmpty,
                  cursorFails.joined(separator: " | "))

            // Editor: select is the one tool whose cursor depends on what is
            // under the pointer, so it is read over a real annotation and
            // over empty canvas, with the annotation's own hitTest asserting
            // both premises first.
            var editorCursorFails: [String] = []
            let cursorEditorImage = CapturedImage(
                cgImage: makeNoiseImage(width: 200, height: 160), scale: 1)
            let cursorWC = EditorWindowController.open(
                with: cursorEditorImage, forceFitForTesting: true)
            let cursorCanvas = cursorWC.canvasForTesting
            let cursorMark = BlurAnnotation(uiScale: 1)
            cursorMark.rect = CGRect(x: 40, y: 40, width: 60, height: 40)
            cursorCanvas.annotations = [cursorMark]
            let overMark = CGPoint(x: cursorMark.rect.midX, y: cursorMark.rect.midY)
            let overEmpty = CGPoint(x: 170, y: 140)
            if !cursorMark.hitTest(overMark) {
                editorCursorFails.append("probe is not on the annotation")
            }
            if cursorMark.hitTest(overEmpty) {
                editorCursorFails.append("empty probe is on the annotation")
            }
            @MainActor func expectEditorCursor(
                _ tool: EditorTool, at point: CGPoint,
                _ want: AppCursor, _ label: String
            ) {
                cursorCanvas.currentTool = tool
                guard let move = NSEvent.mouseEvent(
                    with: .mouseMoved,
                    location: cursorCanvas.convert(point, to: nil),
                    modifierFlags: [], timestamp: 0,
                    windowNumber: cursorCanvas.window?.windowNumber ?? 0,
                    context: nil, eventNumber: 0, clickCount: 1, pressure: 1)
                else {
                    editorCursorFails.append("no mouseMoved event")
                    return
                }
                cursorCanvas.mouseMoved(with: move)
                let got = cursorCanvas.currentCursorForTesting
                if got != want {
                    editorCursorFails.append(
                        "\(label): got \(String(describing: got)) want \(want)")
                }
            }
            expectEditorCursor(.select, at: overMark, .openHand, "select over mark")
            expectEditorCursor(.select, at: overEmpty, .arrow, "select over empty")
            expectEditorCursor(.pen, at: overMark, .crosshair, "pen over mark")
            expectEditorCursor(.text, at: overEmpty, .iBeam, "text")
            expectEditorCursor(.magnifier, at: overEmpty, .crosshair, "magnifier")
            cursorWC.window?.close()
            check("editor-cursor-follows-tool", editorCursorFails.isEmpty,
                  editorCursorFails.joined(separator: " | "))

            // Panel: no selection geometry, so the tool alone decides — and
            // the toolbar has to tell the host, or AppKit keeps serving the
            // previous tool's cached rects.
            var panelCursorFails: [String] = []
            let cursorPanel = ScrollResultPanel.show(
                image: CapturedImage(
                    cgImage: makeNoiseImage(width: 180, height: 140), scale: 1),
                inputs: OverlaySessionInputs(
                    afterShow: true, afterCopy: false, afterSave: false),
                screen: screen, dependencies: noopDeps())
            if let panelHost = cursorPanel.annotationHostForTesting {
                let panelCases: [(OverlayAnnotationTool, AppCursor)] = [
                    (.select, .arrow), (.pen, .crosshair),
                    (.highlight, .crosshair), (.text, .iBeam),
                    (.spotlight, .crosshair),
                ]
                for (tool, want) in panelCases {
                    cursorPanel.clickToolbarButtonForTesting(tag: tool.toolbarTag)
                    if panelHost.cursorForTool != want {
                        panelCursorFails.append(
                            "\(tool): \(panelHost.cursorForTool) want \(want)")
                    }
                    if panelHost.cursorToolForTesting != tool {
                        panelCursorFails.append(
                            "\(tool): host never told, saw \(String(describing: panelHost.cursorToolForTesting))")
                    }
                }
            } else {
                panelCursorFails.append("no annotation host")
            }
            cursorPanel.dismissForTesting()
            check("panel-cursor-follows-tool", panelCursorFails.isEmpty,
                  panelCursorFails.joined(separator: " | "))

            // S5 fail-first: Translate is a real shared toolbar action and
            // both terminal hosts claim it BEFORE the dependency can
            // synchronously re-enter. The dependency observes teardown,
            // preventing duplicate OCR tasks/windows/network requests.
            @MainActor func allButtons12(in root: NSView) -> [NSButton] {
                root.subviews.flatMap { child -> [NSButton] in
                    let own = (child as? NSButton).map { [$0] } ?? []
                    return own + allButtons12(in: child)
                }
            }
            @MainActor func actionCatalog12(in root: NSView)
                -> [(Int, String)] {
                allButtons12(in: root)
                    .filter { $0.tag >= 0 && $0.tag < 100 }
                    // The accessibility label, not `toolTip`: HoverHint turns
                    // the native tooltip OFF on every button it watches, so
                    // this comparison would be "" == "" for both hosts and
                    // could no longer tell their catalogs apart.
                    .map { ($0.tag, $0.accessibilityLabel() ?? "") }
                    .sorted { $0.0 < $1.0 }
            }

            let translateTag12 = OverlayActionCatalog.items.firstIndex {
                $0.intent == .translate
            } ?? -1
            var areaTranslateCalls = 0
            var areaTranslateModes: [Bool] = []
            var areaCompletion = 0
            var areaPhaseDuring: OverlaySessionPhase?
            var areaCompletionDuring = -1
            var areaTranslateRects: [CGRect] = []
            weak var areaTranslateView: SelectionOverlayView?
            let areaTranslateOverlay = SelectionOverlay(
                purpose: .areaReview,
                inputs: OverlaySessionInputs(
                    afterShow: true, afterCopy: true, afterSave: true),
                completion: { _ in areaCompletion += 1 })
            areaTranslateOverlay.routerDependenciesOverride =
                CaptureActionRouter.Dependencies(
                    copyToClipboard: { _ in }, autoSave: { _, _ in },
                    saveAs: { _, _ in }, pin: { _ in },
                    ocrWithMode: { _, autoTranslate in
                        areaTranslateCalls += 1
                        areaTranslateModes.append(autoTranslate)
                        areaPhaseDuring = areaTranslateOverlay.session.phase
                        areaCompletionDuring = areaCompletion
                        if areaTranslateCalls == 1 {
                            areaTranslateView?.performReviewActionForTesting(
                                .translate)
                        }
                    },
                    openEditor: { _ in }, toast: { _ in },
                    setLastCapture: { _ in },
                    setLastAreaRect: { areaTranslateRects.append($0) },
                    logEvent: { _ in })
            let areaTranslateHost = SelectionOverlayView(
                mode: .area, screen: screen, frozen: frozenImage,
                windowList: [], owner: areaTranslateOverlay)
            areaTranslateView = areaTranslateHost
            let areaTranslateSelection = CGRect(
                x: max(80, b.width / 2 - 120),
                y: max(100, b.height / 2 - 80),
                width: 240, height: 160)
            areaTranslateHost.selectForTesting(rect: areaTranslateSelection)
            let areaTranslateButtons = allButtons12(in: areaTranslateHost)
                // Located by CATALOG TAG, not by a copy of the tooltip: the
                // tooltips now name their shortcut key, and a filter holding a
                // stale literal matches nothing — which reads as a passing
                // click that never happened rather than as a failure.
                .filter { $0.tag == translateTag12 }
            areaTranslateButtons.first?.performClick(nil)

            var panelTranslateCalls = 0
            var panelTranslateModes: [Bool] = []
            var panelDetachedDuring = false
            var panelAreaRects = 0
            weak var panelTranslateProbe: ScrollResultPanel?
            let panelTranslateDeps = CaptureActionRouter.Dependencies(
                copyToClipboard: { _ in }, autoSave: { _, _ in },
                saveAs: { _, _ in }, pin: { _ in },
                ocrWithMode: { _, autoTranslate in
                    panelTranslateCalls += 1
                    panelTranslateModes.append(autoTranslate)
                    panelDetachedDuring = ScrollResultPanel.current == nil
                    if panelTranslateCalls == 1 {
                        panelTranslateProbe?.performActionForTesting(.translate)
                    }
                },
                openEditor: { _ in }, toast: { _ in },
                setLastCapture: { _ in },
                setLastAreaRect: { _ in panelAreaRects += 1 },
                logEvent: { _ in })
            let panelTranslate = ScrollResultPanel.show(
                image: CapturedImage(
                    cgImage: makeStripePattern(
                        width: 96, height: 900, seed: 0x5125_7001),
                    scale: 1),
                inputs: OverlaySessionInputs(
                    afterShow: true, afterCopy: true, afterSave: true),
                screen: screen, dependencies: panelTranslateDeps)
            panelTranslateProbe = panelTranslate
            let panelRoot12 = panelTranslate.contentView ?? NSView()
            let panelTranslateButtons = allButtons12(in: panelRoot12)
                // Located by CATALOG TAG, not by a copy of the tooltip: the
                // tooltips now name their shortcut key, and a filter holding a
                // stale literal matches nothing — which reads as a passing
                // click that never happened rather than as a failure.
                .filter { $0.tag == translateTag12 }
            let areaCatalog12 = actionCatalog12(in: areaTranslateHost)
            let panelCatalog12 = actionCatalog12(in: panelRoot12)
            panelTranslateButtons.first?.performClick(nil)
            let catalogsMatch12 = areaCatalog12.count == panelCatalog12.count
                && zip(areaCatalog12, panelCatalog12).allSatisfy {
                    $0.0.0 == $0.1.0 && $0.0.1 == $0.1.1
                }
            let translateHostsOK = areaTranslateButtons.count == 1
                && panelTranslateButtons.count == 1
                && areaCatalog12.count == 6
                && catalogsMatch12
                && Set(areaCatalog12.map(\.0)).count == 6
                && areaTranslateCalls == 1
                && areaTranslateModes == [true]
                && areaTranslateOverlay.session.phase == .completed
                && areaCompletion == 1
                && areaPhaseDuring == .completed
                && areaCompletionDuring == 1
                && areaTranslateRects.count == 1
                && panelTranslateCalls == 1
                && panelTranslateModes == [true]
                && panelDetachedDuring && panelAreaRects == 0
            check("overlay12-translate-hosts-s5", translateHostsOK,
                  "buttons \(areaTranslateButtons.count)/\(panelTranslateButtons.count) catalog \(areaCatalog12)/\(panelCatalog12) calls \(areaTranslateCalls)/\(panelTranslateCalls) modes \(areaTranslateModes)/\(panelTranslateModes) area phase/completion \(areaTranslateOverlay.session.phase)/\(areaCompletion) observed \(String(describing: areaPhaseDuring))/\(areaCompletionDuring) rects \(areaTranslateRects.count)/\(panelAreaRects) detached \(panelDetachedDuring)")
            // RED cleanup: if no Translate button existed, close the retained
            // panel through an existing terminal route.
            if ScrollResultPanel.current === panelTranslate {
                panelTranslate.performActionForTesting(.copy)
            }

            // --- 1.2.16: region OCR keeps the shot, and reads the RIGHT region
            //
            // The fixture carries DIFFERENT text in its top and bottom halves.
            // A region over the top must return the top's words and not the
            // bottom's — which is what pins the coordinate system. View points
            // are bottom-left; `CGImage.cropping(to:)`, `session.pixelRect`
            // and `flattened(cropPixels:)` are top-left. Scaling the view rect
            // without flipping it reads the region mirrored, and every other
            // assertion here would still pass.
            do {
                var ocrFailures: [String] = []
                let regionFixture = makeSplitTextImage(
                    top: "TOPMARK", bottom: "LOWMARK",
                    width: 900, height: 600)
                let regionFrozen = CapturedImage(
                    cgImage: regionFixture, scale: 1)
                var regionCompletions = 0
                let regionOverlay = SelectionOverlay(
                    purpose: .areaReview,
                    inputs: OverlaySessionInputs(
                        afterShow: true, afterCopy: false, afterSave: false),
                    completion: { _ in regionCompletions += 1 })
                regionOverlay.routerDependenciesOverride =
                    CaptureActionRouter.Dependencies(
                        copyToClipboard: { _ in }, autoSave: { _, _ in },
                        saveAs: { _, _ in }, pin: { _ in },
                        ocrWithMode: { _, _ in
                            // Reaching the ROUTER at all means the sub-mode
                            // fell through to the old terminal intent.
                            ocrFailures.append("routed-terminal-ocr")
                        },
                        openEditor: { _ in }, toast: { _ in },
                        setLastCapture: { _ in }, setLastAreaRect: { _ in },
                        logEvent: { _ in })
                let regionHost = SelectionOverlayView(
                    mode: .area, screen: screen, frozen: regionFrozen,
                    windowList: [], owner: regionOverlay)
                regionHost.frame = CGRect(
                    x: 0, y: 0, width: 900, height: 600)
                let regionCrop = CGRect(x: 40, y: 40, width: 820, height: 520)
                regionHost.selectForTesting(rect: regionCrop)

                // Upper half in VIEW coordinates (bottom-left origin), which
                // is where "TOPMARK" is drawn.
                let upper = CGRect(x: 60, y: 330, width: 780, height: 210)
                // Armed through the REAL button, by catalog tag. Calling the
                // test hook here left the dispatcher untested: deleting the
                // `.ocr` intercept in `performReviewAction` restored the whole
                // 1.2.15 terminal behaviour with the suite still green.
                guard let ocrTag = OverlayActionCatalog.items.firstIndex(
                    where: { $0.intent == .ocr })
                else {
                    ocrFailures.append("no-ocr-catalog-entry")
                    check("sliceB-overlay-ocr-region", false, "no catalog entry")
                    return
                }
                regionHost.clickReviewToolbarButtonForTesting(tag: ocrTag)
                if !regionHost.ocrRegionPickingForTesting {
                    ocrFailures.append("button-did-not-arm-picking")
                }
                if regionOverlay.session.phase != .reviewing {
                    ocrFailures.append(
                        "arming-changed-phase \(regionOverlay.session.phase)")
                }
                regionHost.pickOCRRegionForTesting(
                    from: CGPoint(x: upper.minX, y: upper.minY),
                    to: CGPoint(x: upper.maxX, y: upper.maxY))

                // Recognition is async; spin the run loop rather than sleeping
                // so the MainActor hop that fills the panel can actually run.
                let regionDeadline = Date().addingTimeInterval(30)
                while Date() < regionDeadline,
                      regionHost.ocrResultPanelForTesting?
                        .recognizedText.isEmpty != false {
                    RunLoop.current.run(
                        mode: .default, before: Date().addingTimeInterval(0.05))
                }
                let recognized = (regionHost.ocrResultPanelForTesting?
                    .recognizedText ?? "").uppercased()
                if !recognized.contains("TOPMARK") {
                    ocrFailures.append("missing-top '\(recognized)'")
                }
                if recognized.contains("LOWMARK") {
                    ocrFailures.append("read-mirrored '\(recognized)'")
                }

                // The whole point of the owner's request: the shot survives.
                if regionOverlay.session.phase != .reviewing {
                    ocrFailures.append(
                        "session-ended \(regionOverlay.session.phase)")
                }
                if regionCompletions != 0 {
                    ocrFailures.append("completed \(regionCompletions)")
                }
                if regionHost.areaSelectionForTesting != regionCrop {
                    ocrFailures.append("crop-moved")
                }

                // The panel is for reading text NEXT to its pixels, so it may
                // not sit on them.
                if let panelFrame = regionHost.ocrResultPanelFrameForTesting {
                    if panelFrame.intersects(upper) {
                        ocrFailures.append("panel-covers-region \(panelFrame)")
                    }
                } else {
                    ocrFailures.append("no-panel")
                }

                // Moving the crop has to carry the panel with it. Measuring
                // only at the moment it opens leaves this green while the
                // panel sits on the shot.
                let movedCrop = regionCrop.offsetBy(dx: 20, dy: -20)
                regionHost.selectForTesting(rect: movedCrop)
                regionHost.layoutReviewToolbarForTesting()
                if let movedFrame = regionHost.ocrResultPanelFrameForTesting,
                   movedFrame.intersects(upper) {
                    ocrFailures.append("panel-covers-after-move \(movedFrame)")
                }
                regionHost.selectForTesting(rect: regionCrop)
                regionHost.layoutReviewToolbarForTesting()

                // Copy takes the text WITHOUT taking the session with it.
                if let copyButton = regionHost.ocrResultPanelForTesting?
                    .control(identifier: OverlayOCRPanel.copyIdentifier) {
                    copyButton.performClick(nil)
                } else {
                    ocrFailures.append("no-copy-button")
                }
                if regionOverlay.session.phase != .reviewing
                    || regionCompletions != 0 {
                    ocrFailures.append(
                        "copy-ended-session \(regionOverlay.session.phase)")
                }
                if regionHost.ocrResultPanelFrameForTesting != nil {
                    ocrFailures.append("copy-left-panel-open")
                }

                // Esc unwinds one layer at a time: panel, then the pick, then
                // the session. Closing the shot while the text is on screen is
                // exactly what the owner asked us to stop doing.
                regionHost.clickReviewToolbarButtonForTesting(tag: ocrTag)
                if !regionHost.ocrRegionPickingForTesting {
                    ocrFailures.append("second-arm-failed")
                }
                regionHost.handleEscapeForTesting()
                if regionHost.ocrRegionPickingForTesting {
                    ocrFailures.append("esc-left-picking-armed")
                }
                if regionOverlay.session.phase != .reviewing {
                    ocrFailures.append("esc-ended-session-too-early")
                }
                regionHost.handleEscapeForTesting()
                if regionOverlay.session.phase != .completed {
                    ocrFailures.append(
                        "esc-did-not-cancel \(regionOverlay.session.phase)")
                }
                // The security case. Region OCR reads the FLATTENED surface,
                // so a pixelation the user drew over something sensitive hides
                // it from Vision too. Cropping the raw freeze instead would
                // read straight through the redaction and hand back the very
                // words they just covered — and every other assertion above
                // would still pass, because with no annotations the two paths
                // return identical bytes.
                let redactOverlay = SelectionOverlay(
                    purpose: .areaReview,
                    inputs: OverlaySessionInputs(
                        afterShow: true, afterCopy: false, afterSave: false),
                    completion: { _ in })
                redactOverlay.routerDependenciesOverride =
                    CaptureActionRouter.Dependencies(
                        copyToClipboard: { _ in }, autoSave: { _, _ in },
                        saveAs: { _, _ in }, pin: { _ in },
                        ocrWithMode: { _, _ in }, openEditor: { _ in },
                        toast: { _ in }, setLastCapture: { _ in },
                        setLastAreaRect: { _ in }, logEvent: { _ in })
                let redactHost = SelectionOverlayView(
                    mode: .area, screen: screen, frozen: regionFrozen,
                    windowList: [], owner: redactOverlay)
                redactHost.frame = CGRect(x: 0, y: 0, width: 900, height: 600)
                redactHost.selectForTesting(rect: regionCrop)
                redactHost.clickReviewToolbarButtonForTesting(
                    tag: OverlayAnnotationTool.blur.toolbarTag)
                // Cover the upper band, generously, through the real drag.
                redactHost.annotationDragForTesting(
                    from: CGPoint(x: upper.minX - 10, y: upper.minY - 10),
                    to: CGPoint(x: upper.maxX + 10, y: upper.maxY + 10))
                redactHost.clickReviewToolbarButtonForTesting(tag: ocrTag)
                redactHost.pickOCRRegionForTesting(
                    from: CGPoint(x: upper.minX, y: upper.minY),
                    to: CGPoint(x: upper.maxX, y: upper.maxY))
                let redactDeadline = Date().addingTimeInterval(30)
                while Date() < redactDeadline,
                      redactHost.ocrResultPanelForTesting?
                        .statusForTesting == "Recognizing…" {
                    RunLoop.current.run(
                        mode: .default, before: Date().addingTimeInterval(0.05))
                }
                let redacted = (redactHost.ocrResultPanelForTesting?
                    .recognizedText ?? "").uppercased()
                if redactHost.annotationSurfaceIsEmptyForTesting {
                    // The fixture failed, not the feature: with no annotation
                    // the flattened and raw paths return identical bytes, so
                    // the assertion below would prove nothing.
                    ocrFailures.append("redaction-fixture-empty")
                }
                if let sent = redactHost.lastOCRSourceForTesting {
                    writePNG(sent, to: "\(outputDir)/ocr-region-redacted.png")
                }
                if let clean = regionHost.lastOCRSourceForTesting {
                    writePNG(clean, to: "\(outputDir)/ocr-region-clean.png")
                }
                if redacted.contains("TOPMARK") {
                    ocrFailures.append("read-through-redaction '\(redacted)'")
                }
                redactHost.handleEscapeForTesting()
                redactHost.handleEscapeForTesting()

                check("sliceB-overlay-ocr-region",
                      ocrFailures.isEmpty,
                      ocrFailures.prefix(6).joined(separator: " | "))
            }

            // --- 1.2.16: the action keys and the hints that advertise them
            do {
                var keyFailures: [String] = []
                // Routing and the hint read one field, so they cannot drift:
                // a key that routes but is named nowhere is undiscoverable,
                // and a hint naming a key nothing routes is a broken promise.
                for item in OverlayActionCatalog.items {
                    guard let key = item.shortcut else { continue }
                    if !item.tooltip.uppercased().contains(key.uppercased()) {
                        keyFailures.append(
                            "unadvertised \(key) '\(item.tooltip)'")
                    }
                    if OverlayActionCatalog.intent(forShortcutKey: key)
                        != item.intent {
                        keyFailures.append("lookup \(key)")
                    }
                    // Disjoint from the drawing tools by CONSTRUCTION, not by
                    // where the two branches happen to sit in `keyDown`.
                    if OverlayAnnotationTool.tool(forShortcutKey: key) != nil {
                        keyFailures.append("collides-with-tool \(key)")
                    }
                }
                let expected: [(String, CaptureIntent)] = [
                    ("e", .openEditor), ("x", .ocr),
                    ("g", .translate), ("f", .pin),
                ]
                for (key, intent) in expected {
                    if OverlayActionCatalog.intent(forShortcutKey: key)
                        != intent {
                        keyFailures.append(
                            "table \(key) -> "
                            + String(describing:
                                OverlayActionCatalog.intent(forShortcutKey: key)))
                    }
                }
                // Save keeps a modifier and must NOT be reachable bare, or a
                // stray S would open a save sheet instead of Spotlight.
                if OverlayActionCatalog.intent(
                    forShortcutKey: OverlayActionCatalog.saveKey) != nil {
                    keyFailures.append("save-reachable-bare")
                }
                if OverlayAnnotationTool.tool(
                    forShortcutKey: OverlayActionCatalog.saveKey) != .spotlight {
                    keyFailures.append("bare-s-not-spotlight")
                }
                // --- the keys have to actually REACH the view.
                //
                // The table above is static: deleting the whole action-key
                // branch from `keyDown` killed E/X/G/F outright and left this
                // gate green, with the tooltips still advertising them. So
                // every key is fired at a live host through the real
                // responder entry points, and the intent is observed at the
                // router rather than in the catalog.
                @MainActor func keyEvent(
                    _ characters: String,
                    modifiers: NSEvent.ModifierFlags = []
                ) -> NSEvent? {
                    NSEvent.keyEvent(
                        with: .keyDown, location: .zero,
                        modifierFlags: modifiers, timestamp: 0,
                        windowNumber: 0, context: nil,
                        characters: characters,
                        charactersIgnoringModifiers: characters.lowercased(),
                        isARepeat: false, keyCode: 0)
                }
                let keyFrozen = CapturedImage(
                    cgImage: makeTestImage(width: 900, height: 600), scale: 1)
                @MainActor func keyHost(
                    _ record: @escaping (String) -> Void
                ) -> (SelectionOverlay, SelectionOverlayView) {
                    let overlay = SelectionOverlay(
                        purpose: .areaReview,
                        inputs: OverlaySessionInputs(
                            afterShow: true, afterCopy: false, afterSave: false),
                        completion: { _ in record("finish") })
                    overlay.routerDependenciesOverride =
                        CaptureActionRouter.Dependencies(
                            copyToClipboard: { _ in record("copy") },
                            autoSave: { _, _ in record("autoSave") },
                            saveAs: { _, done in
                                record("saveAs")
                                done(.cancelled)
                            },
                            pin: { _ in record("pin") },
                            ocrWithMode: { _, translate in
                                record(translate ? "translate" : "ocr")
                            },
                            openEditor: { _ in record("openEditor") },
                            toast: { _ in }, setLastCapture: { _ in },
                            setLastAreaRect: { _ in }, logEvent: { _ in })
                    let view = SelectionOverlayView(
                        mode: .area, screen: screen, frozen: keyFrozen,
                        windowList: [], owner: overlay)
                    view.frame = CGRect(x: 0, y: 0, width: 900, height: 600)
                    view.selectForTesting(
                        rect: CGRect(x: 100, y: 100, width: 500, height: 340))
                    return (overlay, view)
                }

                // X arms the picker and must NOT reach the router: the whole
                // point of 1.2.16 is that OCR stopped being terminal.
                var xEffects: [String] = []
                let (xOverlay, xView) = keyHost { xEffects.append($0) }
                if let event = keyEvent("x") { xView.keyDown(with: event) }
                if !xView.ocrRegionPickingForTesting {
                    keyFailures.append(
                        "x-did-not-arm phase="
                        + String(describing: xOverlay.session.phase)
                        + " sel=" + String(describing:
                            xView.areaSelectionForTesting))
                }
                if !xEffects.isEmpty {
                    keyFailures.append("x-routed \(xEffects)")
                }
                // And a key arriving mid-drag is swallowed, or a stray letter
                // during a pen stroke would change what the shot is for.
                var dragEffects: [String] = []
                let (dragOverlay, dragView) = keyHost { dragEffects.append($0) }
                dragView.clickReviewToolbarButtonForTesting(
                    tag: OverlayAnnotationTool.pen.toolbarTag)
                dragView.annotationDragForTesting(
                    from: CGPoint(x: 150, y: 150),
                    to: CGPoint(x: 300, y: 260),
                    whileDown: {
                        if let event = keyEvent("x") {
                            dragView.keyDown(with: event)
                        }
                        if dragView.ocrRegionPickingForTesting {
                            keyFailures.append("x-armed-mid-drag")
                        }
                        if let event = keyEvent("f") {
                            dragView.keyDown(with: event)
                        }
                    })
                if dragEffects.contains("pin") {
                    keyFailures.append("f-routed-mid-drag")
                }

                // Each terminal key closes its own session, so each gets its
                // own host — reusing one would test only the first.
                let terminals: [(String, String)] = [
                    ("e", "openEditor"), ("g", "translate"), ("f", "pin"),
                ]
                for (key, expectedEffect) in terminals {
                    var effects: [String] = []
                    let (overlay, view) = keyHost { effects.append($0) }
                    if let event = keyEvent(key) { view.keyDown(with: event) }
                    if !effects.contains(expectedEffect) {
                        keyFailures.append(
                            "\(key)-missed \(expectedEffect) got \(effects)"
                            + " phase=" + String(describing: overlay.session.phase)
                            + " payloadFail=" + String(describing:
                                view.lastPayloadFailureForTesting))
                    }
                }

                // ⌘S goes through the equivalent chain, where ⌘C already
                // lives — from `keyDown` it would never arrive.
                var saveEffects: [String] = []
                let (saveOverlay, saveView) = keyHost { saveEffects.append($0) }
                if let event = keyEvent("s", modifiers: .command) {
                    _ = saveView.performKeyEquivalent(with: event)
                }
                if !saveEffects.contains("saveAs") {
                    keyFailures.append("cmd-s-missed \(saveEffects)")
                }
                // Bare S stays Spotlight: the modifier is what distinguishes
                // them, and losing that turns a tool key into a save sheet.
                var bareEffects: [String] = []
                let (bareOverlay, bareView) = keyHost { bareEffects.append($0) }
                if let event = keyEvent("s") { bareView.keyDown(with: event) }
                if bareEffects.contains("saveAs") {
                    keyFailures.append("bare-s-saved")
                }

                // `SelectionOverlayView.owner` is WEAK. Binding an overlay to
                // `_` lets ARC free it before the key is fired, and every
                // guard that reads `owner` then fails silently — which reads
                // as "the key is not routed" when the routing is fine.
                withExtendedLifetime(
                    [xOverlay, dragOverlay, saveOverlay, bareOverlay]
                ) {}
                check("sliceB-overlay-action-keys",
                      keyFailures.isEmpty,
                      keyFailures.prefix(6).joined(separator: " | "))
            }

            // S5 layout contract. Editing chrome is a vertical rail beside
            // the selection; terminal actions are a horizontal strip below
            // it. Both flip at screen edges and wrap under constrained
            // geometry. Assertions use REAL button frames, not a synthetic
            // geometry helper, so host wiring cannot be vacuous.
            @MainActor func buttonFrame12(
                _ button: NSButton, in root: NSView
            ) -> CGRect {
                button.convert(button.bounds, to: root)
            }
            @MainActor func union12(_ frames: [CGRect]) -> CGRect? {
                guard var result = frames.first else { return nil }
                for frame in frames.dropFirst() { result = result.union(frame) }
                return result
            }
            @MainActor func distinct12(_ values: [CGFloat]) -> Int {
                Set(values.map { Int(($0 * 10).rounded()) }).count
            }
            @MainActor func separation12(_ a: CGRect, _ b: CGRect) -> CGFloat {
                let dx = max(0, max(a.minX - b.maxX, b.minX - a.maxX))
                let dy = max(0, max(a.minY - b.maxY, b.minY - a.maxY))
                return max(dx, dy)
            }
            @MainActor func inspectAreaLayout12(
                view: SelectionOverlayView, selection: CGRect,
                expectToolSide: String?, expectActionSide: String?,
                requireWrap: Bool
            ) -> [String] {
                let buttons = allButtons12(in: view)
                let editing = buttons.filter { $0.tag >= 100 }
                let actions = buttons.filter { $0.tag < 100 }
                let editingFrames = editing.map { buttonFrame12($0, in: view) }
                let actionFrames = actions.map { buttonFrame12($0, in: view) }
                let orderedButtons = editing + actions
                let allFrames = editingFrames + actionFrames
                var failures: [String] = []
                // The AREA catalog: this inspects the area host, which now
                // offers one tool the panel does not, plus Color/Undo/Redo and
                // the Backdrop chooser.
                if editing.count
                    != OverlayAnnotationTool.areaReviewTools.count + 4 {
                    failures.append("editing count \(editing.count)")
                }
                if actions.count != 7 { failures.append("action count \(actions.count)") }
                if let frame = union12(editingFrames), let side = expectToolSide {
                    if side == "right", frame.minX < selection.maxX {
                        failures.append("tools not right \(frame)")
                    }
                    if side == "left", frame.maxX > selection.minX {
                        failures.append("tools not left \(frame)")
                    }
                } else if editingFrames.isEmpty { failures.append("no tool frames") }
                if let frame = union12(actionFrames), let side = expectActionSide {
                    if side == "below", frame.maxY > selection.minY {
                        failures.append("actions not below \(frame)")
                    }
                    if side == "above", frame.minY < selection.maxY {
                        failures.append("actions not above \(frame)")
                    }
                } else if actionFrames.isEmpty { failures.append("no action frames") }
                for (i, frame) in allFrames.enumerated() {
                    if !view.bounds.contains(frame) {
                        failures.append("button \(i) outside \(frame)")
                    }
                    let center = CGPoint(x: frame.midX, y: frame.midY)
                    if view.hitTest(center) !== orderedButtons[i] {
                        failures.append("button \(i) not hit-testable")
                    }
                    for j in (i + 1)..<allFrames.count
                        where frame.intersects(allFrames[j]) {
                        failures.append("buttons \(i)/\(j) overlap")
                    }
                    for (handle, handleRect) in EditableSelectionGeometry
                        .handleRects(for: selection, size: 18)
                        where frame.intersects(handleRect) {
                        failures.append("button \(i) hits \(handle)")
                    }
                }
                if requireWrap {
                    if distinct12(editingFrames.map(\.minX)) <= 1 {
                        failures.append("tools did not wrap columns")
                    }
                    if distinct12(actionFrames.map(\.minY)) <= 1 {
                        failures.append("actions did not wrap rows")
                    }
                    if editingFrames.count >= 2,
                       abs(editingFrames[0].midX - editingFrames[1].midX) > 0.1
                        || editingFrames[0].minY <= editingFrames[1].minY {
                        failures.append("tool order is not top-to-bottom")
                    }
                    if actionFrames.count >= 2,
                       abs(actionFrames[0].midY - actionFrames[1].midY) > 0.1
                        || actionFrames[0].minX >= actionFrames[1].minX {
                        failures.append("action order is not left-to-right")
                    }
                }
                return failures
            }

            var layout12Failures: [String] = []
            let normalSelection = CGRect(
                x: max(80, b.width / 2 - 100),
                y: max(120, b.height / 2 - 70),
                width: 200, height: 140)
            let (normalLayoutOverlay, normalLayoutView) = reviewView()
            _ = normalLayoutOverlay
            normalLayoutView.selectForTesting(rect: normalSelection)
            layout12Failures += inspectAreaLayout12(
                view: normalLayoutView, selection: normalSelection,
                expectToolSide: "right", expectActionSide: "below",
                requireWrap: false).map { "normal \($0)" }

            let rightSelection = CGRect(
                x: b.width - 164, y: max(120, b.height / 2 - 50),
                width: 160, height: 100)
            let (rightLayoutOverlay, rightLayoutView) = reviewView()
            _ = rightLayoutOverlay
            rightLayoutView.selectForTesting(rect: rightSelection)
            layout12Failures += inspectAreaLayout12(
                view: rightLayoutView, selection: rightSelection,
                expectToolSide: "left", expectActionSide: nil,
                requireWrap: false).map { "right \($0)" }

            let bottomSelection = CGRect(
                x: max(80, b.width / 2 - 80), y: 4,
                width: 160, height: 100)
            let (bottomLayoutOverlay, bottomLayoutView) = reviewView()
            _ = bottomLayoutOverlay
            bottomLayoutView.selectForTesting(rect: bottomSelection)
            layout12Failures += inspectAreaLayout12(
                view: bottomLayoutView, selection: bottomSelection,
                expectToolSide: nil, expectActionSide: "above",
                requireWrap: false).map { "bottom \($0)" }

            let fullSelection = CGRect(
                x: 4, y: 4, width: b.width - 8, height: b.height - 8)
            let (fullLayoutOverlay, fullLayoutView) = reviewView()
            _ = fullLayoutOverlay
            fullLayoutView.selectForTesting(rect: fullSelection)
            layout12Failures += inspectAreaLayout12(
                view: fullLayoutView, selection: fullSelection,
                expectToolSide: nil, expectActionSide: nil,
                requireWrap: false).map { "full \($0)" }

            let (tinyLayoutOverlay, tinyLayoutView) = reviewView()
            _ = tinyLayoutOverlay
            let tinySelection = CGRect(
                x: b.width / 2 - 20, y: b.height / 2 - 20,
                width: 40, height: 40)
            tinyLayoutView.selectForTesting(rect: tinySelection)
            layout12Failures += inspectAreaLayout12(
                view: tinyLayoutView, selection: tinySelection,
                expectToolSide: nil, expectActionSide: nil,
                requireWrap: true).map { "tiny \($0)" }

            let tinyCornerOrigins = [
                CGPoint(x: 4, y: 4),
                CGPoint(x: b.width - 44, y: 4),
                CGPoint(x: 4, y: b.height - 44),
                CGPoint(x: b.width - 44, y: b.height - 44),
            ]
            for (corner, origin) in tinyCornerOrigins.enumerated() {
                let (cornerOverlay, cornerView) = reviewView()
                _ = cornerOverlay
                let selection = CGRect(origin: origin, size: CGSize(
                    width: 40, height: 40))
                cornerView.selectForTesting(rect: selection)
                layout12Failures += inspectAreaLayout12(
                    view: cornerView, selection: selection,
                    expectToolSide: nil, expectActionSide: nil,
                    requireWrap: true).map { "corner\(corner) \($0)" }
                let cornerButtons = allButtons12(in: cornerView)
                let cornerToolFrames = cornerButtons.filter { $0.tag >= 100 }
                    .map { buttonFrame12($0, in: cornerView) }
                let cornerActionFrames = cornerButtons.filter { $0.tag < 100 }
                    .map { buttonFrame12($0, in: cornerView) }
                // ADJACENCY, not a distance budget. Production either hugs
                // the selection or sits immediately beyond the other group
                // (the companion candidates in OverlayToolbarLayout.area), so
                // the invariant is "touches one of those two" — which stays
                // just as tight when a toolbar grows. A bound scaled to the
                // toolbars' own size would have let a whole rail slide 400pt
                // away and still pass.
                let neighbourGap: CGFloat = 40
                for (name, frames, companion) in [
                    ("tools", cornerToolFrames, cornerActionFrames),
                    ("actions", cornerActionFrames, cornerToolFrames),
                ] {
                    guard let frame = union12(frames) else { continue }
                    let toSelection = separation12(frame, selection)
                    let toCompanion = union12(companion)
                        .map { separation12(frame, $0) }
                        ?? CGFloat.greatestFiniteMagnitude
                    if min(toSelection, toCompanion) > neighbourGap {
                        layout12Failures.append(
                            "corner\(corner) \(name) teleported \(frame) "
                                + "sel=\(toSelection) companion=\(toCompanion)")
                    }
                }
            }

            let layoutPanel = ScrollResultPanel.show(
                image: CapturedImage(
                    cgImage: makeStripePattern(
                        width: 64, height: 800, seed: 0x5125_7002),
                    scale: 1),
                inputs: OverlaySessionInputs(
                    afterShow: true, afterCopy: false, afterSave: false),
                screen: screen, dependencies: noopDeps())
            if let bar = layoutPanel.toolbarFrameForTesting {
                let frames = layoutPanel.toolbarButtonFramesForTesting
                let rowCount = distinct12(frames.map(\.minY))
                if rowCount <= 1 { layout12Failures.append("panel did not wrap") }
                let barBounds = CGRect(origin: .zero, size: bar.size)
                for (i, frame) in frames.enumerated() {
                    if !barBounds.contains(frame) {
                        layout12Failures.append("panel button \(i) outside")
                    }
                    for j in (i + 1)..<frames.count
                        where frame.intersects(frames[j]) {
                        layout12Failures.append("panel buttons \(i)/\(j) overlap")
                    }
                    if let content = layoutPanel.contentView {
                        let center = CGPoint(
                            x: bar.minX + frame.midX,
                            y: bar.minY + frame.midY)
                        if !(content.hitTest(center) is NSButton) {
                            layout12Failures.append(
                                "panel button \(i) not hit-testable")
                        }
                    }
                }
                if let host = layoutPanel.annotationHostForTesting,
                   host.frame.intersects(bar) {
                    layout12Failures.append("panel host intersects toolbar")
                }
                if layoutPanel.frame.width > screen.visibleFrame.width * 0.9 + 1
                    || layoutPanel.frame.height > screen.visibleFrame.height * 0.9 + 1 {
                    layout12Failures.append("panel exceeds 90% \(layoutPanel.frame)")
                }
            } else {
                layout12Failures.append("panel has no toolbar")
            }
            layoutPanel.performActionForTesting(.copy)

            // Regression for the 5K×40K class: natural width is huge, but
            // vertical fit makes the displayed image narrow. Panel chrome
            // must converge to that FITTED width (plus the 206pt HUD floor)
            // instead of leaving an almost-screen-wide empty toolbar.
            let wideTallPanel = ScrollResultPanel.show(
                image: CapturedImage(
                    cgImage: makeStripePattern(
                        width: 250, height: 2000, seed: 0x5125_7003),
                    scale: 0.1), // 2500×20000pt without a 200MB fixture
                inputs: OverlaySessionInputs(
                    afterShow: true, afterCopy: false, afterSave: false),
                screen: screen, dependencies: noopDeps())
            if let wideBar = wideTallPanel.toolbarFrameForTesting,
               let wideHost = wideTallPanel.annotationHostForTesting {
                let minimumWidth = min(screen.visibleFrame.width * 0.9, 206)
                let expectedCompactWidth = max(minimumWidth, wideHost.frame.width)
                if wideTallPanel.frame.width > expectedCompactWidth + 1 {
                    layout12Failures.append(
                        "wide-tall chrome waste panel \(wideTallPanel.frame.width) host \(wideHost.frame.width)")
                }
                if distinct12(
                    wideTallPanel.toolbarButtonFramesForTesting.map(\.minY)) <= 1 {
                    layout12Failures.append("wide-tall panel did not wrap")
                }
                if wideHost.frame.intersects(wideBar) {
                    layout12Failures.append("wide-tall host intersects toolbar")
                }
                if wideTallPanel.frame.width > screen.visibleFrame.width * 0.9 + 1
                    || wideTallPanel.frame.height
                        > screen.visibleFrame.height * 0.9 + 1 {
                    layout12Failures.append(
                        "wide-tall panel exceeds 90% \(wideTallPanel.frame)")
                }
            } else {
                layout12Failures.append("wide-tall panel missing geometry")
            }
            wideTallPanel.performActionForTesting(.copy)
            check("overlay12-layout-s5", layout12Failures.isEmpty,
                  layout12Failures.joined(separator: "; "))

            // Full-toolbar S1 fail-first gate. It compiles against the old
            // five-tool enum, but stays red until Line/Oval/Highlighter and
            // Counter are actually routed through the production area-view
            // mouse handlers and rendered into the exported crop.
            let s1Names = ["Line", "Oval", "Highlighter", "Counter"]
            let s1Tools = OverlayAnnotationTool.allCases.filter { tool in
                s1Names.contains { tool.tooltip.hasPrefix($0) }
            }
            var s1Failures: [String] = []
            if s1Tools.count != s1Names.count {
                s1Failures.append("catalog \(s1Tools.count)/\(s1Names.count)")
            }
            for tool in s1Tools {
                let name = s1Names.first { tool.tooltip.hasPrefix($0) }
                    ?? tool.tooltip
                let (overlay, view) = reviewView()
                let selection = CGRect(
                    x: max(40, b.width / 2 - 150),
                    y: max(100, b.height / 2 - 100),
                    width: 300, height: 200)
                view.selectForTesting(rect: selection)
                guard let surface = view.annotationSurface else {
                    s1Failures.append("\(name) no surface")
                    continue
                }
                surface.tool = tool
                let start = CGPoint(
                    x: selection.minX + 55,
                    y: selection.minY + 55)
                let end = CGPoint(
                    x: selection.minX + 175,
                    y: selection.minY + 125)
                if let down = liveMouse(.leftMouseDown, start) {
                    view.mouseDown(with: down)
                }
                if let drag = liveMouse(.leftMouseDragged, end) {
                    view.mouseDragged(with: drag)
                }
                if let up = liveMouse(.leftMouseUp, end) {
                    view.mouseUp(with: up)
                }
                guard let annotation = surface.annotations.last else {
                    s1Failures.append("\(name) no annotation")
                    continue
                }
                let correctKind: Bool
                switch (name, annotation) {
                case ("Line", let shape as ShapeAnnotation):
                    if case .line = shape.kind { correctKind = true }
                    else { correctKind = false }
                case ("Oval", let shape as ShapeAnnotation):
                    if case .oval = shape.kind { correctKind = true }
                    else { correctKind = false }
                case ("Highlighter", let shape as ShapeAnnotation):
                    if case .highlight = shape.kind { correctKind = true }
                    else { correctKind = false }
                case ("Counter", let counter as CounterAnnotation):
                    correctKind = counter.number == 1
                default:
                    correctKind = false
                }
                if !correctKind {
                    s1Failures.append("\(name) wrong model")
                }
                let plain = frozenImage.cgImage.cropping(
                    to: overlay.session.pixelRect)
                let flat = surface.flattened(
                    base: frozenImage.cgImage,
                    cropPixels: overlay.session.pixelRect)
                if plain == nil || flat == nil
                    || imagesEqual(plain!, flat!) {
                    s1Failures.append("\(name) no export ink")
                }
                if name == "Counter" {
                    let second = CGPoint(
                        x: selection.minX + 220,
                        y: selection.minY + 145)
                    if let down = liveMouse(.leftMouseDown, second) {
                        view.mouseDown(with: down)
                    }
                    if let up = liveMouse(.leftMouseUp, second) {
                        view.mouseUp(with: up)
                    }
                    let counters = surface.annotations.compactMap {
                        ($0 as? CounterAnnotation)?.number
                    }
                    if counters != [1, 2] {
                        s1Failures.append("Counter sequence \(counters)")
                    }
                }
            }
            check("overlay8-full-tools-s1", s1Failures.isEmpty,
                  s1Failures.joined(separator: "; "))

            // S2 production/catalog gate: Pixelate must be the SAME real
            // toolbar item/tag on area + scroll, and reverse-drag must create
            // the editor's BlurAnnotation model through live mouse handlers.
            // Identity, not a tooltip prefix: slice B adds a second tool whose
            // name also starts with "Pixelate". The gate is about Pixelate
            // having the SAME tag on both surfaces, which identity expresses.
            let s2Tools = OverlayAnnotationTool.allCases.filter { $0 == .blur }
            var s2ToolbarFailures: [String] = []
            if s2Tools.count != 1 {
                s2ToolbarFailures.append("catalog \(s2Tools.count)/1")
            }
            if let tool = s2Tools.first,
               let index = OverlayAnnotationTool.allCases.firstIndex(of: tool) {
                let expectedTag = 100 + index
                let (areaOverlay, view) = reviewView()
                let selection = CGRect(
                    x: max(40, b.width / 2 - 150),
                    y: max(100, b.height / 2 - 100),
                    width: 300, height: 200)
                view.selectForTesting(rect: selection)
                let areaPixelate = view.reviewToolbarButtonsForTesting.filter {
                    $0.tooltip == OverlayAnnotationTool.blur.tooltip
                }
                if areaPixelate.map(\.tag) != [expectedTag] {
                    s2ToolbarFailures.append(
                        "area tags \(areaPixelate.map(\.tag)) all \(view.reviewToolbarButtonsForTesting)")
                }
                view.clickReviewToolbarButtonForTesting(tag: expectedTag)
                if view.annotationSurface?.tool != tool {
                    s2ToolbarFailures.append("area click did not select")
                }
                let start = CGPoint(
                    x: selection.minX + 220,
                    y: selection.minY + 145)
                let end = CGPoint(
                    x: selection.minX + 65,
                    y: selection.minY + 45)
                if let down = liveMouse(.leftMouseDown, start) {
                    view.mouseDown(with: down)
                }
                if let drag = liveMouse(.leftMouseDragged, end) {
                    view.mouseDragged(with: drag)
                }
                if let up = liveMouse(.leftMouseUp, end) {
                    view.mouseUp(with: up)
                }
                let wantRect = CGRect(
                    x: end.x, y: end.y,
                    width: start.x - end.x, height: start.y - end.y)
                if let blur = view.annotationSurface?.annotations.last
                    as? BlurAnnotation {
                    if blur.rect != wantRect {
                        s2ToolbarFailures.append(
                            "reverse rect \(blur.rect) want \(wantRect)")
                    }
                } else {
                    s2ToolbarFailures.append("area no BlurAnnotation")
                }
                _ = areaOverlay.session.phase // retain weak owner through input

                let panel = ScrollResultPanel.show(
                    image: frozenImage,
                    inputs: OverlaySessionInputs(
                        afterShow: true, afterCopy: false, afterSave: false),
                    screen: screen, dependencies: noopDeps())
                let panelPixelate = panel.toolbarButtonsForTesting.filter {
                    $0.tooltip == OverlayAnnotationTool.blur.tooltip
                }
                if panelPixelate.map(\.tag) != [expectedTag] {
                    s2ToolbarFailures.append("panel tags \(panelPixelate.map(\.tag))")
                }
                panel.clickToolbarButtonForTesting(tag: expectedTag)
                if panel.annotationSurface.tool != tool {
                    s2ToolbarFailures.append("panel click did not select")
                }
                panel.clickToolbarButtonForTesting(tag: -1)
            }
            check("overlay9-pixelate-toolbar-s2", s2ToolbarFailures.isEmpty,
                  s2ToolbarFailures.joined(separator: "; "))

            // S3 live-host gate: both real area and scroll-panel responders
            // must write the same editor keys, show the same HUD, and stamp
            // the persisted point width onto marks created afterward.
            do {
                var widths: [String: CGFloat] = [
                    EditorTool.arrow.rawValue: 7,
                    EditorTool.pen.rawValue: 6,
                ]
                var writes: [(key: String, value: CGFloat)] = []
                AnnotationSurface.strokeWidthStoreOverrideForTesting =
                    OverlayStrokeWidthStore(
                        read: { widths[$0] ?? 3 },
                        write: { value, key in
                            widths[key] = value
                            writes.append((key, value))
                        })
                defer {
                    AnnotationSurface.strokeWidthStoreOverrideForTesting = nil
                }
                func lineScroll(_ delta: Int32) -> NSEvent? {
                    guard let cg = CGEvent(
                        scrollWheelEvent2Source: nil, units: .line,
                        wheelCount: 1, wheel1: delta,
                        wheel2: 0, wheel3: 0)
                    else { return nil }
                    return NSEvent(cgEvent: cg)
                }

                var hostFailures: [String] = []
                let (strokeOverlay, strokeView) = reviewView()
                let strokeSelection = CGRect(
                    x: max(40, b.width / 2 - 160),
                    y: max(100, b.height / 2 - 110),
                    width: 320, height: 220)
                strokeView.selectForTesting(rect: strokeSelection)
                strokeView.clickReviewToolbarButtonForTesting(
                    tag: OverlayAnnotationTool.arrow.toolbarTag)
                if let up = lineScroll(1) {
                    strokeView.scrollWheel(with: up)
                    strokeView.scrollWheel(with: up)
                }
                let areaHUD = strokeView.subviews.compactMap {
                    $0 as? StrokePreviewView
                }.last
                if widths[EditorTool.arrow.rawValue] != 8
                    || areaHUD?.isHidden != false
                    || areaHUD?.strokeWidth != 8
                    || areaHUD?.hitTest(CGPoint(
                        x: areaHUD?.bounds.midX ?? 0,
                        y: areaHUD?.bounds.midY ?? 0)) != nil
                    || areaHUD.map({ strokeView.bounds.contains($0.frame) })
                        != true {
                    hostFailures.append(
                        "area width \(String(describing: widths[EditorTool.arrow.rawValue])) hud \(String(describing: areaHUD?.strokeWidth))")
                }
                let areaStart = CGPoint(
                    x: strokeSelection.minX + 40,
                    y: strokeSelection.minY + 40)
                let areaEnd = CGPoint(
                    x: strokeSelection.minX + 150,
                    y: strokeSelection.minY + 120)
                if let down = liveMouse(.leftMouseDown, areaStart) {
                    strokeView.mouseDown(with: down)
                }
                if let drag = liveMouse(.leftMouseDragged, areaEnd) {
                    strokeView.mouseDragged(with: drag)
                }
                if let up = liveMouse(.leftMouseUp, areaEnd) {
                    strokeView.mouseUp(with: up)
                }
                if (strokeView.annotationSurface?.annotations.last
                    as? ShapeAnnotation)?.strokeWidthPt != 8 {
                    hostFailures.append("area model width")
                }

                areaHUD?.isHidden = true
                guard strokeOverlay.session.transition(to: .saving) else {
                    hostFailures.append("area save transition")
                    check("overlay10-stroke-width-hosts-s3", false,
                          hostFailures.joined(separator: "; "))
                    return
                }
                let writesBeforeAreaLock = writes.count
                if let up = lineScroll(1) {
                    strokeView.scrollWheel(with: up)
                }
                if writes.count != writesBeforeAreaLock
                    || areaHUD?.isHidden == false {
                    hostFailures.append("area save-lock")
                }
                _ = strokeOverlay.session.transition(to: .reviewing)

                var panelSaveDone: (@MainActor (SaveAsOutcome) -> Void)?
                let panelDeps = CaptureActionRouter.Dependencies(
                    copyToClipboard: { _ in }, autoSave: { _, _ in },
                    saveAs: { _, done in panelSaveDone = done },
                    pin: { _ in }, ocr: { _ in }, openEditor: { _ in },
                    toast: { _ in }, setLastCapture: { _ in },
                    setLastAreaRect: { _ in }, logEvent: { _ in })
                let narrowPanelImage = CapturedImage(
                    cgImage: makeNoiseImage(width: 64, height: 800), scale: 1)
                let panel = ScrollResultPanel.show(
                    image: narrowPanelImage,
                    inputs: OverlaySessionInputs(
                        afterShow: true, afterCopy: false, afterSave: false),
                    screen: screen, dependencies: panelDeps)
                panel.clickToolbarButtonForTesting(
                    tag: OverlayAnnotationTool.pen.toolbarTag)
                if let host = panel.annotationHostForTesting,
                   let up = lineScroll(1) {
                    host.scrollWheel(with: up)
                    host.scrollWheel(with: up)
                    let panelHUD = (panel.contentView?.subviews ?? [])
                        .compactMap { $0 as? StrokePreviewView }.last
                        ?? host.subviews.compactMap {
                            $0 as? StrokePreviewView
                        }.last
                    let panelHUDFrameOK = panel.contentView.map { content in
                        guard let panelHUD else { return false }
                        let frame = panelHUD.convert(panelHUD.bounds, to: content)
                        return content.bounds.contains(frame)
                            && panelHUD.superview === content
                    } == true
                    if widths[EditorTool.pen.rawValue] != 7
                        || panelHUD?.isHidden != false
                        || panelHUD?.strokeWidth != 7
                        || panelHUD?.hitTest(CGPoint(
                            x: panelHUD?.bounds.midX ?? 0,
                            y: panelHUD?.bounds.midY ?? 0)) != nil
                        || !panelHUDFrameOK {
                        hostFailures.append(
                            "panel width \(String(describing: widths[EditorTool.pen.rawValue])) hud \(String(describing: panelHUD?.strokeWidth)) frame \(panelHUDFrameOK)")
                    }
                    panel.drawWithRealEventsForTesting(
                        fromView: CGPoint(x: 10, y: 20),
                        toView: CGPoint(x: 50, y: 90))
                    if (panel.annotationSurface.annotations.last
                        as? PenAnnotation)?.strokeWidthPt != 7 {
                        hostFailures.append("panel model width")
                    }
                    panelHUD?.isHidden = true
                    panel.performActionForTesting(.save)
                    let writesBeforePanelLock = writes.count
                    host.scrollWheel(with: up)
                    if panelSaveDone == nil
                        || writes.count != writesBeforePanelLock
                        || panelHUD?.isHidden == false {
                        hostFailures.append("panel save-lock")
                    }
                    panelSaveDone?(.cancelled)
                    host.scrollWheel(with: up)
                    if writes.count != writesBeforePanelLock + 1
                        || widths[EditorTool.pen.rawValue] != 7.5
                        || panelHUD?.isHidden != false {
                        hostFailures.append("panel unlock")
                    }
                } else {
                    hostFailures.append("panel host/event")
                }
                panel.clickToolbarButtonForTesting(tag: -1)

                check("overlay10-stroke-width-hosts-s3",
                      hostFailures.isEmpty,
                      hostFailures.joined(separator: "; "))
            }

            // S4 live-host gate: both real responders, both real toolbar
            // target/actions, shortcut routing, and the panel save lock.
            do {
                let redoTag = 202
                @MainActor func keyEvent(
                    _ characters: String,
                    modifiers: NSEvent.ModifierFlags = []
                ) -> NSEvent? {
                    NSEvent.keyEvent(
                        with: .keyDown, location: .zero,
                        modifierFlags: modifiers, timestamp: 0,
                        windowNumber: 0, context: nil,
                        characters: characters,
                        charactersIgnoringModifiers: characters.lowercased(),
                        isARepeat: false, keyCode: 0)
                }
                @MainActor func buttons(in root: NSView) -> [NSButton] {
                    root.subviews.flatMap { child -> [NSButton] in
                        let own = (child as? NSButton).map { [$0] } ?? []
                        return own + buttons(in: child)
                    }
                }
                @MainActor func addAreaCounter(
                    view: SelectionOverlayView, surface: AnnotationSurface,
                    at point: CGPoint
                ) {
                    surface.tool = .counter
                    if let down = liveMouse(.leftMouseDown, point) {
                        view.mouseDown(with: down)
                    }
                    if let up = liveMouse(.leftMouseUp, point) {
                        view.mouseUp(with: up)
                    }
                }

                var hostFailures: [String] = []
                let (historyOverlay, historyView) = reviewView()
                let historySelection = CGRect(
                    x: max(40, b.width / 2 - 150),
                    y: max(100, b.height / 2 - 100),
                    width: 300, height: 200)
                historyView.selectForTesting(rect: historySelection)
                guard let areaSurface = historyView.annotationSurface else {
                    check("overlay11-undo-redo-hosts-s4", false,
                          "area surface")
                    return
                }
                addAreaCounter(
                    view: historyView, surface: areaSurface,
                    at: CGPoint(
                        x: historySelection.minX + 60,
                        y: historySelection.minY + 60))
                addAreaCounter(
                    view: historyView, surface: areaSurface,
                    at: CGPoint(
                        x: historySelection.minX + 120,
                        y: historySelection.minY + 100))
                let areaSecond = areaSurface.annotations.last
                historyView.clickReviewToolbarButtonForTesting(
                    tag: OverlayAnnotationTool.undoToolbarTag)
                let areaButtonsAfterUndo = buttons(in: historyView)
                let areaCatalog = areaButtonsAfterUndo.filter {
                    $0.tag == OverlayAnnotationTool.undoToolbarTag
                        || $0.tag == redoTag
                }
                let areaHistoryButtonsReady = areaCatalog.count == 2
                    && areaCatalog.allSatisfy(\.isEnabled)
                historyView.clickReviewToolbarButtonForTesting(tag: redoTag)
                let areaButtonRedo = areaSurface.annotations.count == 2
                    && areaSurface.annotations.last === areaSecond
                if let cmdZ = keyEvent("z", modifiers: [.command]) {
                    _ = historyView.performKeyEquivalent(with: cmdZ)
                }
                let areaKeyUndo = areaSurface.annotations.count == 1
                if let shiftCmdZ = keyEvent(
                    "z", modifiers: [.command, .shift]) {
                    _ = historyView.performKeyEquivalent(with: shiftCmdZ)
                }
                let areaKeyRedo = areaSurface.annotations.count == 2
                    && areaSurface.annotations.last === areaSecond
                if let cmdZ = keyEvent("z", modifiers: [.command]) {
                    _ = historyView.performKeyEquivalent(with: cmdZ)
                }
                addAreaCounter(
                    view: historyView, surface: areaSurface,
                    at: CGPoint(
                        x: historySelection.minX + 180,
                        y: historySelection.minY + 130))
                let areaBranchCount = areaSurface.annotations.count
                let areaBranchLast = areaSurface.annotations.last
                if let shiftCmdZ = keyEvent(
                    "z", modifiers: [.command, .shift]) {
                    _ = historyView.performKeyEquivalent(with: shiftCmdZ)
                }
                let areaBranchCleared = areaBranchCount == 2
                    && areaSurface.annotations.count == areaBranchCount
                if let capsCmdZ = keyEvent(
                    "z", modifiers: [.capsLock, .command]) {
                    _ = historyView.performKeyEquivalent(with: capsCmdZ)
                }
                let areaCapsUndo = areaSurface.annotations.count == 1
                if let capsShiftCmdZ = keyEvent(
                    "z", modifiers: [.capsLock, .command, .shift]) {
                    _ = historyView.performKeyEquivalent(with: capsShiftCmdZ)
                }
                let areaCapsRedo = areaSurface.annotations.count == 2
                    && areaSurface.annotations.last === areaBranchLast
                if !areaHistoryButtonsReady || !areaButtonRedo
                    || !areaKeyUndo || !areaKeyRedo || !areaBranchCleared
                    || !areaCapsUndo || !areaCapsRedo {
                    hostFailures.append(
                        "area catalog \(areaCatalog.map { ($0.tag, $0.isEnabled) }) button \(areaButtonRedo) keys \(areaKeyUndo)/\(areaKeyRedo) branch \(areaBranchCleared) caps \(areaCapsUndo)/\(areaCapsRedo)")
                }

                let areaShortcuts: [(String, OverlayAnnotationTool)] = [
                    ("l", .line), ("o", .oval), ("h", .highlight),
                    ("n", .counter), ("b", .blur),
                ]
                var areaShortcutsOK = true
                for (key, tool) in areaShortcuts {
                    if let event = keyEvent(key) { historyView.keyDown(with: event) }
                    if areaSurface.tool != tool { areaShortcutsOK = false }
                }
                let textWindow = NSWindow(
                    contentRect: historyView.bounds,
                    styleMask: [.borderless], backing: .buffered, defer: false)
                textWindow.contentView = historyView
                areaSurface.tool = .text
                historyView.beginTextEntryForTesting(atView: CGPoint(
                    x: historySelection.midX, y: historySelection.midY))
                if let event = keyEvent("l") { historyView.keyDown(with: event) }
                let areaTextGuard = areaSurface.tool == .text
                    && historyView.textFieldForTesting != nil
                historyView.commitTextEntryForTesting(text: "")
                textWindow.contentView = nil
                if !areaShortcutsOK || !areaTextGuard {
                    hostFailures.append(
                        "area shortcuts \(areaShortcutsOK) text \(areaTextGuard)")
                }
                _ = historyOverlay.session.phase

                let panelImage = CapturedImage(
                    cgImage: makeNoiseImage(width: 320, height: 480), scale: 1)
                var panelSaveDone: (@MainActor (SaveAsOutcome) -> Void)?
                let panelDeps = CaptureActionRouter.Dependencies(
                    copyToClipboard: { _ in }, autoSave: { _, _ in },
                    saveAs: { _, done in panelSaveDone = done },
                    pin: { _ in }, ocr: { _ in }, openEditor: { _ in },
                    toast: { _ in }, setLastCapture: { _ in },
                    setLastAreaRect: { _ in }, logEvent: { _ in })
                let panel = ScrollResultPanel.show(
                    image: panelImage,
                    inputs: OverlaySessionInputs(
                        afterShow: true, afterCopy: false, afterSave: false),
                    screen: screen, dependencies: panelDeps)
                panel.clickToolbarButtonForTesting(
                    tag: OverlayAnnotationTool.counter.toolbarTag)
                panel.drawWithRealEventsForTesting(
                    fromView: CGPoint(x: 40, y: 60),
                    toView: CGPoint(x: 40, y: 60))
                panel.drawWithRealEventsForTesting(
                    fromView: CGPoint(x: 90, y: 120),
                    toView: CGPoint(x: 90, y: 120))
                let panelSecond = panel.annotationSurface.annotations.last
                panel.clickToolbarButtonForTesting(
                    tag: OverlayAnnotationTool.undoToolbarTag)
                let panelButtonsAfterUndo = panel.contentView.map {
                    buttons(in: $0)
                } ?? []
                let panelCatalog = panelButtonsAfterUndo.filter {
                    $0.tag == OverlayAnnotationTool.undoToolbarTag
                        || $0.tag == redoTag
                }
                let panelHistoryButtonsReady = panelCatalog.count == 2
                    && panelCatalog.allSatisfy(\.isEnabled)
                panel.clickToolbarButtonForTesting(tag: redoTag)
                let panelButtonRedo = panel.annotationSurface.annotations.count == 2
                    && panel.annotationSurface.annotations.last === panelSecond
                if let cmdZ = keyEvent("z", modifiers: [.command]) {
                    _ = panel.performKeyEquivalent(with: cmdZ)
                }
                let panelKeyUndo = panel.annotationSurface.annotations.count == 1
                if let shiftCmdZ = keyEvent(
                    "z", modifiers: [.command, .shift]) {
                    _ = panel.performKeyEquivalent(with: shiftCmdZ)
                }
                let panelKeyRedo = panel.annotationSurface.annotations.count == 2
                    && panel.annotationSurface.annotations.last === panelSecond
                if let capsCmdZ = keyEvent(
                    "z", modifiers: [.capsLock, .command]) {
                    _ = panel.performKeyEquivalent(with: capsCmdZ)
                }
                let panelCapsUndo = panel.annotationSurface.annotations.count == 1
                if let capsShiftCmdZ = keyEvent(
                    "z", modifiers: [.capsLock, .command, .shift]) {
                    _ = panel.performKeyEquivalent(with: capsShiftCmdZ)
                }
                let panelCapsRedo = panel.annotationSurface.annotations.count == 2
                    && panel.annotationSurface.annotations.last === panelSecond
                if !panelHistoryButtonsReady || !panelButtonRedo
                    || !panelKeyUndo || !panelKeyRedo
                    || !panelCapsUndo || !panelCapsRedo {
                    hostFailures.append(
                        "panel catalog \(panelCatalog.map { ($0.tag, $0.isEnabled) }) button \(panelButtonRedo) keys \(panelKeyUndo)/\(panelKeyRedo) caps \(panelCapsUndo)/\(panelCapsRedo)")
                }

                var panelShortcutsOK = true
                for (key, tool) in areaShortcuts {
                    if let event = keyEvent(key) { panel.keyDown(with: event) }
                    if panel.annotationSurface.tool != tool {
                        panelShortcutsOK = false
                    }
                }
                panel.clickToolbarButtonForTesting(
                    tag: OverlayAnnotationTool.text.toolbarTag)
                panel.drawWithRealEventsForTesting(
                    fromView: CGPoint(x: 120, y: 160),
                    toView: CGPoint(x: 120, y: 160))
                if let event = keyEvent("l") { panel.keyDown(with: event) }
                let panelTextGuard = panel.annotationSurface.tool == .text
                    && panel.annotationHostForTesting?.textFieldForTesting != nil
                panel.annotationHostForTesting?.commitActiveTextEntry()
                if !panelShortcutsOK || !panelTextGuard {
                    hostFailures.append(
                        "panel shortcuts \(panelShortcutsOK) text \(panelTextGuard)")
                }

                if let cmdZ = keyEvent("z", modifiers: [.command]) {
                    _ = panel.performKeyEquivalent(with: cmdZ)
                }
                let panelBeforeSave = panel.annotationSurface.annotations.count
                let panelRedoBeforeSave = panelBeforeSave == 1
                let panelLockedLast = panel.annotationSurface.annotations.last
                panel.annotationSurface.tool = .line
                panel.performActionForTesting(.save)
                let lockedButtons = panel.contentView.map { buttons(in: $0) }
                    ?? []
                let lockedHistory = lockedButtons.filter {
                    $0.tag == OverlayAnnotationTool.undoToolbarTag
                        || $0.tag == redoTag
                }
                let panelButtonsLocked = lockedHistory.count == 2
                    && lockedHistory.allSatisfy { !$0.isEnabled }
                if let cmdZ = keyEvent("z", modifiers: [.command]) {
                    _ = panel.performKeyEquivalent(with: cmdZ)
                }
                let panelCmdFrozen =
                    panel.annotationSurface.annotations.count == panelBeforeSave
                    && panel.annotationSurface.annotations.last === panelLockedLast
                if let shiftCmdZ = keyEvent(
                    "z", modifiers: [.command, .shift]) {
                    _ = panel.performKeyEquivalent(with: shiftCmdZ)
                }
                let panelShiftFrozen =
                    panel.annotationSurface.annotations.count == panelBeforeSave
                    && panel.annotationSurface.annotations.last === panelLockedLast
                panel.clickToolbarButtonForTesting(
                    tag: OverlayAnnotationTool.undoToolbarTag)
                panel.clickToolbarButtonForTesting(tag: redoTag)
                if let shortcut = keyEvent("b") { panel.keyDown(with: shortcut) }
                let panelFrozen = panelSaveDone != nil
                    && panel.annotationSurface.annotations.count == panelBeforeSave
                    && panel.annotationSurface.tool == .line
                    && panelButtonsLocked && panelCmdFrozen && panelShiftFrozen
                panelSaveDone?(.cancelled)
                if let shiftCmdZ = keyEvent(
                    "z", modifiers: [.command, .shift]) {
                    _ = panel.performKeyEquivalent(with: shiftCmdZ)
                }
                let panelUnlockedRedo = panelRedoBeforeSave
                    && panel.annotationSurface.annotations.count == 2
                    && panel.annotationSurface.annotations.last === panelSecond
                if !panelFrozen || !panelUnlockedRedo {
                    hostFailures.append(
                        "panel lock \(panelFrozen) unlockRedo \(panelUnlockedRedo)")
                }
                panel.clickToolbarButtonForTesting(tag: -1)

                check("overlay11-undo-redo-hosts-s4",
                      hostFailures.isEmpty,
                      hostFailures.joined(separator: "; "))
            }

            // Retina 2x + shrink→re-expand: the SAME edges give the SAME
            // integral pixelRect — no 1px drift through a resize round trip.
            let retinaFrozen = CapturedImage(
                cgImage: makeStripePattern(width: 1600, height: 1200, seed: 0x2E71_4A00),
                scale: 2)
            let retinaOverlay = SelectionOverlay(
                purpose: .areaReview,
                inputs: OverlaySessionInputs(
                    afterShow: true, afterCopy: false, afterSave: false),
                completion: { _ in })
            retinaOverlay.routerDependenciesOverride = noopDeps()
            let retinaView = SelectionOverlayView(
                mode: .area, screen: screen, frozen: retinaFrozen,
                windowList: [], owner: retinaOverlay)
            let fractional = CGRect(x: 33.4, y: 47.6, width: 211.3, height: 148.7)
            retinaView.selectForTesting(rect: fractional)
            let px1 = retinaOverlay.session.pixelRect
            retinaView.adjustSelectionForTesting(rect: CGRect(
                x: 60, y: 60, width: 80, height: 60))
            retinaView.adjustSelectionForTesting(rect: fractional)
            let px2 = retinaOverlay.session.pixelRect
            check("overlay5-retina-reexpand",
                  px1 == px2 && px1 == px1.integral,
                  "px1 \(px1) px2 \(px2)")


            // Purpose isolation: scroll region and instant OCR hand over the
            // rect exactly once at mouse-up — no review, no initialCapture
            // side effects, no second completion.
            for purpose in [OverlayPurpose.scrollRegion, .instantOCRRegion] {
                var completions = 0
                var gotArea = false
                let overlay = SelectionOverlay(
                    purpose: purpose,
                    inputs: OverlaySessionInputs(
                        afterShow: true, afterCopy: true, afterSave: true),
                    completion: { result in
                        completions += 1
                        if case .area = result { gotArea = true }
                    })
                var copies = 0
                var deps = noopDeps()
                deps.copyToClipboard = { _ in copies += 1 }
                overlay.routerDependenciesOverride = deps
                let view = SelectionOverlayView(
                    mode: .area, screen: screen, frozen: frozenImage,
                    windowList: [], owner: overlay)
                view.selectForTesting(rect: CGRect(
                    x: 50, y: 60, width: 200, height: 150))
                view.selectForTesting(rect: CGRect(
                    x: 50, y: 60, width: 200, height: 150)) // late/double
                check("overlay5-purpose-isolation-\(purpose)",
                      completions == 1 && gotArea && copies == 0
                        && overlay.session.phase == .completed
                        && view.reviewToolbarFrameForTesting == nil,
                      "completions \(completions) area \(gotArea) copies \(copies)")
            }
        }

        // 13. Overlay: flatten fail-closed / allocation / P3 / save-lock ----------
        MainActor.assumeIsolated {
            // S3 headless gate of record: the overlay must read the editor's
            // exact per-tool keys for new marks, and the real scroll host
            // must port the editor's precise/non-precise width machine. The
            // in-memory store keeps selftest away from real UserDefaults.
            do {
                var widths: [String: CGFloat] = [
                    EditorTool.pen.rawValue: 7,
                    EditorTool.arrow.rawValue: 4,
                    EditorTool.line.rawValue: 5,
                    EditorTool.rect.rawValue: 6,
                    EditorTool.oval.rawValue: 8,
                    EditorTool.highlight.rawValue: 11,
                ]
                var reads: [String] = []
                var writes: [(key: String, value: CGFloat)] = []
                AnnotationSurface.strokeWidthStoreOverrideForTesting =
                    OverlayStrokeWidthStore(
                        read: { key in
                            reads.append(key)
                            return widths[key] ?? 3
                        },
                        write: { value, key in
                            widths[key] = value
                            writes.append((key, value))
                        })
                defer {
                    AnnotationSurface.strokeWidthStoreOverrideForTesting = nil
                }

                let creationCases: [(OverlayAnnotationTool, String, CGFloat)] = [
                    (.pen, EditorTool.pen.rawValue, 7),
                    (.arrow, EditorTool.arrow.rawValue, 4),
                    (.line, EditorTool.line.rawValue, 5),
                    (.rect, EditorTool.rect.rawValue, 6),
                    (.oval, EditorTool.oval.rawValue, 8),
                ]
                var creationOK = true
                for (tool, key, expected) in creationCases {
                    let surface = AnnotationSurface(pixelScale: 2)
                    surface.tool = tool
                    _ = surface.beginDrag(atPixel: CGPoint(x: 10, y: 10))
                    surface.continueDrag(toPixel: CGPoint(x: 80, y: 60))
                    surface.endDrag()
                    let width: CGFloat?
                    if let pen = surface.annotations.last as? PenAnnotation {
                        width = pen.strokeWidthPt
                    } else if let shape = surface.annotations.last
                        as? ShapeAnnotation {
                        width = shape.strokeWidthPt
                    } else {
                        width = nil
                    }
                    if width != expected || !reads.contains(key) {
                        creationOK = false
                    }
                }
                widths.removeValue(forKey: EditorTool.line.rawValue)
                let defaultSurface = AnnotationSurface(pixelScale: 1)
                defaultSurface.tool = .line
                _ = defaultSurface.beginDrag(atPixel: CGPoint(x: 2, y: 2))
                defaultSurface.continueDrag(toPixel: CGPoint(x: 20, y: 20))
                defaultSurface.endDrag()
                let defaultOK = (defaultSurface.annotations.last
                    as? ShapeAnnotation)?.strokeWidthPt == 3
                func strokeScrollEvent(
                    units: CGScrollEventUnit, delta: Int32,
                    flags: CGEventFlags = []
                ) -> NSEvent? {
                    guard let cg = CGEvent(
                        scrollWheelEvent2Source: nil, units: units,
                        wheelCount: 1, wheel1: delta,
                        wheel2: 0, wheel3: 0)
                    else { return nil }
                    cg.flags = flags
                    return NSEvent(cgEvent: cg)
                }
                let hostSurface = AnnotationSurface(pixelScale: 1)
                hostSurface.tool = .pen
                let host = AnnotationHostView(
                    frame: CGRect(x: 0, y: 0, width: 160, height: 120),
                    surface: hostSurface,
                    baseImage: makeNoiseImage(width: 160, height: 120),
                    pixelsPerPoint: 1)
                var eligibleScrollOK = true
                for (tool, key, _) in creationCases {
                    widths[key] = 10
                    hostSurface.tool = tool
                    let writesBefore = writes.count
                    if let lineUp = strokeScrollEvent(units: .line, delta: 1) {
                        host.scrollWheel(with: lineUp)
                    }
                    if widths[key] != 10.5
                        || writes.count != writesBefore + 1
                        || writes.last?.key != key {
                        eligibleScrollOK = false
                    }
                }
                widths[EditorTool.pen.rawValue] = 7
                hostSurface.tool = .pen
                let writesBeforePrecise = writes.count
                if let precise9 = strokeScrollEvent(units: .pixel, delta: 9) {
                    host.scrollWheel(with: precise9)
                    host.scrollWheel(with: precise9)
                }
                let preciseOK = widths[EditorTool.pen.rawValue] == 7.5
                    && writes.count == writesBeforePrecise + 1
                let hud = host.subviews.compactMap {
                    $0 as? StrokePreviewView
                }.last
                let hudOK = hud?.isHidden == false
                    && hud?.strokeWidth == 7.5
                    && hud?.color == hostSurface.color

                _ = hostSurface.beginDrag(atPixel: CGPoint(x: 5, y: 5))
                hostSurface.continueDrag(toPixel: CGPoint(x: 50, y: 40))
                hostSurface.endDrag()
                let persistedModelOK =
                    (hostSurface.annotations.last as? PenAnnotation)?
                        .strokeWidthPt == 7.5

                var nonStrokeIgnored = true
                for tool in [
                    OverlayAnnotationTool.highlight, .text, .counter, .blur,
                    .select,
                ] {
                    hud?.isHidden = true
                    hostSurface.tool = tool
                    let writesBefore = writes.count
                    if let lineUp = strokeScrollEvent(units: .line, delta: 1) {
                        host.scrollWheel(with: lineUp)
                    }
                    if writes.count != writesBefore || hud?.isHidden == false {
                        nonStrokeIgnored = false
                    }
                }

                hostSurface.tool = .arrow
                let writesBeforeModified = writes.count
                for flags in [
                    CGEventFlags.maskShift, .maskCommand, .maskControl,
                ] {
                    if let modified = strokeScrollEvent(
                        units: .line, delta: 1, flags: flags) {
                        host.scrollWheel(with: modified)
                    }
                }
                let modifierIgnored = writes.count == writesBeforeModified

                let penBeforeArrow = widths[EditorTool.pen.rawValue]
                widths[EditorTool.arrow.rawValue] = 10
                let writesBeforeNegative = writes.count
                if let lineDown = strokeScrollEvent(units: .line, delta: -1) {
                    host.scrollWheel(with: lineDown)
                }
                let negativeStepOK = widths[EditorTool.arrow.rawValue] == 9.5
                    && writes.count == writesBeforeNegative + 1
                    && writes.last?.key == EditorTool.arrow.rawValue
                    && writes.last?.value == 9.5
                widths[EditorTool.arrow.rawValue] = 20
                let writesBeforeUpper = writes.count
                if let lineUp = strokeScrollEvent(units: .line, delta: 1) {
                    host.scrollWheel(with: lineUp)
                }
                let upperClampOK = widths[EditorTool.arrow.rawValue] == 20
                    && writes.count == writesBeforeUpper + 1
                widths[EditorTool.arrow.rawValue] = 1
                let writesBeforeLower = writes.count
                if let lineDown = strokeScrollEvent(units: .line, delta: -1) {
                    host.scrollWheel(with: lineDown)
                }
                let lowerClampOK = widths[EditorTool.arrow.rawValue] == 1
                    && writes.count == writesBeforeLower + 1
                let perToolIsolationOK =
                    widths[EditorTool.pen.rawValue] == penBeforeArrow

                check("overlay10-stroke-width-core-s3",
                      creationOK && defaultOK && eligibleScrollOK
                        && preciseOK && hudOK && persistedModelOK
                        && nonStrokeIgnored && modifierIgnored
                        && negativeStepOK
                        && upperClampOK && lowerClampOK
                        && perToolIsolationOK,
                      "create \(creationOK) default \(defaultOK) eligible \(eligibleScrollOK) precise \(preciseOK) hud \(hudOK) model \(persistedModelOK) nonStroke \(nonStrokeIgnored) modifiers \(modifierIgnored) negative \(negativeStepOK) clamp \(lowerClampOK)/\(upperClampOK) isolated \(perToolIsolationOK) reads \(reads) writes \(writes)")
            }

            // S4 headless gate of record: a real second history stack must
            // restore the exact annotation object, and any new mutation after
            // undo must invalidate that branch. The shortcut catalog is also
            // shared here so the two UI hosts cannot silently drift.
            do {
                @MainActor func addCounter(
                    _ surface: AnnotationSurface, at point: CGPoint
                ) {
                    surface.tool = .counter
                    _ = surface.beginDrag(atPixel: point)
                    surface.endDrag()
                }

                let history = AnnotationSurface(pixelScale: 1)
                addCounter(history, at: CGPoint(x: 10, y: 10))
                addCounter(history, at: CGPoint(x: 20, y: 20))
                addCounter(history, at: CGPoint(x: 30, y: 30))
                let first = history.annotations.first
                let second = history.annotations[1]
                let third = history.annotations.last
                let historyProbe: any S4RedoProbe = history
                let undoOK = history.undo() && history.undo()
                    && history.annotations.count == 1
                    && history.annotations.first === first
                    && historyProbe.canRedo
                let firstRedo = historyProbe.redo()
                    && history.annotations.count == 2
                    && history.annotations.first === first
                    && history.annotations.last === second
                    && historyProbe.canRedo
                let secondRedo = historyProbe.redo()
                    && history.annotations.count == 3
                    && history.annotations.first === first
                    && history.annotations[1] === second
                    && history.annotations.last === third
                    && !historyProbe.canRedo

                let branch = AnnotationSurface(pixelScale: 1)
                addCounter(branch, at: CGPoint(x: 30, y: 30))
                addCounter(branch, at: CGPoint(x: 40, y: 40))
                let removed = branch.annotations.last
                let branchProbe: any S4RedoProbe = branch
                let branchUndo = branch.undo()
                    && branchProbe.canRedo
                    && branch.annotations.count == 1
                addCounter(branch, at: CGPoint(x: 50, y: 50))
                let branchCleared = !branchProbe.canRedo
                    && !branchProbe.redo()
                    && branch.annotations.count == 2
                    && branch.annotations.last !== removed

                let textBranch = AnnotationSurface(pixelScale: 1)
                addCounter(textBranch, at: CGPoint(x: 60, y: 60))
                addCounter(textBranch, at: CGPoint(x: 70, y: 70))
                let textProbe: any S4RedoProbe = textBranch
                let textUndo = textBranch.undo() && textProbe.canRedo
                textBranch.addText("C", atPixel: CGPoint(x: 80, y: 80))
                let textCleared = textUndo && !textProbe.canRedo
                    && !textProbe.redo()
                    && textBranch.annotations.count == 2
                    && textBranch.annotations.last is TextAnnotation

                let blurNoop = AnnotationSurface(pixelScale: 1)
                addCounter(blurNoop, at: CGPoint(x: 90, y: 90))
                addCounter(blurNoop, at: CGPoint(x: 100, y: 100))
                let blurRemoved = blurNoop.annotations.last
                let blurProbe: any S4RedoProbe = blurNoop
                let blurUndo = blurNoop.undo() && blurProbe.canRedo
                blurNoop.tool = .blur
                _ = blurNoop.beginDrag(atPixel: CGPoint(x: 110, y: 110))
                blurNoop.endDrag()
                let emptyBlurPreserved = blurUndo && blurProbe.canRedo
                    && blurProbe.redo()
                    && blurNoop.annotations.last === blurRemoved

                let validBlur = AnnotationSurface(pixelScale: 1)
                addCounter(validBlur, at: CGPoint(x: 120, y: 120))
                addCounter(validBlur, at: CGPoint(x: 130, y: 130))
                let validBlurProbe: any S4RedoProbe = validBlur
                let validBlurUndo = validBlur.undo()
                    && validBlurProbe.canRedo
                validBlur.tool = .blur
                _ = validBlur.beginDrag(
                    atPixel: CGPoint(x: 140, y: 140))
                validBlur.continueDrag(
                    toPixel: CGPoint(x: 180, y: 175))
                validBlur.endDrag()
                let validBlurCleared = validBlurUndo
                    && !validBlurProbe.canRedo
                    && !validBlurProbe.redo()
                    && validBlur.annotations.last is BlurAnnotation

                check("overlay11-undo-redo-core-s4",
                      undoOK && firstRedo && secondRedo
                        && branchUndo && branchCleared
                        && textCleared && emptyBlurPreserved
                        && validBlurCleared,
                      "undo \(undoOK) redo \(firstRedo)/\(secondRedo) branch \(branchUndo)/\(branchCleared) text \(textCleared) blur \(emptyBlurPreserved)/\(validBlurCleared)")
            }

            // S2 regional pixelation must allocate only the requested blur
            // region, preserve pixels outside it (including the Y-mirrored
            // wrong region), and fail closed if Core Image cannot render.
            let pixelBase = makeNoiseImage(width: 320, height: 240)
            let pixelSurface = AnnotationSurface(pixelScale: 1)
            let blurRect = CGRect(x: 149, y: 60, width: 53, height: 25)
            pixelSurface.addBlurForTesting(rect: blurRect)
            let clickOnlySurface = AnnotationSurface(pixelScale: 1)
            clickOnlySurface.tool = .blur
            _ = clickOnlySurface.beginDrag(atPixel: CGPoint(x: 20, y: 20))
            clickOnlySurface.endDrag()
            let clickOnlyRemoved = clickOnlySurface.isEmpty
            func equalCrops(_ a: CGImage, _ b: CGImage, _ rect: CGRect) -> Bool {
                guard let ac = a.cropping(to: rect),
                      let bc = b.cropping(to: rect) else { return false }
                return imagesEqual(ac, bc)
            }
            let previewCtx = ctx(pixelBase.width, pixelBase.height)
            previewCtx.draw(
                pixelBase,
                in: CGRect(
                    x: 0, y: 0,
                    width: pixelBase.width, height: pixelBase.height))
            AnnotationSurface.regionalPixelateAllocationsForTesting = 0
            AnnotationSurface.lastRegionalPixelateRectForTesting = nil
            AnnotationSurface.lastRegionalPixelateBaseSizeForTesting = nil
            let previewRendered = pixelSurface.drawForPreview(
                in: previewCtx, base: pixelBase)
            let pixelPreview = previewCtx.makeImage()
            let previewBlurTL = CGRect(
                x: blurRect.minX,
                y: CGFloat(pixelBase.height) - blurRect.maxY,
                width: blurRect.width, height: blurRect.height)
            let previewMirrorTL = CGRect(
                x: blurRect.minX, y: blurRect.minY,
                width: blurRect.width, height: blurRect.height)
            let previewPixelsOK = previewRendered
                && pixelPreview.map {
                    !equalCrops(pixelBase, $0, previewBlurTL)
                        && equalCrops(pixelBase, $0, previewMirrorTL)
                } == true
                && AnnotationSurface.regionalPixelateAllocationsForTesting == 1
                && AnnotationSurface.lastRegionalPixelateRectForTesting
                    == blurRect.integral
                && AnnotationSurface.lastRegionalPixelateBaseSizeForTesting
                    == CGSize(width: pixelBase.width, height: pixelBase.height)

            AnnotationSurface.regionalPixelateAllocationsForTesting = 0
            AnnotationSurface.lastRegionalPixelateRectForTesting = nil
            AnnotationSurface.lastRegionalPixelateBaseSizeForTesting = nil
            let pixelDestBefore = AnnotationSurface.flattenAllocationsForTesting
            let pixelCrop = CGRect(x: 80, y: 40, width: 180, height: 150)
            let plainPixelCrop = pixelBase.cropping(to: pixelCrop)!
            let pixelFlat = pixelSurface.flattened(
                base: pixelBase, cropPixels: pixelCrop)
            let visibleBLMinY = CGFloat(pixelBase.height) - pixelCrop.maxY
            let blurTL = CGRect(
                x: blurRect.minX - pixelCrop.minX,
                y: pixelCrop.height
                    - (blurRect.maxY - visibleBLMinY),
                width: blurRect.width, height: blurRect.height)
            let mirroredTL = CGRect(
                x: blurRect.minX - pixelCrop.minX,
                y: blurRect.minY - visibleBLMinY,
                width: blurRect.width, height: blurRect.height)
            var regionalPixelsOK = false
            if let pixelFlat {
                regionalPixelsOK = !equalCrops(
                        plainPixelCrop, pixelFlat, blurTL)
                    && equalCrops(
                        plainPixelCrop, pixelFlat,
                        CGRect(x: 0, y: 0, width: 24, height: 24))
                    && equalCrops(plainPixelCrop, pixelFlat, mirroredTL)
            }
            let regionalAllocOK =
                AnnotationSurface.regionalPixelateAllocationsForTesting == 1
                && AnnotationSurface.lastRegionalPixelateRectForTesting
                    == blurRect.integral
                && AnnotationSurface.lastRegionalPixelateBaseSizeForTesting
                    == CGSize(width: pixelBase.width, height: pixelBase.height)
                && blurRect.width * blurRect.height
                    < CGFloat(pixelBase.width * pixelBase.height) / 10
                && AnnotationSurface.flattenAllocationsForTesting
                    == pixelDestBefore + 1
            let regionalFailed = AnnotationRenderer.withForcedRegionalFailure {
                pixelSurface.flattened(
                    base: pixelBase, cropPixels: pixelCrop) == nil
            }
            check("overlay9-pixelate-regional-s2",
                  previewPixelsOK && regionalPixelsOK
                    && regionalAllocOK && regionalFailed
                    && pixelSurface.annotations.count == 1
                    && clickOnlyRemoved,
                  "preview \(previewPixelsOK) export \(regionalPixelsOK) alloc \(regionalAllocOK) failClosed \(regionalFailed) count \(pixelSurface.annotations.count) clickOnlyRemoved \(clickOnlyRemoved) region \(String(describing: AnnotationSurface.lastRegionalPixelateRectForTesting))")

            // allocation spy: exactly one destination buffer, zero
            // materialized copies, on a large flatten with annotations
            let big = makeStripePattern(width: 720, height: 4000, seed: 0x000B_16F1)
            let surface = AnnotationSurface(pixelScale: 1)
            let bigBlur = CGRect(x: 100, y: 500, width: 80, height: 96)
            surface.addBlurForTesting(rect: bigBlur)
            let allocBefore = AnnotationSurface.flattenAllocationsForTesting
            AnnotationSurface.regionalPixelateAllocationsForTesting = 0
            AnnotationSurface.lastRegionalPixelateRectForTesting = nil
            AnnotationSurface.lastRegionalPixelateBaseSizeForTesting = nil
            let matBefore = MaterializeSpy.count
            let flat = surface.flattened(
                base: big,
                cropPixels: CGRect(x: 0, y: 0, width: 720, height: 4000))
            check("overlay6-flatten-single-buffer",
                  flat != nil
                    && AnnotationSurface.flattenAllocationsForTesting == allocBefore + 1
                    && AnnotationSurface.regionalPixelateAllocationsForTesting == 1
                    && AnnotationSurface.lastRegionalPixelateRectForTesting
                        == bigBlur
                    && AnnotationSurface.lastRegionalPixelateBaseSizeForTesting
                        == CGSize(width: big.width, height: big.height)
                    && bigBlur.width * bigBlur.height
                        < CGFloat(big.width * big.height) / 100
                    && MaterializeSpy.count == matBefore,
                  "destΔ \(AnnotationSurface.flattenAllocationsForTesting - allocBefore) regionΔ \(AnnotationSurface.regionalPixelateAllocationsForTesting) region \(String(describing: AnnotationSurface.lastRegionalPixelateRectForTesting)) base \(String(describing: AnnotationSurface.lastRegionalPixelateBaseSizeForTesting)) matΔ \(MaterializeSpy.count - matBefore)")

            // fail-closed: forced allocation failure returns nil — never a
            // silent un-annotated fallback
            surface.forceRenderFailureForTesting = true
            let failed = surface.flattened(
                base: big,
                cropPixels: CGRect(x: 0, y: 0, width: 720, height: 4000))
            surface.forceRenderFailureForTesting = false
            check("overlay6-flatten-fail-closed", failed == nil,
                  "got \(String(describing: failed))")

            // P3 base keeps its color space through the annotated flatten
            if let p3Space = CGColorSpace(name: CGColorSpace.displayP3),
               let p3Ctx = CGContext(
                data: nil, width: 64, height: 64, bitsPerComponent: 8,
                bytesPerRow: 0, space: p3Space,
                bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) {
                p3Ctx.setFillColor(CGColor(
                    colorSpace: p3Space, components: [1, 0.2, 0.1, 1])
                    ?? NSColor.systemRed.cgColor)
                p3Ctx.fill(CGRect(x: 0, y: 0, width: 64, height: 64))
                if let p3Base = p3Ctx.makeImage() {
                    let s2 = AnnotationSurface(pixelScale: 1)
                    s2.tool = .rect
                    _ = s2.beginDrag(atPixel: CGPoint(x: 8, y: 8))
                    s2.continueDrag(toPixel: CGPoint(x: 40, y: 40))
                    s2.endDrag()
                    let p3Flat = s2.flattened(
                        base: p3Base,
                        cropPixels: CGRect(x: 0, y: 0, width: 64, height: 64))
                    check("overlay6-flatten-p3",
                          p3Flat?.colorSpace?.name == p3Space.name,
                          "space \(String(describing: p3Flat?.colorSpace?.name))")
                } else {
                    check("overlay6-flatten-p3-base", false)
                }
            } else {
                check("overlay6-flatten-p3-env", true)
            }

            // save-lock invariance + per-tool double-click on the area view
            guard let screen = NSScreen.main ?? NSScreen.screens.first else {
                print("SKIP overlay6-ui — no display attached; MUST re-run on an unlocked session")
                return
            }
            let frozenImage = CapturedImage(
                cgImage: makeStripePattern(
                    width: max(8, Int(screen.frame.width)),
                    height: max(8, Int(screen.frame.height)),
                    seed: 0x10CC_10CC),
                scale: 1)
            final class Spy6 {
                var copies = 0
                var saveDone: (@MainActor (SaveAsOutcome) -> Void)?
                var completions = 0
            }
            let spy = Spy6()
            let overlay = SelectionOverlay(
                purpose: .areaReview,
                inputs: OverlaySessionInputs(
                    afterShow: true, afterCopy: false, afterSave: false),
                completion: { _ in spy.completions += 1 })
            overlay.routerDependenciesOverride = CaptureActionRouter.Dependencies(
                copyToClipboard: { _ in spy.copies += 1 },
                autoSave: { _, _ in },
                saveAs: { _, done in spy.saveDone = done },
                pin: { _ in }, ocr: { _ in }, openEditor: { _ in },
                toast: { _ in }, setLastCapture: { _ in },
                setLastAreaRect: { _ in }, logEvent: { _ in })
            let view = SelectionOverlayView(
                mode: .area, screen: screen, frozen: frozenImage,
                windowList: [], owner: overlay)
            view.selectForTesting(rect: CGRect(x: 60, y: 60, width: 240, height: 180))
            guard let surface6 = view.annotationSurface else {
                check("overlay6-ui-surface", false)
                return
            }
            @MainActor func appendPen6(_ start: CGPoint, _ end: CGPoint) {
                surface6.tool = .pen
                _ = surface6.beginDrag(atPixel: start)
                surface6.continueDrag(toPixel: end)
                surface6.endDrag()
            }
            appendPen6(
                CGPoint(x: 90, y: 90), CGPoint(x: 130, y: 130))
            appendPen6(
                CGPoint(x: 110, y: 100), CGPoint(x: 155, y: 145))
            let redoAnnotation6 = surface6.annotations.last
            let preparedRedo6 = surface6.undo()
                && surface6.annotations.count == 1
            let annotationsBeforeSave = surface6.annotations.count
            surface6.tool = .select
            view.performReviewActionForTesting(.save)
            // Save in flight: REAL mouse drags with a drawing tool and a
            // REAL Cmd-Z must leave the annotation set untouched. (Removing
            // either production guard turns this gate red.)
            surface6.tool = .pen
            @MainActor func mouse(
                _ type: NSEvent.EventType, _ p: CGPoint, clicks: Int = 1
            ) -> NSEvent? {
                NSEvent.mouseEvent(
                    with: type, location: p, modifierFlags: [],
                    timestamp: 0, windowNumber: 0, context: nil,
                    eventNumber: 0, clickCount: clicks, pressure: 1)
            }
            let inside = CGPoint(x: 120, y: 120)
            @MainActor func sendDrag(to end: CGPoint) {
                if let down = mouse(.leftMouseDown, inside) { view.mouseDown(with: down) }
                if let drag = mouse(.leftMouseDragged, end) { view.mouseDragged(with: drag) }
                if let up = mouse(.leftMouseUp, end) { view.mouseUp(with: up) }
            }
            @MainActor func sendCmdZ() {
                if let cmdZ = NSEvent.keyEvent(
                    with: .keyDown, location: .zero, modifierFlags: [.command],
                    timestamp: 0, windowNumber: 0, context: nil,
                    characters: "z", charactersIgnoringModifiers: "z",
                    isARepeat: false, keyCode: 6) {
                    _ = view.performKeyEquivalent(with: cmdZ)
                }
            }
            @MainActor func sendShiftCmdZ() {
                if let redo = NSEvent.keyEvent(
                    with: .keyDown, location: .zero,
                    modifierFlags: [.command, .shift],
                    timestamp: 0, windowNumber: 0, context: nil,
                    characters: "z", charactersIgnoringModifiers: "z",
                    isARepeat: false, keyCode: 6) {
                    _ = view.performKeyEquivalent(with: redo)
                }
            }
            @MainActor func buttons6(in root: NSView) -> [NSButton] {
                root.subviews.flatMap { child -> [NSButton] in
                    let own = (child as? NSButton).map { [$0] } ?? []
                    return own + buttons6(in: child)
                }
            }
            let historyButtons6 = buttons6(in: view).filter {
                $0.tag == OverlayAnnotationTool.undoToolbarTag || $0.tag == 202
            }
            let historyButtonsLocked6 = historyButtons6.count == 2
                && historyButtons6.allSatisfy { !$0.isEnabled }
            // STEP-WISE asserts: a drag(+1) cancelled by an undo(−1) must not
            // be able to hide two missing guards behind an unchanged total.
            sendDrag(to: CGPoint(x: 160, y: 160))
            let invariantAfterDrag =
                surface6.annotations.count == annotationsBeforeSave
            sendCmdZ()
            let invariantAfterUndo =
                surface6.annotations.count == annotationsBeforeSave
            sendShiftCmdZ()
            let invariantAfterRedo =
                surface6.annotations.count == annotationsBeforeSave
            view.clickReviewToolbarButtonForTesting(
                tag: OverlayAnnotationTool.undoToolbarTag)
            let invariantAfterUndoButton =
                surface6.annotations.count == annotationsBeforeSave
            view.clickReviewToolbarButtonForTesting(tag: 202)
            let invariantAfterRedoButton =
                surface6.annotations.count == annotationsBeforeSave
            let stillSaving = overlay.session.phase == .saving
            spy.saveDone?(.cancelled)
            let backToReview = overlay.session.phase == .reviewing
                && surface6.annotations.count == annotationsBeforeSave
            // after cancel: the exact redo object returns; undo it, then a
            // new mark forks history and Shift-Cmd-Z must become a no-op.
            sendShiftCmdZ()
            let redoAfterCancel = surface6.annotations.count == 2
                && surface6.annotations.last === redoAnnotation6
            sendCmdZ()
            let undoBeforeBranch = surface6.annotations.count == 1
            sendDrag(to: CGPoint(x: 170, y: 150))
            let drawsAfterCancel =
                surface6.annotations.count == annotationsBeforeSave + 1
            sendShiftCmdZ()
            let redoClearedAfterDraw =
                surface6.annotations.count == annotationsBeforeSave + 1
            sendCmdZ()
            let undoAfterCancel =
                surface6.annotations.count == annotationsBeforeSave
            check("overlay6-save-lock-annotations",
                  preparedRedo6 && historyButtonsLocked6
                    && invariantAfterDrag && invariantAfterUndo
                    && invariantAfterRedo && invariantAfterUndoButton
                    && invariantAfterRedoButton && stillSaving
                    && backToReview && redoAfterCancel && undoBeforeBranch
                    && drawsAfterCancel && redoClearedAfterDraw
                    && undoAfterCancel,
                  "prepared \(preparedRedo6) buttons \(historyButtonsLocked6) drag \(invariantAfterDrag) undo/redo \(invariantAfterUndo)/\(invariantAfterRedo) click \(invariantAfterUndoButton)/\(invariantAfterRedoButton) saving \(stillSaving) back \(backToReview) postRedo \(redoAfterCancel) branch \(undoBeforeBranch)/\(drawsAfterCancel)/\(redoClearedAfterDraw) reundo \(undoAfterCancel)")

            // Area flatten failure: 0 actions, 1 toast, review + drawings
            // intact (fail-closed parity with the panel).
            let spyF = Spy6()
            var failToasts = 0
            let overlayF = SelectionOverlay(
                purpose: .areaReview,
                inputs: OverlaySessionInputs(
                    afterShow: true, afterCopy: false, afterSave: false),
                completion: { _ in spyF.completions += 1 })
            overlayF.routerDependenciesOverride = CaptureActionRouter.Dependencies(
                copyToClipboard: { _ in spyF.copies += 1 },
                autoSave: { _, _ in }, saveAs: { _, _ in },
                pin: { _ in }, ocr: { _ in }, openEditor: { _ in },
                toast: { _ in failToasts += 1 },
                setLastCapture: { _ in },
                setLastAreaRect: { _ in }, logEvent: { _ in })
            let viewF = SelectionOverlayView(
                mode: .area, screen: screen, frozen: frozenImage,
                windowList: [], owner: overlayF)
            viewF.selectForTesting(rect: CGRect(x: 60, y: 60, width: 240, height: 180))
            viewF.annotationSurface?.tool = .rect
            _ = viewF.annotationSurface?.beginDrag(atPixel: CGPoint(x: 100, y: 100))
            viewF.annotationSurface?.continueDrag(toPixel: CGPoint(x: 180, y: 160))
            viewF.annotationSurface?.endDrag()
            viewF.annotationSurface?.tool = .select
            viewF.annotationSurface?.forceRenderFailureForTesting = true
            let annotationsBeforeFail = viewF.annotationSurface?.annotations.count ?? -1
            viewF.performReviewActionForTesting(.copy)
            check("overlay6-area-flatten-fail-closed",
                  spyF.copies == 0 && spyF.completions == 0 && failToasts == 1
                    && overlayF.session.phase == .reviewing
                    && viewF.annotationSurface?.annotations.count == annotationsBeforeFail,
                  "copies \(spyF.copies) toasts \(failToasts) phase \(overlayF.session.phase)")

            // double-click terminal wins over EVERY drawing tool
            var toolsOK = true
            for tool in [OverlayAnnotationTool.pen, .arrow, .rect, .text] {
                let spyT = Spy6()
                let overlayT = SelectionOverlay(
                    purpose: .areaReview,
                    inputs: OverlaySessionInputs(
                        afterShow: true, afterCopy: false, afterSave: false),
                    completion: { _ in spyT.completions += 1 })
                overlayT.routerDependenciesOverride = CaptureActionRouter.Dependencies(
                    copyToClipboard: { _ in spyT.copies += 1 },
                    autoSave: { _, _ in }, saveAs: { _, _ in },
                    pin: { _ in }, ocr: { _ in }, openEditor: { _ in },
                    toast: { _ in }, setLastCapture: { _ in },
                    setLastAreaRect: { _ in }, logEvent: { _ in })
                let viewT = SelectionOverlayView(
                    mode: .area, screen: screen, frozen: frozenImage,
                    windowList: [], owner: overlayT)
                let rectT = CGRect(x: 60, y: 60, width: 240, height: 180)
                viewT.selectForTesting(rect: rectT)
                viewT.annotationSurface?.tool = tool
                if let dbl = NSEvent.mouseEvent(
                    with: .leftMouseDown,
                    location: CGPoint(x: rectT.midX, y: rectT.midY),
                    modifierFlags: [], timestamp: 0, windowNumber: 0,
                    context: nil, eventNumber: 0, clickCount: 2, pressure: 1) {
                    viewT.mouseDown(with: dbl)
                }
                if spyT.copies != 1 || spyT.completions != 1
                    || overlayT.session.phase != .completed {
                    toolsOK = false
                    print("  double-click failed for \(tool): copies \(spyT.copies) completions \(spyT.completions) phase \(overlayT.session.phase)")
                }
            }
            check("overlay6-doubleclick-over-tools", toolsOK, "see above")
        }

        // MARK: slice A — picker / ruler / guides / resize / scroll hint
        do {
            let hint = SliceAHotkeys.bidirectionalScrollHint.lowercased()
            check("sliceA-scroll-hint-bidirectional",
                  hint.contains("lên") && hint.contains("xuống")
                    && ScrollingCapture.bidirectionalScrollHint
                        == SliceAHotkeys.bidirectionalScrollHint,
                  hint)

            check("sliceA-overlay-actions-untouched",
                  OverlayActionCatalog.items.map(\.intent)
                    == [.copy, .save, .pin, .ocr, .translate, .openEditor],
                  "actions \(OverlayActionCatalog.items.map(\.intent))")

            let red = makeSolidImage(
                width: 40, height: 30, color: NSColor.red.cgColor)
            let sampled = PixelColorSampler.sample(
                image: red, at: CGPoint(x: 10, y: 10))
            check("sliceA-color-hex",
                  sampled.map(PixelColorSampler.hexString(from:)) == "#FF0000",
                  sampled.map(PixelColorSampler.hexString(from:)) ?? "nil")

            let mixed = ctx(80, 80)
            mixed.setFillColor(NSColor.white.cgColor)
            mixed.fill(CGRect(x: 0, y: 0, width: 80, height: 80))
            mixed.setFillColor(NSColor.black.cgColor)
            mixed.fill(CGRect(x: 35, y: 35, width: 10, height: 10))
            let mixedImg = mixed.makeImage()!
            let dark = PixelColorSampler.darkest(
                image: mixedImg, around: CGPoint(x: 40, y: 40), radius: 10)
            let far = PixelColorSampler.darkest(
                image: mixedImg, around: CGPoint(x: 4, y: 4), radius: 3)
            check("sliceA-color-darkest",
                  dark.map(PixelColorSampler.hexString(from:)) == "#000000"
                    && far.map(PixelColorSampler.hexString(from:)) == "#FFFFFF",
                  "dark \(dark.map(PixelColorSampler.hexString(from:)) ?? "nil") far \(far.map(PixelColorSampler.hexString(from:)) ?? "nil")")

            let bar = ctx(200, 100)
            bar.setFillColor(NSColor.white.cgColor)
            bar.fill(CGRect(x: 0, y: 0, width: 200, height: 100))
            bar.setFillColor(NSColor.red.cgColor)
            bar.fill(CGRect(x: 40, y: 20, width: 80, height: 60))
            let barImg = bar.makeImage()!
            let hSpan = EdgeRuler.measure(
                image: barImg, from: CGPoint(x: 80, y: 50), axis: .horizontal)
            let vSpan = EdgeRuler.measure(
                image: barImg, from: CGPoint(x: 80, y: 50), axis: .vertical)
            check("sliceA-ruler-bar",
                  hSpan?.length == 80 && hSpan?.start == 40 && hSpan?.end == 120
                    && vSpan?.length == 60 && vSpan?.start == 20 && vSpan?.end == 80,
                  "h \(String(describing: hSpan)) v \(String(describing: vSpan))")

            let gap = EdgeRuler.measure(
                image: barImg, from: CGPoint(x: 10, y: 50), axis: .horizontal)
            check("sliceA-ruler-gap",
                  gap?.start == 0 && gap.map { $0.end <= 41 } == true,
                  "\(String(describing: gap))")

            let guideBase = makeSolidImage(
                width: 120, height: 80, color: NSColor.white.cgColor)
            let guide = GuideAnnotation(
                axis: .vertical, position: 40, length: 80, uiScale: 1)
            let guided = AnnotationRenderer.render(
                base: guideBase, annotations: [guide], pixellated: nil)
            check("sliceA-guides-imprint",
                  !imagesEqual(guideBase, guided),
                  "guide left no ink")

            let beforeRetina = Settings.shared.downscaleRetina
            Settings.shared.downscaleRetina = true
            let src = CapturedImage(
                cgImage: makeSolidImage(
                    width: 200, height: 100, color: NSColor.blue.cgColor),
                scale: 2)
            let shape = ShapeAnnotation(
                kind: .rect,
                start: CGPoint(x: 10, y: 10),
                end: CGPoint(x: 50, y: 40),
                uiScale: 2)
            let half = ImageResizer.scale(src, by: 0.5)
            shape.scaleCoordinates(by: 0.5)
            check("sliceA-resize-independent",
                  half?.cgImage.width == 100
                    && half?.cgImage.height == 50
                    && half?.scale == 2
                    && Settings.shared.downscaleRetina == true
                    && abs(shape.start.x - 5) < 0.01
                    && abs(shape.end.y - 20) < 0.01,
                  "half \(half?.cgImage.width ?? -1)x\(half?.cgImage.height ?? -1) scale \(half?.scale ?? -1) retina \(Settings.shared.downscaleRetina) start \(shape.start)")
            Settings.shared.downscaleRetina = beforeRetina

            let editorImage = CapturedImage(
                cgImage: makeSolidImage(
                    width: 160, height: 80, color: NSColor.orange.cgColor),
                scale: 2)
            let wc = EditorWindowController.open(
                with: editorImage, forceFitForTesting: true)
            let badge = wc.sizeBadgeTitleForTesting
            wc.applyResizeFactor(0.5)
            let after = wc.canvasForTesting.image
            let hex = wc.canvasForTesting.pickColorHexForTesting(
                at: CGPoint(x: 10, y: 10), darkest: false)
            wc.canvasForTesting.beginRuler(.horizontal)
            let rulerOn = wc.canvasForTesting.transientKindForTesting == "ruler"
            wc.canvasForTesting.beginGuide(.vertical)
            let guideOn = wc.canvasForTesting.transientKindForTesting == "guide"
            wc.window?.close()
            let hexOK = hex?.hasPrefix("#") == true && (hex?.count ?? 0) == 7
            check("sliceA-editor-badge-and-hooks",
                  badge.contains("×")
                    && after.cgImage.width == 80
                    && after.scale == 2
                    && hexOK && rulerOn && guideOn,
                  "badge \(badge) size \(after.cgImage.width) hex \(hex ?? "nil") ruler \(rulerOn) guide \(guideOn)")

            func sliceAKey(
                _ keyCode: UInt16,
                characters: String,
                modifiers: NSEvent.ModifierFlags = []
            ) -> NSEvent? {
                NSEvent.keyEvent(
                    with: .keyDown, location: .zero,
                    modifierFlags: modifiers, timestamp: 0,
                    windowNumber: 0, context: nil,
                    characters: characters,
                    charactersIgnoringModifiers: characters,
                    isARepeat: false, keyCode: keyCode)
            }
            func sliceAMouse(
                _ type: NSEvent.EventType, in view: NSView, at viewPoint: CGPoint
            ) -> NSEvent? {
                NSEvent.mouseEvent(
                    with: type, location: view.convert(viewPoint, to: nil),
                    modifierFlags: [], timestamp: 0, windowNumber: 0,
                    context: nil, eventNumber: 1, clickCount: 1, pressure: 1)
            }

            let tiny = makeSolidImage(
                width: 20, height: 20, color: NSColor.white.cgColor)
            let oobFar = PixelColorSampler.darkest(
                image: tiny, around: CGPoint(x: -200, y: -200), radius: 10)
            let oobHigh = PixelColorSampler.darkest(
                image: tiny, around: CGPoint(x: 8_000, y: 8_000), radius: 10)
            let oobEdge = PixelColorSampler.darkest(
                image: tiny, around: CGPoint(x: 2, y: 2), radius: 10)
            check("sliceA-color-darkest-oob",
                  oobFar == nil && oobHigh == nil && oobEdge != nil,
                  "far \(oobFar != nil) high \(oobHigh != nil) edge \(oobEdge != nil)")

            let srcR = CapturedImage(
                cgImage: makeSolidImage(
                    width: 512, height: 512, color: NSColor.blue.cgColor),
                scale: 1)
            let nanS = ImageResizer.scale(srcR, by: .nan)
            let infS = ImageResizer.scale(srcR, by: .infinity)
            let negS = ImageResizer.scale(srcR, by: -2)
            let zeroS = ImageResizer.scale(srcR, by: 0)
            // Narrow: destW exceeds maxDimension only; pixel count stays under 256MP.
            // 64×8 × 600 = 38400×4800 → dim 38400 > 32768, pixels 184.3MP < 256MP.
            let narrow = CapturedImage(
                cgImage: makeSolidImage(
                    width: 64, height: 8, color: NSColor.blue.cgColor),
                scale: 1)
            let onlyDim = ImageResizer.scale(narrow, by: 600)
            // Square: dest stays under maxDimension; pixels exceed 256MP.
            // 512×512 × 40 = 20480×20480 → dim 20480 < 32768, pixels 419MP.
            let onlyPix = ImageResizer.scale(srcR, by: 40)
            let halfS = ImageResizer.scale(srcR, by: 0.5)
            wc.applyResizeFactor(.infinity)
            wc.applyResizeFactor(-3)
            check("sliceA-resize-invalid",
                  nanS == nil && infS == nil && negS == nil && zeroS == nil
                    && onlyDim == nil && onlyPix == nil
                    && halfS?.cgImage.width == 256
                    && wc.canvasForTesting.image.cgImage.width == 80,
                  "nan \(nanS != nil) inf \(infS != nil) dim \(onlyDim != nil) pix \(onlyPix != nil) half \(halfS?.cgImage.width ?? -1)")

            PixelSamplerCache.resetForTesting()
            let tall = makeSolidImage(
                width: 64, height: 4096, color: NSColor.white.cgColor)
            let wcTall = EditorWindowController.open(
                with: CapturedImage(cgImage: tall, scale: 1),
                forceFitForTesting: true)
            let cTall = wcTall.canvasForTesting
            if let moved = sliceAMouse(.mouseMoved, in: cTall, at: CGPoint(x: 20, y: 40)) {
                cTall.mouseMoved(with: moved)
            }
            cTall.beginRuler(.vertical)
            let rebuildAfterBegin = PixelSamplerCache.rebuildCount
            for y in [80, 160, 240, 320, 400] {
                if let moved = sliceAMouse(
                    .mouseMoved, in: cTall, at: CGPoint(x: 20, y: CGFloat(y)))
                {
                    cTall.mouseMoved(with: moved)
                }
            }
            let rebuildAfterMoves = PixelSamplerCache.rebuildCount
            let bytesWhileOpen = PixelSamplerCache.residentByteCount
            let heldWhileOpen = PixelSamplerCache.isHolding(tall)
            wcTall.window?.close()
            check("sliceA-sampler-cache-tall",
                  rebuildAfterBegin == 1 && rebuildAfterMoves == 1
                    && bytesWhileOpen > 0 && heldWhileOpen
                    && PixelSamplerCache.residentByteCount == 0
                    && !PixelSamplerCache.isHolding(tall),
                  "begin \(rebuildAfterBegin) afterMoves \(rebuildAfterMoves) bytes \(bytesWhileOpen) held \(heldWhileOpen) afterClose \(PixelSamplerCache.residentByteCount)")

            let redCap = CapturedImage(
                cgImage: makeSolidImage(
                    width: 80, height: 60, color: NSColor.red.cgColor),
                scale: 1)
            let wcTab = EditorWindowController.open(
                with: redCap, forceFitForTesting: true)
            let cTab = wcTab.canvasForTesting
            if let moved = sliceAMouse(
                .mouseMoved, in: cTab, at: CGPoint(x: 20, y: 20))
            {
                cTab.mouseMoved(with: moved)
            }
            let pb = NSPasteboard.general
            pb.clearContents()
            pb.setString("SENTINEL-SLICE-A", forType: .string)
            if let tab = sliceAKey(48, characters: "\t") {
                _ = cTab.performKeyEquivalent(with: tab)
            }
            let tabHex = pb.string(forType: .string)
            pb.clearContents()
            pb.setString("SENTINEL-OOB", forType: .string)
            cTab.notePointerForTesting(CGPoint(x: -500, y: -500))
            if let shiftTab = sliceAKey(48, characters: "\t", modifiers: [.shift]) {
                _ = cTab.performKeyEquivalent(with: shiftTab)
            }
            let oobClip = pb.string(forType: .string)
            cTab.notePointerForTesting(CGPoint(x: 20, y: 20))
            cTab.mouseExitedForTesting()
            let afterExit = cTab.pixelUnderMouseForTesting()
            pb.clearContents()
            pb.setString("SENTINEL-EXIT", forType: .string)
            if let tab = sliceAKey(48, characters: "\t") {
                _ = cTab.performKeyEquivalent(with: tab)
            }
            let exitClip = pb.string(forType: .string)
            cTab.notePointerForTesting(CGPoint(x: 20, y: 20))
            let beforeScroll = cTab.pointerPixelForTesting
            cTab.invalidatePointerAfterScrollForTesting()
            let afterScrollCache = cTab.pointerPixelForTesting
            wcTab.window?.close()
            check("sliceA-production-tab",
                  tabHex == "#FF0000",
                  "clip \(tabHex ?? "nil")")
            check("sliceA-pointer-stale",
                  oobClip == "SENTINEL-OOB"
                    && afterExit == nil
                    && exitClip == "SENTINEL-EXIT"
                    && beforeScroll == CGPoint(x: 20, y: 20)
                    && afterScrollCache != CGPoint(x: 20, y: 20),
                  "oob \(oobClip ?? "nil") exitPix \(String(describing: afterExit)) exitClip \(exitClip ?? "nil") before \(String(describing: beforeScroll)) after \(String(describing: afterScrollCache))")

            func makeSplitImage(
                width: Int, height: Int, splitX: Int,
                left: NSColor, right: NSColor
            ) -> CGImage {
                let c = ctx(width, height)
                c.setFillColor(left.cgColor)
                c.fill(CGRect(x: 0, y: 0, width: splitX, height: height))
                c.setFillColor(right.cgColor)
                c.fill(CGRect(
                    x: splitX, y: 0, width: width - splitX, height: height))
                return c.makeImage()!
            }
            let splitCG = makeSplitImage(
                width: 200, height: 80, splitX: 100,
                left: NSColor(srgbRed: 1, green: 0, blue: 0, alpha: 1),
                right: NSColor(srgbRed: 0, green: 0, blue: 1, alpha: 1))
            let splitOriginal: CGImage = splitCG
            let wcSplit = EditorWindowController.open(
                with: CapturedImage(cgImage: splitCG, scale: 1),
                forceFitForTesting: true)
            let cSplit = wcSplit.canvasForTesting
            if let moved = sliceAMouse(
                .mouseMoved, in: cSplit, at: CGPoint(x: 150, y: 40))
            {
                cSplit.mouseMoved(with: moved)
            }
            pb.clearContents()
            pb.setString("SENTINEL-PRE-CROP", forType: .string)
            if let tab = sliceAKey(48, characters: "\t") {
                _ = cSplit.performKeyEquivalent(with: tab)
            }
            let preCropHex = pb.string(forType: .string)
            let heldOriginal = PixelSamplerCache.isHolding(splitOriginal)
            wcSplit.selectTool(.crop)
            if let down = sliceAMouse(
                .leftMouseDown, in: cSplit, at: CGPoint(x: 5, y: 5))
            {
                cSplit.mouseDown(with: down)
            }
            if let drag = sliceAMouse(
                .leftMouseDragged, in: cSplit, at: CGPoint(x: 90, y: 70))
            {
                cSplit.mouseDragged(with: drag)
            }
            if let up = sliceAMouse(
                .leftMouseUp, in: cSplit, at: CGPoint(x: 90, y: 70))
            {
                cSplit.mouseUp(with: up)
            }
            cSplit.applyCropSelection()
            let afterCropPtr = cSplit.pointerPixelForTesting
            let afterCropW = cSplit.image.cgImage.width
            let heldOldAfterCrop = PixelSamplerCache.isHolding(splitOriginal)
            if let moved = sliceAMouse(
                .mouseMoved, in: cSplit, at: CGPoint(x: 20, y: 20))
            {
                cSplit.mouseMoved(with: moved)
            }
            pb.clearContents()
            pb.setString("SENTINEL-CROP", forType: .string)
            if let tab = sliceAKey(48, characters: "\t") {
                _ = cSplit.performKeyEquivalent(with: tab)
            }
            let cropHex = pb.string(forType: .string)
            wcSplit.window?.close()

            let wcUndo = EditorWindowController.open(
                with: CapturedImage(cgImage: splitCG, scale: 1),
                forceFitForTesting: true)
            let cUndo = wcUndo.canvasForTesting
            if let moved = sliceAMouse(
                .mouseMoved, in: cUndo, at: CGPoint(x: 150, y: 40))
            {
                cUndo.mouseMoved(with: moved)
            }
            wcUndo.applyResizeFactor(2)
            let afterResizeW = cUndo.image.cgImage.width
            let afterResizePtr = cUndo.pointerPixelForTesting
            if let cmdZ = sliceAKey(6, characters: "z", modifiers: [.command]) {
                _ = cUndo.performKeyEquivalent(with: cmdZ)
            }
            let afterUndoW = cUndo.image.cgImage.width
            let afterUndoPtr = cUndo.pointerPixelForTesting
            if let moved = sliceAMouse(
                .mouseMoved, in: cUndo, at: CGPoint(x: 150, y: 40))
            {
                cUndo.mouseMoved(with: moved)
            }
            pb.clearContents()
            pb.setString("SENTINEL-UNDO", forType: .string)
            if let tab = sliceAKey(48, characters: "\t") {
                _ = cUndo.performKeyEquivalent(with: tab)
            }
            let undoHex = pb.string(forType: .string)
            wcUndo.window?.close()
            check("sliceA-pointer-crop-resize-undo",
                  preCropHex == "#0000FF"
                    && heldOriginal
                    && afterCropPtr == nil
                    && afterCropW < 200
                    && !heldOldAfterCrop
                    && cropHex == "#FF0000"
                    && afterResizeW == 400
                    && afterResizePtr == nil
                    && afterUndoW == 200
                    && afterUndoPtr == nil
                    && undoHex == "#0000FF",
                  "pre \(preCropHex ?? "nil") heldOrig \(heldOriginal) cropPtr \(String(describing: afterCropPtr)) cropW \(afterCropW) heldOld \(heldOldAfterCrop) cropHex \(cropHex ?? "nil") resizeW \(afterResizeW) resizePtr \(String(describing: afterResizePtr)) undoW \(afterUndoW) undoPtr \(String(describing: afterUndoPtr)) undoHex \(undoHex ?? "nil")")

            let barBase = ctx(200, 100)
            barBase.setFillColor(NSColor.white.cgColor)
            barBase.fill(CGRect(x: 0, y: 0, width: 200, height: 100))
            barBase.setFillColor(NSColor.red.cgColor)
            barBase.fill(CGRect(x: 40, y: 20, width: 80, height: 60))
            let barCG = barBase.makeImage()!
            let wcBar = EditorWindowController.open(
                with: CapturedImage(cgImage: barCG, scale: 1),
                forceFitForTesting: true)
            let cBar = wcBar.canvasForTesting
            if let moved = sliceAMouse(
                .mouseMoved, in: cBar, at: CGPoint(x: 80, y: 50))
            {
                cBar.mouseMoved(with: moved)
            }
            if let left = sliceAKey(123, characters: "\u{F702}") {
                cBar.keyDown(with: left)
            }
            let previewOn = cBar.transientKindForTesting == "ruler"
            if let down = sliceAMouse(
                .leftMouseDown, in: cBar, at: CGPoint(x: 80, y: 50))
            {
                cBar.mouseDown(with: down)
            }
            let imprinted = cBar.annotations.contains { $0 is RulerAnnotation }
                && cBar.transientKindForTesting == nil
            let exported = cBar.flattened()?.cgImage ?? barCG
            let exportChanged = !imagesEqual(barCG, exported)
            let canUndo = cBar.undoManager?.canUndo == true
            if let cmdZ = sliceAKey(6, characters: "z", modifiers: [.command]) {
                _ = cBar.performKeyEquivalent(with: cmdZ)
            }
            let undone = cBar.annotations.isEmpty
            let exportRestored = imagesEqual(
                barCG, cBar.flattened()?.cgImage ?? barCG)
            wcBar.window?.close()
            check("sliceA-ruler-imprint-undo-export",
                  previewOn && imprinted && exportChanged && canUndo
                    && undone && exportRestored,
                  "preview \(previewOn) imprint \(imprinted) export \(exportChanged) undo \(canUndo) empty \(undone) restored \(exportRestored)")

            MainActor.assumeIsolated {
                guard let screen = NSScreen.main ?? NSScreen.screens.first else {
                    check("sliceA-overlay-production-tab", false, "no display")
                    check("sliceA-overlay-saving-lock", false, "no display")
                    return
                }
                let frozen = CapturedImage(
                    cgImage: makeSolidImage(
                        width: 200, height: 150, color: NSColor.red.cgColor),
                    scale: 1)
                let overlay = SelectionOverlay(
                    purpose: .areaReview,
                    inputs: OverlaySessionInputs(
                        afterShow: true, afterCopy: false, afterSave: false),
                    completion: { _ in })
                overlay.routerDependenciesOverride =
                    CaptureActionRouter.Dependencies(
                        copyToClipboard: { _ in },
                        autoSave: { _, _ in },
                        saveAs: { _, _ in },
                        pin: { _ in },
                        ocr: { _ in },
                        openEditor: { _ in },
                        toast: { _ in },
                        setLastCapture: { _ in },
                        setLastAreaRect: { _ in },
                        logEvent: { _ in })
                let view = SelectionOverlayView(
                    mode: .area, screen: screen, frozen: frozen,
                    windowList: [], owner: overlay)
                view.selectForTesting(rect: CGRect(x: 10, y: 10, width: 120, height: 90))
                if let moved = NSEvent.mouseEvent(
                    with: .mouseMoved, location: CGPoint(x: 40, y: 40),
                    modifierFlags: [], timestamp: 0, windowNumber: 0,
                    context: nil, eventNumber: 1, clickCount: 0, pressure: 0)
                {
                    view.mouseMoved(with: moved)
                }
                pb.clearContents()
                pb.setString("SENTINEL-OV", forType: .string)
                if let tab = sliceAKey(48, characters: "\t") {
                    _ = view.performKeyEquivalent(with: tab)
                }
                check("sliceA-overlay-production-tab",
                      overlay.session.phase == .reviewing
                        && pb.string(forType: .string) == "#FF0000",
                      "phase \(overlay.session.phase) clip \(pb.string(forType: .string) ?? "nil")")

                pb.clearContents()
                pb.setString("SENTINEL-SAVE", forType: .string)
                let enteredSaving = overlay.session.transition(to: .saving)
                var savingConsumed = false
                if let tab = sliceAKey(48, characters: "\t") {
                    savingConsumed = view.performKeyEquivalent(with: tab)
                }
                check("sliceA-overlay-saving-lock",
                      enteredSaving
                        && overlay.session.phase == .saving
                        && pb.string(forType: .string) == "SENTINEL-SAVE"
                        && savingConsumed,
                      "phase \(overlay.session.phase) clip \(pb.string(forType: .string) ?? "nil") consumed \(savingConsumed)")
                _ = overlay.session.transition(to: .reviewing)

                let splitFrozen = CapturedImage(
                    cgImage: makeSplitImage(
                        width: 200, height: 150, splitX: 100,
                        left: NSColor(srgbRed: 1, green: 0, blue: 0, alpha: 1),
                        right: NSColor(srgbRed: 0, green: 0, blue: 1, alpha: 1)),
                    scale: 1)
                let overlayPtr = SelectionOverlay(
                    purpose: .areaReview,
                    inputs: OverlaySessionInputs(
                        afterShow: true, afterCopy: false, afterSave: false),
                    completion: { _ in })
                overlayPtr.routerDependenciesOverride =
                    CaptureActionRouter.Dependencies(
                        copyToClipboard: { _ in },
                        autoSave: { _, _ in },
                        saveAs: { _, _ in },
                        pin: { _ in },
                        ocr: { _ in },
                        openEditor: { _ in },
                        toast: { _ in },
                        setLastCapture: { _ in },
                        setLastAreaRect: { _ in },
                        logEvent: { _ in })
                let viewPtr = SelectionOverlayView(
                    mode: .area, screen: screen, frozen: splitFrozen,
                    windowList: [], owner: overlayPtr)
                viewPtr.selectForTesting(
                    rect: CGRect(x: 10, y: 10, width: 160, height: 90))
                if let down = NSEvent.mouseEvent(
                    with: .leftMouseDown, location: CGPoint(x: 40, y: 40),
                    modifierFlags: [], timestamp: 0, windowNumber: 0,
                    context: nil, eventNumber: 2, clickCount: 1, pressure: 1)
                {
                    viewPtr.mouseDown(with: down)
                }
                let downInside = viewPtr.pointerInsideForTesting
                pb.clearContents()
                pb.setString("SENTINEL-OV-DOWN", forType: .string)
                if let tab = sliceAKey(48, characters: "\t") {
                    _ = viewPtr.performKeyEquivalent(with: tab)
                }
                let downHex = pb.string(forType: .string)
                if let drag = NSEvent.mouseEvent(
                    with: .leftMouseDragged, location: CGPoint(x: 140, y: 40),
                    modifierFlags: [], timestamp: 0, windowNumber: 0,
                    context: nil, eventNumber: 3, clickCount: 1, pressure: 1)
                {
                    viewPtr.mouseDragged(with: drag)
                }
                if let up = NSEvent.mouseEvent(
                    with: .leftMouseUp, location: CGPoint(x: 140, y: 40),
                    modifierFlags: [], timestamp: 0, windowNumber: 0,
                    context: nil, eventNumber: 4, clickCount: 1, pressure: 1)
                {
                    viewPtr.mouseUp(with: up)
                }
                pb.clearContents()
                pb.setString("SENTINEL-OV-DRAG", forType: .string)
                if let tab = sliceAKey(48, characters: "\t") {
                    _ = viewPtr.performKeyEquivalent(with: tab)
                }
                let dragHex = pb.string(forType: .string)
                if let exited = NSEvent.enterExitEvent(
                    with: .mouseExited, location: CGPoint(x: 140, y: 40),
                    modifierFlags: [], timestamp: 0, windowNumber: 0,
                    context: nil, eventNumber: 5, trackingNumber: 0,
                    userData: nil)
                {
                    viewPtr.mouseExited(with: exited)
                }
                pb.clearContents()
                pb.setString("SENTINEL-OV-EXIT", forType: .string)
                if let tab = sliceAKey(48, characters: "\t") {
                    _ = viewPtr.performKeyEquivalent(with: tab)
                }
                let exitHex = pb.string(forType: .string)
                if let moved = NSEvent.mouseEvent(
                    with: .mouseMoved, location: CGPoint(x: 40, y: 40),
                    modifierFlags: [], timestamp: 0, windowNumber: 0,
                    context: nil, eventNumber: 6, clickCount: 0, pressure: 0)
                {
                    viewPtr.mouseMoved(with: moved)
                }
                let host = NSWindow(
                    contentRect: NSRect(x: 0, y: 0, width: 200, height: 150),
                    styleMask: .borderless, backing: .buffered, defer: false)
                host.contentView = viewPtr
                NotificationCenter.default.post(
                    name: NSWindow.didChangeScreenNotification, object: host)
                let afterScreenInside = viewPtr.pointerInsideForTesting
                pb.clearContents()
                pb.setString("SENTINEL-OV-SCREEN", forType: .string)
                if let tab = sliceAKey(48, characters: "\t") {
                    _ = viewPtr.performKeyEquivalent(with: tab)
                }
                let screenHex = pb.string(forType: .string)
                host.orderOut(nil)
                check("sliceA-overlay-pointer-events",
                      overlayPtr.session.phase == .reviewing
                        // A live crop drag owns every route, including Tab.
                        // Pointer ownership is still updated by mouseDown;
                        // the post-mouseUp blue sample proves the coordinate.
                        && downInside
                        && downHex == "SENTINEL-OV-DOWN"
                        && dragHex == "#0000FF"
                        && exitHex == "SENTINEL-OV-EXIT"
                        && !afterScreenInside
                        && screenHex == "SENTINEL-OV-SCREEN",
                      "down \(downHex ?? "nil") inside \(downInside) drag \(dragHex ?? "nil") exit \(exitHex ?? "nil") screenInside \(afterScreenInside) screen \(screenHex ?? "nil")")
            }
        }

        // MARK: slice B RED — redaction / spotlight / magnifier / backdrop
        //
        // Fail-first gates for the contract in
        // PLANS/SNIPPR_SLICE_B_BACKDROP_TEXTBLUR_SPOTLIGHT_SPEC.md. They compile
        // against the inert declarations in SliceBContract.swift and stay red
        // until the real compositor lands. The two slice A transition gates
        // (catalog == 10 tools, D/S/M unowned) are replaced by the final
        // invariants below, as agreed with Fizz.
        do {
            /// Bottom-left origin probe, matching annotation pixel space.
            func probe(_ image: CGImage, _ x: Int, _ yBL: Int) -> (Int, Int, Int) {
                var bytes = [UInt8](
                    repeating: 0, count: image.width * image.height * 4)
                guard let c = CGContext(
                    data: &bytes, width: image.width, height: image.height,
                    bitsPerComponent: 8, bytesPerRow: image.width * 4,
                    space: CGColorSpace(name: CGColorSpace.sRGB)!,
                    bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                else { return (-1, -1, -1) }
                c.interpolationQuality = .none
                c.draw(image, in: CGRect(
                    x: 0, y: 0, width: image.width, height: image.height))
                let y = image.height - 1 - yBL
                guard x >= 0, x < image.width, y >= 0, y < image.height
                else { return (-1, -1, -1) }
                let i = (y * image.width + x) * 4
                return (Int(bytes[i]), Int(bytes[i + 1]), Int(bytes[i + 2]))
            }
            // 1. Overlay catalog: legacy tags frozen, two tools appended.
            let tools = OverlayAnnotationTool.allCases
            let legacyTips = [
                "Select / Resize frame (V)", "Pen (P)", "Arrow (A)",
                "Rectangle (R)", "Text (T)", "Line (L)", "Oval (O)",
                "Highlighter (H)", "Counter (N)", "Pixelate (B)",
            ]
            let legacyFrozen = tools.count >= 10
                && tools.prefix(10).map(\.tooltip) == legacyTips
                && tools.prefix(10).map(\.toolbarTag) == Array(100..<110)
            let appended = tools.count == 13
                && tools.dropFirst(10).first?.tooltip.hasPrefix("Spotlight") == true
                && tools.dropFirst(10).first?.toolbarTag == 110
                && tools.dropFirst(11).first?.tooltip
                    .hasPrefix("Pixelate text") == true
                && tools.dropFirst(11).first?.toolbarTag == 111
                && tools.last?.tooltip.hasPrefix("Magnifier") == true
                && tools.last?.toolbarTag == 112
            check("sliceB-overlay-catalog-final",
                  legacyFrozen && appended,
                  "count \(tools.count) tips \(tools.map(\.tooltip))")

            // 1b. A magnifier patch is sanitized ONCE, at creation. Everything
            // that changes the redaction set afterwards has to resample it, or
            // the callout keeps displaying pixels the user has since covered —
            // a disclosure, not a stale pixel. The cross-check at the end is
            // the load-bearing one: the REFRESH path must land on the same
            // bytes the CREATION path produces for the same document, so this
            // cannot pass by merely mutating the patch into something else.
            do {
                @MainActor func fieldWithBlock() -> CGImage? {
                    guard let ctx = CGContext(
                        data: nil, width: 400, height: 300,
                        bitsPerComponent: 8, bytesPerRow: 0,
                        space: CGColorSpace(name: CGColorSpace.sRGB)!,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                    else { return nil }
                    ctx.setFillColor(NSColor.white.cgColor)
                    ctx.fill(CGRect(x: 0, y: 0, width: 400, height: 300))
                    ctx.setFillColor(NSColor.red.cgColor)
                    ctx.fill(CGRect(x: 90, y: 90, width: 60, height: 60))
                    return ctx.makeImage()
                }
                @MainActor func patchBytes(_ surface: AnnotationSurface) -> [UInt8]? {
                    guard let magnifier = surface.annotations
                        .compactMap({ $0 as? MagnifierAnnotation }).last,
                          let snapshot = magnifier.snapshot,
                          let ctx = CGContext(
                            data: nil, width: snapshot.width,
                            height: snapshot.height, bitsPerComponent: 8,
                            bytesPerRow: snapshot.width * 4,
                            space: CGColorSpace(name: CGColorSpace.sRGB)!,
                            bitmapInfo: CGImageAlphaInfo
                                .premultipliedLast.rawValue)
                    else { return nil }
                    ctx.draw(snapshot, in: CGRect(
                        x: 0, y: 0, width: snapshot.width,
                        height: snapshot.height))
                    guard let data = ctx.data else { return nil }
                    let count = snapshot.width * snapshot.height * 4
                    return Array(UnsafeBufferPointer(
                        start: data.assumingMemoryBound(to: UInt8.self),
                        count: count))
                }
                @MainActor func newSurface(_ base: CGImage) -> AnnotationSurface {
                    let surface = AnnotationSurface(pixelScale: 1)
                    surface.redactionBaseBounds = CGRect(
                        x: 0, y: 0, width: base.width, height: base.height)
                    surface.redactionBaseImage = base
                    return surface
                }
                @MainActor func addMagnifier(
                    _ surface: AnnotationSurface, base: CGImage,
                    at origin: CGPoint = CGPoint(x: 130, y: 130)
                ) {
                    surface.tool = .magnifier
                    // STRADDLES the red block's edge at 150 on purpose:
                    // pixelating a uniformly red region reproduces red, so a
                    // source wholly inside it would leave the "patch changed"
                    // assertions unable to fail.
                    _ = surface.beginDrag(atPixel: origin)
                    surface.continueDrag(toPixel: CGPoint(
                        x: origin.x + 40, y: origin.y + 40))
                    surface.endDrag()
                    _ = surface.fillPendingMagnifier(base: base)
                }
                @MainActor func addPixelation(
                    _ surface: AnnotationSurface,
                    from start: CGPoint = CGPoint(x: 120, y: 120),
                    to end: CGPoint = CGPoint(x: 190, y: 190)
                ) {
                    surface.tool = .blur
                    _ = surface.beginDrag(atPixel: start)
                    surface.continueDrag(toPixel: end)
                    surface.endDrag()
                }

                var freshFailures: [String] = []
                if let base = fieldWithBlock() {
                    // M then Blur: the patch predates the pixelation.
                    let mFirst = newSurface(base)
                    addMagnifier(mFirst, base: base)
                    let raw = patchBytes(mFirst)
                    if raw == nil { freshFailures.append("no patch after create") }
                    addPixelation(mFirst)
                    let sanitized = patchBytes(mFirst)
                    if sanitized == nil {
                        freshFailures.append("patch lost after pixelate")
                    } else if sanitized == raw {
                        freshFailures.append(
                            "patch unchanged by a pixelation over its source")
                    }
                    // Undo UNCOVERS: the patch must go back to the raw pixels,
                    // exactly — a blurred patch over an unblurred document is
                    // wrong in the other direction.
                    _ = mFirst.undo()
                    if patchBytes(mFirst) != raw {
                        freshFailures.append("undo did not restore the patch")
                    }
                    // Redo covers again.
                    _ = mFirst.redo()
                    if patchBytes(mFirst) != sanitized {
                        freshFailures.append("redo did not re-sanitize")
                    }
                    // An OCR job resolving off the main thread narrows the
                    // mask; the funnel it calls must resample too.
                    if let blur = mFirst.annotations
                        .compactMap({ $0 as? BlurAnnotation }).last {
                        // INSIDE the pixelation (a box that hangs outside it
                        // fails closed to the full rect by design) and clear
                        // of the magnifier's source, so the mask genuinely
                        // narrows away from the sampled pixels.
                        blur.redactionState = .words([
                            CGRect(x: 175, y: 175, width: 10, height: 10),
                        ])
                        mFirst.redactionDidChange()
                        if patchBytes(mFirst) == sanitized {
                            freshFailures.append(
                                "async word mask left the patch stale")
                        }
                    } else {
                        freshFailures.append("no pixelation recorded")
                    }

                    // Blur then M: creation already samples the sanitized
                    // document. Refreshing must reach the SAME bytes, which is
                    // what makes the assertions above about a changed patch
                    // mean "correctly sanitized" rather than merely "different".
                    let blurFirst = newSurface(base)
                    addPixelation(blurFirst)
                    addMagnifier(blurFirst, base: base)
                    let createdSanitized = patchBytes(blurFirst)
                    let mThenBlur = newSurface(base)
                    addMagnifier(mThenBlur, base: base)
                    addPixelation(mThenBlur)
                    if createdSanitized == nil {
                        freshFailures.append("blur-first patch missing")
                    } else if patchBytes(mThenBlur) != createdSanitized {
                        freshFailures.append(
                            "refresh path disagrees with creation path")
                    }
                    if createdSanitized == raw {
                        freshFailures.append("sanitized equals raw — oracle blind")
                    }
                    // A redaction drag STARTS: until its rect is valid the
                    // document is fully masked by both fail-closed paths, so
                    // every callout — not only one under the press — must go
                    // blank before the first dragged event, and come back
                    // after the drag resolves.
                    let twoPatches = newSurface(base)
                    addMagnifier(twoPatches, base: base)
                    addMagnifier(
                        twoPatches, base: base, at: CGPoint(x: 230, y: 40))
                    let patchesBefore = twoPatches.annotations
                        .compactMap { $0 as? MagnifierAnnotation }
                    if patchesBefore.count != 2
                        || patchesBefore.contains(where: { $0.snapshot == nil }) {
                        freshFailures.append("two-patch fixture not built")
                    }
                    twoPatches.tool = .blur
                    // Far from both sources, and nothing dragged yet.
                    _ = twoPatches.beginDrag(atPixel: CGPoint(x: 20, y: 280))
                    if patchesBefore.contains(where: { $0.snapshot != nil }) {
                        freshFailures.append(
                            "callout kept raw pixels at redaction mouse-down")
                    }
                    twoPatches.abandonDrag()
                    if patchesBefore.contains(where: { $0.snapshot == nil }) {
                        freshFailures.append(
                            "abandoned drag left a callout blank")
                    }

                    // No base image = no way to resample: clear rather than
                    // keep showing pixels the document no longer shows.
                    let orphan = newSurface(base)
                    addMagnifier(orphan, base: base)
                    orphan.redactionBaseImage = nil
                    orphan.refreshMagnifierSnapshots()
                    if orphan.annotations
                        .compactMap({ $0 as? MagnifierAnnotation })
                        .contains(where: { $0.snapshot != nil }) {
                        freshFailures.append("orphan patch kept stale pixels")
                    }
                } else {
                    freshFailures.append("no base image")
                }
                check("sliceB-magnifier-redaction-freshness",
                      freshFailures.isEmpty,
                      freshFailures.joined(separator: " | "))
            }

            // 1e. Backdrop in Area Review: one timeline with the marks, two
            // readings of the same freeze per terminal, and a compose failure
            // that changes nothing at all.
            do {
                var bdFailures: [String] = []
                if let bdScreen = NSScreen.main ?? NSScreen.screens.first {
                    @MainActor final class RouteSpy {
                        var copies: [CGSize] = []
                        var pins: [CGSize] = []
                        var editors: [CGSize] = []
                        var ocr: [CGSize] = []
                        var lastCaptures: [CGSize] = []
                        var areaRects: [CGRect] = []
                        var toasts: [String] = []
                        func dependencies() -> CaptureActionRouter.Dependencies {
                            CaptureActionRouter.Dependencies(
                                copyToClipboard: { [self] in
                                    copies.append(CGSize(
                                        width: $0.cgImage.width,
                                        height: $0.cgImage.height))
                                },
                                autoSave: { _, _ in }, saveAs: { _, _ in },
                                pin: { [self] in
                                    pins.append(CGSize(
                                        width: $0.cgImage.width,
                                        height: $0.cgImage.height))
                                },
                                ocrWithMode: { [self] image, _ in
                                    ocr.append(CGSize(
                                        width: image.cgImage.width,
                                        height: image.cgImage.height))
                                },
                                openEditor: { [self] in
                                    editors.append(CGSize(
                                        width: $0.image.cgImage.width,
                                        height: $0.image.cgImage.height))
                                },
                                toast: { [self] in toasts.append($0) },
                                setLastCapture: { [self] in
                                    lastCaptures.append(CGSize(
                                        width: $0.cgImage.width,
                                        height: $0.cgImage.height))
                                },
                                setLastAreaRect: { [self] in
                                    areaRects.append($0)
                                },
                                logEvent: { _ in })
                        }
                    }
                    @MainActor func bdReview(
                        _ spy: RouteSpy, selection: CGRect
                    ) -> (SelectionOverlay, SelectionOverlayView) {
                        let overlay = SelectionOverlay(
                            purpose: .areaReview,
                            inputs: OverlaySessionInputs(
                                afterShow: true, afterCopy: false,
                                afterSave: false),
                            completion: { _ in })
                        overlay.routerDependenciesOverride = spy.dependencies()
                        let view = SelectionOverlayView(
                            mode: .area, screen: bdScreen,
                            frozen: CapturedImage(
                                cgImage: makeStripePattern(
                                    width: Int(bdScreen.frame.width),
                                    height: Int(bdScreen.frame.height),
                                    seed: 0x0817_2026),
                                scale: 1),
                            windowList: [], owner: overlay)
                        view.selectForTesting(rect: selection)
                        return (overlay, view)
                    }
                    let bdSelection = CGRect(
                        x: 200, y: 200, width: 320, height: 240)

                    // --- One timeline. A preset sits BETWEEN two marks and
                    // undoes in its own turn, which a parallel stack could not
                    // reproduce.
                    let orderSpy = RouteSpy()
                    let (orderOverlay, orderView) = bdReview(
                        orderSpy, selection: bdSelection)
                    let orderSurface = orderView.annotationSurface
                        ?? AnnotationSurface(pixelScale: 1)
                    if orderView.annotationSurface == nil {
                        bdFailures.append("no surface after review began")
                    }
                    orderSurface.addBlurForTesting(rect: CGRect(
                        x: 210, y: 210, width: 40, height: 40))
                    if !orderView.applyBackdropPreset(.ocean) {
                        bdFailures.append("ocean refused")
                    }
                    orderSurface.addBlurForTesting(rect: CGRect(
                        x: 300, y: 300, width: 40, height: 40))
                    // Applying the SAME preset is not an edit.
                    if orderView.applyBackdropPreset(.ocean) {
                        bdFailures.append("same preset forked history")
                    }
                    let afterMarks = orderSurface.annotations.count
                    _ = orderSurface.undo()
                    if orderSurface.backdropPreset != .ocean {
                        bdFailures.append("undo of a mark changed the preset")
                    }
                    _ = orderSurface.undo()
                    if orderSurface.backdropPreset != BackdropPreset.none {
                        bdFailures.append("undo did not reach the preset")
                    }
                    _ = orderSurface.undo()
                    if !orderSurface.annotations.isEmpty {
                        bdFailures.append("undo left \(orderSurface.annotations.count)")
                    }
                    _ = orderSurface.redo()
                    _ = orderSurface.redo()
                    if orderSurface.backdropPreset != .ocean {
                        bdFailures.append("redo did not restore the preset")
                    }
                    // A fresh edit after undo drops the whole redo branch.
                    _ = orderSurface.undo()
                    orderSurface.addBlurForTesting(rect: CGRect(
                        x: 400, y: 400, width: 20, height: 20))
                    if orderSurface.canRedo {
                        bdFailures.append("fork kept a redo branch")
                    }
                    if orderSurface.annotations.count >= afterMarks {
                        bdFailures.append("fork did not drop the branch")
                    }
                    orderOverlay.dismissForTesting()

                    // --- Two readings of one freeze. Expected sizes come from
                    // the shared geometry type, not from the code under test.
                    let dualSpy = RouteSpy()
                    let (dualOverlay, dualView) = bdReview(
                        dualSpy, selection: bdSelection)
                    _ = dualView.applyBackdropPreset(.sunset)
                    let innerPixels = CGSize(width: 320, height: 240)
                    let expectedOuter = SliceBBackdrop.outerDimensions(
                        innerWidth: 320, innerHeight: 240, preset: .sunset,
                        pixelScale: 1)
                    // The initial capture ran BEFORE any preset could exist,
                    // so AutoSave's payload is the undecorated crop.
                    if dualSpy.lastCaptures.first != innerPixels {
                        bdFailures.append(
                            "initial capture decorated \(String(describing: dualSpy.lastCaptures.first))")
                    }

                    // See the note at the colour-space gate: OCR is a
                    // sub-mode now, and Translate carries the same
                    // undecorated reading through the router.
                    dualView.performReviewActionForTesting(.translate)
                    if dualSpy.ocr.last != innerPixels {
                        bdFailures.append(
                            "OCR got a framed image \(String(describing: dualSpy.ocr.last))")
                    }
                    // Same call, two readings: the recognizer reads the crop,
                    // the app remembers the picture the user saw.
                    if let expectedOuter {
                        let framed = CGSize(
                            width: CGFloat(expectedOuter.width),
                            height: CGFloat(expectedOuter.height))
                        if dualSpy.lastCaptures.last != framed {
                            bdFailures.append(
                                "OCR remembered \(String(describing: dualSpy.lastCaptures.last)) want \(framed)")
                        }
                    }
                    dualOverlay.dismissForTesting()

                    let visualSpy = RouteSpy()
                    let (visualOverlay, visualView) = bdReview(
                        visualSpy, selection: bdSelection)
                    _ = visualView.applyBackdropPreset(.sunset)
                    // Preview geometry is the same layout the export uses.
                    if let outer = visualView.backdropPreviewOuterRectForTesting,
                       let expectedOuter {
                        if abs(outer.width - CGFloat(expectedOuter.width)) > 0.5
                            || abs(outer.height
                                - CGFloat(expectedOuter.height)) > 0.5 {
                            bdFailures.append(
                                "preview \(outer.size) vs export \(expectedOuter)")
                        }
                    } else {
                        bdFailures.append("no preview rect")
                    }
                    visualView.performReviewActionForTesting(.copy)
                    if let expectedOuter {
                        let want = CGSize(
                            width: CGFloat(expectedOuter.width),
                            height: CGFloat(expectedOuter.height))
                        if visualSpy.copies.last != want {
                            bdFailures.append(
                                "Copy not framed \(String(describing: visualSpy.copies.last)) want \(want)")
                        }
                        if visualSpy.lastCaptures.last != want {
                            bdFailures.append("lastCapture not framed")
                        }
                        if want == innerPixels {
                            bdFailures.append("frame added nothing — oracle blind")
                        }
                    }
                    // The crop the user chose is unchanged by the decoration.
                    if visualSpy.areaRects.last?.size != innerPixels {
                        bdFailures.append(
                            "lastAreaRect moved with the frame \(String(describing: visualSpy.areaRects.last))")
                    }
                    visualOverlay.dismissForTesting()

                    // --- Compose fails: nothing may change. Not the router,
                    // not the phase, not history, and not the text still being
                    // typed — which is exactly what committing the field
                    // before the compose would have broken.
                    let failSpy = RouteSpy()
                    let (failOverlay, failView) = bdReview(
                        failSpy, selection: bdSelection)
                    _ = failView.applyBackdropPreset(.mint)
                    failView.beginTextEntryForTesting(atView: CGPoint(
                        x: 260, y: 260))
                    // Typed, NOT committed: the terminal action is what must
                    // decide whether this text becomes a mark.
                    failView.typeTextForTesting("secret")
                    let historyBefore = failView.annotationSurface?
                        .annotations.count ?? -1
                    ForcedOuterComposeFailure.scoped {
                        failView.performReviewActionForTesting(.copy)
                    }
                    if !failSpy.copies.isEmpty {
                        bdFailures.append("failed compose still copied")
                    }
                    if failOverlay.session.phase != .reviewing {
                        bdFailures.append(
                            "failed compose left phase \(failOverlay.session.phase)")
                    }
                    if failView.annotationSurface?.annotations.count
                        != historyBefore {
                        bdFailures.append("failed compose mutated history")
                    }
                    if failView.textFieldForTesting == nil {
                        bdFailures.append("failed compose committed the text")
                    }
                    if failSpy.toasts.isEmpty {
                        bdFailures.append("failed compose was silent")
                    }
                    // Recovering: the same click now works, and the text that
                    // survived is in the exported image exactly once.
                    failView.performReviewActionForTesting(.copy)
                    if failSpy.copies.count != 1 {
                        bdFailures.append(
                            "recovery copies \(failSpy.copies.count)")
                    }
                    let textMarks = failView.annotationSurface?.annotations
                        .filter { $0 is TextAnnotation }.count ?? -1
                    if textMarks != 1 {
                        bdFailures.append("text committed \(textMarks) times")
                    }
                    failOverlay.dismissForTesting()
                } else {
                    bdFailures.append("no screen")
                }
                check("sliceB-area-backdrop-routes", bdFailures.isEmpty,
                      bdFailures.joined(separator: " | "))
            }

            @MainActor func rasterizeSpec(
                _ image: CGImage
            ) -> ((Int, Int) -> Int)? {
                let w = image.width, h = image.height
                var bytes = [UInt8](repeating: 0, count: w * h * 4)
                guard let c = CGContext(
                    data: &bytes, width: w, height: h, bitsPerComponent: 8,
                    bytesPerRow: w * 4,
                    space: CGColorSpace(name: CGColorSpace.sRGB)!,
                    bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                else { return nil }
                c.interpolationQuality = .none
                c.draw(image, in: CGRect(
                    x: 0, y: 0, width: CGFloat(w), height: CGFloat(h)))
                let snapshot = bytes
                // x, y bottom-left -> red channel.
                return { x, y in Int(snapshot[((h - 1 - y) * w + x) * 4]) }
            }

            // C3: the spec's numbers, written out HERE as literals. A gate
            // that asked production for its expectations would agree with any
            // table at all, including one that drifted.
            do {
                var specFailures: [String] = []
                func rgbBytes(_ color: CGColor) -> (Int, Int, Int, CGFloat)? {
                    guard let converted = color.converted(
                        to: CGColorSpace(name: CGColorSpace.sRGB)!,
                        intent: .defaultIntent, options: nil),
                        let c = converted.components, c.count >= 4
                    else { return nil }
                    return (
                        Int((c[0] * 255).rounded()),
                        Int((c[1] * 255).rounded()),
                        Int((c[2] * 255).rounded()),
                        c[3])
                }
                let expectedStops:
                    [BackdropPreset: [(CGFloat, (Int, Int, Int))]] = [
                    .ocean: [
                        (0.00, (139, 180, 255)), (0.28, (74, 124, 240)),
                        (0.62, (46, 61, 184)), (1.00, (26, 24, 104)),
                    ],
                    .sunset: [
                        (0.00, (255, 208, 138)), (0.28, (255, 126, 74)),
                        (0.62, (230, 61, 120)), (1.00, (122, 34, 136)),
                    ],
                    .mint: [
                        (0.00, (154, 245, 212)), (0.28, (61, 220, 176)),
                        (0.62, (26, 154, 138)), (1.00, (10, 69, 80)),
                    ],
                    .graphite: [
                        (0.00, (90, 98, 112)), (0.32, (52, 58, 70)),
                        (0.68, (28, 32, 40)), (1.00, (11, 13, 17)),
                    ],
                ]
                let expectedWash:
                    [BackdropPreset: ((Int, Int, Int), CGFloat)] = [
                    .ocean: ((255, 255, 255), 0.20),
                    .sunset: ((255, 232, 192), 0.18),
                    .mint: ((232, 255, 246), 0.16),
                    .graphite: ((139, 155, 184), 0.14),
                ]
                let expectedSeeds: [BackdropPreset: UInt32] = [
                    .ocean: 0x0CE4_0001, .sunset: 0x5E70_0002,
                    .mint: 0xA117_0003, .graphite: 0x6A40_0004,
                ]
                for preset in BackdropPreset.allCases where preset != .none {
                    let stops = SliceBBackdrop.gradientStops(for: preset)
                    guard let want = expectedStops[preset],
                          stops.count == want.count else {
                        specFailures.append("\(preset.rawValue) stop count")
                        continue
                    }
                    for (index, pair) in zip(stops, want).enumerated() {
                        if abs(pair.0.location - pair.1.0) > 0.001 {
                            specFailures.append(
                                "\(preset.rawValue) loc\(index) "
                                    + "\(pair.0.location)")
                        }
                        guard let got = rgbBytes(pair.0.color) else {
                            specFailures.append(
                                "\(preset.rawValue) colour\(index)")
                            continue
                        }
                        if (got.0, got.1, got.2) != pair.1.1 {
                            specFailures.append(
                                "\(preset.rawValue) stop\(index) "
                                    + "\((got.0, got.1, got.2)) "
                                    + "want \(pair.1.1)")
                        }
                    }
                    let wash = SliceBBackdrop.radialWash(for: preset)
                    if let wantWash = expectedWash[preset],
                       let centre = rgbBytes(wash.centre),
                       let edge = rgbBytes(wash.edge) {
                        if (centre.0, centre.1, centre.2) != wantWash.0
                            || abs(centre.3 - wantWash.1) > 0.001 {
                            specFailures.append(
                                "\(preset.rawValue) wash centre "
                                    + "\((centre.0, centre.1, centre.2)) "
                                    + "α\(centre.3)")
                        }
                        // The wash must vanish at the rim, or it would tint
                        // the whole frame rather than light one corner.
                        if edge.3 != 0 {
                            specFailures.append(
                                "\(preset.rawValue) wash edge α\(edge.3)")
                        }
                    } else {
                        specFailures.append("\(preset.rawValue) wash missing")
                    }
                    if SliceBBackdrop.grainSeed(for: preset)
                        != expectedSeeds[preset] {
                        specFailures.append("\(preset.rawValue) seed")
                    }
                }
                // The hash, recomputed here from the spec's own formula. If
                // production's mixing constants drift, the tiles change and
                // this catches it without a stored image.
                func referenceHash(_ x: Int, _ y: Int, _ seed: UInt32) -> UInt32 {
                    var h = seed
                    h &+= UInt32(bitPattern: Int32(truncatingIfNeeded: x))
                        &* 374_761_393
                    h &+= UInt32(bitPattern: Int32(truncatingIfNeeded: y))
                        &* 668_265_263
                    h ^= h >> 13
                    h &*= 1_274_126_177
                    h ^= h >> 16
                    return h
                }
                let seed = SliceBBackdrop.grainSeed(for: .ocean)
                for (x, y) in [(0, 0), (1, 0), (0, 1), (63, 91), (127, 127)] {
                    if SliceBBackdrop.grainHash(x: x, y: y, seed: seed)
                        != referenceHash(x, y, seed) {
                        specFailures.append("hash(\(x),\(y))")
                    }
                }
                // And the tile really carries those values: ±2 around mid
                // grey, opaque, 128 texels square.
                if let tile = SliceBBackdrop.grainTile(for: .ocean) {
                    if tile.width != 128 || tile.height != 128 {
                        specFailures.append(
                            "tile \(tile.width)x\(tile.height)")
                    }
                    var bytes = [UInt8](repeating: 0, count: 128 * 128 * 4)
                    if let c = CGContext(
                        data: &bytes, width: 128, height: 128,
                        bitsPerComponent: 8, bytesPerRow: 128 * 4,
                        space: CGColorSpace(name: CGColorSpace.sRGB)!,
                        bitmapInfo: CGImageAlphaInfo
                            .premultipliedLast.rawValue) {
                        c.interpolationQuality = .none
                        c.draw(tile, in: CGRect(
                            x: 0, y: 0, width: 128, height: 128))
                        var sawLow = false, sawHigh = false
                        for y in 0..<128 {
                            for x in 0..<128 {
                                // Row-major from the TOP, which is how a
                                // CGContext's buffer is laid out and how the
                                // tile was authored. Orientation is immaterial
                                // to a repeating dither, but the gate has to
                                // read it the way it was written.
                                let i = (y * 128 + x) * 4
                                let want = 128
                                    + Int(referenceHash(x, y, seed) % 5) - 2
                                if Int(bytes[i]) != want
                                    || Int(bytes[i + 1]) != want
                                    || Int(bytes[i + 2]) != want
                                    || bytes[i + 3] != 255 {
                                    specFailures.append(
                                        "tile(\(x),\(y)) \(bytes[i]) "
                                            + "want \(want)")
                                }
                                if want < 128 { sawLow = true }
                                if want > 128 { sawHigh = true }
                            }
                        }
                        if !(sawLow && sawHigh) {
                            specFailures.append("tile is flat — oracle blind")
                        }
                    }
                    // Deterministic across calls, and the cache hands back the
                    // same object rather than rebuilding a different one.
                    if SliceBBackdrop.grainTile(for: .ocean) !== tile {
                        specFailures.append("tile not cached")
                    }
                    if SliceBBackdrop.grainTile(for: .sunset) === tile {
                        specFailures.append("seeds share a tile")
                    }
                } else {
                    specFailures.append("no grain tile")
                }
                // Hairline: 1pt at α0.16 white, inside the plate.
                if let c = CGContext(
                    data: nil, width: 60, height: 60, bitsPerComponent: 8,
                    bytesPerRow: 0,
                    space: CGColorSpace(name: CGColorSpace.sRGB)!,
                    bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) {
                    c.setFillColor(NSColor.black.cgColor)
                    c.fill(CGRect(x: 0, y: 0, width: 60, height: 60))
                    SliceBBackdrop.drawPlateHairline(
                        in: c, rect: CGRect(x: 0, y: 0, width: 60, height: 60),
                        pixelScale: 1)
                    if let out = c.makeImage(), let px = rasterizeSpec(out) {
                        // Mid-edge, where the stroke is straight: black lifted
                        // by 0.16 of white is ~41.
                        let edge = px(0, 30)
                        let middle = px(30, 30)
                        if abs(edge - 41) > 3 {
                            specFailures.append("hairline edge \(edge)")
                        }
                        if middle != 0 {
                            specFailures.append("hairline bled inward \(middle)")
                        }
                    }
                }
                // Geometry the spec freezes.
                if SliceBBackdrop.cornerRadiusPt != 12
                    || SliceBBackdrop.shadowOffsetPt != -8
                    || SliceBBackdrop.shadowBlurPt != 24
                    || SliceBBackdrop.paddingFraction != 0.06
                    || SliceBBackdrop.minPadding != 40
                    || SliceBBackdrop.maxPadding != 320
                    || SliceBBackdrop.shadowSafetyFactor != 1.25 {
                    specFailures.append("geometry moved")
                }
                // The corner table, written here as literals rather than read
                // back from the code it checks — and the SAME numbers the
                // Windows build uses, so a capture framed on either platform
                // is the same product.
                let cornerCases:
                    [(short: CGFloat, long: CGFloat,
                      none: CGFloat, small: CGFloat,
                      medium: CGFloat, large: CGFloat)] = [
                    // the capture the owner complained about
                    (1523, 3285, 0, 18.276, 36.552, 60.92),
                    (1080, 1920, 0, 12.96, 25.92, 43.2),
                    (400, 800, 0, 8, 12, 16),
                    // tiny: the floors are floors, and half the short edge caps
                    (20, 200, 0, 8, 10, 10),
                ]
                for c in cornerCases {
                    let document = CGSize(width: c.long, height: c.short)
                    let want: [(BackdropCornerStyle, CGFloat)] = [
                        (.none, c.none), (.small, c.small),
                        (.medium, c.medium), (.large, c.large),
                    ]
                    for (style, radius) in want {
                        let got = SliceBBackdrop.cornerRadius(
                            documentPoints: document, style: style)
                        if abs(got - radius) > 0.01 {
                            specFailures.append(
                                "corner \(Int(c.short))pt \(style): \(got) want \(radius)")
                        }
                    }
                    // Orientation cannot matter: the short edge decides.
                    let rotated = SliceBBackdrop.cornerRadius(
                        documentPoints: CGSize(width: c.short, height: c.long),
                        style: .medium)
                    if abs(rotated - c.medium) > 0.01 {
                        specFailures.append(
                            "corner \(Int(c.short))pt rotated: \(rotated)")
                    }
                    for style in BackdropCornerStyle.allCases
                    where SliceBBackdrop.cornerRadius(
                        documentPoints: document, style: style) > c.short / 2 + 0.01 {
                        specFailures.append(
                            "corner \(Int(c.short))pt \(style) exceeds half the edge")
                    }
                }
                // The default is what a user who never opens the menu gets —
                // asked through the formula, because comparing two constants
                // is folded away and a check that cannot fail is not a check.
                let reference = CGSize(width: 1920, height: 1080)
                if abs(
                    SliceBBackdrop.cornerRadius(
                        documentPoints: reference,
                        style: SliceBBackdrop.defaultCornerStyle)
                        - SliceBBackdrop.cornerRadius(
                            documentPoints: reference, style: .medium)) > 0.01 {
                    specFailures.append("default corner style is not medium")
                }
                // And the old fixed radius is now the FLOOR of Medium, not the
                // radius: a 4K capture must round more than a thumbnail does.
                if SliceBBackdrop.cornerRadius(
                    documentPoints: CGSize(width: 4000, height: 4000),
                    style: .medium) <= SliceBBackdrop.cornerRadiusPt {
                    specFailures.append("a 4K capture still rounds like a thumbnail")
                }
                check("sliceB-backdrop-presets-match-spec",
                      specFailures.isEmpty,
                      specFailures.prefix(6).joined(separator: " | "))
            }

            // WP1: BackdropStyle freeze + v0 compositor parity.
            do {
                var styleFailures: [String] = []
                let ids = BackdropGradientCatalog.ids
                if ids != [
                    "ocean", "sunset", "mint", "graphite",
                    "lavender", "rose", "ember", "meadow",
                    "lagoon", "midnight", "paper", "fog",
                ] {
                    styleFailures.append("catalog ids \(ids)")
                }
                if BackdropGradientCatalog.entry(id: "ocean")?.stops
                    != ["#8BB4FF", "#4A7CF0", "#2E3DB8", "#1A1868"]
                    || BackdropGradientCatalog.entry(id: "graphite")?
                        .locations != BackdropGradientCatalog.graphiteLocations
                    || BackdropGradientCatalog.entry(id: "paper")?
                        .shadowAlphaAtStrength1 != 0.22
                    || BackdropGradientCatalog.entry(id: "paper")?
                        .wash.alpha != 0.10
                    || BackdropGradientCatalog.visualAxis
                        != "topLeftToBottomRight" {
                    styleFailures.append("catalog bytes")
                }
                let ocean = BackdropStyle.from(preset: .ocean)
                if ocean.kind != .gradient || ocean.gradientId != "ocean"
                    || ocean.legacyPreset != .ocean
                    || ocean.paddingFraction != 0.06
                    || ocean.shadowStrength != 1
                    || ocean.cornerStyle != .medium
                    || ocean.alignment != .cc || ocean.ratio != .auto
                    || !ocean.autoBalance {
                    styleFailures.append("from-ocean \(ocean)")
                }
                if BackdropStyle.from(preset: .none).kind != .none
                    || BackdropStyle.gradient("nope").gradientId != "ocean" {
                    styleFailures.append("clamp/none")
                }
                let encoded = try? JSONEncoder().encode(ocean)
                let decoded = encoded.flatMap {
                    try? JSONDecoder().decode(BackdropStyle.self, from: $0)
                }
                if decoded != ocean {
                    styleFailures.append("codable")
                }
                // Parameterized padding with v0 defaults matches the frozen
                // numbers: 1000 → 60, 400 → 40, 40000 → 320, retina floor 80.
                if SliceBBackdrop.padding(
                    forLongEdge: 1000, pixelScale: 1, style: ocean) != 60
                    || SliceBBackdrop.padding(
                        forLongEdge: 400, pixelScale: 1, style: ocean) != 40
                    || SliceBBackdrop.padding(
                        forLongEdge: 40000, pixelScale: 1, style: ocean) != 320
                    || SliceBBackdrop.padding(
                        forLongEdge: 60, pixelScale: 2, style: ocean) != 80 {
                    styleFailures.append("padding-v0")
                }
                let weak = { () -> BackdropStyle in
                    var s = ocean
                    s.shadowStrength = 0
                    return s
                }()
                if SliceBBackdrop.padding(
                    forLongEdge: 60, pixelScale: 2, style: weak)
                    != SliceBBackdrop.minPadding {
                    styleFailures.append("padding-no-shadow-floor")
                }
                let inner = makeSolidImage(
                    width: 50, height: 40, color: NSColor.white.cgColor)
                let cornerBefore = Settings.shared.backdropCornerStyle
                Settings.shared.backdropCornerStyle = .medium
                defer { Settings.shared.backdropCornerStyle = cornerBefore }
                let viaPreset = SliceBBackdrop.compose(
                    image: inner, preset: .ocean,
                    budgetBytes: SliceBExport.defaultBudgetBytes)
                let viaStyle = SliceBBackdrop.compose(
                    image: inner, style: ocean,
                    budgetBytes: SliceBExport.defaultBudgetBytes)
                if viaPreset == nil || viaStyle == nil
                    || (viaPreset != nil && viaStyle != nil
                        && !imagesEqual(viaPreset!, viaStyle!)) {
                    styleFailures.append("compose-parity")
                }
                let shadow = ocean.shadowMetrics()
                if abs(shadow.offsetPt - SliceBBackdrop.shadowOffsetPt) > 0.001
                    || abs(shadow.blurPt - SliceBBackdrop.shadowBlurPt) > 0.001
                    || abs(shadow.alpha - 0.35) > 0.001 {
                    styleFailures.append(
                        "shadow \(shadow.offsetPt) \(shadow.blurPt) \(shadow.alpha)")
                }
                let paper = BackdropStyle.gradient("paper").shadowMetrics()
                if abs(paper.alpha - 0.22) > 0.001 {
                    styleFailures.append("paper-alpha \(paper.alpha)")
                }
                check("sliceB-backdrop-style-v0-parity",
                      styleFailures.isEmpty,
                      styleFailures.prefix(6).joined(separator: " | "))
            }

            // WP2: JSON v2 catalog + wash on the 8 new ids, plus solid /
            // image / wallpaper / blur fills and the extra dest-sized reserve.
            do {
                var fillFailures: [String] = []
                for id in BackdropGradientCatalog.ids {
                    guard let e = BackdropGradientCatalog.entry(id: id) else {
                        fillFailures.append("missing \(id)")
                        continue
                    }
                    if e.stops.count != 4 || e.locations.count != 4 {
                        fillFailures.append("\(id) stops \(e.stops.count)")
                    }
                    if e.wash.centerUnit != CGPoint(x: 0.22, y: 0.78)
                        || abs(e.wash.radiusDiagonalFactor - 0.85) > 0.001 {
                        fillFailures.append("\(id) wash geom")
                    }
                }
                let lavender = BackdropGradientCatalog.entry(id: "lavender")
                if lavender?.stops != ["#C6B5FC", "#A78BFA", "#6D48D7", "#3C2876"]
                    || lavender?.wash.color != "#F5F0FF"
                    || lavender?.wash.alpha != 0.18 {
                    fillFailures.append("lavender v2")
                }
                let inner = makeSolidImage(
                    width: 50, height: 40, color: NSColor.white.cgColor)
                let ocean = SliceBBackdrop.compose(
                    image: inner, style: .gradient("ocean"),
                    budgetBytes: SliceBExport.defaultBudgetBytes)
                let lavenderFrame = SliceBBackdrop.compose(
                    image: inner, style: .gradient("lavender"),
                    budgetBytes: SliceBExport.defaultBudgetBytes)
                if lavenderFrame == nil {
                    fillFailures.append("lavender compose")
                } else if let ocean, let lavenderFrame,
                          imagesEqual(ocean, lavenderFrame) {
                    fillFailures.append("lavender==ocean")
                }
                let red = SliceBBackdrop.compose(
                    image: inner, style: .solid("#EF4444"),
                    budgetBytes: SliceBExport.defaultBudgetBytes)
                if let red, !cornerIsMostly(red, rMin: 180, gMax: 130, bMax: 130) {
                    fillFailures.append("solid-red corner")
                } else if red == nil {
                    fillFailures.append("solid compose")
                }
                let fillDir = URL(fileURLWithPath: NSTemporaryDirectory())
                    .appendingPathComponent("snippr-wp2-fill")
                try? FileManager.default.createDirectory(
                    at: fillDir, withIntermediateDirectories: true)
                let redURL = fillDir.appendingPathComponent("red.png")
                let halfURL = fillDir.appendingPathComponent("half.png")
                if !writePNG(
                    makeSolidImage(
                        width: 10, height: 10,
                        color: NSColor(srgbRed: 1, green: 0, blue: 0, alpha: 1)
                            .cgColor),
                    to: redURL)
                {
                    fillFailures.append("write red png")
                }
                let half = makeLeftRightImage(
                    width: 80, height: 40,
                    left: NSColor.black.cgColor, right: NSColor.white.cgColor)
                if !writePNG(half, to: halfURL) {
                    fillFailures.append("write half png")
                }
                let fromFile = SliceBBackdrop.compose(
                    image: inner, style: .image(redURL.path),
                    budgetBytes: SliceBExport.defaultBudgetBytes)
                if let fromFile,
                   !cornerIsMostly(fromFile, rMin: 180, gMax: 80, bMax: 80) {
                    fillFailures.append("image-red corner")
                } else if fromFile == nil {
                    fillFailures.append("image compose")
                }
                let green = makeSolidImage(
                    width: 12, height: 12,
                    color: NSColor(srgbRed: 0, green: 1, blue: 0, alpha: 1)
                        .cgColor)
                let papered = BackdropFillOverride.scopedWallpaper(green) {
                    SliceBBackdrop.compose(
                        image: inner, style: .wallpaper(),
                        budgetBytes: SliceBExport.defaultBudgetBytes)
                }
                if let papered,
                   !cornerIsMostly(papered, rMax: 80, gMin: 180, bMax: 80) {
                    fillFailures.append("wallpaper-green corner")
                } else if papered == nil {
                    fillFailures.append("wallpaper compose")
                }
                let sharp = SliceBBackdrop.compose(
                    image: inner, style: .image(halfURL.path),
                    budgetBytes: SliceBExport.defaultBudgetBytes)
                var blurStyle = BackdropStyle.blurred(
                    source: .image, imagePath: halfURL.path)
                blurStyle.blurRadiusPt = 28
                let blurred = SliceBBackdrop.compose(
                    image: inner, style: blurStyle,
                    budgetBytes: SliceBExport.defaultBudgetBytes)
                if sharp == nil || blurred == nil {
                    fillFailures.append("blur compose")
                } else if let sharp, let blurred, imagesEqual(sharp, blurred) {
                    fillFailures.append("blur==sharp")
                }
                // Preview draws in POINTS (pixelScale 1, grain = layout.pixelScale);
                // export compose draws in PIXELS (pixelScale = image scale, grain = 1).
                // The two must yield the same visual radius: 28pt, i.e. 56px @2x.
                func blurRadiusViaDrawFrame(
                    pixelScale: CGFloat, documentPixelsPerUserUnit: CGFloat
                ) -> CGFloat {
                    let w = 80, h = 50
                    var bytes = [UInt8](repeating: 0, count: w * h * 4)
                    guard let c = CGContext(
                        data: &bytes, width: w, height: h,
                        bitsPerComponent: 8, bytesPerRow: w * 4,
                        space: CGColorSpace(name: CGColorSpace.sRGB)!,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                    else { return -1 }
                    SliceBBackdrop.resetLastBlurRadiusForTesting()
                    _ = SliceBBackdrop.drawFrame(
                        in: c,
                        size: CGSize(width: w, height: h),
                        target: CGRect(x: 10, y: 10, width: 60, height: 30),
                        style: blurStyle,
                        pixelScale: pixelScale,
                        documentPixelsPerUserUnit: documentPixelsPerUserUnit)
                    return SliceBBackdrop.lastBlurRadiusForTesting
                }
                let previewRadius = blurRadiusViaDrawFrame(
                    pixelScale: 1, documentPixelsPerUserUnit: 2)
                let exportRadius = blurRadiusViaDrawFrame(
                    pixelScale: 2, documentPixelsPerUserUnit: 1)
                if abs(previewRadius - 28) > 0.01
                    || abs(exportRadius - 56) > 0.01 {
                    fillFailures.append(
                        "blur radius preview \(previewRadius) export \(exportRadius)")
                }
                if SliceBBackdrop.extraFillBuffers(for: blurStyle) != 2 {
                    fillFailures.append(
                        "extraFillBuffers blurred \(SliceBBackdrop.extraFillBuffers(for: blurStyle))")
                }
                let kept = BackdropStyle.blurred(
                    source: .image, imagePath: "/tmp/x.png")
                if kept.imagePath != "/tmp/x.png" || kept.blurSource != .image {
                    fillFailures.append("blur imagePath clamped away")
                }
                if BackdropStyle.image("/tmp/x.png").imagePath == nil {
                    fillFailures.append("image path clamped")
                }
                let oceanReserve = SliceBBackdrop.reservedBytes(
                    forInnerWidth: 50, height: 40, style: .gradient("ocean"))
                let imageReserve = SliceBBackdrop.reservedBytes(
                    forInnerWidth: 50, height: 40, style: .image("/tmp/x.png"))
                let blurReserve = SliceBBackdrop.reservedBytes(
                    forInnerWidth: 50, height: 40, style: blurStyle)
                if oceanReserve == Int.max || imageReserve != oceanReserve * 2 {
                    fillFailures.append(
                        "reserve ocean \(oceanReserve) image \(imageReserve)")
                }
                if oceanReserve == Int.max || blurReserve != oceanReserve * 3 {
                    fillFailures.append(
                        "reserve blur \(blurReserve) ocean \(oceanReserve)")
                }
                // Small preview-size blur is worth caching. An export-size
                // dest (>16 MB) is used once and must not occupy a slot.
                SliceBBackdrop.resetBlurFillCacheForTesting()
                _ = blurRadiusViaDrawFrame(
                    pixelScale: 1, documentPixelsPerUserUnit: 1)
                if SliceBBackdrop.blurFillCacheCountForTesting != 1 {
                    fillFailures.append(
                        "small blur cache \(SliceBBackdrop.blurFillCacheCountForTesting)")
                }
                do {
                    let big = 2300
                    var bigStyle = blurStyle
                    bigStyle.blurRadiusPt = 1
                    var bigBytes = [UInt8](
                        repeating: 0, count: big * big * 4)
                    if let bigCtx = CGContext(
                        data: &bigBytes, width: big, height: big,
                        bitsPerComponent: 8, bytesPerRow: big * 4,
                        space: CGColorSpace(name: CGColorSpace.sRGB)!,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                    {
                        _ = SliceBBackdrop.drawFill(
                            in: bigCtx,
                            size: CGSize(width: big, height: big),
                            style: bigStyle)
                    }
                    if SliceBBackdrop.blurFillCacheCountForTesting != 1 {
                        fillFailures.append(
                            "export-size blur cached \(SliceBBackdrop.blurFillCacheCountForTesting)")
                    }
                }
                check("sliceB-backdrop-fills-wp2",
                      fillFailures.isEmpty,
                      fillFailures.prefix(8).joined(separator: " | "))
            }

            // WP3: alignment / ratio / inset / auto-balance. v0 geometry
            // (auto + cc + autoBalance + inset 0) must be byte-identical to
            // inner+2*pad; everything else redistributes extra space without
            // dropping an edge below the shadow floor.
            do {
                var geoFailures: [String] = []
                let ocean = BackdropStyle.from(preset: .ocean)
                // Long edge 1000 → pad 60, shadow floor 40, so alignment has
                // room to hug an edge. 200×100 would clamp pad to the floor
                // and make tl/br a no-op.
                let innerW = 1000, innerH = 500
                let scale: CGFloat = 1
                let pad = Int(SliceBBackdrop.padding(
                    forLongEdge: CGFloat(max(innerW, innerH)),
                    pixelScale: scale, style: ocean))
                let floor = Int(SliceBBackdrop.shadowExtent(
                    pixelScale: scale, offsetPt: ocean.shadowMetrics().offsetPt,
                    blurPt: ocean.shadowMetrics().blurPt))
                let v0 = BackdropLayout(
                    innerPixels: CGSize(width: CGFloat(innerW), height: CGFloat(innerH)),
                    pixelScale: scale, style: ocean)
                if Int(v0.outerPixelSize.width) != innerW + 2 * pad
                    || Int(v0.outerPixelSize.height) != innerH + 2 * pad
                    || Int(v0.padLeftPixels) != pad || Int(v0.padRightPixels) != pad
                    || Int(v0.padBottomPixels) != pad || Int(v0.padTopPixels) != pad
                    || Int(v0.insetPixels) != 0
                    || Int(v0.platePixelRect.minX) != pad
                    || Int(v0.platePixelRect.width) != innerW {
                    geoFailures.append(
                        "v0 \(Int(v0.outerPixelSize.width))x\(Int(v0.outerPixelSize.height)) "
                            + "pad \(Int(v0.padLeftPixels))")
                }
                let viaOuter = SliceBBackdrop.outerDimensions(
                    innerWidth: innerW, innerHeight: innerH, style: ocean,
                    pixelScale: scale)
                if viaOuter?.width != Int(v0.outerPixelSize.width)
                    || viaOuter?.height != Int(v0.outerPixelSize.height) {
                    geoFailures.append("outerDimensions drifted from layout")
                }

                func layout(_ mutate: (inout BackdropStyle) -> Void) -> BackdropLayout {
                    var s = ocean
                    mutate(&s)
                    return BackdropLayout(
                        innerPixels: CGSize(
                            width: CGFloat(innerW), height: CGFloat(innerH)),
                        pixelScale: scale, style: s)
                }

                let centered = layout { $0.autoBalance = true; $0.alignment = .tl }
                let alsoCentered = layout { $0.autoBalance = true; $0.alignment = .br }
                if centered.platePixelRect != alsoCentered.platePixelRect
                    || centered.platePixelRect != v0.platePixelRect {
                    geoFailures.append("autoBalance did not centre")
                }

                let hugTL = layout { $0.autoBalance = false; $0.alignment = .tl }
                let hugBR = layout { $0.autoBalance = false; $0.alignment = .br }
                if hugTL.platePixelRect.minX != CGFloat(floor)
                    || hugTL.padTopPixels != CGFloat(floor)
                    || hugBR.padRightPixels != CGFloat(floor)
                    || hugBR.padBottomPixels != CGFloat(floor)
                    || hugTL.outerPixelSize != v0.outerPixelSize
                    || hugTL.platePixelRect.origin == hugBR.platePixelRect.origin {
                    geoFailures.append(
                        "alignment tl \(hugTL.platePixelRect.origin) "
                            + "br \(hugBR.platePixelRect.origin)")
                }

                let square = layout { $0.ratio = .oneOne }
                if Int(square.outerPixelSize.width) != Int(square.outerPixelSize.height)
                    || Int(square.outerPixelSize.width) < innerW + 2 * pad {
                    geoFailures.append(
                        "1:1 \(Int(square.outerPixelSize.width))x"
                            + "\(Int(square.outerPixelSize.height))")
                }

                for ratio in BackdropRatio.allCases {
                    for align in BackdropAlignment.allCases {
                        for balanced in [true, false] {
                            let L = layout {
                                $0.ratio = ratio
                                $0.alignment = align
                                $0.autoBalance = balanced
                            }
                            let left = Int(L.padLeftPixels)
                            let right = Int(L.padRightPixels)
                            let bottom = Int(L.padBottomPixels)
                            let top = Int(L.padTopPixels)
                            let cW = Int(L.platePixelRect.width)
                            let cH = Int(L.platePixelRect.height)
                            let oW = Int(L.outerPixelSize.width)
                            let oH = Int(L.outerPixelSize.height)
                            if left < floor || right < floor
                                || bottom < floor || top < floor {
                                geoFailures.append(
                                    "floor \(ratio.rawValue)/\(align.rawValue)/b\(balanced)")
                            }
                            if left + cW + right != oW
                                || bottom + cH + top != oH
                                || cW != innerW || cH != innerH {
                                geoFailures.append(
                                    "sum \(ratio.rawValue)/\(align.rawValue)")
                            }
                            if let r = ratio.widthOverHeight, oH > 0 {
                                let got = Double(oW) / Double(oH)
                                if abs(got - Double(r)) > 0.02 {
                                    geoFailures.append(
                                        "ratio \(ratio.rawValue) \(got)")
                                }
                            }
                            if geoFailures.count > 12 { break }
                        }
                        if geoFailures.count > 12 { break }
                    }
                    if geoFailures.count > 12 { break }
                }

                var insetStyle = ocean
                insetStyle.insetFraction = 0.10
                let insetL = BackdropLayout(
                    innerPixels: CGSize(
                        width: CGFloat(innerW), height: CGFloat(innerH)),
                    pixelScale: scale, style: insetStyle)
                let wantInset = Int((0.10 * CGFloat(innerH)).rounded())
                if Int(insetL.insetPixels) != wantInset
                    || Int(insetL.platePixelRect.width) != innerW - 2 * wantInset
                    || Int(insetL.outerPixelSize.width) != innerW + 2 * pad {
                    geoFailures.append(
                        "inset \(Int(insetL.insetPixels)) "
                            + "plate \(Int(insetL.platePixelRect.width)) "
                            + "outer \(Int(insetL.outerPixelSize.width))")
                }

                // Source crop: a red strip on the left edge must not survive
                // in the plate after inset. The canvas keeps those pixels.
                if let strip = CGContext(
                    data: nil, width: innerW, height: innerH,
                    bitsPerComponent: 8, bytesPerRow: 0,
                    space: CGColorSpace(name: CGColorSpace.sRGB)!,
                    bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                {
                    strip.setFillColor(CGColor(srgbRed: 1, green: 1, blue: 1, alpha: 1))
                    strip.fill(CGRect(x: 0, y: 0, width: innerW, height: innerH))
                    strip.setFillColor(CGColor(srgbRed: 1, green: 0, blue: 0, alpha: 1))
                    strip.fill(CGRect(x: 0, y: 0, width: CGFloat(wantInset), height: CGFloat(innerH)))
                    if let src = strip.makeImage(),
                       let framed = SliceBBackdrop.compose(
                            image: src, style: insetStyle,
                            budgetBytes: SliceBExport.defaultBudgetBytes)
                    {
                        let plate = insetL.platePixelRect
                        var bytes = [UInt8](
                            repeating: 0, count: framed.width * framed.height * 4)
                        if let c = CGContext(
                            data: &bytes, width: framed.width, height: framed.height,
                            bitsPerComponent: 8, bytesPerRow: framed.width * 4,
                            space: CGColorSpace(name: CGColorSpace.sRGB)!,
                            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                        {
                            c.interpolationQuality = .none
                            c.draw(framed, in: CGRect(
                                x: 0, y: 0, width: framed.width, height: framed.height))
                            // CGImage origin is top-left; plate is y-up.
                            let x = Int(plate.minX) + 1
                            let yTop = framed.height - (Int(plate.minY) + 1) - 1
                            let i = (yTop * framed.width + x) * 4
                            if bytes[i] > 200 && bytes[i + 1] < 40 && bytes[i + 2] < 40 {
                                geoFailures.append("inset leaked source edge")
                            }
                            if framed.width != Int(insetL.outerPixelSize.width) {
                                geoFailures.append(
                                    "compose outer \(framed.width) layout "
                                        + "\(Int(insetL.outerPixelSize.width))")
                            }
                        }
                    } else {
                        geoFailures.append("inset compose nil")
                    }
                }

                let mapped = SliceBBackdrop.sourcePoint(
                    fromPadded: CGPoint(x: 90, y: 70), layout: v0)
                let expected = SliceBBackdrop.sourcePoint(
                    fromPadded: CGPoint(x: 90, y: 70), padding: v0.padPoints)
                if mapped != expected {
                    geoFailures.append("sourcePoint \(mapped) vs \(expected)")
                }

                check("sliceB-backdrop-geometry-wp3",
                      geoFailures.isEmpty,
                      geoFailures.prefix(8).joined(separator: " | "))
            }

            // 1a-2. A sidebar chip is a PREVIEW, so it is drawn by the one
            //       fill the canvas and the export use.
            //
            // Building a chip from `entry.stops` is the tempting shortcut and
            // it is wrong: `paintFill` ignores the catalog entirely for the
            // four v0 ids and paints the production ramp, so a hand-rolled
            // chip advertises a colour the canvas can never produce — the user
            // picks Ocean and gets a different Ocean. This compares the chip's
            // FRAME pixels against a reference drawn straight through
            // `drawFrame`, reading the chip's own geometry so the two cannot
            // drift apart.
            do {
                var swatchFailures: [String] = []
                let chipSize = BackdropSwatch.size
                let scale: CGFloat = 2
                let px = CGSize(
                    width: chipSize.width * scale, height: chipSize.height * scale)

                func pixels(_ image: CGImage) -> [UInt8]? {
                    let w = image.width, h = image.height
                    var bytes = [UInt8](repeating: 0, count: w * h * 4)
                    guard let c = CGContext(
                        data: &bytes, width: w, height: h, bitsPerComponent: 8,
                        bytesPerRow: w * 4,
                        space: CGColorSpace(name: CGColorSpace.sRGB)!,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                    else { return nil }
                    c.draw(image, in: CGRect(x: 0, y: 0, width: w, height: h))
                    return bytes
                }

                for id in BackdropGradientCatalog.ids {
                    let style = BackdropStyle.gradient(id)
                    guard let chip = BackdropSwatch.image(
                        for: style, size: chipSize, scale: scale),
                        let chipCG = chip.cgImage(
                            forProposedRect: nil, context: nil, hints: nil)
                    else {
                        swatchFailures.append("\(id):no-chip")
                        continue
                    }
                    guard let reference = CGContext(
                        data: nil, width: Int(px.width), height: Int(px.height),
                        bitsPerComponent: 8, bytesPerRow: 0,
                        space: CGColorSpace(name: CGColorSpace.sRGB)!,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                    else {
                        swatchFailures.append("\(id):no-context")
                        continue
                    }
                    // Production, with the chip's own geometry.
                    _ = SliceBBackdrop.drawFrame(
                        in: reference, size: px,
                        target: BackdropSwatch.frameTarget(
                            pixelSize: px, style: style),
                        style: style, pixelScale: scale,
                        documentPixelsPerUserUnit:
                            BackdropSwatch.documentPixelsPerUserUnit)
                    guard let refCG = reference.makeImage(),
                          let a = pixels(chipCG), let b = pixels(refCG),
                          a.count == b.count
                    else {
                        swatchFailures.append("\(id):no-pixels")
                        continue
                    }
                    // Only the frame is compared: the chip fills the plate with
                    // a stand-in document, which the reference leaves as fill.
                    let plate = BackdropSwatch.frameTarget(
                        pixelSize: px, style: style).insetBy(dx: -2, dy: -2)
                    let w = Int(px.width)
                    var checked = 0, differing = 0
                    for y in 0..<Int(px.height) {
                        for x in 0..<w where !plate.contains(
                            CGPoint(x: CGFloat(x), y: CGFloat(y))) {
                            let i = (y * w + x) * 4
                            checked += 1
                            // Exact: both went through the same function, in
                            // the same colour space, at the same scale.
                            if a[i] != b[i] || a[i + 1] != b[i + 1]
                                || a[i + 2] != b[i + 2] {
                                differing += 1
                            }
                        }
                    }
                    if checked < 200 {
                        swatchFailures.append("\(id):frame-too-small \(checked)")
                    }
                    if differing != 0 {
                        swatchFailures.append(
                            "\(id):not-production \(differing)/\(checked)")
                    }
                }
                // None removes the frame, so its chip must not paint one.
                if let noneChip = BackdropSwatch.image(
                    for: .none, size: chipSize, scale: scale),
                    let cg = noneChip.cgImage(
                        forProposedRect: nil, context: nil, hints: nil),
                    let bytes = pixels(cg) {
                    // Corner pixel: plain chrome, not a gradient.
                    if bytes[0] != bytes[1] || bytes[1] != bytes[2] {
                        swatchFailures.append("none:painted-a-frame")
                    }
                } else {
                    swatchFailures.append("none:no-chip")
                }
                check("sliceB-backdrop-swatch-uses-production-fill",
                      swatchFailures.isEmpty,
                      swatchFailures.prefix(6).joined(separator: " | "))
            }

            // 1a-3. The panel's own contract: what a control means, and when
            //       a drag is one edit rather than none or forty.
            do {
                var panelFailures: [String] = []
                var applied: [BackdropStyle] = []
                var groupsOpened = 0, groupsClosed = 0

                func makeModel(
                    _ start: BackdropStyle = .gradient("ocean")
                ) -> BackdropPanelModel {
                    applied.removeAll()
                    groupsOpened = 0
                    groupsClosed = 0
                    let m = BackdropPanelModel(style: start)
                    m.onApply = { style in
                        applied.append(style)
                        return true
                    }
                    m.onBeginContinuousEdit = { groupsOpened += 1 }
                    m.onEndContinuousEdit = { groupsClosed += 1 }
                    return m
                }

                // Picking a cell is a statement about where the shot sits, so
                // it turns auto-balance off — and does it in ONE apply, or the
                // user needs two undos to take back one click.
                let align = makeModel()
                if !align.style.autoBalance {
                    panelFailures.append("fixture-autobalance-off")
                }
                align.choose(alignment: .tl)
                if applied.count != 1 {
                    panelFailures.append("alignment-applies \(applied.count)")
                }
                if align.style.alignment != .tl || align.style.autoBalance {
                    panelFailures.append(
                        "alignment \(align.style.alignment) ab \(align.style.autoBalance)")
                }

                // Turning auto-balance back on KEEPS the anchor: the
                // compositor ignores it, and turning it off again must return
                // the shot where the user last put it, not to the centre.
                align.setAutoBalance(true)
                if !align.style.autoBalance || align.style.alignment != .tl {
                    panelFailures.append(
                        "autobalance-loses-anchor \(align.style.alignment)")
                }
                align.setAutoBalance(false)
                if align.style.alignment != .tl {
                    panelFailures.append("anchor-not-restored")
                }

                // A drag that changes nothing must leave NO undo group. An
                // empty group is one Cmd+Z that undoes nothing, which reads as
                // a lost undo.
                let empty = makeModel()
                empty.beginContinuousEdit()
                empty.endContinuousEdit()
                if groupsOpened != 0 || groupsClosed != 0 {
                    panelFailures.append(
                        "empty-drag-groups \(groupsOpened)/\(groupsClosed)")
                }

                // A drag that does change something is exactly ONE group,
                // however many steps it took.
                let dragged = makeModel()
                dragged.beginContinuousEdit()
                for step in 1...20 {
                    var next = dragged.style
                    next.paddingFraction = 0.02 + CGFloat(step) * 0.005
                    dragged.apply(next)
                }
                dragged.endContinuousEdit()
                if groupsOpened != 1 || groupsClosed != 1 {
                    panelFailures.append(
                        "drag-groups \(groupsOpened)/\(groupsClosed)")
                }
                if applied.count != 20 {
                    panelFailures.append("drag-applies \(applied.count)")
                }

                // The chip cache key carries the style's continuous fields, so
                // a drag mints a new chip per step. It must not grow forever.
                BackdropSwatch.resetCache()
                for step in 0..<200 {
                    var style = BackdropStyle.gradient("ocean")
                    style.paddingFraction = 0.02 + CGFloat(step) * 0.0005
                    _ = BackdropSwatch.image(for: style)
                }
                if BackdropSwatch.cacheCountForTesting > 96 {
                    panelFailures.append(
                        "cache-unbounded \(BackdropSwatch.cacheCountForTesting)")
                }
                BackdropSwatch.resetCache()
                if BackdropSwatch.cacheCountForTesting != 0 {
                    panelFailures.append("cache-not-cleared")
                }

                // The geometry group is only shown once a compositor reads it.
                if !BackdropPanelFeature.geometryEnabled {
                    panelFailures.append("geometry-hidden-after-wp3")
                }
                // 1.2.13 was 236pt — 24pt short of four chips — and ate the
                // first letter of Inset/Alignment/Ratio. Slack must stay
                // positive so a couple of points of safe-area cannot clip.
                if BackdropPanelView.width < 260
                    || BackdropPanelView.layoutSlack < 2 {
                    panelFailures.append(
                        "clip-risk w=\(BackdropPanelView.width) "
                            + "slack=\(BackdropPanelView.layoutSlack)")
                }
                check("sliceB-backdrop-panel-contract",
                      panelFailures.isEmpty,
                      panelFailures.prefix(8).joined(separator: " | "))
            }

            // 1a-4. WP7 presets and auto-apply.
            //
            // A preset is a NAMED BackdropStyle, so it cannot describe a
            // backdrop the app is unable to draw. Auto-apply reaches the
            // editor as document state and copy/save as composed pixels, and
            // the two must read the SAME style or a capture is framed on one
            // route and bare on the other.
            do {
                var presetFailures: [String] = []
                // The gate writes real defaults, so it restores them.
                let savedBlob = Settings.shared.backdropPresetData
                let savedEnabled = Settings.shared.backdropAutoApplyEnabled
                let savedChoice = Settings.shared.backdropAutoApplyPreset
                defer {
                    Settings.shared.backdropPresetData = savedBlob
                    Settings.shared.backdropAutoApplyEnabled = savedEnabled
                    Settings.shared.backdropAutoApplyPreset = savedChoice
                }
                BackdropPresetStore.removeAllForTesting()

                var lagoon = BackdropStyle.gradient("lagoon")
                lagoon.paddingFraction = 0.11
                lagoon.shadowStrength = 0.5
                if BackdropPresetStore.add(name: "  Studio  ", style: lagoon) == nil {
                    presetFailures.append("add-refused")
                }
                // Whitespace is trimmed on the way in, or "Studio" and
                // "Studio " would be two presets a user cannot tell apart.
                if BackdropPresetStore.load().first?.name != "Studio" {
                    presetFailures.append(
                        "name \(BackdropPresetStore.load().first?.name ?? "nil")")
                }
                // Round-trip: every field, not just the fill.
                if BackdropPresetStore.style(named: "studio") != lagoon.clamped() {
                    presetFailures.append("roundtrip")
                }
                // A duplicate name is REFUSED, not silently renamed or made to
                // overwrite the preset the user already has.
                if BackdropPresetStore.add(name: "STUDIO", style: .gradient("ocean")) != nil
                    || BackdropPresetStore.load().count != 1 {
                    presetFailures.append("duplicate-accepted")
                }
                if BackdropPresetStore.add(name: "   ", style: lagoon) != nil {
                    presetFailures.append("blank-accepted")
                }

                // Auto-apply is stored by NAME, so a rename has to follow it or
                // it would quietly stop applying anything.
                Settings.shared.backdropAutoApplyEnabled = true
                Settings.shared.backdropAutoApplyPreset = "Studio"
                if BackdropPresetStore.rename(from: "Studio", to: "Studio Warm") == nil {
                    presetFailures.append("rename-refused")
                }
                if Settings.shared.backdropAutoApplyPreset != "Studio Warm" {
                    presetFailures.append(
                        "rename-orphans-autoapply "
                        + (Settings.shared.backdropAutoApplyPreset ?? "nil"))
                }
                if BackdropPresetStore.autoApplyStyle != lagoon.clamped() {
                    presetFailures.append("autoapply-style")
                }
                // Off means off, whatever is selected.
                Settings.shared.backdropAutoApplyEnabled = false
                if BackdropPresetStore.autoApplyStyle != nil {
                    presetFailures.append("autoapply-ignores-toggle")
                }
                Settings.shared.backdropAutoApplyEnabled = true

                // Deleting the preset every capture used turns auto-apply OFF
                // rather than leaving it pointing at nothing.
                if BackdropPresetStore.remove(name: "studio warm") == nil {
                    presetFailures.append("remove-refused")
                }
                if Settings.shared.backdropAutoApplyPreset != nil
                    || BackdropPresetStore.autoApplyStyle != nil {
                    presetFailures.append("delete-leaves-dangling-autoapply")
                }
                if !BackdropPresetStore.load().isEmpty {
                    presetFailures.append("remove-left-entries")
                }

                // The editor route: document state, NOT baked pixels. The user
                // must still be able to drop the frame after the shot.
                let shot = CapturedImage(
                    cgImage: SelfTest.makeTestImage(width: 200, height: 160),
                    scale: 1)
                let framedEditor = EditorWindowController.open(
                    with: shot, backdrop: lagoon, forceFitForTesting: true)
                let editorCanvas = framedEditor.canvasForTesting
                if editorCanvas.backdropStyleForTesting.gradientId != "lagoon"
                    || editorCanvas.backdropStyleForTesting.paddingFraction != 0.11 {
                    presetFailures.append(
                        "editor-style \(editorCanvas.backdropStyleForTesting.gradientId ?? "nil")")
                }
                if editorCanvas.image.cgImage.width != 200 {
                    presetFailures.append(
                        "editor-baked \(editorCanvas.image.cgImage.width)")
                }
                // And it is undoable/removable like any other backdrop.
                if !editorCanvas.applyBackdropStyle(.none)
                    || editorCanvas.backdropStyleForTesting.kind != .none {
                    presetFailures.append("editor-frame-stuck")
                }
                // An editor opened WITHOUT a backdrop stays bare even with
                // auto-apply on: a gate or a file must not inherit the user's
                // hotkey setting.
                let bare = EditorWindowController.open(
                    with: shot, forceFitForTesting: true)
                if bare.canvasForTesting.backdropStyleForTesting.kind != .none {
                    presetFailures.append("bare-editor-inherited")
                }

                // The copy/save route: composed pixels, same style, and the
                // outer size the ONE geometry source predicts.
                if let composed = AppDelegate.compose(shot, backdrop: lagoon) {
                    let layout = BackdropLayout(
                        innerPixels: CGSize(width: 200, height: 160),
                        pixelScale: 1, style: lagoon.clamped())
                    if composed.cgImage.width != Int(layout.outerPixelSize.width)
                        || composed.cgImage.height
                            != Int(layout.outerPixelSize.height) {
                        presetFailures.append(
                            "composed \(composed.cgImage.width)x\(composed.cgImage.height) "
                            + "want \(Int(layout.outerPixelSize.width))x\(Int(layout.outerPixelSize.height))")
                    }
                } else {
                    presetFailures.append("compose-nil")
                }
                // Fails CLOSED: a frame the budget cannot afford costs the
                // frame, never the screenshot.
                let huge = CapturedImage(
                    cgImage: SelfTest.makeTestImage(width: 40, height: 40), scale: 1)
                let refused = ForcedOuterComposeFailure.scoped {
                    AppDelegate.compose(huge, backdrop: lagoon)
                }
                if refused != nil {
                    presetFailures.append("compose-not-fail-closed")
                }
                // `.none` is the identity, not a compose.
                if AppDelegate.compose(shot, backdrop: .none)?.cgImage.width != 200 {
                    presetFailures.append("none-composed")
                }
                check("sliceB-backdrop-presets-autoapply",
                      presetFailures.isEmpty,
                      presetFailures.prefix(8).joined(separator: " | "))
            }

            // 1a-5. The branch that CHOOSES editor-as-state vs copy/save-as-
            //       pixels. The two halves are gated above; this is the
            //       missing middle. It is a pure plan — compose is injected
            //       so the gate never touches the clipboard or the disk.
            //
            // Copy/save/rescue do NOT depend on afterShow (the WP7 bug
            // was `!afterShow` skipping the bake when the editor opened).
            // Editor-only does not compose: a capture nobody will export
            // must not pay for a frame.
            //
            // Intended mutation: `needsPixels = !afterShow` (the old guard)
            // → `copy-show-left-bare`.
            do {
                var routeFailures: [String] = []
                let shot = CapturedImage(
                    cgImage: SelfTest.makeTestImage(width: 200, height: 160),
                    scale: 1)
                var lagoon = BackdropStyle.gradient("lagoon")
                lagoon.paddingFraction = 0.11
                var composeCalls = 0
                func bake(
                    _ image: CapturedImage, _ style: BackdropStyle
                ) -> CapturedImage? {
                    composeCalls += 1
                    return AppDelegate.compose(image, backdrop: style)
                }
                func plan(
                    show: Bool, copy: Bool = false, save: Bool = false,
                    style: BackdropStyle?,
                    compose: (CapturedImage, BackdropStyle) -> CapturedImage?
                        = bake
                ) -> BackdropAutoApply.Plan {
                    BackdropAutoApply.plan(
                        image: shot, afterShow: show, afterCopy: copy,
                        afterSave: save, style: style, compose: compose)
                }
                let layout = BackdropLayout(
                    innerPixels: CGSize(width: 200, height: 160),
                    pixelScale: 1, style: lagoon.clamped())
                func isComposed(_ image: CapturedImage) -> Bool {
                    image.cgImage !== shot.cgImage
                        && image.cgImage.width == Int(layout.outerPixelSize.width)
                        && image.cgImage.height == Int(layout.outerPixelSize.height)
                }

                // Editor-only + style: document state, no bake.
                composeCalls = 0
                let shown = plan(show: true, style: lagoon)
                if composeCalls != 0 {
                    routeFailures.append("editor-only-composed \(composeCalls)")
                }
                if shown.exportImage.cgImage !== shot.cgImage {
                    routeFailures.append("editor-only-baked")
                }
                if case .editor(let style) = shown.destination {
                    if style != lagoon {
                        routeFailures.append(
                            "editor-style \(style?.gradientId ?? "nil")")
                    }
                } else {
                    routeFailures.append("editor-not-document")
                }

                // Copy WHILE the editor opens: clipboard is composed, editor
                // is still document state. This is the WP7 bug if export
                // stays the original.
                composeCalls = 0
                let copyShow = plan(show: true, copy: true, style: lagoon)
                if composeCalls != 1 {
                    routeFailures.append("copy-show-calls \(composeCalls)")
                }
                if !isComposed(copyShow.exportImage) {
                    routeFailures.append("copy-show-left-bare")
                }
                if case .editor(let style) = copyShow.destination {
                    if style != lagoon {
                        routeFailures.append("copy-show-lost-style")
                    }
                } else {
                    routeFailures.append("copy-show-no-editor")
                }

                // Save WHILE the editor opens: file is composed, editor
                // is still document state. Same WP7 bug on the save
                // route — Honey's A3.
                composeCalls = 0
                let saveShow = plan(show: true, save: true, style: lagoon)
                if composeCalls != 1 {
                    routeFailures.append("save-show-calls \(composeCalls)")
                }
                if !isComposed(saveShow.exportImage) {
                    routeFailures.append("save-show-left-bare")
                }
                if case .editor(let style) = saveShow.destination {
                    if style != lagoon {
                        routeFailures.append("save-show-lost-style")
                    }
                } else {
                    routeFailures.append("save-show-no-editor")
                }

                // Save-only + style: compose once, no editor. Honey A4.
                composeCalls = 0
                let saveOnly = plan(show: false, save: true, style: lagoon)
                if composeCalls != 1 {
                    routeFailures.append("save-only-calls \(composeCalls)")
                }
                if saveOnly.opensEditor {
                    routeFailures.append("save-only-opens-editor")
                }
                if !isComposed(saveOnly.exportImage) {
                    routeFailures.append("save-only-left-bare")
                }

                // Copy AND save, with editor: one bake, one bitmap.
                composeCalls = 0
                let both = plan(
                    show: true, copy: true, save: true, style: lagoon)
                if composeCalls != 1 {
                    routeFailures.append("copy-save-calls \(composeCalls)")
                }
                if !isComposed(both.exportImage) {
                    routeFailures.append("copy-save-left-bare")
                }
                if !both.opensEditor {
                    routeFailures.append("copy-save-no-editor")
                }

                // Copy-only + style: compose once, no editor.
                composeCalls = 0
                let baked = plan(show: false, copy: true, style: lagoon)
                if composeCalls != 1 {
                    routeFailures.append("bake-calls \(composeCalls)")
                }
                if baked.opensEditor {
                    routeFailures.append("bake-opens-editor")
                }
                if !isComposed(baked.exportImage) {
                    routeFailures.append("bake-left-bare")
                }

                // Rescue copy (nothing configured) still bakes.
                composeCalls = 0
                let rescue = plan(show: false, style: lagoon)
                if composeCalls != 1 {
                    routeFailures.append("rescue-calls \(composeCalls)")
                }
                if rescue.opensEditor {
                    routeFailures.append("rescue-opens-editor")
                }
                if !isComposed(rescue.exportImage) {
                    routeFailures.append("rescue-left-bare")
                }

                // Compose refuses: keep the shot, copy+show still opens editor.
                let refused = plan(
                    show: true, copy: true, style: lagoon,
                    compose: { _, _ in nil })
                if refused.exportImage.cgImage !== shot.cgImage {
                    routeFailures.append("fail-closed-lost-shot")
                }
                if !refused.opensEditor {
                    routeFailures.append("fail-closed-drops-editor")
                }

                // Editor with no style stays bare, and does not compose.
                composeCalls = 0
                let bareEditor = plan(show: true, style: nil)
                if composeCalls != 0 {
                    routeFailures.append("bare-editor-composed")
                }
                if case .editor(let style) = bareEditor.destination {
                    if style != nil {
                        routeFailures.append("bare-editor-got-style")
                    }
                } else {
                    routeFailures.append("bare-editor-not-opened")
                }

                // Copy with no style: original, no compose, no editor.
                composeCalls = 0
                let bareExport = plan(show: false, copy: true, style: nil)
                if composeCalls != 0 {
                    routeFailures.append("none-composed")
                }
                if bareExport.exportImage.cgImage !== shot.cgImage {
                    routeFailures.append("none-baked")
                }
                if bareExport.opensEditor {
                    routeFailures.append("none-opens-editor")
                }

                // `.none` is the identity, not a bake — even on the export
                // route. `autoApplyStyle` already filters this; plan must
                // too, or a caller that skipped the store would still bake.
                composeCalls = 0
                let identity = plan(
                    show: false, copy: true, style: BackdropStyle.none)
                if composeCalls != 0 {
                    routeFailures.append("kind-none-composed")
                }
                if identity.exportImage.cgImage !== shot.cgImage {
                    routeFailures.append("kind-none-baked")
                }

                check("sliceB-backdrop-autoapply-route",
                      routeFailures.isEmpty,
                      routeFailures.prefix(8).joined(separator: " | "))
            }

            // 1a-6. Overlay mini (WP4b). Smaller than the WP4a mockup, ten
            //       thumbs plus None, padding S/M/L, and a placement solver
            //       that will not sit on the crop when any other frame fits.
            //
            // Intended mutation: OverlayToolbarLayout.popover, drop the
            // `avoidPenalty * 1_000_000` term → covering-selection.
            do {
                var miniFails: [String] = []
                let spec = OverlayQuickBackdrop.self
                if spec.size.width >= spec.mockupSize.width {
                    miniFails.append("not-narrower \(spec.size.width)")
                }
                if spec.size.height >= spec.mockupSize.height {
                    miniFails.append("not-shorter \(spec.size.height)")
                }
                if spec.chipSize.width >= spec.mockupChipSize.width
                    || spec.chipSize.height >= spec.mockupChipSize.height {
                    miniFails.append("chip \(spec.chipSize)")
                }
                if spec.gradientIds.count != 10 {
                    miniFails.append("thumbs \(spec.gradientIds.count)")
                }
                if spec.gradientIds.contains("ember")
                    || spec.gradientIds.contains("meadow") {
                    miniFails.append("full-catalog-on-overlay")
                }
                let wantIds = [
                    "ocean", "sunset", "mint", "graphite",
                    "lavender", "rose", "lagoon", "midnight",
                    "paper", "fog",
                ]
                if spec.gradientIds != wantIds {
                    miniFails.append("ids \(spec.gradientIds)")
                }
                let pads = spec.paddingTicks.map(\.fraction)
                if pads != [0.04, 0.06, 0.10] {
                    miniFails.append("padding \(pads)")
                }

                // Pure geometry: a centre crop with the button on its right
                // must place the mini to the right of the button, not on the
                // shot. A crop against the right edge must flip.
                let bounds = CGRect(x: 0, y: 0, width: 1200, height: 800)
                let centre = CGRect(x: 400, y: 250, width: 320, height: 240)
                let rightAnchor = CGRect(
                    x: centre.maxX + 10, y: centre.midY - 15,
                    width: 34, height: 30)
                if let placed = OverlayToolbarLayout.popover(
                    size: spec.size, anchor: rightAnchor, avoid: centre,
                    bounds: bounds)
                {
                    if placed.frame.intersects(centre) {
                        miniFails.append("covering-selection \(placed.frame)")
                    }
                    if !bounds.insetBy(dx: 10, dy: 10).contains(placed.frame) {
                        miniFails.append("outside-bounds \(placed.frame)")
                    }
                } else {
                    miniFails.append("no-centre-placement")
                }

                let edge = CGRect(
                    x: bounds.maxX - 220, y: 300, width: 200, height: 180)
                let edgeAnchor = CGRect(
                    x: edge.minX - 44, y: edge.midY - 15,
                    width: 34, height: 30)
                if let placed = OverlayToolbarLayout.popover(
                    size: spec.size, anchor: edgeAnchor, avoid: edge,
                    bounds: bounds)
                {
                    if placed.frame.intersects(edge) {
                        miniFails.append("edge-covering \(placed.frame)")
                    }
                    if placed.placement == .right
                        && placed.frame.minX >= edgeAnchor.midX {
                        miniFails.append("did-not-flip \(placed.placement)")
                    }
                } else {
                    miniFails.append("no-edge-placement")
                }

                if let screen = NSScreen.main ?? NSScreen.screens.first {
                    @MainActor final class MiniSpy {
                        var editors: [CGSize] = []
                        var lastCaptures: [CGSize] = []
                        func dependencies() -> CaptureActionRouter.Dependencies {
                            CaptureActionRouter.Dependencies(
                                copyToClipboard: { _ in },
                                autoSave: { _, _ in }, saveAs: { _, _ in },
                                pin: { _ in },
                                ocrWithMode: { _, _ in },
                                openEditor: { [self] in
                                    editors.append(CGSize(
                                        width: $0.image.cgImage.width,
                                        height: $0.image.cgImage.height))
                                },
                                toast: { _ in },
                                setLastCapture: { [self] in
                                    lastCaptures.append(CGSize(
                                        width: $0.cgImage.width,
                                        height: $0.cgImage.height))
                                },
                                setLastAreaRect: { _ in },
                                logEvent: { _ in })
                        }
                    }
                    let spy = MiniSpy()
                    let overlay = SelectionOverlay(
                        purpose: .areaReview,
                        inputs: OverlaySessionInputs(
                            afterShow: true, afterCopy: false,
                            afterSave: false),
                        completion: { _ in })
                    overlay.routerDependenciesOverride = spy.dependencies()
                    let view = SelectionOverlayView(
                        mode: .area, screen: screen,
                        frozen: CapturedImage(
                            cgImage: makeStripePattern(
                                width: Int(screen.frame.width),
                                height: Int(screen.frame.height),
                                seed: 0x0824_2026),
                            scale: 1),
                        windowList: [], owner: overlay)
                    // Long edge must beat the 40 px padding floor or S/M/L
                    // all render as the same outer size (320 × 0.06 rounds
                    // to 19 and is lifted to 40, same as 0.10).
                    let selection = CGRect(
                        x: 80, y: 80, width: 720, height: 480)
                    view.selectForTesting(rect: selection)
                    view.showBackdropMiniForTesting()
                    if !view.backdropMiniIsShownForTesting {
                        miniFails.append("mini-not-shown")
                    }
                    if let frame = view.backdropMiniFrameForTesting {
                        if frame.intersects(selection) {
                            miniFails.append("host-covering \(frame)")
                        }
                        if abs(frame.width - spec.size.width) > 0.5
                            || abs(frame.height - spec.size.height) > 0.5 {
                            miniFails.append("host-size \(frame.size)")
                        }
                    } else {
                        miniFails.append("no-host-frame")
                    }
                    for id in spec.gradientIds {
                        if view.backdropMiniControlForTesting(
                            OverlayBackdropMiniIdentifier.gradient(id)) == nil {
                            miniFails.append("missing-\(id)")
                        }
                    }
                    if view.backdropMiniControlForTesting(
                        OverlayBackdropMiniIdentifier.gradient("ember")) != nil
                        || view.backdropMiniControlForTesting(
                            OverlayBackdropMiniIdentifier.gradient("meadow")) != nil {
                        miniFails.append("ember-or-meadow-present")
                    }
                    if view.backdropMiniControlForTesting(
                        OverlayBackdropMiniIdentifier.none) == nil {
                        miniFails.append("missing-none")
                    }

                    // Drive the REAL chip, not applyBackdropStyle: the
                    // identifier is the wiring the user clicks.
                    view.backdropMiniControlForTesting(
                        OverlayBackdropMiniIdentifier.gradient("lavender"))
                        .map { $0.performClick(nil) }
                    let afterLav = view.annotationSurface?.backdropStyle
                    if afterLav?.kind != .gradient
                        || afterLav?.gradientId != "lavender" {
                        miniFails.append(
                            "lavender \(String(describing: afterLav?.gradientId))")
                    }
                    // v0 view must NOT pretend lavender is Ocean.
                    if view.annotationSurface?.backdropPreset != BackdropPreset.none {
                        miniFails.append(
                            "lavender-as-preset \(String(describing: view.annotationSurface?.backdropPreset))")
                    }
                    let inner = overlay.session.pixelRect.size
                    let lavLayout = BackdropLayout(
                        innerPixels: inner, pixelScale: 1,
                        style: afterLav ?? .none)
                    if let outer = view.backdropPreviewOuterRectForTesting {
                        if abs(outer.width - lavLayout.outerPointSize.width) > 0.5
                            || abs(outer.height
                                - lavLayout.outerPointSize.height) > 0.5 {
                            miniFails.append(
                                "preview \(outer.size) vs \(lavLayout.outerPointSize)")
                        }
                    } else {
                        miniFails.append("no-lavender-preview")
                    }

                    view.backdropMiniControlForTesting(
                        OverlayBackdropMiniIdentifier.paddingL)
                        .map { $0.performClick(nil) }
                    let afterPad = view.annotationSurface?.backdropStyle
                    if abs((afterPad?.paddingFraction ?? 0) - 0.10) > 0.0001 {
                        miniFails.append(
                            "padding \(String(describing: afterPad?.paddingFraction))")
                    }
                    if afterPad?.gradientId != "lavender" {
                        miniFails.append("padding-dropped-fill")
                    }
                    let padLayout = BackdropLayout(
                        innerPixels: inner, pixelScale: 1,
                        style: afterPad ?? .none)
                    let padM = SliceBBackdrop.padding(
                        forLongEdge: 2000, pixelScale: 1,
                        style: afterLav ?? .none)
                    let padL = SliceBBackdrop.padding(
                        forLongEdge: 2000, pixelScale: 1,
                        style: afterPad ?? .none)
                    if padL <= padM {
                        miniFails.append("padding-did-nothing \(padM)/\(padL)")
                    }

                    // Same chip again is not an edit.
                    let countBefore = view.annotationSurface?.annotations.count
                    view.backdropMiniControlForTesting(
                        OverlayBackdropMiniIdentifier.paddingL)
                        .map { $0.performClick(nil) }
                    if view.annotationSurface?.annotations.count != countBefore {
                        miniFails.append("same-padding-forked")
                    }

                    if let mini = view.backdropMiniViewForTesting {
                        let rect = view.convert(
                            mini.openEditorButtonFrame, from: mini)
                        let p = CGPoint(x: rect.midX, y: rect.midY)
                        if view.areaCursor(at: p) != .pointingHand {
                            miniFails.append(
                                "open-editor-cursor \(String(describing: view.areaCursor(at: p)))")
                        }
                    } else {
                        miniFails.append("mini-view-missing")
                    }
                    let remembered = Settings.shared.backdropLastStyle
                    if remembered?.gradientId != "lavender"
                        || abs((remembered?.paddingFraction ?? 0) - 0.10) > 0.0001 {
                        miniFails.append(
                            "last-used \(String(describing: remembered?.gradientId))")
                    }
                    view.openBackdropEditorForTesting()
                    if spy.editors.count != 1 {
                        miniFails.append("editor-calls \(spy.editors.count)")
                    }
                    if spy.editors.last != inner {
                        miniFails.append(
                            "editor-baked \(String(describing: spy.editors.last))")
                    }
                    if spy.lastCaptures.last != padLayout.outerPointSize {
                        miniFails.append(
                            "lastCapture \(String(describing: spy.lastCaptures.last)) want \(padLayout.outerPointSize)")
                    }
                    overlay.dismissForTesting()
                } else {
                    miniFails.append("no-screen")
                }

                check("sliceB-backdrop-overlay-mini",
                      miniFails.isEmpty,
                      miniFails.prefix(8).joined(separator: " | "))
            }

            // Last-used is a VIEW of the default, not a frame. Opening the
            // editor with the sidebar already open (overlay "Open in Editor…")
            // must show it AND still require a click to apply.
            do {
                var lastFails: [String] = []
                var last = BackdropStyle.gradient("mint")
                last.paddingFraction = 0.08
                Settings.shared.rememberBackdropStyle(last)
                let wc = EditorWindowController.open(
                    with: CapturedImage(
                        cgImage: makeSolidImage(
                            width: 160, height: 120,
                            color: NSColor.gray.cgColor),
                        scale: 1),
                    forceFitForTesting: true,
                    openBackdropPanel: true)
                if !wc.isBackdropPanelOpen {
                    lastFails.append("panel-closed")
                }
                if wc.canvasForTesting.backdropStyleForTesting.kind != .none {
                    lastFails.append("document-framed")
                }
                let panel = wc.backdropPanelModel
                if panel?.style.gradientId != "mint"
                    || panel?.isPreselected != true {
                    lastFails.append(
                        "preselect \(String(describing: panel?.style.gradientId)) "
                            + "pre \(String(describing: panel?.isPreselected))")
                }
                panel?.choose(gradientId: "mint")
                if wc.canvasForTesting.backdropStyleForTesting.gradientId != "mint"
                    || panel?.isPreselected != false {
                    lastFails.append("click-did-not-apply")
                }
                wc.close()
                UserDefaults.standard.removeObject(
                    forKey: Settings.Keys.backdropLastStyle)
                check("sliceB-backdrop-last-used-preselect",
                      lastFails.isEmpty,
                      lastFails.joined(separator: " | "))
            }

            // 1b-2. The fill paints INSIDE the canvas and nowhere else.
            //
            // Every primitive the fill uses covers the current clip rather
            // than a rect: a gradient is unbounded and `byTiling` replicates
            // until something stops it. In a bitmap the buffer edge stopped
            // them, so compose looked correct — but the editor draws into the
            // window's context, where a view has not clipped to its bounds by
            // default since macOS 14, and the backdrop ran across the whole
            // scroll view. At fit zoom the window edge hid it; at 4% on a tall
            // scrolling capture the owner saw a diagonal band over everything.
            do {
                var bleedFailures: [String] = []
                let sentinel: UInt8 = 77
                let canvasSize = CGSize(width: 120, height: 90)
                /// Draws into a context THREE times the canvas, with the
                /// canvas placed in the middle, and reports every pixel
                /// outside the canvas that moved off the sentinel colour.
                func bledOutside(
                    _ label: String,
                    _ body: (CGContext, CGSize) -> Void
                ) {
                    let w = Int(canvasSize.width) * 3
                    let h = Int(canvasSize.height) * 3
                    var bytes = [UInt8](repeating: 0, count: w * h * 4)
                    guard let c = CGContext(
                        data: &bytes, width: w, height: h,
                        bitsPerComponent: 8, bytesPerRow: w * 4,
                        space: CGColorSpace(name: CGColorSpace.sRGB)!,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                    else {
                        bleedFailures.append("\(label):no-context")
                        return
                    }
                    c.setFillColor(CGColor(
                        srgbRed: CGFloat(sentinel) / 255,
                        green: CGFloat(sentinel) / 255,
                        blue: CGFloat(sentinel) / 255, alpha: 1))
                    c.fill(CGRect(x: 0, y: 0, width: w, height: h))
                    c.saveGState()
                    // The canvas origin is NOT the context origin: a fill that
                    // clipped to its own bounds in device space rather than in
                    // user space would pass a centred test and still bleed.
                    c.translateBy(x: canvasSize.width, y: canvasSize.height)
                    body(c, canvasSize)
                    c.restoreGState()
                    let inside = CGRect(
                        origin: CGPoint(
                            x: canvasSize.width, y: canvasSize.height),
                        size: canvasSize)
                    var strays = 0
                    var firstStray = ""
                    for y in 0..<h {
                        for x in 0..<w
                        where !inside.contains(
                            CGPoint(x: CGFloat(x) + 0.5, y: CGFloat(y) + 0.5)) {
                            let i = (y * w + x) * 4
                            if bytes[i] != sentinel || bytes[i + 1] != sentinel
                                || bytes[i + 2] != sentinel {
                                strays += 1
                                if firstStray.isEmpty {
                                    firstStray = "@\(x),\(y)="
                                        + "\(bytes[i]),\(bytes[i + 1]),"
                                        + "\(bytes[i + 2])"
                                }
                            }
                        }
                    }
                    if strays > 0 {
                        bleedFailures.append(
                            "\(label):\(strays)px \(firstStray)")
                    }
                    // Positive premise: the canvas itself HAS been painted, so
                    // a fill that drew nothing at all cannot pass this gate.
                    let centre = ((h / 2) * w + w / 2) * 4
                    if bytes[centre] == sentinel
                        && bytes[centre + 1] == sentinel
                        && bytes[centre + 2] == sentinel {
                        bleedFailures.append("\(label):painted-nothing")
                    }
                }
                for preset in BackdropPreset.allCases where preset != .none {
                    bledOutside("fill-\(preset.rawValue)") { c, size in
                        SliceBBackdrop.drawFill(
                            in: c, size: size, preset: preset)
                    }
                    bledOutside("frame-\(preset.rawValue)") { c, size in
                        SliceBBackdrop.drawFrame(
                            in: c, size: size,
                            target: CGRect(
                                x: 20, y: 20,
                                width: size.width - 40,
                                height: size.height - 40),
                            preset: preset, pixelScale: 1)
                    }
                }
                // The editor route the owner actually saw: a very tall
                // scrolling capture at 4%, drawn through the production
                // override into a context that does NOT bound it.
                MainActor.assumeIsolated {
                    let tall = makeStripePattern(
                        width: 1433, height: 6469, seed: 0x1208_2026)
                    let wc = EditorWindowController.open(
                        with: CapturedImage(cgImage: tall, scale: 1),
                        forceFitForTesting: true)
                    let canvas = wc.canvasForTesting
                    _ = canvas.applyBackdrop(.mint)
                    canvas.enclosingScrollView?.magnification = 0.04
                    guard let wrapper = wc.documentWrapperForTesting else {
                        bleedFailures.append("editor:no-wrapper")
                        wc.window?.close()
                        return
                    }
                    if !wrapper.clipsToBounds {
                        bleedFailures.append("editor:wrapper-unclipped")
                    }
                    let bounds = wrapper.bounds
                    let margin: CGFloat = 40
                    let w = Int(bounds.width + margin * 2)
                    let h = Int(bounds.height + margin * 2)
                    var bytes = [UInt8](repeating: 0, count: w * h * 4)
                    guard w > 0, h > 0, let c = CGContext(
                        data: &bytes, width: w, height: h,
                        bitsPerComponent: 8, bytesPerRow: w * 4,
                        space: CGColorSpace(name: CGColorSpace.sRGB)!,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                    else {
                        bleedFailures.append("editor:no-context")
                        wc.window?.close()
                        return
                    }
                    c.setFillColor(CGColor(
                        srgbRed: CGFloat(sentinel) / 255,
                        green: CGFloat(sentinel) / 255,
                        blue: CGFloat(sentinel) / 255, alpha: 1))
                    c.fill(CGRect(x: 0, y: 0, width: w, height: h))
                    c.translateBy(x: margin, y: margin)
                    let graphics = NSGraphicsContext(
                        cgContext: c, flipped: false)
                    NSGraphicsContext.saveGraphicsState()
                    NSGraphicsContext.current = graphics
                    wrapper.draw(bounds)
                    NSGraphicsContext.restoreGraphicsState()
                    var editorStrays = 0
                    for y in 0..<h {
                        for x in 0..<w
                        where CGFloat(x) < margin || CGFloat(y) < margin
                            || CGFloat(x) >= margin + bounds.width
                            || CGFloat(y) >= margin + bounds.height {
                            let i = (y * w + x) * 4
                            if bytes[i] != sentinel { editorStrays += 1 }
                        }
                    }
                    if editorStrays > 0 {
                        bleedFailures.append("editor:\(editorStrays)px")
                    }
                    wc.window?.close()
                }
                check("sliceB-backdrop-fill-never-paints-outside-canvas",
                      bleedFailures.isEmpty,
                      bleedFailures.prefix(6).joined(separator: " | "))
            }

            // C1. What the user reviews and what the export writes describe
            //     the same picture: the same colour space and the same crop.
            //
            //     Colour: a framed export is composed in sRGB, so the inner
            //     render has to LAND in sRGB — not be rendered in the source's
            //     P3 and converted afterwards, which blends every annotation
            //     against different primaries. The band below is a saturated
            //     NON-primary P3 colour on purpose: pure P3 green converts to
            //     (0,255,0) and would make this oracle blind.
            //
            //     Crop: the payload crops by `session.pixelRect.integral`, so
            //     everything on screen has to describe that same rect. A
            //     selection dragged to a half point at scale 2 (the 127/128
            //     seam below) used to leave the frame, its padding and the
            //     reported rect a half point away from the exported ones.
            MainActor.assumeIsolated {
                var c1Failures: [String] = []
                let p3 = CGColorSpace(name: CGColorSpace.displayP3)!
                let sRGB = CGColorSpace(name: CGColorSpace.sRGB)!
                let bandRect = CGRect(x: 220, y: 220, width: 60, height: 60)
                @MainActor final class ImageSpy {
                    var visual: [CGImage] = []
                    var semantic: [CGImage] = []
                    func dependencies() -> CaptureActionRouter.Dependencies {
                        CaptureActionRouter.Dependencies(
                            copyToClipboard: { [self] in
                                visual.append($0.cgImage)
                            },
                            autoSave: { _, _ in }, saveAs: { _, _ in },
                            pin: { _ in },
                            ocrWithMode: { [self] image, _ in
                                semantic.append(image.cgImage)
                            },
                            openEditor: { _ in }, toast: { _ in },
                            setLastCapture: { _ in }, setLastAreaRect: { _ in },
                            logEvent: { _ in })
                    }
                }
                /// A P3 source: mid grey everywhere, with one saturated band
                /// that sRGB cannot represent.
                func p3Source(scale: CGFloat, size: CGSize) -> CGImage? {
                    let w = Int(size.width * scale)
                    let h = Int(size.height * scale)
                    guard let c = CGContext(
                        data: nil, width: w, height: h, bitsPerComponent: 8,
                        bytesPerRow: 0, space: p3,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                    else { return nil }
                    c.setFillColor(CGColor(
                        colorSpace: p3, components: [0.5, 0.5, 0.5, 1])!)
                    c.fill(CGRect(x: 0, y: 0, width: w, height: h))
                    c.setFillColor(CGColor(
                        colorSpace: p3, components: [0.05, 0.92, 0.42, 1])!)
                    c.fill(CGRect(
                        x: bandRect.minX * scale, y: bandRect.minY * scale,
                        width: bandRect.width * scale,
                        height: bandRect.height * scale))
                    return c.makeImage()
                }
                /// Reads one pixel of `image` through `space`, which is what
                /// makes the difference between "the pixels were converted"
                /// and "the pixels were relabelled" visible.
                func read(
                    _ image: CGImage, _ x: Int, _ yBL: Int, in space: CGColorSpace
                ) -> (Int, Int, Int)? {
                    let w = image.width, h = image.height
                    guard x >= 0, x < w, yBL >= 0, yBL < h else { return nil }
                    var bytes = [UInt8](repeating: 0, count: w * h * 4)
                    guard let c = CGContext(
                        data: &bytes, width: w, height: h, bitsPerComponent: 8,
                        bytesPerRow: w * 4, space: space,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                    else { return nil }
                    c.interpolationQuality = .none
                    c.draw(image, in: CGRect(x: 0, y: 0, width: w, height: h))
                    let i = ((h - 1 - yBL) * w + x) * 4
                    return (Int(bytes[i]), Int(bytes[i + 1]), Int(bytes[i + 2]))
                }
                func near(
                    _ a: (Int, Int, Int)?, _ b: (Int, Int, Int)?, _ tol: Int
                ) -> Bool {
                    guard let a, let b else { return false }
                    return abs(a.0 - b.0) <= tol && abs(a.1 - b.1) <= tol
                        && abs(a.2 - b.2) <= tol
                }
                guard let screen = NSScreen.main ?? NSScreen.screens.first
                else {
                    check("sliceB-backdrop-preview-matches-export",
                          false, "no screen")
                    return
                }
                @MainActor func review(
                    _ spy: ImageSpy, scale: CGFloat, selection: CGRect
                ) -> (SelectionOverlay, SelectionOverlayView)? {
                    guard let base = p3Source(
                        scale: scale, size: screen.frame.size) else { return nil }
                    let overlay = SelectionOverlay(
                        purpose: .areaReview,
                        inputs: OverlaySessionInputs(
                            afterShow: true, afterCopy: false, afterSave: false),
                        completion: { _ in })
                    overlay.routerDependenciesOverride = spy.dependencies()
                    let view = SelectionOverlayView(
                        mode: .area, screen: screen,
                        frozen: CapturedImage(cgImage: base, scale: scale),
                        windowList: [], owner: overlay)
                    view.selectForTesting(rect: selection)
                    return (overlay, view)
                }
                // The crop is chosen so the saturated band sits inside it.
                let colourSelection = CGRect(
                    x: 200, y: 200, width: 120, height: 100)
                // Where the band is, relative to the crop, in points.
                let bandInCrop = CGPoint(
                    x: bandRect.midX - colourSelection.minX,
                    y: bandRect.midY - colourSelection.minY)

                /// One pixel of `color` painted into a context of `space` —
                /// CoreGraphics' own conversion, computed independently of
                /// anything under test.
                func swatch(
                    _ color: CGColor, in space: CGColorSpace
                ) -> (Int, Int, Int)? {
                    var bytes = [UInt8](repeating: 0, count: 4)
                    guard let c = CGContext(
                        data: &bytes, width: 1, height: 1, bitsPerComponent: 8,
                        bytesPerRow: 4, space: space,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                    else { return nil }
                    c.setFillColor(color)
                    c.fill(CGRect(x: 0, y: 0, width: 1, height: 1))
                    return (Int(bytes[0]), Int(bytes[1]), Int(bytes[2]))
                }
                let bandColour = CGColor(
                    colorSpace: p3, components: [0.05, 0.92, 0.42, 1])!

                // -- framed: the semantic payload is sRGB and carries the
                //    CONVERTED colour, computed here by CoreGraphics rather
                //    than by the code under test.
                let framedSpy = ImageSpy()
                if let (overlay, view) = review(
                    framedSpy, scale: 1, selection: colourSelection) {
                    _ = view.applyBackdropPreset(.ocean)
                    // `.translate`, not `.ocr`: since 1.2.16 the OCR button
                    // opens the region sub-mode and never reaches the router,
                    // so it can no longer serve as the vehicle for observing a
                    // payload. Translate is the OTHER undecorated intent —
                    // `usesDecoration` returns false for both and the router
                    // hands both the same snapshot — so what this gate
                    // measures is unchanged.
                    view.performReviewActionForTesting(.translate)
                    if let semantic = framedSpy.semantic.last {
                        if semantic.colorSpace?.name != CGColorSpace.sRGB {
                            c1Failures.append(
                                "semantic space "
                                    + "\(String(describing: semantic.colorSpace?.name))")
                        }
                        let got = read(
                            semantic, Int(bandInCrop.x), Int(bandInCrop.y),
                            in: sRGB)
                        let want = swatch(bandColour, in: sRGB)
                        // The raw P3 numbers, to prove the two readings are
                        // actually different — a band that survived the
                        // conversion unchanged would prove nothing at all.
                        let raw = swatch(bandColour, in: p3)
                        if !near(got, want, 3) {
                            c1Failures.append(
                                "band \(String(describing: got)) "
                                    + "want \(String(describing: want))")
                        }
                        if near(want, raw, 3) {
                            c1Failures.append(
                                "band-blind \(String(describing: raw))")
                        }
                    } else {
                        c1Failures.append("no semantic payload")
                    }
                    overlay.dismissForTesting()
                }
                // A terminal CLOSES the session, so the composed reading needs
                // its own review — the same reason the dual-payload gate keeps
                // one overlay per intent.
                let composedSpy = ImageSpy()
                if let (overlay, view) = review(
                    composedSpy, scale: 1, selection: colourSelection) {
                    _ = view.applyBackdropPreset(.ocean)
                    view.performReviewActionForTesting(.copy)
                    if let visual = composedSpy.visual.last {
                        if visual.colorSpace?.name != CGColorSpace.sRGB {
                            c1Failures.append("visual not sRGB")
                        }
                        // The frame was built AROUND the converted inner: the
                        // band reads the same in the composed picture.
                        let layout = BackdropLayout(
                            innerPixels: colourSelection.size,
                            pixelScale: 1, preset: .ocean)
                        let inVisual = read(
                            visual,
                            Int(bandInCrop.x + layout.padPixels),
                            Int(bandInCrop.y + layout.padPixels), in: sRGB)
                        let inSemantic = framedSpy.semantic.last.flatMap {
                            read(
                                $0, Int(bandInCrop.x), Int(bandInCrop.y),
                                in: sRGB)
                        }
                        if !near(inVisual, inSemantic, 2) {
                            c1Failures.append(
                                "composed inner \(String(describing: inVisual)) "
                                    + "vs semantic \(String(describing: inSemantic))")
                        }
                    } else {
                        c1Failures.append("no visual payload")
                    }
                    overlay.dismissForTesting()
                }

                // -- `.none`: not one byte converted. The document keeps its
                //    own space, so a P3 capture stays P3.
                let plainSpy = ImageSpy()
                if let (overlay, view) = review(
                    plainSpy, scale: 1, selection: colourSelection) {
                    // `.translate`, not `.ocr`: since 1.2.16 the OCR button
                    // opens the region sub-mode and never reaches the router,
                    // so it can no longer serve as the vehicle for observing a
                    // payload. Translate is the OTHER undecorated intent —
                    // `usesDecoration` returns false for both and the router
                    // hands both the same snapshot — so what this gate
                    // measures is unchanged.
                    view.performReviewActionForTesting(.translate)
                    if let semantic = plainSpy.semantic.last {
                        if semantic.colorSpace?.name != CGColorSpace.displayP3 {
                            c1Failures.append(
                                "none converted to "
                                    + "\(String(describing: semantic.colorSpace?.name))")
                        }
                        let got = read(
                            semantic, Int(bandInCrop.x), Int(bandInCrop.y),
                            in: p3)
                        let want = swatch(bandColour, in: p3)
                        if !near(got, want, 0) {
                            c1Failures.append(
                                "none band moved \(String(describing: got)) "
                                    + "want \(String(describing: want))")
                        }
                    } else {
                        c1Failures.append("no plain payload")
                    }
                    overlay.dismissForTesting()
                }

                // -- Geometry, at scale 1 and scale 2, from a selection whose
                //    edges land BETWEEN pixels. At scale 2 the left edge sits
                //    on the 127/128 seam.
                for scale in [CGFloat(1), CGFloat(2)] {
                    for preset in [BackdropPreset.none, .ocean] {
                        let fractional = CGRect(
                            x: 63.75, y: 40.25, width: 32.4, height: 24.6)
                        let spy = ImageSpy()
                        guard let (overlay, view) = review(
                            spy, scale: scale, selection: fractional)
                        else {
                            c1Failures.append("no overlay @\(scale)")
                            continue
                        }
                        if preset != .none {
                            _ = view.applyBackdropPreset(preset)
                        }
                        let px = overlay.session.pixelRect
                        let canonical = view.areaSelectionForTesting
                        if px != px.integral {
                            c1Failures.append("pixelRect fractional \(px)")
                        }
                        // The seam premise: at scale 2 this selection must
                        // actually straddle pixel 127/128, or the gate is
                        // testing a rect that happened to be aligned.
                        if scale == 2 && px.minX != 127 {
                            c1Failures.append("seam moved \(px.minX)")
                        }
                        if let canonical {
                            let backX = canonical.minX * scale
                            let backW = canonical.width * scale
                            if abs(backX - px.minX) > 0.001
                                || abs(backW - px.width) > 0.001 {
                                c1Failures.append(
                                    "selection \(canonical) vs px \(px) "
                                        + "@\(scale)")
                            }
                            if canonical == fractional {
                                c1Failures.append("never quantized @\(scale)")
                            }
                        } else {
                            c1Failures.append("no selection @\(scale)")
                        }
                        if preset != .none {
                            let layout = BackdropLayout(
                                innerPixels: px.size, pixelScale: scale,
                                preset: preset)
                            if let outer = view
                                .backdropPreviewOuterRectForTesting {
                                if abs(outer.width * scale
                                        - layout.outerPixelSize.width) > 0.01
                                    || abs(outer.height * scale
                                        - layout.outerPixelSize.height) > 0.01 {
                                    c1Failures.append(
                                        "preview outer \(outer.size) "
                                            + "vs export "
                                            + "\(layout.outerPixelSize) @\(scale)")
                                }
                            } else {
                                c1Failures.append("no preview rect @\(scale)")
                            }
                            view.performReviewActionForTesting(.copy)
                            if let visual = spy.visual.last {
                                if CGFloat(visual.width)
                                    != layout.outerPixelSize.width
                                    || CGFloat(visual.height)
                                        != layout.outerPixelSize.height {
                                    c1Failures.append(
                                        "export \(visual.width)x\(visual.height)"
                                            + " vs layout "
                                            + "\(layout.outerPixelSize) @\(scale)")
                                }
                            } else {
                                c1Failures.append("no export @\(scale)")
                            }
                        } else {
                            view.performReviewActionForTesting(.copy)
                            if let visual = spy.visual.last,
                               CGFloat(visual.width) != px.width
                                || CGFloat(visual.height) != px.height {
                                c1Failures.append(
                                    "plain export \(visual.width)x\(visual.height)"
                                        + " vs \(px.size) @\(scale)")
                            }
                        }
                        overlay.dismissForTesting()
                    }
                }
                check("sliceB-backdrop-preview-matches-export",
                      c1Failures.isEmpty,
                      c1Failures.prefix(6).joined(separator: " | "))
            }

            // C2. The live caption is clipped by the crop the export makes —
            //     in BOTH hosts, and while it is being typed.
            //
            //     A text field is a SUBVIEW: the draw-path clip that shapes
            //     the document does not reach it, so a caption typed near a
            //     rounded corner showed on screen and was missing from the
            //     export. The clip therefore lives on the field, as a layer
            //     mask, and the field editor — the NSTextView AppKit swaps in
            //     while the field is first responder, which is what actually
            //     draws the glyphs — must be inside it too.
            MainActor.assumeIsolated {
                var c2Failures: [String] = []
                /// Drains the main queue so a production notification observer
                /// has actually run before anything is asserted.
                func settle() {
                    var drained = false
                    DispatchQueue.main.async { drained = true }
                    let deadline = Date().addingTimeInterval(1)
                    while !drained && Date() < deadline {
                        RunLoop.current.run(
                            until: min(
                                deadline, Date().addingTimeInterval(0.01)))
                    }
                }
                /// Asserts a mask exists, is not empty, and answers both ways:
                /// a point outside the rounded document is OUT, a point well
                /// inside is IN. A mask that clipped everything, or nothing,
                /// fails one of the two.
                func checkMask(
                    _ label: String, _ mask: CAShapeLayer?,
                    outside: CGPoint, inside: CGPoint
                ) {
                    guard let mask, let path = mask.path else {
                        c2Failures.append("\(label):no-mask")
                        return
                    }
                    if path.isEmpty {
                        c2Failures.append("\(label):empty-path")
                        return
                    }
                    if path.contains(outside) {
                        c2Failures.append("\(label):corner-in \(outside)")
                    }
                    if !path.contains(inside) {
                        c2Failures.append("\(label):interior-out \(inside)")
                    }
                }

                // -- Editor: a real window, a real field editor, and a zoom
                //    delivered by the production observer rather than by
                //    calling the canvas' handler directly.
                let base = makeStripePattern(
                    width: 600, height: 400, seed: 0x0C02_2026)
                let wc = EditorWindowController.open(
                    with: CapturedImage(cgImage: base, scale: 1),
                    forceFitForTesting: true)
                let canvas = wc.canvasForTesting
                _ = canvas.applyBackdrop(.ocean)
                canvas.beginTextEditingForTesting(at: CGPoint(x: 2, y: 2))
                wc.documentWrapperForTesting?.layoutSubtreeIfNeeded()
                if let field = canvas.textFieldForTesting {
                    let corner = field.convert(
                        CGPoint(x: 2, y: 2), from: canvas)
                    let interior = field.convert(
                        CGPoint(x: canvas.bounds.midX, y: canvas.bounds.midY),
                        from: canvas)
                    checkMask(
                        "editor-field", field.layer?.mask as? CAShapeLayer,
                        outside: corner, inside: interior)
                    // The premise the mask state alone cannot give: the field
                    // is LIVE, so what draws the glyphs is the field editor,
                    // and the mask has to cover it in ITS coordinates.
                    if let editor = field.currentEditor() as? NSTextView {
                        let editorCorner = editor.convert(
                            CGPoint(x: 2, y: 2), from: canvas)
                        let editorInterior = editor.convert(
                            CGPoint(
                                x: canvas.bounds.midX, y: canvas.bounds.midY),
                            from: canvas)
                        // The mask sits on the field, and the editor is inside
                        // it, so the editor's points are converted back into
                        // the masked layer's space before they are tested.
                        let inField = (
                            corner: field.convert(editorCorner, from: editor),
                            interior: field.convert(
                                editorInterior, from: editor))
                        checkMask(
                            "editor-currentEditor",
                            field.layer?.mask as? CAShapeLayer,
                            outside: inField.corner, inside: inField.interior)
                    } else {
                        c2Failures.append("editor:no-field-editor")
                    }
                    @MainActor func expectedScale() -> CGFloat {
                        (wc.window?.backingScaleFactor ?? 2)
                            * max(
                                0.01,
                                canvas.enclosingScrollView?.magnification ?? 1)
                    }
                    // Zoom through the PRODUCTION path: the scroll view's
                    // bounds change posts the notification the controller
                    // observes. Calling `magnificationDidChange()` by hand
                    // would have proved the method works while the wiring
                    // that calls it stayed broken.
                    canvas.enclosingScrollView?.magnification = 2
                    settle()
                    if let mask = canvas.textFieldForTesting?
                        .layer?.mask as? CAShapeLayer,
                       abs(mask.contentsScale - expectedScale()) > 0.05 {
                        c2Failures.append(
                            "editor:zoom-stale \(mask.contentsScale) "
                                + "want \(expectedScale())")
                    }
                    // A 1x <-> 2x display move changes the backing scale with
                    // no zoom and no layout; AppKit's own callback is the only
                    // thing that fires, so that is what is called here.
                    canvas.viewDidChangeBackingProperties()
                    if let mask = canvas.textFieldForTesting?
                        .layer?.mask as? CAShapeLayer,
                       abs(mask.contentsScale - expectedScale()) > 0.05 {
                        c2Failures.append(
                            "editor:backing-stale \(mask.contentsScale)")
                    }
                } else {
                    c2Failures.append("editor:no-field")
                }
                wc.window?.close()

                // -- Area review: the caption there had NO mask at all, so it
                //    could be drawn over the rounded plate the export clips.
                if let screen = NSScreen.main ?? NSScreen.screens.first {
                    let overlay = SelectionOverlay(
                        purpose: .areaReview,
                        inputs: OverlaySessionInputs(
                            afterShow: true, afterCopy: false, afterSave: false),
                        completion: { _ in })
                    let view = SelectionOverlayView(
                        mode: .area, screen: screen,
                        frozen: CapturedImage(
                            cgImage: makeStripePattern(
                                width: Int(screen.frame.width),
                                height: Int(screen.frame.height),
                                seed: 0x0C02_2027),
                            scale: 1),
                        windowList: [], owner: overlay)
                    let selection = CGRect(
                        x: 200, y: 200, width: 320, height: 240)
                    view.selectForTesting(rect: selection)
                    _ = view.applyBackdropPreset(.ocean)
                    // Typed INSIDE the crop, near its corner — where the
                    // rounded plate cuts and the square field does not.
                    view.beginTextEntryForTesting(
                        atView: CGPoint(
                            x: selection.minX + 3, y: selection.minY + 3))
                    if let field = view.textFieldForTesting {
                        let canonical = view.areaSelectionForTesting ?? selection
                        let corner = field.convert(
                            CGPoint(x: canonical.minX + 1,
                                    y: canonical.minY + 1),
                            from: view)
                        let interior = field.convert(
                            CGPoint(x: canonical.midX, y: canonical.midY),
                            from: view)
                        checkMask(
                            "area-field", field.layer?.mask as? CAShapeLayer,
                            outside: corner, inside: interior)
                        // The mask follows the crop: after a review resize the
                        // old plate is gone, and a mask still describing it
                        // would clip the caption in the wrong place.
                        let moved = CGRect(
                            x: selection.minX + 40, y: selection.minY + 30,
                            width: 300, height: 220)
                        view.adjustSelectionForTesting(rect: moved)
                        let movedCanonical =
                            view.areaSelectionForTesting ?? moved
                        checkMask(
                            "area-field-after-crop",
                            field.layer?.mask as? CAShapeLayer,
                            outside: field.convert(
                                CGPoint(x: movedCanonical.minX + 1,
                                        y: movedCanonical.minY + 1),
                                from: view),
                            inside: field.convert(
                                CGPoint(x: movedCanonical.midX,
                                        y: movedCanonical.midY),
                                from: view))
                        // `.none` still clips — to a SQUARE crop, so the same
                        // corner point is now inside.
                        _ = view.applyBackdropPreset(.none)
                        if let mask = field.layer?.mask as? CAShapeLayer,
                           let path = mask.path {
                            let squareCorner = field.convert(
                                CGPoint(x: movedCanonical.minX + 1,
                                        y: movedCanonical.minY + 1),
                                from: view)
                            if !path.contains(squareCorner) {
                                c2Failures.append("area-none:corner-clipped")
                            }
                            let outsideCrop = field.convert(
                                CGPoint(x: movedCanonical.minX - 8,
                                        y: movedCanonical.midY),
                                from: view)
                            if path.contains(outsideCrop) {
                                c2Failures.append("area-none:outside-crop-in")
                            }
                        } else {
                            c2Failures.append("area-none:no-mask")
                        }
                    } else {
                        c2Failures.append("area:no-field")
                    }
                    overlay.dismissForTesting()
                } else {
                    c2Failures.append("area:no-screen")
                }
                check("sliceB-backdrop-live-caption-clipped",
                      c2Failures.isEmpty,
                      c2Failures.prefix(6).joined(separator: " | "))
            }

            // P0. The crop is a privacy boundary for the magnifier.
            //
            // A magnifier TRANSPORTS pixels: whatever its source covers is
            // reproduced, enlarged, somewhere else. A source that was inside
            // the crop when the callout was made can be put outside it
            // afterwards by a crop move or resize — so the boundary is
            // enforced in the compositor, where every route passes, rather
            // than at the drag. CONTAINS, not intersects: a source that hangs
            // half out still shows the half that is out.
            MainActor.assumeIsolated {
                var magFailures: [String] = []
                let secret = CGRect(x: 220, y: 220, width: 40, height: 40)
                let callout = CGRect(x: 400, y: 400, width: 80, height: 80)
                func sourceImage(_ size: CGSize) -> CGImage? {
                    guard let c = CGContext(
                        data: nil, width: Int(size.width),
                        height: Int(size.height), bitsPerComponent: 8,
                        bytesPerRow: 0,
                        space: CGColorSpace(name: CGColorSpace.sRGB)!,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                    else { return nil }
                    c.setFillColor(NSColor(white: 0.55, alpha: 1).cgColor)
                    c.fill(CGRect(origin: .zero, size: size))
                    // The pixels that must never travel outside the crop.
                    c.setFillColor(
                        NSColor(srgbRed: 1, green: 0, blue: 0, alpha: 1).cgColor)
                    c.fill(secret)
                    return c.makeImage()
                }
                func isRed(_ image: CGImage, _ x: Int, _ yBL: Int) -> Bool {
                    let w = image.width, h = image.height
                    guard x >= 0, x < w, yBL >= 0, yBL < h else { return false }
                    var bytes = [UInt8](repeating: 0, count: w * h * 4)
                    guard let c = CGContext(
                        data: &bytes, width: w, height: h, bitsPerComponent: 8,
                        bytesPerRow: w * 4,
                        space: CGColorSpace(name: CGColorSpace.sRGB)!,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                    else { return false }
                    c.interpolationQuality = .none
                    c.draw(image, in: CGRect(x: 0, y: 0, width: w, height: h))
                    let i = ((h - 1 - yBL) * w + x) * 4
                    return Int(bytes[i]) > 150 && Int(bytes[i + 1]) < 110
                        && Int(bytes[i + 2]) < 110
                }
                let size = CGSize(width: 640, height: 520)
                if let base = sourceImage(size) {
                    func compositorShot(visible: CGRect) -> CGImage? {
                        let mag = MagnifierAnnotation(uiScale: 1)
                        mag.sourceRect = secret
                        mag.calloutRect = callout
                        mag.snapshot = SliceBCompositor.magnifierSnapshot(
                            base: base, sourceRect: secret, redactions: [])
                        guard mag.snapshot != nil else { return nil }
                        guard let c = CGContext(
                            data: nil, width: Int(size.width),
                            height: Int(size.height), bitsPerComponent: 8,
                            bytesPerRow: 0,
                            space: CGColorSpace(name: CGColorSpace.sRGB)!,
                            bitmapInfo: CGImageAlphaInfo
                                .premultipliedLast.rawValue)
                        else { return nil }
                        c.draw(base, in: CGRect(origin: .zero, size: size))
                        SliceBCompositor.draw(
                            [mag], in: c, base: base, visiblePixels: visible)
                        return c.makeImage()
                    }
                    let centreX = Int(callout.midX), centreY = Int(callout.midY)
                    // Premise: with the source wholly inside the crop the
                    // callout IS drawn, so the probes below mean something.
                    if let inside = compositorShot(
                        visible: CGRect(origin: .zero, size: size)) {
                        if !isRed(inside, centreX, centreY) {
                            magFailures.append("inside-crop:not-drawn")
                        }
                    } else {
                        magFailures.append("inside-crop:no-shot")
                    }
                    // Source entirely outside the crop.
                    if let outside = compositorShot(
                        visible: CGRect(
                            x: 300, y: 300, width: 340, height: 220)),
                       isRed(outside, centreX, centreY) {
                        magFailures.append("outside-crop:leaked")
                    }
                    // Source only PARTLY outside — still a leak of the part
                    // that is out, so `contains` is the test, not `intersects`.
                    if let partial = compositorShot(
                        visible: CGRect(
                            x: 240, y: 240, width: 400, height: 280)),
                       isRed(partial, centreX, centreY) {
                        magFailures.append("partial-crop:leaked")
                    }
                } else {
                    magFailures.append("no-base")
                }
                // And the Area preview asks the same question the export does:
                // before this, the preview passed the WHOLE image as visible,
                // so a callout the export dropped stayed on screen.
                if let screen = NSScreen.main ?? NSScreen.screens.first,
                   let base = sourceImage(screen.frame.size) {
                    let overlay = SelectionOverlay(
                        purpose: .areaReview,
                        inputs: OverlaySessionInputs(
                            afterShow: true, afterCopy: false, afterSave: false),
                        completion: { _ in })
                    let view = SelectionOverlayView(
                        mode: .area, screen: screen,
                        frozen: CapturedImage(cgImage: base, scale: 1),
                        windowList: [], owner: overlay)
                    view.selectForTesting(
                        rect: CGRect(x: 200, y: 200, width: 320, height: 300))
                    if let surface = view.annotationSurface {
                        let mag = MagnifierAnnotation(uiScale: 1)
                        mag.sourceRect = secret
                        mag.calloutRect = callout
                        mag.snapshot = SliceBCompositor.magnifierSnapshot(
                            base: base, sourceRect: secret, redactions: [])
                        surface.addAnnotationForTesting(mag)
                        view.needsDisplay = true
                        if let shot = SelfTest.directDrawSnapshotForTesting(view),
                           !isRed(
                            shot,
                            Int(callout.midX * CGFloat(shot.width)
                                / view.bounds.width),
                            Int(callout.midY * CGFloat(shot.height)
                                / view.bounds.height)) {
                            magFailures.append("preview:premise-not-drawn")
                        }
                        // The crop moves off the source; the callout stays
                        // inside the crop, so anything red there came from
                        // pixels the export will not contain.
                        view.adjustSelectionForTesting(
                            rect: CGRect(
                                x: 300, y: 300, width: 320, height: 240))
                        view.needsDisplay = true
                        if let shot = SelfTest.directDrawSnapshotForTesting(view),
                           isRed(
                            shot,
                            Int(callout.midX * CGFloat(shot.width)
                                / view.bounds.width),
                            Int(callout.midY * CGFloat(shot.height)
                                / view.bounds.height)) {
                            magFailures.append("preview:leaked-after-crop")
                        }
                    } else {
                        magFailures.append("preview:no-surface")
                    }
                    overlay.dismissForTesting()
                }
                check("sliceB-magnifier-crop-privacy",
                      magFailures.isEmpty,
                      magFailures.prefix(6).joined(separator: " | "))
            }

            // 1c. Keyboard is host-scoped. The panel deliberately shows no
            // magnifier button, so routing M there would select a tool with no
            // control and no way back. The letters the tooltips advertise must
            // also actually work — a hint naming a key the host ignores is a
            // promise the app breaks.
            do {
                var keyFailures: [String] = []
                for key in ["v", "p", "a", "r", "t", "l", "o", "h", "n", "b", "s"] {
                    if OverlayAnnotationTool.tool(
                        forShortcutKey: key,
                        in: OverlayAnnotationTool.areaReviewTools) == nil {
                        keyFailures.append("area ignores \(key)")
                    }
                    if OverlayAnnotationTool.tool(
                        forShortcutKey: key,
                        in: OverlayAnnotationTool.panelTools) == nil {
                        keyFailures.append("panel ignores \(key)")
                    }
                }
                if OverlayAnnotationTool.tool(
                    forShortcutKey: "m",
                    in: OverlayAnnotationTool.areaReviewTools) != .magnifier {
                    keyFailures.append("area lost M")
                }
                if OverlayAnnotationTool.tool(
                    forShortcutKey: "m",
                    in: OverlayAnnotationTool.panelTools) != nil {
                    keyFailures.append("panel routed M to a hidden tool")
                }
                // Every advertised letter resolves to the tool whose tooltip
                // advertises it, on the host that shows it.
                for tool in OverlayAnnotationTool.areaReviewTools {
                    guard let range = tool.tooltip.range(
                        of: #"\(([A-Z])\)"#, options: .regularExpression)
                    else { continue }
                    let letter = tool.tooltip[range]
                        .dropFirst().dropLast().lowercased()
                    if OverlayAnnotationTool.tool(
                        forShortcutKey: letter,
                        in: OverlayAnnotationTool.areaReviewTools) != tool {
                        keyFailures.append(
                            "\(tool.rawValue) advertises \(letter), routes elsewhere")
                    }
                }
                check("sliceB-host-scoped-shortcuts", keyFailures.isEmpty,
                      keyFailures.joined(separator: " | "))
            }

            // 1d. The hover hint on all three hosts. The overlay and the panel
            // never activate, so AppKit's own tooltip cannot serve them; the
            // editor DOES activate, so leaving the native tooltip on would
            // show two descriptions side by side. Both halves are pinned here,
            // together with the geometry that the ~206pt panel breaks first.
            do {
                var hintFailures: [String] = []
                @MainActor func hintButtons(in root: NSView) -> [NSButton] {
                    root.subviews.flatMap { child -> [NSButton] in
                        let own = (child as? NSButton).map { [$0] } ?? []
                        return own + hintButtons(in: child)
                    }
                }
                @MainActor func hintKey(_ characters: String) -> NSEvent? {
                    NSEvent.keyEvent(
                        with: .keyDown, location: .zero, modifierFlags: [],
                        timestamp: 0, windowNumber: 0, context: nil,
                        characters: characters,
                        charactersIgnoringModifiers: characters,
                        isARepeat: false, keyCode: 0)
                }

                if let hintScreen = NSScreen.main ?? NSScreen.screens.first {
                    // --- Area review, inside a real window so the hint has a
                    // content view to live in.
                    let hintOverlay = SelectionOverlay(
                        purpose: .areaReview,
                        inputs: OverlaySessionInputs(
                            afterShow: true, afterCopy: false, afterSave: false),
                        completion: { _ in })
                    hintOverlay.routerDependenciesOverride =
                        CaptureActionRouter.Dependencies(
                            copyToClipboard: { _ in }, autoSave: { _, _ in },
                            saveAs: { _, _ in }, pin: { _ in }, ocr: { _ in },
                            openEditor: { _ in }, toast: { _ in },
                            setLastCapture: { _ in },
                            setLastAreaRect: { _ in }, logEvent: { _ in })
                    let hintFrozen = CapturedImage(
                        cgImage: makeSolidImage(
                            width: Int(hintScreen.frame.width),
                            height: Int(hintScreen.frame.height),
                            color: NSColor.darkGray.cgColor),
                        scale: 1)
                    let areaHintView = SelectionOverlayView(
                        mode: .area, screen: hintScreen, frozen: hintFrozen,
                        windowList: [], owner: hintOverlay)
                    let areaHintWindow = NSWindow(
                        contentRect: hintScreen.frame, styleMask: .borderless,
                        backing: .buffered, defer: false)
                    areaHintWindow.contentView = areaHintView
                    areaHintView.selectForTesting(rect: CGRect(
                        x: 200, y: 200, width: 300, height: 200))
                    let areaCatalog = areaHintView.reviewToolbarButtonsForTesting
                    if areaCatalog.contains(where: { $0.tooltip.isEmpty }) {
                        hintFailures.append("area hint catalog has gaps")
                    }
                    if areaHintView.nativeTooltipsForTesting
                        .contains(where: { $0 != nil }) {
                        hintFailures.append("area kept a native tooltip")
                    }
                    let areaButtons = hintButtons(in: areaHintView)
                    if let probe = areaButtons.first(where: {
                        $0.tag == OverlayAnnotationTool.pixelateText.toolbarTag
                    }) {
                        areaHintView.hoverHint.showImmediatelyForTesting(probe)
                        if areaHintView.hoverHint.visibleTextForTesting
                            != OverlayAnnotationTool.pixelateText.tooltip {
                            hintFailures.append("area hint text wrong")
                        }
                        if let frame = areaHintView.hoverHint.hintFrameForTesting {
                            if !areaHintView.bounds.insetBy(dx: -1, dy: -1)
                                .contains(frame) {
                                hintFailures.append("area hint outside \(frame)")
                            }
                            // Decoration only: the click must reach the button.
                            if let hit = areaHintView.hitTest(
                                areaHintView.convert(
                                    CGPoint(x: frame.midX, y: frame.midY),
                                    to: areaHintView.superview)),
                               String(describing: type(of: hit))
                                .contains("HintView") {
                                hintFailures.append("area hint swallowed a click")
                            }
                        } else {
                            hintFailures.append("area hint did not show")
                        }
                        // A keyboard tool switch is an authoritative change of
                        // what the pointer means: the hint goes with it.
                        if let event = hintKey("l") {
                            areaHintView.keyDown(with: event)
                        }
                        if areaHintView.hoverHint.visibleTextForTesting != nil {
                            hintFailures.append("area hint survived a key switch")
                        }
                    } else {
                        hintFailures.append("area probe button missing")
                    }
                    areaHintView.hoverHint.detachAll()
                    if areaButtons.contains(where: { button in
                        button.trackingAreas.contains {
                            $0.userInfo?["snipprHoverHint"] != nil
                        }
                    }) {
                        hintFailures.append("area tracking areas outlived detach")
                    }
                    if let probe = areaButtons.first,
                       areaHintView.hoverHint.textForTesting(probe) != nil {
                        hintFailures.append("area catalog outlived detach")
                    }
                    areaHintWindow.orderOut(nil)
                    hintOverlay.dismissForTesting()

                    // --- Scroll panel: the narrow one. Its content is about
                    // 206pt wide, which the longest sentence exceeds outright.
                    let hintPanel = ScrollResultPanel.show(
                        image: CapturedImage(
                            cgImage: makeStripePattern(
                                width: 90, height: 900, seed: 0x1128_0817),
                            scale: 1),
                        inputs: OverlaySessionInputs(
                            afterShow: true, afterCopy: false, afterSave: false),
                        screen: hintScreen,
                        dependencies: CaptureActionRouter.Dependencies(
                            copyToClipboard: { _ in }, autoSave: { _, _ in },
                            saveAs: { _, _ in }, pin: { _ in }, ocr: { _ in },
                            openEditor: { _ in }, toast: { _ in },
                            setLastCapture: { _ in },
                            setLastAreaRect: { _ in }, logEvent: { _ in }))
                    if hintPanel.toolbarButtonsForTesting
                        .contains(where: { $0.tooltip.isEmpty }) {
                        hintFailures.append("panel hint catalog has gaps")
                    }
                    if hintPanel.nativeTooltipsForTesting
                        .contains(where: { $0 != nil }) {
                        hintFailures.append("panel kept a native tooltip")
                    }
                    let panelContent = hintPanel.contentView ?? NSView()
                    if let probe = hintButtons(in: panelContent).first(where: {
                        $0.tag == OverlayAnnotationTool.pixelateText.toolbarTag
                    }) {
                        hintPanel.hoverHint.showImmediatelyForTesting(probe)
                        if let frame = hintPanel.hoverHint.hintFrameForTesting {
                            if frame.minX < panelContent.bounds.minX - 0.5
                                || frame.maxX > panelContent.bounds.maxX + 0.5 {
                                hintFailures.append(
                                    "panel hint clamped outside \(frame) in \(panelContent.bounds)")
                            }
                            if frame.width > HoverHint.maxWidth + 0.5 {
                                hintFailures.append(
                                    "panel hint did not wrap \(frame.width)")
                            }
                            // Wrapping means taller, not clipped: a single
                            // 22pt line cannot hold the pixelate sentence at
                            // this width.
                            if frame.height <= 22.5 {
                                hintFailures.append(
                                    "panel hint stayed one line \(frame.height)")
                            }
                        } else {
                            hintFailures.append("panel hint did not show")
                        }
                        hintPanel.hoverHint.hide()
                        if hintPanel.hoverHint.visibleTextForTesting != nil {
                            hintFailures.append("panel hide left a hint up")
                        }
                    } else {
                        hintFailures.append("panel probe button missing")
                    }
                    hintPanel.close()
                }

                // --- Editor: an activating window, so the native tooltip must
                // be off and the hint must go down on an authoritative switch.
                let hintWC = EditorWindowController.open(
                    with: CapturedImage(
                        cgImage: makeSolidImage(
                            width: 240, height: 160,
                            color: NSColor.gray.cgColor),
                        scale: 1),
                    forceFitForTesting: true)
                let editorButtons = hintWC.toolButtonsForTesting
                if let probe = editorButtons.first(where: {
                    $0.tool == .pixelateText
                })?.button {
                    hintWC.hoverHint.showImmediatelyForTesting(probe)
                    if hintWC.hoverHint.visibleTextForTesting
                        != EditorTool.pixelateText.tooltip {
                        hintFailures.append("editor hint text wrong")
                    }
                    hintWC.selectTool(.crop)
                    if hintWC.hoverHint.visibleTextForTesting != nil {
                        hintFailures.append("editor hint survived selectTool")
                    }
                } else {
                    hintFailures.append("editor probe button missing")
                }
                hintWC.window?.close()

                check("sliceB-hover-hint-three-hosts", hintFailures.isEmpty,
                      hintFailures.joined(separator: " | "))
            }

            // 2. Editor keys: old letters untouched, D/S/M/⇧B owned by B.
            let keys = SliceAHotkeys.editorToolKeys
            let legacyKeys = keys["v"] == .select && keys["a"] == .arrow
                && keys["l"] == .line && keys["r"] == .rect && keys["o"] == .oval
                && keys["h"] == .highlight && keys["p"] == .pen
                && keys["t"] == .text && keys["n"] == .counter
                && keys["b"] == .blur && keys["c"] == .crop
            let editorTips = EditorTool.allCases.map(\.tooltip)
            let newKeys = keys["d"] != nil && keys["s"] != nil && keys["m"] != nil
                && editorTips.contains { $0.hasPrefix("Backdrop (D)") }
                && editorTips.contains { $0.hasPrefix("Spotlight (S)") }
                && editorTips.contains { $0.hasPrefix("Magnifier (M)") }
                && editorTips.contains { $0.hasPrefix("Pixelate text (⇧B)") }
            check("sliceB-editor-keys-final",
                  legacyKeys && newKeys,
                  "keys \(keys.keys.sorted()) tips \(editorTips)")

            // 3. Every toolbar button must SHOW something. Demanding that each
            //    primary symbol resolve directly would contradict the fallback
            //    the toolbars deliberately go through — and would fail on a
            //    macOS 14 deployment target for a correct build, while leaving
            //    that fallback as dead code no gate ever runs.
            let resolvedPrimary = SliceBSymbols.image(
                named: "rectangle.dashed", fallback: "questionmark")
            let usesFallback = SliceBSymbols.image(
                named: "definitely.not.a.symbol.\(UUID().uuidString)",
                fallback: "questionmark")
            let bothMissing = SliceBSymbols.image(
                named: "definitely.not.a.symbol.\(UUID().uuidString)",
                fallback: "also.not.a.symbol.\(UUID().uuidString)")
            let symbolContract = resolvedPrimary != nil && usesFallback != nil
                && bothMissing != nil
            check("sliceB-symbols-resolve",
                  symbolContract
                    && EditorTool.allCases.count == 15
                    && OverlayAnnotationTool.areaReviewTools.count == 13
                    && OverlayAnnotationTool.panelTools.count == 12,
                  "primary \(resolvedPrimary != nil) fallback \(usesFallback != nil) "
                    + "placeholder \(bothMissing != nil) "
                    + "editor \(EditorTool.allCases.count) "
                    + "overlay \(OverlayAnnotationTool.areaReviewTools.count)"
                    + "/\(OverlayAnnotationTool.panelTools.count)")

            // 4. A redaction never renders "nothing".
            let redactRect = CGRect(x: 10, y: 20, width: 100, height: 40)
            let wordA = CGRect(x: 12, y: 22, width: 20, height: 10)
            let wordB = CGRect(x: 40, y: 22, width: 30, height: 10)
            let fullStates: [RedactionState] = [.rect, .pendingFull, .fallbackFull]
            let masksFull = fullStates.allSatisfy {
                SliceBRedaction.maskRects(state: $0, rect: redactRect) == [redactRect]
            }
            let masksWords = SliceBRedaction.maskRects(
                state: .words([wordA, wordB]), rect: redactRect) == [wordA, wordB]
            let emptyIsFallback = RedactionState.resolvedWords([]) == .fallbackFull
                && RedactionState.resolvedWords([wordA]) == .words([wordA])
                && !SliceBRedaction.maskRects(
                    state: .words([]), rect: redactRect).isEmpty
            check("sliceB-mask-never-empty",
                  masksFull && masksWords && emptyIsFallback,
                  "full \(masksFull) words \(masksWords) empty \(emptyIsFallback)")

            // 5. Async OCR landing on a superseded annotation is dropped.
            let staleApply = SliceBRedaction.applyWords(
                [wordA], to: .pendingFull, generation: 1, current: 2)
            let liveApply = SliceBRedaction.applyWords(
                [wordA], to: .pendingFull, generation: 3, current: 3)
            let emptyApply = SliceBRedaction.applyWords(
                [], to: .pendingFull, generation: 3, current: 3)
            check("sliceB-ocr-race",
                  staleApply == .pendingFull
                    && liveApply == .words([wordA])
                    && emptyApply == .fallbackFull,
                  "stale \(staleApply) live \(liveApply) empty \(emptyApply)")

            // 6. Phase order: redaction -> spotlight -> foreground (stable).
            let phaseBlur = BlurAnnotation(uiScale: 1)
            phaseBlur.rect = CGRect(x: 0, y: 0, width: 10, height: 10)
            let phaseSpot = SpotlightAnnotation(uiScale: 1)
            let phaseArrow = ShapeAnnotation(
                kind: .arrow, start: .zero, end: CGPoint(x: 5, y: 5), uiScale: 1)
            let phaseMag = MagnifierAnnotation(uiScale: 1)
            let ordered = SliceBCompositor.phaseOrder(
                [phaseArrow, phaseSpot, phaseBlur, phaseMag])
            let orderOK = ordered.count == 4
                && ordered[0] === phaseBlur && ordered[1] === phaseSpot
                && ordered[2] === phaseArrow && ordered[3] === phaseMag
            let phaseOK = SliceBCompositor.phase(of: phaseBlur) == .redaction
                && SliceBCompositor.phase(of: phaseSpot) == .spotlight
                && SliceBCompositor.phase(of: phaseArrow) == .foreground
                && SliceBCompositor.phase(of: phaseMag) == .foreground
            check("sliceB-phase-order", orderOK && phaseOK,
                  "order \(ordered.map { type(of: $0) }) phases ok \(phaseOK)")

            // 7. Pixels: pixelate must not erase the dim layer, and the render
            //    must not depend on insertion order.
            let phaseBase = makeNoiseImage(width: 120, height: 80)
            let phasePix = AnnotationRenderer.pixellate(phaseBase, scale: 1)
            let spot = SpotlightAnnotation(uiScale: 1)
            spot.rect = CGRect(x: 70, y: 20, width: 30, height: 30)
            spot.baseBounds = CGRect(x: 0, y: 0, width: 120, height: 80)
            spot.dimFraction = 0.7
            let wide = BlurAnnotation(uiScale: 1)
            wide.rect = CGRect(x: 0, y: 0, width: 60, height: 80)
            let spotFirst = AnnotationRenderer.render(
                base: phaseBase, annotations: [spot, wide], pixellated: phasePix)
            let blurFirst = AnnotationRenderer.render(
                base: phaseBase, annotations: [wide, spot], pixellated: phasePix)
            let noSpot = AnnotationRenderer.render(
                base: phaseBase, annotations: [wide], pixellated: phasePix)
            let orderIndependent = imagesEqual(spotFirst, blurFirst)
            // inside the blur AND outside the spotlight: dim must survive
            let dimOverBlur = luma(probe(spotFirst, 20, 40)) < luma(probe(noSpot, 20, 40))
            // inside the spotlight: untouched
            let brightInside = luma(probe(spotFirst, 85, 35)) == luma(probe(noSpot, 85, 35))
            check("sliceB-phase-pixels",
                  orderIndependent && dimOverBlur && brightInside,
                  "orderIndep \(orderIndependent) dimOverBlur \(dimOverBlur) brightInside \(brightInside)")

            // 7b. Two overlapping holes: intersection stays bright (even-odd
            //     would flip it back to dim) and the surround is dimmed once.
            do {
                let white = makeSolidImage(
                    width: 100, height: 80, color: NSColor.white.cgColor)
                let a = SpotlightAnnotation(uiScale: 1)
                a.rect = CGRect(x: 10, y: 10, width: 40, height: 40)
                a.baseBounds = CGRect(x: 0, y: 0, width: 100, height: 80)
                a.dimFraction = 0.5
                let b = SpotlightAnnotation(uiScale: 1)
                b.rect = CGRect(x: 30, y: 10, width: 40, height: 40)
                b.baseBounds = a.baseBounds
                b.dimFraction = 0.5
                let both = AnnotationRenderer.render(
                    base: white, annotations: [a, b], pixellated: nil)
                let onlyA = AnnotationRenderer.render(
                    base: white, annotations: [a], pixellated: nil)
                let none = AnnotationRenderer.render(
                    base: white, annotations: [], pixellated: nil)
                let baseL = luma(probe(none, 15, 30))
                let holeA = luma(probe(both, 15, 30))
                let overlap = luma(probe(both, 35, 30))
                let holeB = luma(probe(both, 55, 30))
                let outside = luma(probe(both, 5, 5))
                let outsideA = luma(probe(onlyA, 5, 5))
                check("sliceB-spotlight-union-holes",
                      holeA == baseL && overlap == baseL && holeB == baseL
                        && outside < baseL && abs(outside - outsideA) <= 2,
                      "A \(holeA) overlap \(overlap) B \(holeB) "
                        + "out \(outside)/\(outsideA) base \(baseL)")
            }

            // 8. A magnifier must sample the SANITIZED layer.
            let magCtx = ctx(60, 40)
            magCtx.setFillColor(NSColor.white.cgColor)
            magCtx.fill(CGRect(x: 0, y: 0, width: 60, height: 40))
            magCtx.setFillColor(NSColor.black.cgColor)
            magCtx.fill(CGRect(x: 14, y: 14, width: 4, height: 4))
            let magBase = magCtx.makeImage()!
            let source = CGRect(x: 8, y: 8, width: 16, height: 16)
            let covering = BlurAnnotation(uiScale: 1)
            covering.rect = CGRect(x: 6, y: 6, width: 24, height: 24)
            let sanitized = SliceBCompositor.magnifierSnapshot(
                base: magBase, sourceRect: source, redactions: [covering])
            let untouched = SliceBCompositor.magnifierSnapshot(
                base: magBase, sourceRect: source, redactions: [])
            func hasPureBlack(_ image: CGImage?) -> Bool {
                guard let image else { return false }
                for y in 0..<image.height where y % 2 == 0 {
                    for x in 0..<image.width where x % 2 == 0 {
                        if luma(probe(image, x, y)) < 24 { return true }
                    }
                }
                return false
            }
            check("sliceB-magnifier-vs-redaction",
                  sanitized != nil && untouched != nil
                    && !hasPureBlack(sanitized) && hasPureBlack(untouched),
                  "sanitized \(sanitized != nil) untouched \(untouched != nil)")

            // 9. Export fails closed instead of handing back a clean base.
            let exportBase = makeSolidImage(
                width: 40, height: 30, color: NSColor.green.cgColor)
            let exportOK = SliceBExport.checkedRender(
                base: exportBase, annotations: [], pixellated: nil,
                budgetBytes: SliceBExport.defaultBudgetBytes)
            let exportStarved = SliceBExport.checkedRender(
                base: exportBase, annotations: [], pixellated: nil,
                budgetBytes: 16)
            check("sliceB-export-fail-closed",
                  exportOK?.width == 40 && exportStarved == nil,
                  "ok \(exportOK?.width ?? -1) starved \(exportStarved == nil)")

            // 10. Backdrop padding cap + None parity + budget fail-closed.
            let padOK = SliceBBackdrop.padding(forLongEdge: 1000) == 60
                && SliceBBackdrop.padding(forLongEdge: 400) == 40
                && SliceBBackdrop.padding(forLongEdge: 40000) == 320
            let backdropBase = makeSolidImage(
                width: 50, height: 40, color: NSColor.systemTeal.cgColor)
            let plain = SliceBBackdrop.compose(
                image: backdropBase, preset: .none,
                budgetBytes: SliceBExport.defaultBudgetBytes)
            let plainParity = plain.map { imagesEqual($0, backdropBase) } == true
            let framed = SliceBBackdrop.compose(
                image: backdropBase, preset: .ocean,
                budgetBytes: SliceBExport.defaultBudgetBytes)
            let framedOK = framed?.width == 50 + 2 * Int(SliceBBackdrop.minPadding)
            let backdropStarved = SliceBBackdrop.compose(
                image: backdropBase, preset: .ocean, budgetBytes: 16)
            check("sliceB-backdrop-budget",
                  padOK && plainParity && framedOK && backdropStarved == nil,
                  "pad \(padOK) none \(plainParity) framed \(framed?.width ?? -1) starved \(backdropStarved == nil)")

            // 10b. Retina: the frame must be wide enough for its own shadow,
            // and an outer-compose failure must be fail-closed.
            //
            // Shadow is a POINT metric: at scale 2 it reaches 64 px past the
            // image, while the fixed 40 px floor would cut it off at the outer
            // canvas. The four outer border lines are checked for a dark band,
            // with the ring just outside the image as a positive control so the
            // gate cannot pass by finding no shadow at all.
            let extentOK = SliceBBackdrop.shadowExtent(pixelScale: 2) == 80
                && SliceBBackdrop.shadowExtent(pixelScale: 1) == 40
                && SliceBBackdrop.padding(forLongEdge: 60, pixelScale: 2) == 80
                && SliceBBackdrop.padding(forLongEdge: 60, pixelScale: 1) == 40
            let retinaInner = makeSolidImage(
                width: 60, height: 40, color: NSColor.white.cgColor)
            let retinaFrame = SliceBBackdrop.compose(
                image: retinaInner, preset: .ocean,
                budgetBytes: SliceBExport.defaultBudgetBytes, pixelScale: 2)
            let expectedOuter = SliceBBackdrop.outerDimensions(
                innerWidth: 60, innerHeight: 40, preset: .ocean, pixelScale: 2)
            let dimsOK = expectedOuter?.width == 220
                && expectedOuter?.height == 200
                && retinaFrame?.width == expectedOuter?.width
                && retinaFrame?.height == expectedOuter?.height
            // One rasterization; `probe` redraws the whole image per call.
            func rasterize(_ image: CGImage) -> [UInt8]? {
                var bytes = [UInt8](
                    repeating: 0, count: image.width * image.height * 4)
                guard let c = CGContext(
                    data: &bytes, width: image.width, height: image.height,
                    bitsPerComponent: 8, bytesPerRow: image.width * 4,
                    space: CGColorSpace(name: CGColorSpace.sRGB)!,
                    bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                else { return nil }
                c.interpolationQuality = .none
                c.draw(image, in: CGRect(
                    x: 0, y: 0, width: image.width, height: image.height))
                return bytes
            }
            // The reference is the SAME gradient over the SAME frame with no
            // shadow and no image, built from the preset's own colours and
            // axis. Comparing against it needs no assumption about where the
            // shadow falls off — an earlier version fitted a plane to the
            // border pixels, which would quietly absorb the very shadow it was
            // meant to detect.
            func gradientReference(width: Int, height: Int) -> CGImage? {
                guard let c = CGContext(
                    data: nil, width: width, height: height,
                    bitsPerComponent: 8, bytesPerRow: 0,
                    space: CGColorSpace(name: CGColorSpace.sRGB)!,
                    bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue),
                    SliceBBackdrop.drawFill(
                        in: c,
                        size: CGSize(width: width, height: height),
                        preset: .ocean, documentPixelsPerUserUnit: 1)
                else { return nil }
                // PRODUCTION's fill, not a hand-rolled gradient: the frame is
                // a four-stop ramp plus a radial wash plus grain, and a
                // two-stop reference would report a difference the export does
                // not have.
                return c.makeImage()
            }
            var shadowOK = false
            var shadowDetail = "frame nil"
            if let frame = retinaFrame, let px = rasterize(frame),
               let ref = gradientReference(
                   width: frame.width, height: frame.height),
               let refPx = rasterize(ref) {
                let w = frame.width, h = frame.height
                func lum(_ b: [UInt8], _ x: Int, _ yBL: Int) -> Int {
                    let i = ((h - 1 - yBL) * w + x) * 4
                    return luma((Int(b[i]), Int(b[i + 1]), Int(b[i + 2])))
                }
                func alpha(_ x: Int, _ yBL: Int) -> Int {
                    Int(px[((h - 1 - yBL) * w + x) * 4 + 3])
                }
                func deficit(_ x: Int, _ y: Int) -> Int {
                    lum(refPx, x, y) - lum(px, x, y)
                }
                var worstBorder = 0
                var opaque = true
                for x in 0..<w {
                    for y in [0, h - 1] {
                        worstBorder = max(worstBorder, abs(deficit(x, y)))
                        if alpha(x, y) != 255 { opaque = false }
                    }
                }
                for y in 0..<h {
                    for x in [0, w - 1] {
                        worstBorder = max(worstBorder, abs(deficit(x, y)))
                        if alpha(x, y) != 255 { opaque = false }
                    }
                }
                // Positive control in the middle of the band below the image,
                // away from the corners where the 2-D falloff is weakest and
                // most kernel-dependent: without it, a frame drawing no shadow
                // at all would sail through the border check.
                let pad = 80
                let band = ((pad + 20)..<(pad + 40)).map { deficit($0, pad - 3) }
                let shadowed = band.min() ?? 0
                shadowOK = worstBorder <= 4 && opaque && shadowed >= 10
                shadowDetail = "border \(worstBorder) opaque \(opaque) "
                    + "shadowed \(shadowed)"
            }
            check("sliceB-backdrop-shadow-extent",
                  extentOK && dimsOK && shadowOK,
                  "extent \(extentOK) dims \(dimsOK) \(shadowDetail)")

            // 10c. A failed outer compose returns nil rather than a frame that
            // is missing its background, so terminal callers cannot proceed.
            let composeFailed = ForcedOuterComposeFailure.scoped {
                SliceBBackdrop.compose(
                    image: retinaInner, preset: .ocean,
                    budgetBytes: SliceBExport.defaultBudgetBytes, pixelScale: 2)
            }
            let composeAfter = SliceBBackdrop.compose(
                image: retinaInner, preset: .ocean,
                budgetBytes: SliceBExport.defaultBudgetBytes, pixelScale: 2)
            let noneUnaffected = ForcedOuterComposeFailure.scoped {
                SliceBBackdrop.compose(
                    image: retinaInner, preset: .none,
                    budgetBytes: SliceBExport.defaultBudgetBytes)
            }
            check("sliceB-backdrop-outer-fail-closed",
                  composeFailed == nil && composeAfter != nil
                    && noneUnaffected != nil,
                  "failed \(composeFailed == nil) after \(composeAfter != nil) "
                    + "none \(noneUnaffected != nil)")

            // 11. New types survive copy / move / resize like every other mark.
            let sp = SpotlightAnnotation(uiScale: 1)
            sp.rect = CGRect(x: 10, y: 10, width: 20, height: 20)
            sp.baseBounds = CGRect(x: 0, y: 0, width: 100, height: 100)
            let spCopy = sp.copyAnnotation() as? SpotlightAnnotation
            spCopy?.move(by: CGPoint(x: 5, y: 0))
            let spOK = spCopy != nil && spCopy !== sp
                && sp.rect.origin.x == 10 && spCopy?.rect.origin.x == 15
            sp.scaleCoordinates(by: 2)
            let spScaled = sp.rect == CGRect(x: 20, y: 20, width: 40, height: 40)
                && sp.baseBounds.width == 200
            let mg = MagnifierAnnotation(uiScale: 1)
            mg.sourceRect = CGRect(x: 10, y: 10, width: 10, height: 10)
            mg.calloutRect = CGRect(x: 40, y: 40, width: 30, height: 30)
            mg.move(by: CGPoint(x: 3, y: 4))
            // dragging the callout must not re-aim the source
            let mgMoved = mg.calloutRect.origin == CGPoint(x: 43, y: 44)
                && mg.sourceRect.origin == CGPoint(x: 10, y: 10)
            mg.scaleCoordinates(by: 2)
            let mgScaled = mg.sourceRect == CGRect(x: 20, y: 20, width: 20, height: 20)
                && mg.calloutRect == CGRect(x: 86, y: 88, width: 60, height: 60)
            check("sliceB-annotation-copy-move-scale",
                  spOK && spScaled && mgMoved && mgScaled,
                  "spot \(spOK)/\(spScaled) mag \(mgMoved)/\(mgScaled)")
        }

        // MARK: slice B RED2 — production paths, injected failures
        //
        // RED0 pinned the contract; these drive the REAL editor canvas, the
        // real AnnotationSurface and the real toolbar/key routing through
        // injected failures, so a green here cannot be faked by a helper.
        do {
            func probe2(_ image: CGImage, _ x: Int, _ yBL: Int) -> (Int, Int, Int) {
                var bytes = [UInt8](
                    repeating: 0, count: image.width * image.height * 4)
                guard let c = CGContext(
                    data: &bytes, width: image.width, height: image.height,
                    bitsPerComponent: 8, bytesPerRow: image.width * 4,
                    space: CGColorSpace(name: CGColorSpace.sRGB)!,
                    bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                else { return (-1, -1, -1) }
                c.interpolationQuality = .none
                c.draw(image, in: CGRect(
                    x: 0, y: 0, width: image.width, height: image.height))
                let y = image.height - 1 - yBL
                guard x >= 0, x < image.width, y >= 0, y < image.height
                else { return (-1, -1, -1) }
                let i = (y * image.width + x) * 4
                return (Int(bytes[i]), Int(bytes[i + 1]), Int(bytes[i + 2]))
            }
            func viewSnapshot(_ view: NSView) -> CGImage? {
                guard let rep = view.bitmapImageRepForCachingDisplay(
                    in: view.bounds) else { return nil }
                view.cacheDisplay(in: view.bounds, to: rep)
                return rep.cgImage
            }

            // 1. Editor preview must not show clean pixels when pixelation fails
            let leakBase = makeNoiseImage(width: 200, height: 120)
            let leakWC = EditorWindowController.open(
                with: CapturedImage(cgImage: leakBase, scale: 1),
                forceFitForTesting: true)
            let leakCanvas = leakWC.canvasForTesting
            // Baseline: the same canvas with nothing on it. Comparing against
            // this instead of against the source image keeps the gate immune
            // to view resampling — the only difference we accept is the
            // redaction itself.
            leakCanvas.display()
            let cleanShot = viewSnapshot(leakCanvas)
            let leakBlur = BlurAnnotation(uiScale: 1)
            leakBlur.rect = CGRect(x: 20, y: 20, width: 80, height: 60)
            leakCanvas.annotations.append(leakBlur)
            let leakShot = AnnotationRenderer.withForcedRegionalFailure {
                () -> CGImage? in
                leakCanvas.needsDisplay = true
                leakCanvas.display()
                return viewSnapshot(leakCanvas)
            }
            var coveredSame = true
            if let clean = cleanShot, let failed = leakShot {
                coveredSame = (0..<6).allSatisfy { i in
                    let x = 30 + i * 8
                    return probe2(clean, x, 50) == probe2(failed, x, 50)
                }
            }
            check("sliceB2-editor-preview-failclosed",
                  cleanShot != nil && leakShot != nil && !coveredSame,
                  "clean \(cleanShot != nil) shot \(leakShot != nil) leaked \(coveredSame)")

            // 2. A failed render must not export and must not close the editor
            let pb = NSPasteboard.general
            pb.clearContents()
            pb.setString("SENTINEL-B2-COPY", forType: .string)
            AnnotationRenderer.withForcedRegionalFailure {
                leakWC.copyImage()
            }
            let clipboardIntact = pb.string(forType: .string) == "SENTINEL-B2-COPY"
            AnnotationRenderer.withForcedRegionalFailure {
                leakWC.escPressed()
            }
            let stillOpen = leakWC.window?.isVisible == true
            let stateIntact = leakCanvas.annotations.count == 1
                && leakCanvas.image.cgImage.width == 200
            check("sliceB2-editor-transactional",
                  clipboardIntact && stillOpen && stateIntact,
                  "clip \(clipboardIntact) open \(stillOpen) state \(stateIntact)")
            leakWC.window?.close()

            // 3. Overlay/scroll surface preview must fail closed too
            let surfBase = makeNoiseImage(width: 160, height: 100)
            let (rendered, surfLeak) = MainActor.assumeIsolated {
                () -> (Bool, Bool) in
                let surface = AnnotationSurface(pixelScale: 1)
                let surfBlur = BlurAnnotation(uiScale: 1)
                surfBlur.rect = CGRect(x: 30, y: 30, width: 60, height: 40)
                surface.addAnnotationForTesting(surfBlur)
                let surfCtx = ctx(160, 100)
                surfCtx.draw(
                    surfBase, in: CGRect(x: 0, y: 0, width: 160, height: 100))
                let ok = AnnotationRenderer.withForcedRegionalFailure {
                    surface.drawForPreview(in: surfCtx, base: surfBase)
                }
                let shot = surfCtx.makeImage()
                let leak = shot.map {
                    probe2($0, 60, 50) == probe2(surfBase, 60, 50)
                } ?? true
                return (ok, leak)
            }
            check("sliceB2-surface-preview-failclosed",
                  !rendered && !surfLeak,
                  "renderedAll \(rendered) leaked \(surfLeak)")

            // 4. Real OCR on a region that is NOT at the origin, so a
            //    bottom-left / top-left mix-up cannot pass.
            let ocrCtx = ctx(300, 200)
            ocrCtx.setFillColor(NSColor.white.cgColor)
            ocrCtx.fill(CGRect(x: 0, y: 0, width: 300, height: 200))
            let ocrAttrs: [NSAttributedString.Key: Any] = [
                .font: NSFont.boldSystemFont(ofSize: 26),
                .foregroundColor: NSColor.black,
            ]
            let ocrNS = NSGraphicsContext(cgContext: ocrCtx, flipped: false)
            NSGraphicsContext.saveGraphicsState()
            NSGraphicsContext.current = ocrNS
            ("Nguyen 0912345678" as NSString).draw(
                at: CGPoint(x: 60, y: 130), withAttributes: ocrAttrs)
            NSGraphicsContext.restoreGraphicsState()
            let ocrImage = ocrCtx.makeImage()!
            let ocrRegion = CGRect(x: 40, y: 110, width: 240, height: 60)
            let words = SliceBOCR.wordRects(base: ocrImage, region: ocrRegion)
            let inRegion = !words.isEmpty && words.allSatisfy {
                ocrRegion.insetBy(dx: -6, dy: -6).contains($0)
            }
            let notFlipped = !words.isEmpty && words.allSatisfy { $0.midY > 100 }
            check("sliceB2-ocr-regional",
                  inRegion && notFlipped,
                  "words \(words.count) inRegion \(inRegion) notFlipped \(notFlipped)")

            // 5. Text redaction on a tall stitch must pixelate the WORDS, not
            //    the whole rect, and must never materialize the whole image.
            let tall = makeNoiseImage(width: 400, height: 4000)
            let tallWord = CGRect(x: 60, y: 3810, width: 40, height: 14)
            MainActor.assumeIsolated {
                let tallSurface = AnnotationSurface(pixelScale: 1)
                let tallBlur = BlurAnnotation(uiScale: 1)
                tallBlur.rect = CGRect(x: 50, y: 3800, width: 160, height: 40)
                tallBlur.redactionState = .words([tallWord])
                tallSurface.addAnnotationForTesting(tallBlur)
                AnnotationSurface.regionalPixelateAllocationsForTesting = 0
                AnnotationSurface.lastRegionalPixelateRectForTesting = nil
                let tallCtx = ctx(400, 4000)
                tallCtx.draw(
                    tall, in: CGRect(x: 0, y: 0, width: 400, height: 4000))
                _ = tallSurface.drawForPreview(in: tallCtx, base: tall)
            }
            let lastRect = AnnotationSurface.lastRegionalPixelateRectForTesting
            let regionArea = (lastRect?.width ?? 0) * (lastRect?.height ?? 0)
            let wordArea = tallWord.width * tallWord.height
            let stayedSmall = lastRect != nil && regionArea <= wordArea * 4
            let baseUntouched = AnnotationSurface
                .lastRegionalPixelateBaseSizeForTesting == CGSize(
                    width: 400, height: 4000)
            check("sliceB2-tall-regional",
                  stayedSmall && baseUntouched,
                  "region \(String(describing: lastRect)) area \(regionArea) word \(wordArea) base \(String(describing: AnnotationSurface.lastRegionalPixelateBaseSizeForTesting))")

            // 6. Magnifier patch invalidation vs redactions
            let magSource = CGRect(x: 10, y: 10, width: 20, height: 20)
            let overlapping = BlurAnnotation(uiScale: 1)
            overlapping.rect = CGRect(x: 15, y: 15, width: 30, height: 30)
            let faraway = BlurAnnotation(uiScale: 1)
            faraway.rect = CGRect(x: 200, y: 200, width: 10, height: 10)
            check("sliceB2-magnifier-rebuild",
                  SliceBCompositor.needsRebuild(
                    source: magSource, redactions: [overlapping])
                    && !SliceBCompositor.needsRebuild(
                        source: magSource, redactions: [faraway]),
                  "overlap \(SliceBCompositor.needsRebuild(source: magSource, redactions: [overlapping])) far \(SliceBCompositor.needsRebuild(source: magSource, redactions: [faraway]))")

            // 6b. A magnifier drag is VISIBLE while it runs: the source frame
            //     and the outline of the callout it will make. Nothing is
            //     sampled until release, so no pixel can leak. After release
            //     the frame stays around the source next to the callout.
            do {
                let w = 200, h = 200
                let gray = makeSolidImage(
                    width: w, height: h,
                    color: CGColor(gray: 0.5, alpha: 1))
                func render(_ surface: AnnotationSurface) -> [UInt8] {
                    let c = ctx(w, h)
                    c.draw(gray, in: CGRect(x: 0, y: 0, width: w, height: h))
                    _ = surface.drawForPreview(in: c, base: gray)
                    return rgbaBytes(c.makeImage()!)
                }
                func lum(_ b: [UInt8], _ x: Int, _ yBL: Int) -> Int {
                    let i = ((h - 1 - yBL) * w + x) * 4
                    return (Int(b[i]) + Int(b[i + 1]) + Int(b[i + 2])) / 3
                }
                let baseLum = lum(rgbaBytes(gray), 100, 100)
                var dragFailures: [String] = []
                var frameFailures: [String] = []
                var clampFailures: [String] = []
                MainActor.assumeIsolated {
                    let surface = AnnotationSurface(pixelScale: 1)
                    surface.tool = .magnifier
                    _ = surface.beginDrag(atPixel: CGPoint(x: 20, y: 20))
                    surface.continueDrag(toPixel: CGPoint(x: 60, y: 50))
                    guard let mag = surface.annotations.last
                        as? MagnifierAnnotation
                    else { dragFailures.append("no draft"); return }
                    if mag.snapshot != nil {
                        dragFailures.append("sampled during drag")
                    }
                    let mid = render(surface)
                    // Source (20,20)-(60,50): white hairline just inside,
                    // dark hairline just outside, interior untouched.
                    if lum(mid, 20, 35) < 200 {
                        dragFailures.append("left edge not white \(lum(mid, 20, 35))")
                    }
                    if lum(mid, 19, 35) > baseLum - 30 {
                        dragFailures.append("left outer not dark \(lum(mid, 19, 35))")
                    }
                    if lum(mid, 40, 49) < 200 {
                        dragFailures.append("top edge not white \(lum(mid, 40, 49))")
                    }
                    if abs(lum(mid, 40, 35) - baseLum) > 2 {
                        dragFailures.append("interior touched \(lum(mid, 40, 35))")
                    }
                    // Callout outline (dashed) along its left edge.
                    let out = mag.calloutRect
                    if out.width < 79 || out.minX < 60 {
                        dragFailures.append("callout \(out)")
                    } else {
                        let x = Int(out.minX)
                        var inked = 0
                        for y in Int(out.minY + 1)..<Int(out.maxY - 1)
                        where abs(lum(mid, x, y) - baseLum) > 40 { inked += 1 }
                        if inked < 20 {
                            dragFailures.append("callout outline inked \(inked)")
                        }
                    }
                    // Released but not yet sampled: fail closed, draw nothing.
                    surface.endDrag()
                    let released = render(surface)
                    if lum(released, 20, 35) >= 200 || lum(released, 19, 35) < baseLum - 30 {
                        frameFailures.append("frame drawn without snapshot")
                    }
                    if !surface.fillPendingMagnifier(base: gray) {
                        frameFailures.append("no pending magnifier")
                    }
                    let filled = render(surface)
                    if lum(filled, 20, 35) < 200 {
                        frameFailures.append("source frame missing after fill \(lum(filled, 20, 35))")
                    }
                    if lum(filled, 19, 35) > baseLum - 30 {
                        frameFailures.append("source outer missing after fill \(lum(filled, 19, 35))")
                    }
                    if abs(lum(filled, 40, 35) - baseLum) > 2 {
                        frameFailures.append("interior touched after fill")
                    }
                    let ring = lum(filled, Int(out.minX), Int(out.midY))
                    if ring < 200 { frameFailures.append("callout ring \(ring)") }

                    // Clamp: a source near the right edge flips the callout
                    // to the left of it, and one near the top is pulled down.
                    let doc = CGRect(x: 0, y: 0, width: 200, height: 200)
                    let right = MagnifierAnnotation.calloutRect(
                        for: CGRect(x: 150, y: 20, width: 40, height: 30),
                        gap: 16, within: doc)
                    if right.maxX > 200 || right.minX < 0 || right.width != 80 {
                        clampFailures.append("right \(right)")
                    }
                    if right.maxX > 150 - 16 + 0.5 {
                        clampFailures.append("did not flip left \(right)")
                    }
                    let top = MagnifierAnnotation.calloutRect(
                        for: CGRect(x: 20, y: 170, width: 40, height: 30),
                        gap: 16, within: doc)
                    if top.maxY > 200 || top.minY < 0 {
                        clampFailures.append("top \(top)")
                    }
                    let legacy = MagnifierAnnotation.calloutRect(
                        for: CGRect(x: 150, y: 20, width: 40, height: 30),
                        gap: 16, within: nil)
                    if legacy.minX != 206 || legacy.minY != 20 {
                        clampFailures.append("legacy \(legacy)")
                    }
                    // A LARGE source (owner's 1.2.11 report): 2× does not fit
                    // on the right, and flipping left would land on top of
                    // the source. The callout must stay off the source,
                    // inside the document, and still at least 1×.
                    let big = CGRect(x: 150, y: 500, width: 400, height: 230)
                    let bigDoc = CGRect(x: 0, y: 0, width: 1280, height: 1121)
                    let bigOut = MagnifierAnnotation.calloutRect(
                        for: big, gap: 16, within: bigDoc)
                    if bigOut.intersects(big) {
                        clampFailures.append("large source covered \(bigOut)")
                    }
                    if !bigDoc.contains(bigOut) {
                        clampFailures.append("large callout outside \(bigOut)")
                    }
                    if bigOut.width < big.width - 0.5 {
                        clampFailures.append("large callout below 1x \(bigOut)")
                    }
                    if abs(bigOut.width / big.width - bigOut.height / big.height) > 0.01 {
                        clampFailures.append("large callout aspect \(bigOut)")
                    }
                    // Room only BELOW: the callout goes there instead of
                    // covering the source.
                    let wide = CGRect(x: 10, y: 120, width: 180, height: 30)
                    let wideOut = MagnifierAnnotation.calloutRect(
                        for: wide, gap: 16, within: doc)
                    if wideOut.intersects(wide) || !doc.contains(wideOut)
                        || wideOut.maxY > wide.minY {
                        clampFailures.append("wide source \(wideOut)")
                    }
                    // No room anywhere: 1×, inside the document, overlap
                    // accepted because nothing else is possible.
                    let huge = CGRect(x: 10, y: 10, width: 180, height: 180)
                    let hugeOut = MagnifierAnnotation.calloutRect(
                        for: huge, gap: 16, within: doc)
                    if !doc.contains(hugeOut) || hugeOut.width != 180 {
                        clampFailures.append("huge source \(hugeOut)")
                    }
                    // And the surface uses the host's bounds during the drag.
                    let clamped = AnnotationSurface(pixelScale: 1)
                    clamped.tool = .magnifier
                    clamped.magnifierBounds = { doc }
                    _ = clamped.beginDrag(atPixel: CGPoint(x: 150, y: 20))
                    clamped.continueDrag(toPixel: CGPoint(x: 190, y: 50))
                    if let live = clamped.annotations.last as? MagnifierAnnotation,
                       live.calloutRect.maxX > 200 {
                        clampFailures.append("surface unclamped \(live.calloutRect)")
                    } else if !(clamped.annotations.last is MagnifierAnnotation) {
                        clampFailures.append("no clamped draft")
                    }
                    clamped.abandonDrag()
                }
                check("sliceB-magnifier-drag-frame", dragFailures.isEmpty,
                      dragFailures.joined(separator: "; "))
                check("sliceB-magnifier-source-frame", frameFailures.isEmpty,
                      frameFailures.joined(separator: "; "))
                check("sliceB-magnifier-callout-clamped", clampFailures.isEmpty,
                      clampFailures.joined(separator: "; "))
            }

            // 7. Backdrop keeps inner coordinates and P3/alpha on `.none`
            let mapped = SliceBBackdrop.sourcePoint(
                fromPadded: CGPoint(x: 90, y: 70), padding: 40)
            let p3Space = CGColorSpace(name: CGColorSpace.displayP3)!
            let p3ctx = CGContext(
                data: nil, width: 30, height: 20, bitsPerComponent: 8,
                bytesPerRow: 0, space: p3Space,
                bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
            p3ctx.setFillColor(NSColor.systemPink.cgColor)
            p3ctx.fill(CGRect(x: 0, y: 0, width: 30, height: 20))
            let p3Image = p3ctx.makeImage()!
            let p3None = SliceBBackdrop.compose(
                image: p3Image, preset: .none,
                budgetBytes: SliceBExport.defaultBudgetBytes)
            let p3Kept = p3None?.colorSpace?.name == p3Space.name
                && p3None.map { imagesEqualForTesting($0, p3Image) } == true
            // `.none` returns the input untouched, so it proves nothing about
            // the composed path. The real question is a FRAMED P3 image with
            // ASYMMETRIC alpha: transparent, 25% and opaque bands in a colour
            // outside sRGB. A gradient-only output — the old black-fill bug
            // inverted — has to fail, so the framed result is compared against
            // a reference composed the same way with NO source image.
            let p3AlphaCtx = CGContext(
                data: nil, width: 30, height: 20, bitsPerComponent: 8,
                bytesPerRow: 0, space: p3Space,
                bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
            p3AlphaCtx.clear(CGRect(x: 0, y: 0, width: 30, height: 20))
            // Saturated P3 green: outside sRGB, so a lost colour space shows.
            let wideGreen = CGColor(
                colorSpace: p3Space, components: [0, 1, 0, 1])!
            p3AlphaCtx.setFillColor(wideGreen)
            p3AlphaCtx.fill(CGRect(x: 10, y: 0, width: 10, height: 20))
            p3AlphaCtx.setAlpha(0.25)
            p3AlphaCtx.setFillColor(wideGreen)
            p3AlphaCtx.fill(CGRect(x: 20, y: 0, width: 10, height: 20))
            p3AlphaCtx.setAlpha(1)
            let p3Alpha = p3AlphaCtx.makeImage()!
            let emptyCtx = CGContext(
                data: nil, width: 30, height: 20, bitsPerComponent: 8,
                bytesPerRow: 0, space: p3Space,
                bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
            emptyCtx.clear(CGRect(x: 0, y: 0, width: 30, height: 20))
            let p3Empty = emptyCtx.makeImage()!
            let p3Framed = SliceBBackdrop.compose(
                image: p3Alpha, preset: .sunset,
                budgetBytes: SliceBExport.defaultBudgetBytes)
            let p3Reference = SliceBBackdrop.compose(
                image: p3Empty, preset: .sunset,
                budgetBytes: SliceBExport.defaultBudgetBytes)
            // The reference above is composed by the SAME production code, so
            // it cannot answer whether the stops or the axis are right — both
            // sides would be wrong together. This checks the two gradient
            // endpoints against hard-coded Sunset values, in sRGB, at
            // backdrop-only coordinates: the axis runs from top-left to
            // bottom-right, so a swapped or rotated axis moves them.
            var stopsOK = false
            var stopsDetail = "no frame"
            let sRGB = CGColorSpace(name: CGColorSpace.sRGB)!
            let stopInner = makeSolidImage(
                width: 200, height: 200, color: NSColor.white.cgColor)
            if let stopFrame = SliceBBackdrop.compose(
                image: stopInner, preset: .sunset,
                budgetBytes: SliceBExport.defaultBudgetBytes) {
                let w = stopFrame.width, h = stopFrame.height
                var bytes = [UInt8](repeating: 0, count: w * h * 4)
                let c = CGContext(
                    data: &bytes, width: w, height: h, bitsPerComponent: 8,
                    bytesPerRow: w * 4, space: sRGB,
                    bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                c?.interpolationQuality = .none
                c?.draw(stopFrame, in: CGRect(x: 0, y: 0, width: w, height: h))
                func pixel(_ x: Int, _ yBL: Int) -> (Int, Int, Int) {
                    let i = ((h - 1 - yBL) * w + x) * 4
                    return (Int(bytes[i]), Int(bytes[i + 1]), Int(bytes[i + 2]))
                }
                // Endpoints only: interpolation-free, so no assumption about
                // how CoreGraphics blends between the stops.
                let startPixel = pixel(0, h - 1)
                let endPixel = pixel(w - 1, 0)
                func near(
                    _ a: (Int, Int, Int), _ b: (Int, Int, Int), _ tol: Int
                ) -> Bool {
                    abs(a.0 - b.0) <= tol && abs(a.1 - b.1) <= tol
                        && abs(a.2 - b.2) <= tol
                }
                // The SPEC's first and last Sunset stops, written here as
                // literals rather than read from production — a gate that
                // asked `gradientStops` for its expectation would agree with
                // any table at all. Tolerance covers the radial wash and the
                // ±2/255 grain, both of which reach the corners: the wash is
                // centred at (0.22w, 0.78h), so the top-left corner carries a
                // real amount of it and the bottom-right almost none.
                stopsOK = near(startPixel, (255, 208, 138), 26)
                    && near(endPixel, (122, 34, 136), 6)
                stopsDetail = "start \(startPixel) end \(endPixel)"
            }

            var p3FramedOK = false
            var p3Detail = "framed nil"
            if let framed = p3Framed, let reference = p3Reference,
               framed.width == reference.width {
                // sRGB, because a FRAMED export is sRGB. Reading it back
                // through P3 would convert it a second time and leave every
                // expectation in this block one conversion out of step.
                func readBack(_ image: CGImage) -> [UInt8]? {
                    var bytes = [UInt8](
                        repeating: 0, count: image.width * image.height * 4)
                    guard let c = CGContext(
                        data: &bytes, width: image.width, height: image.height,
                        bitsPerComponent: 8, bytesPerRow: image.width * 4,
                        space: CGColorSpace(name: CGColorSpace.sRGB)!,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
                    else { return nil }
                    c.interpolationQuality = .none
                    c.draw(image, in: CGRect(
                        x: 0, y: 0, width: image.width, height: image.height))
                    return bytes
                }
                if let got = readBack(framed), let want = readBack(reference) {
                    let pad = Int(SliceBBackdrop.padding(forLongEdge: 30))
                    let row = framed.height / 2
                    func px(_ b: [UInt8], _ x: Int) -> (Int, Int, Int, Int) {
                        let i = (row * framed.width + x) * 4
                        return (Int(b[i]), Int(b[i + 1]), Int(b[i + 2]),
                                Int(b[i + 3]))
                    }
                    // Source-over, computed from the reference itself: the
                    // transparent band must equal the backdrop exactly, the
                    // opaque band must equal the source exactly, and the 25%
                    // band must land between the two.
                    func blend(_ dst: Int, _ src: Int, _ a: Double) -> Double {
                        Double(src) * a + Double(dst) * (1 - a)
                    }
                    let clearX = pad + 5, solidX = pad + 15, mixX = pad + 25
                    let clearGot = px(got, clearX), clearWant = px(want, clearX)
                    let solidGot = px(got, solidX)
                    let mixGot = px(got, mixX), mixDst = px(want, mixX)
                    let srcGreen = wideGreen.components ?? [0, 0, 0, 1]
                    let srcBytes = (
                        Int((srcGreen[0] * 255).rounded()),
                        Int((srcGreen[1] * 255).rounded()),
                        Int((srcGreen[2] * 255).rounded()))
                    func close(
                        _ a: (Int, Int, Int, Int), _ b: (Int, Int, Int),
                        _ tol: Int
                    ) -> Bool {
                        abs(a.0 - b.0) <= tol && abs(a.1 - b.1) <= tol
                            && abs(a.2 - b.2) <= tol
                    }
                    let transparentShowsBackdrop = close(
                        clearGot, (clearWant.0, clearWant.1, clearWant.2), 2)
                    // The framed context is sRGB, so a P3 source is converted
                    // on the way in. Expect the CONVERTED colour, built by
                    // drawing the same source into an sRGB context — that is
                    // CoreGraphics' own conversion, not compose's.
                    func convertedToSRGB(
                        _ image: CGImage, atX x: Int
                    ) -> (Int, Int, Int)? {
                        let w = image.width, h = image.height
                        var probe = [UInt8](repeating: 0, count: w * h * 4)
                        guard let c = CGContext(
                            data: &probe, width: w, height: h,
                            bitsPerComponent: 8, bytesPerRow: w * 4,
                            space: CGColorSpace(name: CGColorSpace.sRGB)!,
                            bitmapInfo: CGImageAlphaInfo
                                .premultipliedLast.rawValue)
                        else { return nil }
                        c.interpolationQuality = .none
                        c.draw(image, in: CGRect(
                            x: 0, y: 0, width: CGFloat(w), height: CGFloat(h)))
                        let i = ((h / 2) * w + x) * 4
                        return (
                            Int(probe[i]), Int(probe[i + 1]), Int(probe[i + 2]))
                    }
                    // The opaque band of the source sits at x 10..<20.
                    let convertedSource = convertedToSRGB(p3Alpha, atX: 15)
                        ?? srcBytes
                    let opaqueShowsSource = close(solidGot, convertedSource, 3)
                    let quarterBlends = close(
                        mixGot,
                        (Int(blend(
                            mixDst.0, convertedSource.0, 0.25).rounded()),
                         Int(blend(
                            mixDst.1, convertedSource.1, 0.25).rounded()),
                         Int(blend(
                            mixDst.2, convertedSource.2, 0.25).rounded())),
                        4)
                    // A gradient-only result would satisfy the first check and
                    // fail these two, which is exactly the point.
                    let differsFromReference = !close(
                        solidGot, (px(want, solidX).0, px(want, solidX).1,
                                   px(want, solidX).2), 6)
                    // A FRAMED export is sRGB by design (the spec writes every
                    // stop, wash and grain value in sRGB), while `.none` still
                    // keeps its input space — the check just above.
                    let spaceKept = framed.colorSpace?.name
                        == CGColorSpace.sRGB
                    let opaqueOut = clearGot.3 == 255 && solidGot.3 == 255
                        && mixGot.3 == 255
                    p3FramedOK = spaceKept && opaqueOut
                        && transparentShowsBackdrop && opaqueShowsSource
                        && quarterBlends && differsFromReference
                    p3Detail = "space \(spaceKept) alpha \(opaqueOut) "
                        + "clear \(transparentShowsBackdrop) "
                        + "solid \(opaqueShowsSource) mix \(quarterBlends) "
                        + "differs \(differsFromReference) "
                        + "got \(solidGot) want \(convertedSource) "
                        + "rawP3 \(srcBytes)"
                }
            }
            check("sliceB2-backdrop-mapping",
                  mapped == CGPoint(x: 50, y: 30) && p3Kept && p3FramedOK
                    && stopsOK,
                  "mapped \(mapped) p3 \(p3Kept) \(p3Detail) "
                    + "stops \(stopsDetail)")

            // 8. Spotlight stays a singleton (preference OFF) and is hit by
            //    its hole. Surface gates below assume replace; pin OFF so a
            //    machine whose defaults already have multiple ON cannot
            //    flip them.
            SliceBCompositor.multipleSpotlightOverrideForTesting = false
            let spot1 = SpotlightAnnotation(uiScale: 1)
            spot1.rect = CGRect(x: 10, y: 10, width: 40, height: 40)
            let spot2 = SpotlightAnnotation(uiScale: 1)
            spot2.rect = CGRect(x: 60, y: 60, width: 20, height: 20)
            let afterSecond = SliceBCompositor.applySpotlight(
                existing: [spot1], new: spot2, multiple: false)
            // E. Spotlight replacement is one transaction, and it puts the
            //    previous one back WHERE it was.
            var spotFailures: [String] = []
            do {
                let surface = AnnotationSurface(pixelScale: 1)
                let markA = CounterAnnotation(uiScale: 1)
                let oldSpot = SpotlightAnnotation(uiScale: 1)
                oldSpot.rect = CGRect(x: 10, y: 10, width: 40, height: 30)
                oldSpot.dimFraction = 0.3
                let markB = CounterAnnotation(uiScale: 1)
                // The prior spotlight sits in the MIDDLE. With it last, an
                // implementation that simply appends the restored spotlight
                // would look correct while being wrong.
                surface.addAnnotationForTesting(markA)
                surface.addAnnotationForTesting(oldSpot)
                surface.addAnnotationForTesting(markB)
                if !surface.setSpotlightDim(0.7) {
                    spotFailures.append("replace-refused")
                }
                let newSpot = surface.annotations
                    .compactMap { $0 as? SpotlightAnnotation }.last
                if surface.annotations.count != 3
                    || surface.annotations[0] !== markA
                    || surface.annotations[1] !== markB
                    || surface.annotations[2] !== newSpot
                    || newSpot === oldSpot
                    || newSpot?.dimFraction != 0.7 {
                    spotFailures.append(
                        "after-replace \(surface.annotations.count)")
                }
                _ = surface.undo()
                // Back to the ORIGINAL order and the original object.
                if surface.annotations.count != 3
                    || surface.annotations[0] !== markA
                    || surface.annotations[1] !== oldSpot
                    || surface.annotations[2] !== markB
                    || oldSpot.dimFraction != 0.3 {
                    spotFailures.append(
                        "after-undo \(surface.annotations.map { type(of: $0) })")
                }
                _ = surface.redo()
                if surface.annotations.count != 3
                    || surface.annotations[0] !== markA
                    || surface.annotations[1] !== markB
                    || surface.annotations[2] !== newSpot
                    // ONE transaction: the replacement is a single step, so
                    // nothing is left on the redo branch after it.
                    || surface.canRedo {
                    spotFailures.append(
                        "after-redo canRedo \(surface.canRedo)")
                }
            }
            check("sliceB-spotlight-prior-index",
                  spotFailures.isEmpty, spotFailures.joined(separator: " | "))

            // F. A click — a zero-area drag — is not a mutation: the previous
            //    spotlight comes back untouched and the redo branch survives.
            var zeroFailures: [String] = []
            do {
                let surface = AnnotationSurface(pixelScale: 1)
                let markA = CounterAnnotation(uiScale: 1)
                let oldSpot = SpotlightAnnotation(uiScale: 1)
                oldSpot.rect = CGRect(x: 10, y: 10, width: 40, height: 30)
                let markB = CounterAnnotation(uiScale: 1)
                surface.addAnnotationForTesting(markA)
                surface.addAnnotationForTesting(oldSpot)
                surface.addAnnotationForTesting(markB)
                // Something on the redo branch, so the gate can tell whether a
                // no-op wrongly cleared it.
                let discarded = CounterAnnotation(uiScale: 1)
                surface.addAnnotationForTesting(discarded)
                _ = surface.undo()
                let redoAvailableBefore = surface.canRedo
                // Snapshot the fields too: reinserting the SAME object after
                // mutating it in place would satisfy an identity check while
                // having changed exactly what the user drew.
                let oldRect = oldSpot.rect
                let oldDim = oldSpot.dimFraction
                let oldBase = oldSpot.baseBounds
                surface.tool = .spotlight
                let started = surface.beginDrag(atPixel: CGPoint(x: 80, y: 80))
                // A drag that never started would leave the document already
                // correct, and every assertion below would pass for nothing.
                if !started || !surface.isDragging {
                    zeroFailures.append(
                        "not-started \(started) \(surface.isDragging)")
                }
                // Mid-drag the draft HAS displaced the previous spotlight:
                // that is the state the release has to undo.
                let midSpots = surface.annotations
                    .compactMap { $0 as? SpotlightAnnotation }
                if midSpots.count != 1 || midSpots.first === oldSpot {
                    zeroFailures.append("mid-draft \(midSpots.count)")
                }
                surface.continueDrag(toPixel: CGPoint(x: 80, y: 80))
                surface.endDrag()
                if surface.annotations.count != 3
                    || surface.annotations[0] !== markA
                    || surface.annotations[1] !== oldSpot
                    || surface.annotations[2] !== markB {
                    zeroFailures.append(
                        "order \(surface.annotations.count)")
                }
                if oldSpot.rect != oldRect || oldSpot.dimFraction != oldDim
                    || oldSpot.baseBounds != oldBase {
                    zeroFailures.append(
                        "old-mutated \(oldSpot.rect) \(oldSpot.dimFraction)")
                }
                // Checked HERE, before the redo below: `redo()` clears the
                // active draft itself, so a release that restored the array
                // correctly while leaving the draft alive would be cleaned up
                // by the very step meant to observe it.
                if surface.isDragging {
                    zeroFailures.append("still-dragging")
                }
                if !redoAvailableBefore || !surface.canRedo {
                    zeroFailures.append(
                        "redo \(redoAvailableBefore) -> "
                        + "\(surface.canRedo)")
                }
                // Redo restores the whole document, not just its last element.
                _ = surface.redo()
                if surface.annotations.count != 4
                    || surface.annotations[0] !== markA
                    || surface.annotations[1] !== oldSpot
                    || surface.annotations[2] !== markB
                    || surface.annotations[3] !== discarded
                    || surface.canRedo {
                    zeroFailures.append(
                        "after-redo \(surface.annotations.count) "
                        + "canRedo \(surface.canRedo)")
                }
            }
            // G. Nothing routes while the mouse is down. Driven through the
            //    REAL hosts with real events, with the key pressed BETWEEN the
            //    drag and the release — the window where the draft is already
            //    in the document and its transaction is half-built.
            var midDragFailures: [String] = []
            // Immediately invoked, so an environment guard can bail out of
            // THIS case without returning from the whole selftest.
            let runAreaMidDrag = {
                guard let screen = NSScreen.screens.first else {
                    midDragFailures.append("no-screen")
                    return
                }
                let frozenImage = makeSolidImage(
                    width: Int(screen.frame.width * 2),
                    height: Int(screen.frame.height * 2),
                    color: NSColor.white.cgColor)
                final class MidDragSpy {
                    var copies = 0
                    var saveDone: (@MainActor (SaveAsOutcome) -> Void)?
                    var completions = 0
                }
                let spy = MidDragSpy()
                let overlay = SelectionOverlay(
                    purpose: .areaReview,
                    inputs: OverlaySessionInputs(
                        afterShow: true, afterCopy: false, afterSave: false),
                    completion: { _ in spy.completions += 1 })
                overlay.routerDependenciesOverride =
                    CaptureActionRouter.Dependencies(
                        copyToClipboard: { _ in spy.copies += 1 },
                        autoSave: { _, _ in },
                        saveAs: { _, done in spy.saveDone = done },
                        pin: { _ in }, ocr: { _ in }, openEditor: { _ in },
                        toast: { _ in }, setLastCapture: { _ in },
                        setLastAreaRect: { _ in }, logEvent: { _ in })
                let view = SelectionOverlayView(
                    mode: .area, screen: screen,
                    frozen: CapturedImage(cgImage: frozenImage, scale: 2),
                    windowList: [], owner: overlay)
                view.selectForTesting(
                    rect: CGRect(x: 60, y: 60, width: 240, height: 180))
                let surface = view.annotationSurface
                if surface == nil { midDragFailures.append("no-surface") }
                // An existing spotlight, so a mid-drag digit has something to
                // corrupt: it used to clone the DRAFT and strand this one.
                let existing = SpotlightAnnotation(uiScale: 1)
                existing.rect = CGRect(x: 70, y: 70, width: 60, height: 40)
                existing.dimFraction = 0.3
                surface?.addAnnotationForTesting(existing)
                surface?.tool = .spotlight
                func key(_ chars: String) -> NSEvent? {
                    NSEvent.keyEvent(
                        with: .keyDown, location: .zero, modifierFlags: [],
                        timestamp: 0, windowNumber: 0, context: nil,
                        characters: chars, charactersIgnoringModifiers: chars,
                        isARepeat: false, keyCode: 0)
                }
                var midDragDim: CGFloat = 0
                var midDragCopies = 0
                var midDragCompletions = 0
                view.annotationDragForTesting(
                    from: CGPoint(x: 100, y: 100),
                    to: CGPoint(x: 180, y: 160)
                ) {
                    // A digit, a tool switch and a terminal action, all in the
                    // window where the draft is live.
                    if let event = key("5") { view.keyDown(with: event) }
                    // A key this surface really maps: the overlay has no
                    // Magnifier, so "m" would be a no-op even without the
                    // guard and would prove nothing.
                    if let event = key("l") { view.keyDown(with: event) }
                    view.performReviewActionForTesting(.copy)
                    midDragDim = existing.dimFraction
                    midDragCopies = spy.copies
                    midDragCompletions = spy.completions
                }
                if midDragDim != 0.3 {
                    midDragFailures.append("digit-applied \(midDragDim)")
                }
                if midDragCopies != 0 || midDragCompletions != 0 {
                    midDragFailures.append(
                        "terminal-ran \(midDragCopies)/\(midDragCompletions)")
                }
                if surface?.tool != .spotlight {
                    midDragFailures.append(
                        "tool-switched \(String(describing: surface?.tool))")
                }
                // The drag still completes normally afterwards: one spotlight,
                // the new one, with the prior recorded rather than stranded.
                let spots = (surface?.annotations ?? [])
                    .compactMap { $0 as? SpotlightAnnotation }
                if spots.count != 1 || spots.first === existing {
                    midDragFailures.append("finalize \(spots.count)")
                }
                // A new spotlight starts at the DEFAULT darkness; it does not
                // inherit the one it replaced, and the blocked digit must not
                // have reached it either.
                if spots.first?.dimFraction != 0.6 {
                    midDragFailures.append(
                        "new-dim \(spots.first?.dimFraction ?? -1)")
                }
                // And undo restores the one it replaced, in place.
                _ = surface?.undo()
                if surface?.annotations.count != 1
                    || surface?.annotations.first !== existing {
                    midDragFailures.append("undo-prior")
                }
                // POSITIVE CONTROL. Without it the zeros above could simply
                // mean this fixture can never route a terminal action at all.
                view.performReviewActionForTesting(.copy)
                // The whole route, not just its dependency: the session has to
                // finish too, or "completions == 0" mid-drag would still be a
                // negative with nothing positive behind it.
                if spy.copies != 1 || spy.completions != 1 {
                    midDragFailures.append(
                        "control \(spy.copies)/\(spy.completions)")
                }
            }

            runAreaMidDrag()

            // The panel implements the same policy separately, so it gets the
            // same question asked of it through its own real events.
            let runPanelMidDrag = {
                final class PanelMidDragSpy {
                    var copies = 0
                }
                let spy = PanelMidDragSpy()
                guard let screen = NSScreen.screens.first else {
                    midDragFailures.append("no-screen-panel")
                    return
                }
                let panelImage = CapturedImage(
                    cgImage: makeSolidImage(
                        width: 600, height: 400, color: NSColor.white.cgColor),
                    scale: 1)
                let deps = CaptureActionRouter.Dependencies(
                    copyToClipboard: { _ in spy.copies += 1 },
                    autoSave: { _, _ in }, saveAs: { _, _ in },
                    pin: { _ in }, ocr: { _ in }, openEditor: { _ in },
                    toast: { _ in }, setLastCapture: { _ in },
                    setLastAreaRect: { _ in }, logEvent: { _ in })
                let panel = ScrollResultPanel.show(
                    image: panelImage,
                    inputs: OverlaySessionInputs(
                        afterShow: true, afterCopy: false, afterSave: false),
                    screen: screen, dependencies: deps)
                let surface = panel.annotationSurface
                let existing = SpotlightAnnotation(uiScale: 1)
                existing.rect = CGRect(x: 40, y: 40, width: 80, height: 60)
                existing.dimFraction = 0.3
                surface.addAnnotationForTesting(existing)
                surface.tool = .spotlight
                func panelKey(_ chars: String) -> NSEvent? {
                    NSEvent.keyEvent(
                        with: .keyDown, location: .zero, modifierFlags: [],
                        timestamp: 0, windowNumber: panel.windowNumber,
                        context: nil, characters: chars,
                        charactersIgnoringModifiers: chars,
                        isARepeat: false, keyCode: 0)
                }
                var panelDim: CGFloat = 0
                var panelCopies = 0
                panel.drawWithRealEventsForTesting(
                    fromView: CGPoint(x: 60, y: 60),
                    toView: CGPoint(x: 160, y: 140)
                ) {
                    if let event = panelKey("5") { panel.keyDown(with: event) }
                    if let event = panelKey("l") { panel.keyDown(with: event) }
                    panel.performActionForTesting(.copy)
                    panelDim = existing.dimFraction
                    panelCopies = spy.copies
                }
                if panelDim != 0.3 {
                    midDragFailures.append("panel-digit \(panelDim)")
                }
                if panelCopies != 0 {
                    midDragFailures.append("panel-terminal \(panelCopies)")
                }
                if surface.tool != .spotlight {
                    midDragFailures.append("panel-tool \(surface.tool)")
                }
                let spots = surface.annotations
                    .compactMap { $0 as? SpotlightAnnotation }
                if spots.count != 1 || spots.first === existing
                    || spots.first?.dimFraction != 0.6 {
                    midDragFailures.append("panel-finalize \(spots.count)")
                }
                _ = surface.undo()
                if surface.annotations.count != 1
                    || surface.annotations.first !== existing {
                    midDragFailures.append("panel-undo-prior")
                }
                // Same positive control on the panel's own route — including
                // the teardown. Dismissing by hand afterwards would hide a
                // Copy that stopped closing the panel.
                panel.performActionForTesting(.copy)
                if spy.copies != 1 {
                    midDragFailures.append("panel-control \(spy.copies)")
                }
                if ScrollResultPanel.current === panel || panel.isVisible {
                    midDragFailures.append(
                        "panel-not-dismissed \(panel.isVisible)")
                    panel.dismissForTesting()
                }
            }
            runPanelMidDrag()
            // H. The real toolbar, at the smallest size the window allows.
            //    Fifteen tools cannot fit one 560 pt row, which is why there
            //    are two — and the proof has to come from the production
            //    hierarchy, not from a stack rebuilt for the occasion.
            var toolbarFailures: [String] = []
            let runToolbarLayout = {
                let wc = EditorWindowController.open(
                    with: CapturedImage(
                        cgImage: makeSolidImage(
                            width: 400, height: 300,
                            color: NSColor.white.cgColor),
                        scale: 1),
                    forceFitForTesting: true)
                defer { wc.window?.close() }
                let buttons = wc.toolButtonsForTesting
                if buttons.count != 15 {
                    toolbarFailures.append("count \(buttons.count)")
                    return
                }
                // Derived from a real button: its superview is the tool row,
                // whose superview is the two-row stack.
                guard let toolRow = buttons.first?.button.superview
                        as? NSStackView,
                      let stack = toolRow.superview as? NSStackView,
                      let actionRow = stack.arrangedSubviews.first
                        as? NSStackView,
                      let bar = stack.superview,
                      let window = wc.window,
                      let content = window.contentView,
                      let host = content.superview
                else {
                    toolbarFailures.append("hierarchy")
                    return
                }
                if stack.arrangedSubviews.count != 2
                    || stack.arrangedSubviews.last !== toolRow {
                    toolbarFailures.append(
                        "rows \(stack.arrangedSubviews.count)")
                }
                let actions = wc.actionButtonsForTesting
                let expectedActions = [
                    ("copy", "Copy (⌘C)"), ("save", "Save (⌘S)"),
                    ("pin", "Pin to screen (⌘P)"),
                    ("ocr", "Recognize text (OCR)"),
                    ("translate", "OCR + Translate"),
                ]
                if actions.map(\.name) != expectedActions.map(\.0) {
                    toolbarFailures.append("actions \(actions.map(\.name))")
                }
                let chrome: [(String, NSView)] = [
                    ("colorWell", wc.colorWellForTesting),
                    ("sizeBadge", wc.sizeBadgeForTesting),
                    ("zoom", wc.zoomLabelForTesting),
                ]
                // The constrained 30x28 icons: tools and the five terminal
                // actions. The size badge is deliberately not in here.
                let iconButtons: [NSView] =
                    buttons.map { $0.button } + actions.map { $0.button }

                // ONE verifier over the LIVE hierarchy, run at both sizes.
                // Everything geometric is re-asked after the resize, because a
                // control can be fine at one width and overflow, overlap or go
                // dead at another.
                // Positive comparison: `abs(a - b) > tol` is FALSE for NaN,
                // so every tolerance check written that way fails open.
                func near(_ a: CGFloat, _ b: CGFloat, _ tol: CGFloat = 0.5)
                    -> Bool {
                    a.isFinite && b.isFinite && abs(a - b) <= tol
                }
                @MainActor func verifyLayout(_ phase: String) {
                    content.layoutSubtreeIfNeeded()
                    // Rows and bar.
                    // 0.01: production constrains these to exactly 35, 35
                    // and 70, so half a point of slack is room a real gap can
                    // hide in rather than tolerance for rounding.
                    if !near(toolRow.frame.height, 35, 0.01)
                        || !near(actionRow.frame.height, 35, 0.01)
                        || !near(bar.frame.height, 70, 0.01) {
                        toolbarFailures.append(
                            "\(phase):row-heights \(actionRow.frame.height)/"
                            + "\(toolRow.frame.height)/\(bar.frame.height)")
                    }
                    for (name, view) in [
                        ("bar", bar), ("stack", stack as NSView),
                        ("toolRow", toolRow as NSView),
                        ("actionRow", actionRow as NSView),
                    ] where view.hasAmbiguousLayout {
                        toolbarFailures.append("\(phase):\(name)-ambiguous")
                    }
                    // Every exposed control: it belongs to its row DIRECTLY —
                    // coordinates alone would let a reparented or nested view
                    // pass — is inside that row and inside the bar, has a real
                    // frame, is not ambiguous, and answers a hit at its centre.
                    let members: [(String, NSView, NSStackView)] =
                        buttons.map { ($0.tool.rawValue, $0.button, toolRow) }
                        + actions.map { ($0.name, $0.button, actionRow) }
                        + chrome.map { ($0.0, $0.1, actionRow) }
                    // Arranged membership and visual order: `superview` alone
                    // does not say a view is arranged by the stack, nor where.
                    if stack.arrangedSubviews.count != 2
                        || stack.arrangedSubviews.first !== actionRow
                        || stack.arrangedSubviews.last !== toolRow {
                        toolbarFailures.append("\(phase):stack-order")
                    }
                    let arrangedTools = toolRow.arrangedSubviews
                        .compactMap { view in
                            buttons.first { $0.button === view }?.tool
                        }
                    if arrangedTools != EditorTool.allCases {
                        toolbarFailures.append(
                            "\(phase):tool-order \(arrangedTools.count)")
                    }
                    // The WHOLE exposed sequence, chrome included: pinning
                    // only the five buttons would let the colour well, the
                    // badge or the zoom label move around them.
                    let exposedNames = Set(
                        actions.map(\.name) + chrome.map(\.0))
                    let arrangedActions = actionRow.arrangedSubviews
                        .compactMap { view -> String? in
                            if let match = actions.first(
                                where: { $0.button === view }) {
                                return match.name
                            }
                            return chrome.first { $0.1 === view }?.0
                        }
                        .filter { exposedNames.contains($0) }
                    if arrangedActions != actions.map(\.name)
                        + chrome.map(\.0) {
                        toolbarFailures.append(
                            "\(phase):action-order \(arrangedActions)")
                    }
                    for (name, view, row) in members {
                        if view.superview !== row {
                            toolbarFailures.append("\(phase):\(name)-parent")
                        }
                        if !row.arrangedSubviews.contains(where: { $0 === view }) {
                            toolbarFailures.append("\(phase):\(name)-arranged")
                        }
                        if view.isHidden || view.frame.width <= 0
                            || view.frame.height <= 0 {
                            toolbarFailures.append("\(phase):\(name)-hidden")
                            continue
                        }
                        // Not merely positive: an icon button squeezed to a
                        // point would satisfy that while denying the very
                        // reason there are two rows.
                        // The zoom label is display-only, so it is not asked
                        // to be enabled; everything else here is actionable.
                        if let control = view as? NSControl,
                           view !== wc.zoomLabelForTesting,
                           !control.isEnabled {
                            toolbarFailures.append("\(phase):\(name)-disabled")
                        }
                        // Exact size for the icon buttons only. The size badge
                        // is also an NSButton but carries no size constraint —
                        // it is intrinsic, and demanding 30x28 of it would fail
                        // a correct build.
                        // Auto Layout constrains alignment rectangles. An
                        // SF-symbol button's frame includes symbol-specific
                        // alignment insets on current AppKit, so frame height
                        // is neither 28 nor uniform even when the required
                        // 30x28 constraints are satisfied exactly.
                        let alignment = view.alignmentRect(forFrame: view.frame)
                        if iconButtons.contains(where: { $0 === view }) {
                            if !near(alignment.width, 30)
                                || !near(alignment.height, 28) {
                                toolbarFailures.append(
                                    "\(phase):\(name)-size \(alignment.size)")
                            }
                        } else if view === wc.colorWellForTesting {
                            if !near(alignment.width, 28)
                                || !near(alignment.height, 24) {
                                toolbarFailures.append(
                                    "\(phase):\(name)-size \(alignment.size)")
                            }
                        }
                        if view.hasAmbiguousLayout {
                            toolbarFailures.append("\(phase):\(name)-ambiguous")
                        }
                        // `alignment` is already in the direct superview's
                        // coordinates; every member is required above to be a
                        // direct arranged child of `row`.
                        let inRow = alignment
                        if inRow.minX < -0.5
                            || inRow.maxX > row.bounds.width + 0.5
                            || inRow.minY < -0.5
                            || inRow.maxY > row.bounds.height + 0.5 {
                            toolbarFailures.append("\(phase):\(name)-row")
                        }
                        let inBar = row.convert(alignment, to: bar)
                        if inBar.minX < -0.5
                            || inBar.maxX > bar.bounds.width + 0.5
                            || inBar.minY < -0.5
                            || inBar.maxY > bar.bounds.height + 0.5 {
                            toolbarFailures.append("\(phase):\(name)-bar")
                        }
                        // hitTest takes a point in the RECEIVER'S superview
                        // space, so the centre is converted into the content
                        // view's parent. The chrome may answer with a subview
                        // of its own, which still counts as reachable.
                        let centre = CGPoint(
                            x: view.bounds.midX, y: view.bounds.midY)
                        let hit = content.hitTest(view.convert(centre, to: host))
                        // A button must answer for ITSELF: a child sitting on
                        // top of it would swallow the click while still being
                        // a descendant. Only composite chrome — a colour well
                        // draws through a subview — may answer with one.
                        let reachable = view is NSButton
                            ? hit === view
                            : (hit === view
                                || hit?.isDescendant(of: view) == true)
                        if !reachable {
                            toolbarFailures.append("\(phase):\(name)-hit")
                        }
                    }
                    // Rows tile the bar: same width as the stack, the stack
                    // filling the bar, the bar filling the content width, and
                    // the two rows not colliding. x overlap is by design; a
                    // rect intersection needs BOTH axes, so asking for it
                    // across the rows catches a vertical collision the earlier
                    // wording waved away.
                    // Full rects, not just sizes: matching widths and heights
                    // still allow a gap above one row and an overflow below
                    // the other.
                    if bar.superview !== content
                        || !near(bar.frame.minX, content.bounds.minX)
                        || !near(bar.frame.maxX, content.bounds.maxX)
                        || !near(bar.frame.maxY, content.bounds.maxY) {
                        toolbarFailures.append(
                            "\(phase):bar-frame \(bar.frame)")
                    }
                    if !near(stack.frame.minX, bar.bounds.minX)
                        || !near(stack.frame.maxX, bar.bounds.maxX)
                        || !near(stack.frame.minY, bar.bounds.minY)
                        || !near(stack.frame.maxY, bar.bounds.maxY) {
                        toolbarFailures.append(
                            "\(phase):stack-frame \(stack.frame)")
                    }
                    for (name, row) in [
                        ("toolRow", toolRow), ("actionRow", actionRow),
                    ] where !near(row.frame.minX, stack.bounds.minX)
                        || !near(row.frame.maxX, stack.bounds.maxX) {
                        toolbarFailures.append(
                            "\(phase):\(name)-x \(row.frame)")
                    }
                    if toolRow.frame.intersects(actionRow.frame) {
                        toolbarFailures.append("\(phase):rows-collide")
                    }
                    let rowsUnion = toolRow.frame.union(actionRow.frame)
                    // The shared edge directly, not just a union and a sum:
                    // two independent tolerances could each absorb half a gap.
                    let lower = toolRow.frame.minY < actionRow.frame.minY
                        ? toolRow.frame : actionRow.frame
                    let upper = lower == toolRow.frame
                        ? actionRow.frame : toolRow.frame
                    // BOTH: a shared edge alone still allows a matching gap
                    // at each outer edge — two rows of 34.5 inside 70 meet
                    // exactly and leave 0.5 top and bottom.
                    if !near(rowsUnion.minY, stack.bounds.minY, 0.01)
                        || !near(rowsUnion.maxY, stack.bounds.maxY, 0.01)
                        || !near(lower.maxY, upper.minY, 0.01)
                        || !near(toolRow.frame.height + actionRow.frame.height,
                                 stack.bounds.height, 0.01) {
                        toolbarFailures.append(
                            "\(phase):rows-do-not-tile \(rowsUnion)")
                    }
                    // Nothing actionable in either row that this gate has not
                    // accounted for; spacers and separators are not controls
                    // and are ignored by design.
                    // `subviews`, not `arrangedSubviews`: a control added
                    // directly to a row is not arranged by the stack but is
                    // still on screen and still clickable.
                    let known = Set(members.map { ObjectIdentifier($0.1) })
                    for row in [toolRow, actionRow] {
                        for view in row.subviews
                        where view is NSControl
                            && !known.contains(ObjectIdentifier(view)) {
                            toolbarFailures.append(
                                "\(phase):unexpected-control")
                        }
                    }
                    // Disjoint WITHIN each row.
                    for row in [toolRow, actionRow] {
                        let frames = members
                            .filter { $0.2 === row && !$0.1.isHidden }
                            .map {
                                ($0.0, $0.1.alignmentRect(forFrame: $0.1.frame))
                            }
                        for i in frames.indices {
                            for j in frames.indices where j > i
                                && frames[i].1.intersects(frames[j].1) {
                                toolbarFailures.append(
                                    "\(phase):overlap \(frames[i].0)/"
                                    + "\(frames[j].0)")
                            }
                        }
                    }
                }

                // Programmatic `setContentSize` is allowed to bypass
                // `contentMinSize`; AppKit then stops at the stack's fitting
                // width instead. Pin the declared user-resize floor itself,
                // and exercise the live hierarchy at that exact floor.
                if !near(window.contentMinSize.width, 560)
                    || !near(window.contentMinSize.height, 190) {
                    toolbarFailures.append(
                        "content-min \(window.contentMinSize)")
                }
                window.setContentSize(NSSize(width: 560, height: 300))
                content.layoutSubtreeIfNeeded()
                let width = content.bounds.width
                if !near(width, 560) {
                    toolbarFailures.append("min-width \(width)")
                }
                verifyLayout("min")

                // Wiring is asked once: a resize does not change it.
                for (tool, button) in buttons {
                    if button.identifier?.rawValue != tool.rawValue {
                        toolbarFailures.append("\(tool.rawValue):identifier")
                    }
                    // Backdrop opens the Option A sidebar; it is a document
                    // style, not a drawing mode, so it never selects a tool.
                    let expectedSelector = tool == .backdrop
                        ? NSSelectorFromString("toggleBackdropPanel:")
                        : NSSelectorFromString("toolTapped:")
                    if button.target !== wc
                        || button.action != expectedSelector {
                        toolbarFailures.append("\(tool.rawValue):action")
                    }
                    // All three semantic strings, exactly. makeButton sets
                    // the tooltip, the accessibility label and the image
                    // description from one string on purpose, so checking one
                    // of them — or merely that they are non-empty — would let
                    // two tools swap their descriptions unnoticed.
                    let label = button.accessibilityLabel() ?? ""
                    // The native tooltip is deliberately OFF — the editor is
                    // an activating window, so AppKit would draw its own
                    // beside the app's hint. The sentence lives in the hint
                    // catalog and in accessibility instead.
                    if label != tool.tooltip || button.toolTip != nil
                        || wc.hoverHint.textForTesting(button) != tool.tooltip
                        || button.accessibilityHelp() != tool.tooltip
                        || button.image == nil
                        || button.image?.accessibilityDescription
                            != tool.tooltip {
                        toolbarFailures.append(
                            "\(tool.rawValue):label(\(label))")
                    }
                }
                for ((name, tooltip), pair) in zip(expectedActions, actions) {
                    let button = pair.button
                    if button.target !== wc {
                        toolbarFailures.append("\(name):target")
                    }
                    if button.action
                        != NSSelectorFromString(
                            name == "translate" ? "runTranslate"
                                : name == "ocr" ? "runOCR"
                                : name == "pin" ? "pinImage"
                                : name == "save" ? "saveImage" : "copyImage") {
                        toolbarFailures.append("\(name):action")
                    }
                    if button.accessibilityLabel() != tooltip
                        || button.toolTip != nil
                        || wc.hoverHint.textForTesting(button) != tooltip
                        || button.accessibilityHelp() != tooltip
                        || button.image?.accessibilityDescription != tooltip {
                        toolbarFailures.append(
                            "\(name):label(\(button.accessibilityLabel() ?? "nil"))")
                    }
                    if button.image == nil {
                        toolbarFailures.append("\(name):image")
                    }
                }
                if wc.colorWellForTesting.target !== wc
                    || wc.colorWellForTesting.action
                        != NSSelectorFromString("colorChanged") {
                    toolbarFailures.append("colorWell:action")
                }
                if wc.sizeBadgeForTesting.target !== wc
                    || wc.sizeBadgeForTesting.action
                        != NSSelectorFromString("sizeBadgeClicked") {
                    toolbarFailures.append("sizeBadge:action")
                }
                // A real click on a NON-Backdrop tool must select it: target
                // and action being right says the wiring exists, not that it
                // works. Backdrop, the terminal actions and the size badge are
                // left alone — their menus run nested event loops.
                let sentinel = EditorTool.rect
                wc.selectTool(.select)
                if let button = buttons.first(where: { $0.tool == sentinel })?
                    .button {
                    button.performClick(nil)
                    if wc.canvasForTesting.currentTool != sentinel {
                        toolbarFailures.append(
                            "click \(wc.canvasForTesting.currentTool.rawValue)")
                    }
                } else {
                    toolbarFailures.append("no-sentinel")
                }

                // Re-expand: the same geometry, hit and hierarchy questions,
                // and every control re-acquired by identity and parent — not
                // just the first one.
                window.setContentSize(NSSize(width: 900, height: 600))
                content.layoutSubtreeIfNeeded()
                if !near(content.bounds.width, 900) {
                    toolbarFailures.append("no-expand \(content.bounds.width)")
                }
                verifyLayout("wide")
                let afterTools = wc.toolButtonsForTesting
                if afterTools.count != buttons.count
                    || !zip(afterTools, buttons).allSatisfy({
                        $0.0.button === $0.1.button
                            && $0.0.button.superview === toolRow
                    }) {
                    toolbarFailures.append("tool-identity-after-resize")
                }
                let afterActions = wc.actionButtonsForTesting
                if afterActions.count != actions.count
                    || !zip(afterActions, actions).allSatisfy({
                        $0.0.button === $0.1.button
                            && $0.0.button.superview === actionRow
                    }) {
                    toolbarFailures.append("action-identity-after-resize")
                }
                let afterChrome: [(String, NSView)] = [
                    ("colorWell", wc.colorWellForTesting),
                    ("sizeBadge", wc.sizeBadgeForTesting),
                    ("zoom", wc.zoomLabelForTesting),
                ]
                if !zip(afterChrome, chrome).allSatisfy({
                    $0.0.1 === $0.1.1 && $0.0.1.superview === actionRow
                }) {
                    toolbarFailures.append("chrome-identity-after-resize")
                }
            }
            runToolbarLayout()
            // I. Save-lock against a REAL worker, on the scroll panel.
            //    pendingForTesting holds no physical slot, so it cannot answer
            //    what happens to one; this blocks the recognizer instead and
            //    watches the slot, the owner and the mask through each stage.
            var lockStageFailures: [String] = []
            // Set when the OCR seam could not be safely handed back. Nothing
            // after this gate can be trusted in that state.
            var seamUnsafe = false
            let runSaveLockStages = {
                guard let screen = NSScreen.screens.first else {
                    lockStageFailures.append("no-screen")
                    return
                }
                let release = DispatchSemaphore(value: 0)
                let started = DispatchSemaphore(value: 0)
                // The recognizer seam is process-wide. It is restored to
                // whatever was there BEFORE, and only after the worker has
                // been released and drained — resetting it while a blocked
                // worker is still queued would let that worker wake up inside
                // real Vision and poison the slot for every later gate.
                let previousRecognizer = SliceBOCR.recognizerForTesting
                func slots() -> Int {
                    MainActor.assumeIsolated { SliceBRedactionJob.inFlight }
                }
                func owners() -> Int {
                    MainActor.assumeIsolated {
                        SliceBRedactionJob.ownerCountForTesting
                    }
                }
                let slotBase = slots()
                let ownerBase = owners()
                // A dirty baseline makes every later slot claim relative to
                // someone else's worker, so the gate refuses to guess.
                if slotBase != 0 || ownerBase != 0 {
                    // Every later OCR gate measures against these numbers, so
                    // a dirty baseline is not something to note and walk past:
                    // it takes the same fail-stop as a held seam.
                    lockStageFailures.append(
                        "dirty-baseline \(slotBase)/\(ownerBase)")
                    seamUnsafe = true
                    return
                }
                // Declared BEFORE the drain that waits on them.
                let workerFinished = DispatchSemaphore(value: 0)
                let scopeLock = NSLock()
                var scopeEnded = false
                func endScope() {
                    scopeLock.lock()
                    scopeEnded = true
                    scopeLock.unlock()
                    // Wake anything already parked in the closure.
                    for _ in 0..<8 { release.signal() }
                }
                var signalled = false
                var workerReturned = false
                var workerContained = false
                var workerEntered = false
                let entryLock = NSLock()
                @discardableResult
                func releaseAndDrain() -> Bool {
                    // Retryable: signalling happens once, but polling can be
                    // repeated, so a worker that finishes just after a timeout
                    // still lets the seam go back.
                    if workerContained { return true }
                    entryLock.lock()
                    let entered = workerEntered
                    entryLock.unlock()
                    // Nothing to wait for if no worker ever entered — a
                    // fixture that bailed before drawing would otherwise stall
                    // ten seconds on a signal nobody will send.
                    guard entered else {
                        // Enqueued but not yet in the closure: the background
                        // block looks the recognizer up when it runs, so
                        // restoring now would send it into the real one. Wait
                        // for the slot to come back instead.
                        if slots() > 0 {
                            let queued = Date().addingTimeInterval(10)
                            while slots() > 0, Date() < queued {
                                RunLoop.current.run(
                                    until: Date().addingTimeInterval(0.02))
                            }
                        }
                        workerContained = slots() == 0
                        if !workerContained {
                            lockStageFailures.append(
                                "queued-worker \(slots())")
                        }
                        return workerContained
                    }
                    if !signalled {
                        signalled = true
                        release.signal()
                    }
                    // Wait for OUR worker to return, then let the main queue
                    // deliver its result so the slot is actually given back.
                    // Waited for ONCE. A retry that waited again would block
                    // on a second signal nobody sends, add another ten seconds
                    // and then report the worker as missing even though its
                    // result had just landed.
                    if !workerReturned {
                        if workerFinished.wait(timeout: .now() + 10) == .timedOut {
                            lockStageFailures.append("worker-never-returned")
                            workerContained = false
                            return false
                        }
                        workerReturned = true
                    }
                    // The slot is given back on the main queue AFTER the
                    // worker returns, so it is waited for separately — and the
                    // baseline is a clean zero, so this is about this job.
                    let deadline = Date().addingTimeInterval(5)
                    while slots() > 0, Date() < deadline {
                        RunLoop.current.run(
                            until: Date().addingTimeInterval(0.02))
                    }
                    if slots() != 0 {
                        lockStageFailures.append("slot-not-returned \(slots())")
                        workerContained = false
                        return false
                    }
                    workerContained = true
                    return true
                }
                // The worker signals its own completion, so the drain waits
                // for THIS job rather than for an aggregate count another
                // fixture's worker could balance. Once the scope has ended the
                // closure stops blocking entirely, so a straggler cannot park
                // in it and cannot reach real Vision either.
                SliceBOCR.recognizerForTesting = { _ in
                    entryLock.lock()
                    workerEntered = true
                    entryLock.unlock()
                    started.signal()
                    scopeLock.lock()
                    let ended = scopeEnded
                    scopeLock.unlock()
                    if !ended { release.wait() }
                    defer { workerFinished.signal() }
                    return .success([
                        RecognizedWord(
                            rect: CGRect(x: 6, y: 6, width: 20, height: 12),
                            confidence: 0.9),
                    ])
                }
                var panelToClean: ScrollResultPanel?
                defer {
                    // The seam goes back ONLY once our worker has provably
                    // returned. If it has not, leaving the blocking recognizer
                    // installed is the containment: a stale worker then wakes
                    // in this closure rather than in real Vision.
                    // Panel FIRST, so a late result cannot land on a live
                    // surface while the worker is being released. Either
                    // condition closes it: a regression that clears `current`
                    // but forgets to order the window out would leak it.
                    if let panelToClean,
                       panelToClean.isVisible
                        || ScrollResultPanel.current === panelToClean {
                        panelToClean.dismissForTesting()
                        // Verified, not assumed: the early exits never reach
                        // Stage 5's check, so a dismiss that failed here would
                        // let the worker land on a live panel and the suite
                        // carry on regardless.
                        if panelToClean.isVisible
                            || ScrollResultPanel.current === panelToClean {
                            lockStageFailures.append("cleanup-leaked")
                            seamUnsafe = true
                            // The failure is already recorded, so this hides
                            // nothing — but the worker is about to be woken,
                            // and it must not be able to mutate or repaint a
                            // surface the gate just found still alive.
                            panelToClean.annotationSurface
                                .cancelAllRedactionJobs()
                        }
                    }
                    // Then release and drain OUR worker, and only then put the
                    // seam back. Ending the scope first makes the closure stop
                    // blocking, so a straggler passes straight through it
                    // rather than entering the recognizer that comes back —
                    // leaving a blocking closure installed would instead hang
                    // the next gate that used the seam.
                    // The scope ends first so the closure stops blocking,
                    // then the worker is drained. The seam goes back ONLY once
                    // the slot has returned: a job still queued would look the
                    // recognizer up when it finally runs, and restoring early
                    // would send it into the real one. Keeping this closure
                    // installed is safe now that it no longer blocks.
                    endScope()
                    // One more attempt after the scope ended, since the
                    // closure no longer blocks and a straggler may have just
                    // finished.
                    if releaseAndDrain() || releaseAndDrain() {
                        SliceBOCR.recognizerForTesting = previousRecognizer
                    } else {
                        // The suite cannot continue past this: a fake
                        // recognizer left installed feeds invented words to
                        // every later OCR gate, and a dirty slot shifts their
                        // baselines. The flag stops the run below.
                        lockStageFailures.append("seam-held")
                        seamUnsafe = true
                    }
                }

                final class LockSpy {
                    var saveDone: (@MainActor (SaveAsOutcome) -> Void)?
                    var saveAsCalls = 0
                    var inCallback: [String] = []
                    /// Runs INSIDE saveAs. Checking after the action returns
                    /// would say nothing about the order at the boundary.
                    var observe: (@MainActor () -> Void)?
                    var observations = 0
                    var copyCalls = 0
                }
                let spy = LockSpy()
                let panelImage = CapturedImage(
                    cgImage: makeNoiseImage(width: 400, height: 300), scale: 1)
                let panel = ScrollResultPanel.show(
                    image: panelImage,
                    inputs: OverlaySessionInputs(
                        afterShow: true, afterCopy: false, afterSave: false),
                    screen: screen,
                    dependencies: CaptureActionRouter.Dependencies(
                        copyToClipboard: { _ in spy.copyCalls += 1 },
                        autoSave: { _, _ in },
                        saveAs: { _, done in
                            spy.saveAsCalls += 1
                            spy.saveDone = done
                            spy.observations += 1
                            spy.observe?()
                        },
                        pin: { _ in }, ocr: { _ in }, openEditor: { _ in },
                        toast: { _ in }, setLastCapture: { _ in },
                        setLastAreaRect: { _ in }, logEvent: { _ in }))
                panelToClean = panel
                let surface = panel.annotationSurface
                let host = ForwardingRepaintDelegate(
                    wrapping: surface.redactionDelegate)
                surface.redactionDelegate = host
                // Created the way a user creates one, so production starts AND
                // registers the job.
                panel.clickToolbarButtonForTesting(
                    tag: OverlayAnnotationTool.pixelateText.toolbarTag)
                if surface.tool != .pixelateText {
                    lockStageFailures.append("tool \(surface.tool)")
                }
                panel.drawWithRealEventsForTesting(
                    fromView: CGPoint(x: 40, y: 40),
                    toView: CGPoint(x: 140, y: 110))
                guard let blur = surface.annotations
                    .compactMap({ $0 as? BlurAnnotation }).last else {
                    lockStageFailures.append("no-redaction")
                    return
                }
                if surface.redactionJobCountForTesting != 1 {
                    lockStageFailures.append(
                        "not-registered \(surface.redactionJobCountForTesting)")
                }
                let generation = blur.redactionGeneration
                if started.wait(timeout: .now() + 5) == .timedOut {
                    lockStageFailures.append("worker-never-started")
                    return
                }
                if slots() != slotBase + 1 || owners() != ownerBase + 1
                    || blur.redactionState != .pendingFull {
                    lockStageFailures.append(
                        "start \(slots()) \(owners()) "
                        + String(describing: blur.redactionState))
                }

                // Stage 1 — a FAILED render leaves the job alive and untouched.
                let repaintsBeforeFail = host.repaints
                // The panel exports through the surface renderer, which has
                // no backdrop compose in it — the outer seam would not fail
                // anything, the save would succeed, and this stage would be
                // asserting against a document that had already been handed
                // off.
                AnnotationRenderer.withForcedRegionalFailure {
                    panel.performActionForTesting(.save)
                }
                if spy.saveAsCalls != 0 {
                    lockStageFailures.append(
                        "failed-render-saved \(spy.saveAsCalls)")
                }
                if blur.redactionState != .pendingFull
                    || blur.redactionGeneration != generation
                    || host.repaints != repaintsBeforeFail
                    || surface.redactionJobCountForTesting != 1
                    || slots() != slotBase + 1 || owners() != ownerBase + 1
                    || ScrollResultPanel.current !== panel
                    || !panel.isVisible {
